window.ATLAS_I18N_LOR={"01IO012":["Параллельные дисциплины","Дайте союзнику +3|+0 или +0|+3 до конца раунда.","","\"Не бойся перемен. Они испытают тебя на прочность, но лучшего учителя тебе не найти\". – Карма","Заклинание",[],["Иония"],"ОБЫЧНОЕ"],"01IO015":["Ясуо","Когда вы оглушаете или возвращаете врага, я наношу ему 2 ед. урона.","Вы оглушили или вернули 5+ бойцов.","\"Смерть похожа на ветер...\"","Боец",[],["Иония"],"Чемпион"],"01IO020":["Хранительница масок","Призвав меня, дайте другим союзникам +1|+0 до конца раунда.","","\"Сегодня вы станете живым воплощением дисциплинированности, прилежания, скромности и равновесия. Сегодня вы станете Кинку\".","Боец",[],["Иония"],"ОБЫЧНОЕ"],"01IO045":["Вестник весны","Поддержка: до конца раунда дайте навык Вампиризм союзнику, которого я поддерживаю.","","\"Недолго длилось торжество зимы.\nПрошел по насту кто-то – слышим мы.\nВ следах его растет трава и новая лоза,\nЛесной ковер зазеленел: так к нам пришла весна\".\n– стихотворение из провинции Шонь-Сянь","Боец",[],["Иония"],"ОБЫЧНОЕ"],"01IO008":["Хвостатая мечница","Оглушив или вернув бойца, даруйте мне +2|+0.","","\"Думаешь, я милая и пушистая? Посмотрим, что ты скажешь на ЭТО!\"","Боец",["ЙОРДЛ"],["Иония"],"РЕДКОЕ"],"01IO040":["Клинок жизни Кинку","","","\"Когда-то здесь стояли наши школы, храмы и дома, а теперь остались лишь полные теней развалины. Орден Зеда осквернил наследие этого священного места. Я сделаю все, чтобы он пожалел об этом!\"","Боец",[],["Иония"],"ОБЫЧНОЕ"],"01IO041":["Карма","Конец раунда: создайте в руке случайное заклинание из своих регионов.","Вы достигли Просветления.","\"Занимаясь созерцанием, можно максимально сосредоточиться и придумать, как обойти любую преграду\".","Боец",[],["Иония"],"Чемпион"],"01IO011":["Возвращение","Верните союзника.","","Мудрый боец тверд и решителен, а еще он не полагается на волю случая. Вовремя отступив, он увеличит шансы на победу в будущем.","Заклинание",[],["Иония"],"ОБЫЧНОЕ"],"01IO009":["Зед","Атака: призовите атакующего бойца Живая тень с моими характеристиками.","На моих глазах я или союзные Живые тени дважды нанесли удар вражескому нексусу.","\"Только дураки служат равновесию. Тени открыли мне истинную силу\".","Боец",[],["Иония"],"Чемпион"],"01IO014":["Старейшина поляны","Призвав меня, даруйте союзникам в руке +1|+1.","","Знания ионийцев хранятся в письменных источниках, но жизнь этим древним текстам дают рассказы и учения старейшин.","Боец",[],["Иония"],"ОБЫЧНОЕ"],"01IO005":["Ловкий поро","","","\"Знаю, это странно, но последнее, что я помню… это прикосновение чего-то пушистого\". – Грабитель из Навори","Боец",["ПОРО"],["Иония"],"ОБЫЧНОЕ"],"01IO044":["Заговорщик из Навори","Чтобы сыграть меня, верните союзника.","","\"Эй, нам надо отсюда выбираться! Спрашиваешь, как меня зовут? По дороге расскажу, обещаю…\"","Боец",[],["Иония"],"ОБЫЧНОЕ"],"01IO023":["Самоцветный защитник","Разыгрывая карту: даруйте союзнику в руке +3|+3.","","\"Если случалось воевать, жители поселка шли за помощью к древнему хранителю Осенней долины. Самые удачливые получали благословение, способное изменить ход сражения\".\n– Из \"Саги об Исконной земле\"","Боец",[],["Иония"],"РЕДКОЕ"],"01IO029":["Посевы","Даруйте союзникам в руке +1|+0.","","\"Нет, дети, это не просто семена. Это наследие самой земли, залог будущего процветания\". – Карма","Заклинание",[],["Иония"],"РЕДКОЕ"],"01IO003":["Клеймо смерти","Заберите у союзника Эфемерность и даруйте ее врагу.","","\"Я клинок во тьме\". – Зед\n\n","Заклинание",[],["Иония"],"РЕДКОЕ"],"01IO047":["Теневая вспышка","Сделайте ВСЕХ сторонников в бою эфемерными.","","Когда равновесие магических потоков нарушается, они выплескиваются из царства духов в материальный мир, что влечет за собой самые неожиданные последствия.","Заклинание",[],["Иония"],"ЭПИЧЕСКОЕ"],"01IO026":["Вдохновляющий наставник","Разыгрывая карту: даруйте союзнику в руке +1|+0.","","\"Много лет я превращал свое тело в грозное оружие. Без устали наблюдал за птицами, описывал форму облаков... А сколько подносов со сладкими булочками я поднял! Где вы еще видели такую целеустремленность?\"","Боец",[],["Иония"],"ОБЫЧНОЕ"],"01IO024":["Рассвет и сумерки","Призовите 2 точные копии союзника. Они будут эфемерны.","","\"Шену грозят опасности двух миров – он не справится и подведет обитателей обоих. Я же всецело посвятил себя Ионии\". – Зед","Заклинание",[],["Иония"],"РЕДКОЕ"],"01IO028":["Чешуйчатый кусака","Разыгрывая карту: даруйте мне либо +3|+0, либо +0|+3.","","Этот старейший обитатель поляны отлично умеет приспосабливаться, а потому прошел проверку временем.","Боец",["РЕПТИЛИЯ"],["Иония"],"ОБЫЧНОЕ"],"01IO057":["Теневая убийца","Призвав меня, вытяните 1 карту.","","Она бесшумно\nСкользит сквозь тень, когтями\nПуть отмечая.","Боец",[],["Иония"],"ОБЫЧНОЕ"],"01IO032":["Шен","Поддержка: до конца раунда дайте Щит союзнику, которого я поддерживаю.","На моих глазах союзники получали Щит 5 раз.","\"Мир духов и материальный мир сплетены, словно сцепленные в замок ладони…\" ","Боец",[],["Иония"],"Чемпион"],"01IO013":["Зловещая тень","","","\"Чем ты пожертвуешь ради силы? Этот путь начнется с клятвы и не закончится, пока не заберет все, что у тебя есть\". – Зед","Боец",[],["Иония"],"ОБЫЧНОЕ"],"01IO018":["Спешка","Дайте союзнику +1|+0 и Быструю атаку до конца раунда.","","Сражение – это гонка, в которой нужно успеть первым отнять жизнь противника.","Заклинание",[],["Иония"],"ОБЫЧНОЕ"],"01IO056":["Енэ, Охотник на ветер","Разыгрывая карту: оглушите 2 врагов.","","\"Когда я был ребенком, брат спросил меня: \"Ветер преследует или убегает?\" Раньше брат преследовал меня, чтобы всему научиться. Теперь я преследую его, чтобы свершить правосудие\".","Боец",[],["Иония"],"РЕДКОЕ"],"01IO016":["Мудрец ветра","Разыгрывая карту: создайте точную копию карты из руки. Копировать карту Мудрец ветра нельзя.","","\"Воин оплакивал свою потерю, и старейшина сказал ему в утешение такие слова: \"Ищи небесного мудреца. Он один может вернуть то, что покинуло мир, но еще живо в памяти\".\n– Из \"Саги об Исконной земле\"","Боец",["ПТИЦА"],["Иония"],"РЕДКОЕ"],"01IO036":["Страж поляны","Удар: снизьте стоимость самого дорогого бойца в руке на 1.","","\"Дозорные! К нам движется… движутся ДВА огромных лохматых существа. Зовите подмо… Нет, стоп! Я опять посмотрел не в тот конец трубы...\"","Боец",["ЙОРДЛ"],["Иония"],"ОБЫЧНОЕ"],"01IO033":["Мина Быстроногая","Разыгрывая карту: верните 3 врагов.","","\"Несемся мы, значит, через лужайку – и вдруг откуда ни возьмись выпрыгивает эта мелюзга! Бам, бам, бам! – и всех нас раскидала!\" – Грабитель из Навори","Боец",[],["Иония"],"ЭПИЧЕСКОЕ"],"01IO001":["Ритуал обновления","Восстановите союзнику или своему нексусу 4 ед. здоровья. Вытяните 1 карту.","","\"Только просветленный разум поможет обрести целостность\". – Карма","Заклинание",[],["Иония"],"РЕДКОЕ"],"01IO010":["Плечом к плечу","Поменяйте местами 2 союзников. Дайте обоим Щит до конца раунда.","","\"Я иду ровной поступью\". – Шен\n","Заклинание",[],["Иония"],"РЕДКОЕ"],"01IO022":["Призрак","Дайте союзнику Изворотливость до конца раунда.","","\"Действуй скрытно и не возвращайся, пока не выполнишь задачу\". – Зед","Заклинание",[],["Иония"],"ОБЫЧНОЕ"],"01IO021":["Птенец ветрокрыла","Призвав меня, дайте другим союзникам +2|+2 до конца раунда.","","\"Весна в Ионии начинается на склонах скал, где раньше бутонов раскрываются крылья птенцов – поднятый ими ветерок предвещает оттепель\".\n– Из \"Саги об Исконной земле\"","Боец",[],["Иония"],"ЭПИЧЕСКОЕ"],"01IO054":["Эпохальная проницательность","Создайте в руке другое случайное заклинание из своих регионов.\nПросветление: создайте два заклинания.","","\"Если надежда гаснет, знай, что мы никогда не остаемся одни. Наше прошлое всегда рядом. Оно видело бесчисленное множество завтрашних дней, озаренных светом надежды\". – Карма","Заклинание",[],["Иония"],"РЕДКОЕ"],"01IO027":["Теневая пророчица","Удар по нексусу: создайте в руке мою копию.","","\"Плоти нельзя доверять. Она хрупка, словно граница меж светом и тенью\".","Боец",[],["Иония"],"ЭПИЧЕСКОЕ"],"01IO031":["Пьющий облака","Стоимость ваших взрывных и мгновенных заклинаний снижается на 1.","","Во всех окрестных деревнях было слышно его пение: длинные, низкие волны звука лились с неба на холмы – странные и зыбкие, как послеполуденные облака.","Боец",[],["Иония"],"РЕДКОЕ"],"01IO002":["Воля Ионии","Верните бойца.","","Едва ступив на землю Ионии, захватчики обнаружили, что покорить ее обитателей будет лишь половиной дела.","Заклинание",[],["Иония"],"ОБЫЧНОЕ"],"01IO017":["Лазутчик из Навори","Призвав меня, дайте мне Изворотливость до конца раунда.","","\"Я легко застану его врасплох! Вытащи меня оттуда – и поделим добычу поровну. Сплошная выгода для тебя!\"","Боец",["ЙОРДЛ"],["Иония"],"ОБЫЧНОЕ"],"01IO042":["Ученик из школы боевых искусств","Призвав другого союзника, дайте мне +1|+1 до конца раунда.","","\"Какой смысл сражаться, если никто не видит красоту твоих движений?\"","Боец",[],["Иония"],"ОБЫЧНОЕ"],"01IO006":["Парочка с поляны","Призвав другого союзника, дайте мне +1|+0 до конца раунда.","","\"Осторожно, ветки! Влево, ВЛЕВО!\"\n\"Когда я буду сидеть на ТВОИХ плечах, пушистик, мы пойдем куда ты скажешь. А пока что командую я!\"","Боец",[],["Иония"],"РЕДКОЕ"],"01IO050":["Разведчица Кинку","Верность: призовите из своей колоды союзника стоимостью 1.","","Она прокладывает путь для тех, кто пойдет следом.","Боец",[],["Иония"],"РЕДКОЕ"],"01IO048":["Юсари","","","\"Твой орден изгнал нас с родных земель. Ты доказал, что силен, мастер Зед. Теперь позволь мне доказать, что я достоин стать твоим учеником\".","Боец",[],["Иония"],"РЕДКОЕ"],"01IO007":["Рен Клинок тени","Удар: создайте в руке карту Зловещая тень.","","\"Беги, сражайся, прячься – разницы нет. Тени все равно придут за тобой\".","Боец",[],["Иония"],"ЭПИЧЕСКОЕ"],"01IO053":["Изумрудный пробудитель","Просветление: у меня +4|+4.","","\"Войны развязывают из самых низменных побуждений. Но они не властны над высшими ценностями: доверием, терпением и мудростью\".","Боец",[],["Иония"],"ОБЫЧНОЕ"],"01IO004":["Зелье здоровья","Восстановите союзнику или своему нексусу 3 ед. здоровья.","","В любую эпоху у представителей любого народа есть свои народные целебные средства: некоторые более действенные, некоторые – менее.","Заклинание",[],["Иония"],"ОБЫЧНОЕ"],"01IO049":["Отказ","Остановите Быстрое заклинание, Медленное заклинание или Способность.","","Нет.","Заклинание",[],["Иония"],"РЕДКОЕ"],"01IO052":["Разбойник из Навори","Призвав меня, призовите бойца Грабитель из Навори с моими характеристиками.","","\"Когда-то я был бродячим музыкантом – меня знали в каждой деревне отсюда до Пласидиума… А потом пришли ноксианцы. Теперь я живу на краденые медяки. Говорила мне мама: учись на лекаря…\"","Боец",[],["Иония"],"ОБЫЧНОЕ"],"01IO030":["Эмпиреец","","","\"Небеса содрогнулись, когда плети ветра и грозовые тучи смяли наш отряд. Мы бросились в погоню за чудовищем – но разве можно догнать ветер?\" – Легат","Боец",["ДРАКОН"],["Иония"],"ЭПИЧЕСКОЕ"],"01IO019":["Служительница поляны","Когда союзник получает Щит, даруйте мне +2|+0.","","\"Поляна защищает своих. А тебе здесь не место\".","Боец",[],["Иония"],"ОБЫЧНОЕ"],"01IO046":["Стальная буря","Оглушите атакующего врага.","","\"Хасеги\"! – Ясуо","Заклинание",["СТИХИЯ"],["Иония"],"РЕДКОЕ"],"01IO037":["Пристанище духа","Дайте союзнику Щит и Вампиризм до конца раунда.","","\"Этот клинок принадлежал моему отцу. Пусть он даст тебе силу, которой когда-то недостало мне\". – Шен","Заклинание",[],["Иония"],"ОБЫЧНОЕ"],"01IO043":["Повелитель рек","Удар: вытяните заклинание.","","\"Мы – гордые дети Исконной земли. Ее магия пронизывает здешние леса, реки, горы, равнины – и нашу вастайскую кровь\".","Боец",[],["Иония"],"РЕДКОЕ"],"01IO038":["Монашка-отшельница","Разыгрывая карту: верните всех остальных союзников.","","\"Быстрая реакция и острое чутье. Другие спутники мне не нужны\".","Боец",[],["Иония"],"РЕДКОЕ"],"01IO039":["Теневой переход","Верните одного союзника и призовите вместо него другого: Живая тень.","","\"Пока они гоняются за шепчущими тенями, я вырву им сердца\". – Зед","Заклинание",[],["Иония"],"ОБЫЧНОЕ"],"01IO055":["Защитник ци","Даруйте Щит союзнику в руке.\nВытяните 1 карту.","","\"Те, кто хранит равновесие, могут рассчитывать на защиту ордена Кинку\". – Шен\n","Заклинание",[],["Иония"],"ОБЫЧНОЕ"],"01NX020":["Дрейвен","Призвав меня либо когда я наношу удар: создайте в руке карту Вращающийся топор.","Я нанес удар, использовав 2+ Вращающихся топора (вместе или по отдельности).","\"Хочешь автограф? Вставай в очередь\".","Боец",[],["Ноксус"],"Чемпион"],"01NX006":["Владимир","Разыгрывая карту: нанесите 1 ед. урона любому числу союзников, а затем нанесите столько же урона врагу.","5+ союзников выжили, получив урон.","Порочный. Холодный. Жестокий. Интригующий. Знающий. Очаровательный.\nНеотразимый…","Боец",[],["Ноксус"],"Чемпион"],"01NX004":["Выбраковка","Убейте бойца с силой не больше 3.","","Все мы когда-нибудь умрем. Просто слабые умрут быстрее.","Заклинание",[],["Ноксус"],"РЕДКОЕ"],"01NX048":["Алый хранитель","Когда я выживаю, получив урон, создайте в руке случайного бойца Алого круга.","","\"Рад всех вас видеть!\" – \"Значит, вы тоже получили приглашение?\" – \"На Упоительный бал!\" – \"Дружной компанией!\" – \"Есть о чем подумать. Кай, а ты что скажешь? Ты пойдешь на бал?\"","Боец",[],["Ноксус"],"ОБЫЧНОЕ"],"01NX038":["Дариус","","Я вижу вражеский нексус с половиной стартового запаса здоровья или менее.","\"Железная воля и нечеловеческая сила. Сложно представить более достойного командующего для Трифарианского легиона\". – Свейн\n","Боец",[],["Ноксус"],"Чемпион"],"01NX023":["Паучье полчище","Когда меня призывают, даруйте остальным союзникам-паукам +2|+0.","","Она пленяет с первого взгляда. Они – с первого укуса.","Боец",["ПАУК"],["Ноксус"],"РЕДКОЕ"],"01NX013":["Решающий маневр","Оглушите врага. Дайте всем союзникам +2|+0 до конца раунда.","","\"Бросить против врага численно превосходящие силы может любой дурак. Хитрость нужна, чтобы скрывать преимущество до решающего момента\". – Свейн","Заклинание",[],["Ноксус"],"РЕДКОЕ"],"01NX046":["Паук-стражник","Разыгрывая карту: оглушите врага.","","\"Я очарован ее бесконечно длинными ногами, парализующе-сладким голосом и алыми как роза глазами. Поверить не могу, что она пригласила меня на ужин!\"\n– Невезучий аристократ","Боец",["ПАУК"],["Ноксус"],"ОБЫЧНОЕ"],"01NX047":["Магия крови","Нанесите одному союзнику 1 ед. урона и дайте другому +2|+2 до конца раунда.","","\"Ты даешь, я забираю. Это называется разделением обязанностей\". – Владимир","Заклинание",[],["Ноксус"],"ОБЫЧНОЕ"],"01NX040":["Легионер-диверсантка","Атака: нанесите 1 ед. урона вражескому нексусу.","","\"Наши щитоломы могут разрубить человека надвое, но у легиона есть и другие, более... деликатные средства\". – Свейн","Боец",[],["Ноксус"],"ОБЫЧНОЕ"],"01NX025":["Братские узы","Даруйте 2 союзникам +2|+0.","","\"Узы, которые создаются на войне, ничем не уступают родственным – ведь их тоже скрепляет кровь\". – Легионер-ветеран","Заклинание",[],["Ноксус"],"ОБЫЧНОЕ"],"01NX055":["Домашний паук","Призвав меня, призовите карту Паучок.","","\"Мои паучки любят гостей. Жаль, что эти чувства не взаимны...\" – Элиза","Боец",["ПАУК"],["Ноксус"],"ОБЫЧНОЕ"],"01NX030":["Алая ученица","Когда я выживаю, получив урон, нанесите 1 ед. урона вражескому нексусу.","","\"Особенно в свете текущих событий?\" – \"Естественно, мы должны пойти все вместе\". – \"Если будешь так переживать, то когда веселиться? Лучше обещай мне первый танец\". – \"Лучше вообще обойтись без них!\"","Боец",[],["Ноксус"],"РЕДКОЕ"],"01NX007":["Комментатор боев","Атака: дайте другим атакующим союзникам +1|+0 до конца раунда.","","Он ликующе взревел. В этот миг триумфа сердце арены билось в одном ритме с его собственным – он буквально повелевал чувствами собравшейся толпы.","Боец",[],["Ноксус"],"РЕДКОЕ"],"01NX021":["Ноксианский мародер","Атака: даруйте союзным Ноксианским мародерам везде +1|+1.","","За Трифарианским легионом всегда тянутся грабители – любители поживиться за счет слабых и раненых.","Боец",[],["Ноксус"],"ОБЫЧНОЕ"],"01NX009":["Любимец толпы","Призвав меня, даруйте мне +1|+1 за каждого имеющегося союзника.","","Одних уравнителей фанаты любят за обаяние, других – за мастерство и скорость. У Вессида нет ни того, ни другого, зато он лучше всех размазывает противников по стенке.","Боец",[],["Ноксус"],"РЕДКОЕ"],"01NX011":["Кружащаяся смерть","Союзник в бою наносит удар врагу в бою.","","\"У меня самая лучшая работа\". – Дрейвен","Заклинание",[],["Ноксус"],"ОБЫЧНОЕ"],"01NX053":["Бой уравнителей","Если у вас есть союзник с силой 5+, убейте ВСЕХ бойцов с силой не более 4.","","\"КТО ХОЧЕТ УРАВНИТЬСЯ?\" – Комментатор боев","Заклинание",[],["Ноксус"],"ЭПИЧЕСКОЕ"],"01NX054":["Угрожающий рык","Оглушите всех врагов с силой не более 4.","","\"Он набирает в грудь воздуха… Кажется, сейчас он… о да, да! Это знаменитый боевой клич Громобоя! У нас трясутся поджилки! Гро-мо-бой!\" – Комментатор боев","Заклинание",[],["Ноксус"],"РЕДКОЕ"],"01NX029":["Легионер-ветеран","Когда другой союзник выживает, получив урон, даруйте ему +1|+0.","","Он вернулся с войны еле живым, но супружеская забота и аптекарские снадобья совершили чудо. Ноксус не пожалел средств, чтобы сохранить жизнь этого ветерана, и теперь он передает свой опыт другим.","Боец",[],["Ноксус"],"ЭПИЧЕСКОЕ"],"01NX014":["Шираза Клинок","Я наношу нексусу вдвое больше урона.","","\"Что он сказал?! У него точно камни в голове. Зато понятно, зачем ему такие плечи\".","Боец",[],["Ноксус"],"ЭПИЧЕСКОЕ"],"01NX042":["Катарина","Когда меня призывают, создайте в руке мимолетную карту Лезвие клинка.","Я нанесла удар однажды. Верните меня после того, как мой уровень повысится.","\"Тренировка с демасийскими мишенями помогает оставаться в форме\".","Боец",[],["Ноксус"],"Чемпион"],"01NX051":["Капитан Фаррон","Когда меня призывают, создайте в руке 2 карты Истребление.","","В Сточных ямах Зауна молодого Бена Фаррона считали опасным, неуравновешенным и непредсказуемым. Ноксус же с радостью принял Бена и признал его таланты.","Боец",[],["Ноксус"],"ЭПИЧЕСКОЕ"],"01NX012":["Легионер арьергарда","","","В Ноксусе, где солдат ценят за проявленную на поле боя храбрость, назначение в арьергард считается едва ли не наказанием.","Боец",[],["Ноксус"],"ОБЫЧНОЕ"],"01NX043":["Лезвие клинка","Нанесите 1 ед. урона любой цели.","","\"В умелых руках клинок может разрезать что угодно… я не преувеличиваю\". – Катарина","Заклинание",[],["Ноксус"],"ОБЫЧНОЕ"],"01NX037":["Легионер-гренадер","Предсмертный вздох: нанесите вражескому нексусу 1 ед. урона.","","Каждый ноксианец с детства знает, что достойно прожитая жизнь – это жизнь на службе Империи. Легионеры-гренадеры наглядно демонстрируют, как это нужно делать.","Боец",[],["Ноксус"],"ОБЫЧНОЕ"],"01NX010":["Легат","Призвав меня, даруйте мне +1|+1 за каждого бойца, которого вы оглушили или вернули.","","Все ноксианцы знают три принципа силы, но чтобы подняться выше рядового, нужно научиться их применять.","Боец",[],["Ноксус"],"ОБЫЧНОЕ"],"01NX017":["Барабанщица легиона","Поддержка: до конца раунда дайте быструю атаку союзнику, которого я поддерживаю.","","С каждым ударом в барабан они расширяли владения Ноксуса. Ничто не могло их остановить. И не остановило.","Боец",[],["Ноксус"],"ОБЫЧНОЕ"],"01NX003":["Букмекер","Начало раунда: сбросьте карту с самой низкой стоимостью и вытяните 1 карту.","","\"…Ты ставил на то, что выживет ТОЛЬКО Шираза, но тот парнишка из Ионии, хоть и лишился руки, но не умер. То есть он тоже выжил. Конечно, можно удвоить ставки и…\"","Боец",["ЙОРДЛ"],["Ноксус"],"РЕДКОЕ"],"01NX039":["Дальновидность","Сбросив или разыграв это заклинание, даруйте союзникам +1|+0.","","\"Тем, кто не видит будущего, нет в нем места\".\n– Джерико Свейн","Заклинание",[],["Ноксус"],"РЕДКОЕ"],"01NX041":["Трифарианский щитолом","","","\"Я не буду тратить время на осаду. Посылайте щитоломов\". – Дариус","Боец",[],["Ноксус"],"ОБЫЧНОЕ"],"01NX036":["Минотавр-уравнитель","Начало раунда: оглушите слабейшего врага.","","\"Мне плевать, кто и чем тебя обидел. Если хочешь, чтобы я уделал его на арене – плати вперед. За сопливые истории я скидку не делаю\".","Боец",[],["Ноксус"],"РЕДКОЕ"],"01NX044":["Таран","Атака: даруйте мне +4|+0.","","\"Они отказались открывать ворота, командир. Требуют переговоров с Дариусом, но он в двух днях пути. Прикажете выслать гонцов?\"\n\"В этом нет необходимости\".","Боец",[],["Ноксус"],"ЭПИЧЕСКОЕ"],"01NX005":["Алая аристократка","Разыгрывая карту: нанесите союзнику 1 ед. урона, а также даруйте ему +1|+0 и Пробивание.","","\"А как же! Приглашение на бал…\" – \"Родные будут просто \"в восторге\". – \"Моя дорогая, при всем уважении – за такое отец лишит меня наследства. Быть может, пойдем в одинаковых платьях?\"","Боец",[],["Ноксус"],"ОБЫЧНОЕ"],"01NX016":["Способный трифарианец","Призвав меня, даруйте мне +2|+0, если у вас есть еще один ноксианский союзник.","","\"Звание получишь, когда топор затупится в бесконечных битвах, а ботинки промокнут от крови\".\n– Легионер-ветеран","Боец",[],["Ноксус"],"ОБЫЧНОЕ"],"01NX019":["Мощь","Дайте союзнику +3|+0 и Пробивание до конца раунда.","","\"Деликатные методы переоценены. Это не значит, что они плохи. Просто переоценены\". – Дариус","Заклинание",[],["Ноксус"],"ОБЫЧНОЕ"],"01NX015":["Любимый питомец","","","Она любит всех своих питомцев. Просто этого – особенно.","Боец",["ПАУК"],["Ноксус"],"ОБЫЧНОЕ"],"01NX050":["Цветок смерти","Нанесите 1 ед. урона ВСЕМ бойцам в бою.","","\"Потанцуй со мной\". – Катарина","Заклинание",[],["Ноксус"],"РЕДКОЕ"],"01NX056":["Шунпо","Нанесите врагу 2 ед. урона, а затем активируйте Рвение.","","Если вы видите клинок, спасаться уже поздно.","Заклинание",[],["Ноксус"],"ОБЫЧНОЕ"],"01NX033":["Трифарианский инспектор","Призвав меня, вытяните 1 карту за каждого союзника с силой 5+.","","\"Чтобы выбрать тех, кто достоин служить в Трифарианском легионе, нужно видеть кандидатов насквозь… А она за милю отличит волков от овец\". – Легат","Боец",[],["Ноксус"],"РЕДКОЕ"],"01NX052":["Кровь за кровь","Нанесите 1 ед. урона союзному стороннику. Если тот выживет, создайте в руке его копию.","","Первое практическое занятие гемоманта – зрелище не для слабонервных.","Заклинание",[],["Ноксус"],"ОБЫЧНОЕ"],"01NX045":["Дикарь-уравнитель","","","\"А теперь КОГТИЙ! В прошлый раз он одолел Безумную Пятерку… и превратил ее в Безумную Тройку. Итак! Принимаю ставки на жертву! Четыре к одному!\" – Карл, букмекер","Боец",[],["Ноксус"],"РЕДКОЕ"],"01NX031":["Трифарианская охотница за славой","","","Для многих попасть в Трифарианский легион – это уже предел мечтаний. Но не для всех…","Боец",[],["Ноксус"],"РЕДКОЕ"],"01NX002":["Истребление","Нанесите 4 ед. урона вражескому нексусу.","","\"Иногда города берут тактической хитростью. А иногда надо просто ударить посильнее\". – Дариус","Заклинание",[],["Ноксус"],"РЕДКОЕ"],"01NX008":["Наездник на василиске","Верность: даруйте мне +1|+1 и Пробивание.","","Этому бойцу нужны лошади, но не для того, чтобы на них ездить. Для чудовища они – лакомство.","Боец",[],["Ноксус"],"РЕДКОЕ"],"01NX034":["Ласковый поро","","","\"В Ноксусе нет места для… слаб… КТО-НИБУДЬ, СНИМИТЕ ЭТО С МЕНЯ!\" – Дариус","Боец",["ПОРО"],["Ноксус"],"ОБЫЧНОЕ"],"01NX035":["Главный фанат Дрейвена","Призвав меня, переместите чемпиона Дрейвен на верх колоды, если он не в руке и не на поле.","","\"Хочешь автограф? Вставай… вставай в очередь\".","Боец",[],["Ноксус"],"ОБЫЧНОЕ"],"01NX026":["Безрассудный трифарианец","","","\"Безрассудство – порок, но в легионе из него сделают полезный инструмент\". – Свейн","Боец",[],["Ноксус"],"ОБЫЧНОЕ"],"01NX027":["Эликсир гнева","Дайте союзнику +3|+0 до конца раунда.","","\"Если вам не пожали руку, ее всегда можно сжать в кулак\".\n– Ноксианская аксиома","Заклинание",[],["Ноксус"],"ОБЫЧНОЕ"],"01NX022":["Ноксианская гильотина","Убейте раненого бойца, чтобы создать в руке мимолетную версию карты Ноксианская гильотина.","","Милосердие Дариуса – быстрый удар.","Заклинание",[],["Ноксус"],"РЕДКОЕ"],"01NX032":["Алый пробудитель","Призвав меня, нанесите 1 ед. урона всем остальным союзникам.","","\"Ты так говоришь, будто у меня есть выбор\".","Боец",[],["Ноксус"],"РЕДКОЕ"],"01NX024":["Кейто Рука","Поддержка: до конца раунда дайте союзнику, которого я поддерживаю, +3|+0 и Пробивание.","","\"Шираза – чудесная девушка... в смысле, подруга. Вы не подумайте, мы вовсе не встречаемся! Но если бы встречались, я хотел бы передать ей поздравления на нашу годовщину... Все, хватит вопросов!\"","Боец",[],["Ноксус"],"ЭПИЧЕСКОЕ"],"01NX049":["Коварство","Оглушите врага.","","\"Дайте противнику веревку – и он сам повесится. Зачем тратить силы?\" – Ле Блан","Заклинание",[],["Ноксус"],"ОБЫЧНОЕ"],"01DE031":["Глашатаи зари","Конец раунда: если в этом раунде погиб союзник, даруйте остальным союзникам +1|+1.","","\"Зло взяло верх, но лишь на время. Почтите павших, и пусть память о них станет вашим надежным доспехом\".","Боец",[],["Демасия"],"ЭПИЧЕСКОЕ"],"01DE022":["Люциан","","На моих глазах погибли 4+ союзника или союзная Сенна.","\"Я в порядке, пока у меня есть ты, Сенна\".","Боец",[],["Демасия"],"Чемпион"],"01DE019":["Мобилизация","Снизьте стоимость союзников в руке на 1.","","\"С пшеничного поля – на поле боя! Нам нужен каждый демасиец, способный держать в руках оружие\". – Гарен","Заклинание",[],["Демасия"],"РЕДКОЕ"],"01DE042":["Люкс","","На моих глазах вы потратили на заклинания 6+ ед. маны. Когда мой уровень повышается, создайте в руке карту Последняя искра.","\"Я всегда чувствовала, что отличаюсь от других. У меня внутри огонек. Я не знаю, что это такое, но обязательно выясню!\" ","Боец",[],["Демасия"],"Чемпион"],"01DE010":["Быстрокрылый копейщик","Предсмертный вздох: создайте в руке случайного элитного бойца.","","\"Нужно быть очень смелым, чтобы доверить свою жизнь среброкрылому и вести бой высоко над землей. Смелым и очень выносливым\". – Гарен","Боец",["ЭЛИТА","ПТИЦА"],["Демасия"],"РЕДКОЕ"],"01DE020":["Защитница Авангарда","","","\"Мы понятия не имели, что это за создания. Но ужас, написанный на лицах наших товарищей, был красноречивее слов\".","Боец",["ЭЛИТА"],["Демасия"],"ОБЫЧНОЕ"],"01DE034":["Боевой кузнец","Если вы призвали элитного бойца, даруйте ему +1|+1.","","\"Победу выковывают в кузне\".","Боец",[],["Демасия"],"РЕДКОЕ"],"01DE002":["Тианна Краунгард","Призвав меня, используйте Рвение.","","Наша семья проливала кровь за родное королевство. Я не позволю втоптать в грязь фамильную честь ради какой-то игры света.","Боец",[],["Демасия"],"ЭПИЧЕСКОЕ"],"01DE012":["Гарен","Призвав меня, дайте другим союзникам +1|+1 до конца раунда.","Я нанес удар дважды.","Воинская подготовка и выносливость – вот что нужно солдату. Мы не отступим даже пред лицом величайшей угрозы.","Боец",["ЭЛИТА"],["Демасия"],"Чемпион"],"01DE017":["Один в поле воин","Если у вас ровно один союзник, даруйте ему +3|+3.","","Если союзников больше не осталось, настоящий герой идет к победе в одиночку.","Заклинание",[],["Демасия"],"РЕДКОЕ"],"01DE045":["Фиора","","Мне удалось убить двух врагов.","\"На дуэлях и турнирах, в боях учебных и настоящих я всегда ищу достойных противников. Я не успокоюсь, пока меня не признают лучшей\".","Боец",[],["Демасия"],"Чемпион"],"01DE052":["Стальной строй","Призвав меня или атакуя: дайте союзникам Щит до конца раунда.","","\"Это построение лежит в основе нашей тактики. Оно держится на вере каждого воина в собственный щит – и в щиты товарищей. Пока держится строй, стоит и наша держава\". – Гарен\n","Боец",[],["Демасия"],"ЭПИЧЕСКОЕ"],"01DE021":["Нескончаемая погоня","Рвение.",""," \"Каждый должен встретиться со своим страхом лицом к лицу. Ты можешь начать с меня\". – Люциан\n","Заклинание",[],["Демасия"],"ОБЫЧНОЕ"],"01DE025":["Арест","Союзник берет в плен бойца.","","\"Вы обязаны выполнять наши требования, ведь мы – представители закона вашего родного королевства. Это не обсуждается\". – Охотник на магов – увещеватель","Заклинание",[],["Демасия"],"ОБЫЧНОЕ"],"01DE007":["Правосудие","Союзник в бою наносит удар всем врагам в бою.","","Правосудие все расставит по своим местам.","Заклинание",[],["Демасия"],"ЭПИЧЕСКОЕ"],"01DE055":["Дуэлянт Лоранов","Разыгрывая карту: даруйте союзнику в руке Выбор противника.","","\"Сперва я посчитал его напыщенным фазаном с дорогим клинком – но оказалось, что он умеет им пользоваться! Я бы потребовал реванша, но из-за дурацкого акцента не разобрал его имени\". – Демасийский младший лейтенант","Боец",[],["Демасия"],"ОБЫЧНОЕ"],"01DE048":["Охотник на магов – подстрекатель","Впервые разыграв заклинание стоимостью 6+, даруйте мне +2|+2.","","\"Во время Рунических войн магию никто не контролировал, и она едва не погубила Рунтерру. Наш орден защищает Демасию от магии, уничтожая ее на своей и чужой территории\". – Из \"Практического руководства\" охотников на магов","Боец",[],["Демасия"],"РЕДКОЕ"],"01DE001":["Знаменосец Авангарда","Верность: даруйте другим союзникам +1|+1.","","\"Наше знамя имеет огромный смысл. Оно символизирует нашего короля, наши дома и самих демасийцев. Это знак веры в Демасию. Подними его повыше – покажи, что нам есть чем гордиться\". – Тианна Краунгард ","Боец",["ЭЛИТА"],["Демасия"],"РЕДКОЕ"],"01DE043":["Военные повара","Поддержка: до конца раунда дайте +1|+1 союзнику, которого я поддерживаю.","","Демасийская армия сильна не только бойцами.","Боец",[],["Демасия"],"ОБЫЧНОЕ"],"01DE049":["Удалой поро","","","\"Этот новобранец отвагой и выносливостью не уступает нашим лучшим воинам. Дослужится ли он до Авангарда? Ростом он подкачал, но все возможно\". – Сержант Авангарда","Боец",["ПОРО"],["Демасия"],"ОБЫЧНОЕ"],"01DE053":["Шевалье Лоранов","Удар: создайте в руке другого случайного сторонника из своих регионов с выбором противника.","","\"Ну началось...\" – Фиора","Боец",[],["Демасия"],"ЭПИЧЕСКОЕ"],"01DE033":["Почтение памяти","Моя стоимость снижается на 1 за каждого союзника, погибшего в этом раунде. Призовите случайно выбранного сторонника из Демасии стоимостью 5.","","\"Сегодня мы восстанем против несправедливости, погубившей наших предшественников. Жертвы наших соратников не напрасны!\" – Сияющая стражница","Заклинание",[],["Демасия"],"РЕДКОЕ"],"01DE044":["Прилив храбрости","Восстановите союзнику все единицы здоровья, а затем удвойте его силу и здоровье.","","Демасийский воин стоит двух вражеских бойцов! И это не просто слова.","Заклинание",[],["Демасия"],"РЕДКОЕ"],"01DE024":["Охотник на магов – хранитель","Предсмертный вздох: создайте в руке случайное заклинание стоимостью 6+ из любого региона, кроме Демасии.","","\"Магические предметы, безусловно, интригуют. Но в них заключена опасная сила, поэтому их следует передавать из рук доброхотов в руки специалистов\".\n– Из \"Практического руководства\" охотников на магов","Боец",[],["Демасия"],"ОБЫЧНОЕ"],"01DE004":["Среброкрыл Авангарда","Разыгрывая карту: призовите мою точную копию.","","Они стремительно обрушились с неба, словно неудержимые серебряные молнии. А потом исчезли так же быстро, как появились. ","Боец",["ЭЛИТА","ПТИЦА"],["Демасия"],"ОБЫЧНОЕ"],"01DE011":["Протеже Лоранов","","","\"ЧТО он сделал?! Я доверил ему бесценную прекрасно сбалансированную саблю работы Пьера де Гилларда! Он обещал, что будет использовать ее только на тренировках!\" – Оружейник Лоранов","Боец",[],["Демасия"],"ОБЫЧНОЕ"],"01DE047":["Преемственность","Призовите карту Воин Бесстрашного авангарда.","","В Бесстрашном авангарде новобранцам выдают доспехи их предшественников, которые полагается носить с гордостью и осознанием возложенной на солдат чести.","Заклинание",[],["Демасия"],"ОБЫЧНОЕ"],"01DE046":["Разведчик Авангарда","","","Тихо – не значит безопасно.","Боец",["ЭЛИТА"],["Демасия"],"ОБЫЧНОЕ"],"01DE050":["Зачистка","Наложите на сторонника Безмолвие.","","\"Петрицитовый греймарк – это наша защита от магии, символ нашей ответственности и полномочий. Его следует беречь как зеницу ока\".\n– Из \"Практического руководства\" охотников на магов","Заклинание",[],["Демасия"],"ОБЫЧНОЕ"],"01DE040":["Охотник на магов – увещеватель","Впервые разыграв заклинание стоимостью 6+, даруйте мне +1|+1 и Выбор противника.","","\"Жители Демасии, для меня большая честь защищать вас! Но без вашей безоговорочной поддержки нам не обойтись, ведь маги скрываются даже здесь, за высокими стенами нашей столицы\".\n","Боец",[],["Демасия"],"РЕДКОЕ"],"01DE036":["Оруженосец Авангарда","Моя стоимость снижается на 1, когда вы призываете элитного бойца.","","\"Каждое путешествие и каждый встречный чему-то меня научили. Но чем больше я узнавала, чем сильнее становилась, тем яснее понимала, как много еще предстоит пройти\". – Цитрия, оруженосец Авангарда\n","Боец",["ЭЛИТА"],["Демасия"],"ОБЫЧНОЕ"],"01DE037":["Парирование","Дайте союзнику +3|+0 и Щит до конца раунда.","","\"Ты дерешься, как поро. И почему меня это совсем не удивляет...\" – Фиора","Заклинание",[],["Демасия"],"РЕДКОЕ"],"01DE014":["Подкрепление","Призовите 2 Воинов Бесстрашного авангарда, а затем даруйте элитным союзникам +1|+1.","","\"Противники знают, что напасть на одного из нас – значит напасть на всех\".\n– Из кодекса Авангарда\n","Заклинание",[],["Демасия"],"РЕДКОЕ"],"01DE015":["Сияющая стражница","Призвав меня, даруйте мне Вампиризм и Стойкость, если в этом раунде погиб союзник.","","\"Ее товарищей увлекли на дно холодные руки нежити. Она осталась одна – сияющее воплощение правосудия. Клинок в ее руках на каждом взмахе пел имена погибших\". – Демасийский младший лейтенант","Боец",[],["Демасия"],"РЕДКОЕ"],"01DE003":["Оружейник Лоранов","Разыгрывая карту: даруйте союзнику +2|+2.","","\"Да, они прекрасны. Но, как и любой тонко настроенный инструмент, они раскрывают свою истинную красоту лишь в руках мастера\". ","Боец",[],["Демасия"],"РЕДКОЕ"],"01DE026":["Поединок","Союзник и враг наносят удар друг другу.","","\"Не нужно слов. Пусть говорят клинки\". – Фиора","Заклинание",[],["Демасия"],"ОБЫЧНОЕ"],"01DE032":["Призматический барьер","Дайте союзнику Щит до конца раунда.","","\"Если ты отличаешься от других, от тебя могут все отвернуться. Отличия считаются слабостью, но на самом деле они делают нас сильнее и добрее. Даже в самые темные времена я буду защищать тебя!\" – Люкс","Заклинание",[],["Демасия"],"ОБЫЧНОЕ"],"01DE027":["К бою!","Дайте союзникам Выбор противника до конца раунда.","","\"Вы не найдете демасийца, который отказался бы от урока фехтования с Лораном... Или выжил после него\".\n– Фиора","Заклинание",[],["Демасия"],"РЕДКОЕ"],"01DE006":["Сержант Авангарда","Когда меня призывают, создайте в руке карту За Демасию!","","\"Он с утра до ночи тренирует нас на плацу, а потом лично ведет в бой. Он тверд как сталь и надежен как камень. Лучшего командира и пожелать нельзя\". – Демасийский младший лейтенант","Боец",["ЭЛИТА"],["Демасия"],"РЕДКОЕ"],"01DE038":["Сенна, Страж света","Когда впервые погибает союзный Люциан, даруйте мне +1|+1 и Двойную атаку.","","\"Стражи – это главная линия обороны между миром людей и полчищами неупокоенных мертвецов. Мы наносим первый мощный удар и никогда не отступаем, если на кону жизни наших товарищей\".","Боец",[],["Демасия"],"РЕДКОЕ"],"01DE041":["Спина к спине","Дайте 2 союзникам +3|+3 до конца раунда.","","\"Я иду в атаку, прикрой меня!\"\n\"Забавно... Я собирался сказать то же самое!\"\n– Лорн и Дакс из Восточного батальона","Заклинание",[],["Демасия"],"РЕДКОЕ"],"01DE035":["За Демасию!","Дайте союзникам +3|+3 до конца раунда.","","\"Это наши дома, наши семьи, наши братья и сестры по оружию. Наша гордость, наша честь, наша сила. Сегодня мы сражаемся за нашу родину. Повторяйте же все за мной: ДЕМАСИЯ!\" – Сержант Авангарда","Заклинание",[],["Демасия"],"РЕДКОЕ"],"01DE018":["Световой удар","Дайте союзнику +1|+1 до конца раунда.","","\"Нежить так отчаянно бросается в каждый бой, будто он последний. Мы позаботимся о том, чтобы так оно и было\". – Люциан\n\n","Заклинание",[],["Демасия"],"ОБЫЧНОЕ"],"01DE009":["Стальная защитница","Разыгрывая карту: дайте союзнику Щит до конца раунда.","","\"Наша держава процветает, потому что жизнь каждого воина – это монета, которую мы не хотим тратить\".\n– Король Джарван III","Боец",[],["Демасия"],"ОБЫЧНОЕ"],"01DE039":["Цитрия из Клаудфилда","","","\"На ночь мама всегда рассказывала мне истории о величайших героях Демасии, пока сама точила меч, – и мне снились увлекательные приключения. А теперь я начну создавать собственную историю\".","Боец",["ЭЛИТА"],["Демасия"],"ОБЫЧНОЕ"],"01DE056":["Клинок Авангарда","Атака: даруйте мне +2|+2.","","\"Стоит мне услышать боевой клич, как ноги сами несут меня на поля боя. Я жду лишь приказа госпожи, чтобы исполнить ее волю и узнать свою судьбу\".","Боец",["ЭЛИТА"],["Демасия"],"ОБЫЧНОЕ"],"01DE029":["Легкокрылый охотник","Призывая союзника, даруйте мне Выбор противника.","","Охотничий инстинкт у этих созданий развит не хуже, чем у их родственников-остроклювов, причем свой малый размер они упорно отказываются осознавать.","Боец",["ПТИЦА"],["Демасия"],"ОБЫЧНОЕ"],"01DE028":["Конница Авангарда","","","Авангарду не нужны барабаны, чтобы задавать ритм марша. Достаточно мерного стука копыт.","Боец",["ЭЛИТА"],["Демасия"],"ОБЫЧНОЕ"],"01DE013":["Кольчуга","Даруйте союзнику Стойкость.","","Демасийская сталь известна во всем мире благодаря непревзойденной прочности. Для работы с ней привлекают только истинных мастеров кузнечного дела.","Заклинание",[],["Демасия"],"ОБЫЧНОЕ"],"01DE023":["Охотница на магов – дознаватель","Впервые разыграв заклинание стоимостью 6+, создайте в руке карту Арест.","","\"Простите за вторжение. Нам стало известно о неких странных происшествиях в вашем доме. В ваших интересах с нами сотрудничать…\"","Боец",[],["Демасия"],"ОБЫЧНОЕ"],"01DE051":["Цитрия Отважная","Атака: дайте другим атакующим союзникам +1|+1 и Устрашение до конца раунда.","","\"Я никогда не считала легенды и предания вымыслом. Это приключения, которые манят меня в путь. Я ушла из Клаудфилда на поиски собственных приключений – и нашла их. И это только начало!\"\n","Боец",["ЭЛИТА"],["Демасия"],"ЭПИЧЕСКОЕ"],"01DE054":["Воительница Авангарда","Призвав меня, вытяните карту бойца, если в этом раунде погиб союзник.","","\"Мы будем чтить павших каждым боевым кличем, каждым взмахом меча, каждым принятым на щит ударом. Сегодня мы победим!\"","Боец",["ЭЛИТА"],["Демасия"],"ОБЫЧНОЕ"],"01DE030":["Пикирующий среброкрыл","","","Стрелы тучами летели с крепостных стен, но ни одна не достала сновавшую по небу серебряную искру. ","Боец",["ПТИЦА"],["Демасия"],"ОБЫЧНОЕ"],"01PZ040":["Джинкс","","Я вижу, что у вас в руке закончились карты.","\"В чем дело, Скелетница?\"\n\"Я за тебя волнуюсь, Джинкс! Когда тебе становится скучно, ты…\"\n\"…хочешь что-нибудь взорвать! Отличная идея, Скелетница!\"","Боец",[],["Пилтовер и Заун"],"Чемпион"],"01PZ008":["Тимо","Удар по нексусу: прикрепите 5 Ядовитых грибов к случайным картам в колоде противника.","Вы поместили в колоду 15+ Ядовитых грибов.","\"Правило бандлскаута №154: не бояться неизвестного. Правило №276: лесные жители – наши друзья. Правило №354: пушистых можно гладить, но нельзя есть. Правило №417…\"","Боец",["ЙОРДЛ"],["Бандл Сити","Пилтовер и Заун"],"Чемпион"],"01PZ056":["Хеймердингер","Разыграв заклинание, создайте в руке мимолетную турель такой же стоимости. Теперь ее стоимость равна 0.","На моих глазах вы призвали союзной техники в сумме на 12+ ед. силы.","\"Сумасшедший ученый? Чушь! У меня все дома, я просто чуточку неорганизован и слегка эксцентричен\".","Боец",["ЙОРДЛ"],["Бандл Сити","Пилтовер и Заун"],"Чемпион"],"01PZ013":["Улучшенный экспериментатор","Разыгрывая карту: сбросьте все карты из руки. Вытяните 3 карты. Нанесите врагу 3 ед. урона.","","Смелые мечты стоили ему обеих рук, но его это не остановило. Невероятное упорство!","Боец",[],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"01PZ007":["Праздничное приспособление","Поддержка: создайте в колоде 4 копии союзника, которого я поддерживаю.","","Заслышав грохот пушек, люди толпами поспешили на площадь, чтобы увидеть представление. А потом месяц вытряхивали из волос конфетти!","Боец",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"01PZ018":["Юное дарование","","","Как она прицеливается? Хороший вопрос!","Боец",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"01PZ019":["Нетерпеливый ученик","Призвав меня, восполните 2 ед. маны заклинаний.","","Не всем пилтоверцам дано сразу совершать научные открытия. Некоторых нужно подтолкнуть в правильную сторону, если они, к примеру, смотрят на науку под неправильным углом.","Боец",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"01PZ025":["Торговец грибами","Разыграв заклинание, прикрепите 3 Ядовитых гриба в колоде противника.","","\"Хороши грибочки?\"\n\"Конечно! Самые лучшие! Я с каждым лично беседовал!\"\n\"Ну ладно, взвесь мне… Погоди, что ты сказал?\"\n\"Да-да. Вот этот скоро женится…\"\n\"Сколько ты их съел?\"\n\"…на ракушке!\"","Боец",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"01PZ048":["Корина Вераза","Разыгрывая карту: уничтожьте 5 верхних карт своей колоды, а затем нанесите всем врагам и вражескому нексусу 1 ед. урона за каждое уничтоженное заклинание.","","\"Пилтоверцы помешались на своих болтах и шестеренках и уже не в состоянии увидеть красоту каждого лепестка, каждого стебелька в моей теплице. Они недостойны изящной смерти, которую я для них готовлю\".","Боец",[],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"01PZ028":["Шараш-монтаж","Сбросив или разыграв это заклинание, призовите бойца Утильный выползень.","","У юной изобретательницы оставались считанные секунды и горстка случайных деталей. И тут ее осенило! Она вспомнила существо, семенившее по берегу реки в далеких джунглях.","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"01PZ050":["Переполняющая магия","Дайте союзнику +4|+0 и Быструю атаку до конца раунда.","","\"Она щекочет руку, когда начинает светиться. Так и должно быть, да?\" – Эзреаль","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"01PZ054":["Новичок из взрывотряда","Атака: нанесите 2 ед. урона вражескому нексусу.","","\"Ты уверен, что все получится?\"\n\"Нет\".\n\"Я думала, ты скажешь \"да\"!\n\"Тогда лучше вообще не спрашивай\".","Боец",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"01PZ030":["Подозрительная личность","Разыгрывая карту: выберите сторонника. Превратите меня в его точную копию.","","\"Приветствую, коллеги-химбароны!\"","Боец",["ЙОРДЛ"],["Пилтовер и Заун"],"РЕДКОЕ"],"01PZ017":["Продавец старых капсул","Призвав меня, призовите 2 Капсулы с кислотой.","","\"Ты от Зиеля? Я ж ему сказал: мне чужого не надо. Но как я могу вернуть деньги за то, чего в глаза не видел? Правда, я получил новую партию бочек, с которой готов расстаться, если хорошо попросишь…\"","Боец",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"01PZ038":["Копатель Сточных ям","Разыгрывая карту: сбросьте 1 карту, чтобы вытянуть 1.","","В Сточных ямах ничего не пропадает зря.","Боец",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"01PZ036":["Эзреаль","Удар по нексусу: создайте в руке мимолетную карту Мистический выстрел.","Вы 8+ раз выбрали целью врагов.","\"Летные очки? Есть. Шарф? Есть. Потрясная магическая перчатка, принцип работы которой я совершенно точно понимаю? Все есть!\"","Боец",[],["Пилтовер и Заун"],"Чемпион"],"01PZ035":["Джей Медарда","Когда я становлюсь целью, вытяните 1 карту.","","Джей, наследник влиятельного пилтоверского клана Медарда, очень расстраивал отца тем, что вместо управления семейным бизнесом предпочитал гоняться за древними артефактами.","Боец",[],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"01PZ010":["Грибное облако","Прикрепите 5 Ядовитых грибов в колоде противника.","","Сначала – тихий хлопок взорвавшейся шляпки. Потом – обжигающая боль, от которой немеет тело. И наконец – чье-то отдаленное хихиканье.","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"01PZ045":["Заунская оборванка","Разыгрывая карту: сбросьте 1 карту, чтобы вытянуть 1.","","\"Я думал, помойные крысы своим помогают\".\n\"У них каждый только о себе заботится, братишка\".\n\"Да уж... Слушай, ты не видел мой кошелек?\"","Боец",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"01PZ002":["Хозяин злачного местечка","Призвав меня, создайте в руке случайную карту за каждый раз, когда призывали карту Хозяин злачного местечка в этой игре.","","\"Да, приятель, хмель у нас слабый – прямо как запашок над Сточными ямами, ха-ха. Ведро вон там, рядом с трубадуром\".","Боец",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"01PZ004":["Прицельный залп","Нанесите 3 ед. урона вражескому бойцу или нексусу, 2 ед. урона другому бойцу и 1 ед. урона третьему.","","\"Я не удачливый, я умелый\". – Эзреаль","Заклинание",[],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"01PZ020":["Отважная поро","","","Первый полет она совершила случайно: в день Прогресса, прихорашиваясь, упала в пушку для салюта. Теперь она вновь и вновь взмывает в небо под радостное аханье толпы.","Боец",["ПОРО"],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"01PZ046":["Подделки","Создайте в своей колоде 4 точные копии карты, которая есть у вас в руке.","","Подражание – самый честный вид воровства.","Заклинание",[],["Пилтовер и Заун"],"РЕДКОЕ"],"01PZ052":["Мистический выстрел","Нанесите 2 ед. урона любой цели.","","\"Я никогда не промахиваюсь. Просто иногда делаю предупредительные выстрелы\". – Эзреаль","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"01PZ033":["Преследование совершенства","Если в этом матче вы сыграли 20 новых карт, призовите карту Котострофа.","","\"Все, кто воплощал в жизнь задумку фон Иппа, оказались обмануты. Мы не ведали, что творили, какую страшную мощь выпустили на свободу\". – Пилтоверский инженер","Заклинание",[],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"01PZ005":["Хекстековый преобразователь","Превратите одного сторонника в точную копию другого.","","\"Ты все ныла, что хочешь сбросить вес!\"\n\"И ты превратил меня в йордла?!\"\n\"Теперь ты весишь меньше!\"\n\"А ЕЩЕ Я ЙОРДЛ!\"","Заклинание",[],["Пилтовер и Заун"],"РЕДКОЕ"],"01PZ021":["Приспешники Миденстокка","Удар по нексусу: призовите мою точную копию.","","\"Господин Берц, мы нашли вас спящим в хранилище под золотыми шестеренками, в обнимку со сломанной дверью сейфа\".\n\"Это был мой брат-близнец\".\n\"Вы все еще держите дверь\".\n\"Вы ничего не докажете!\"","Боец",[],["Пилтовер и Заун"],"РЕДКОЕ"],"01PZ031":["Разряд Статикка","Нанесите 1 ед. урона вражескому бойцу или нексусу и 1 ед. урона другому бойцу.\nВытяните 1 карту.","","\"Вот так мы и открыли дуговой разряд! Не буду отрицать, это мой предшественник создал модель... правда бедняга не просчитал длину дуги разряда\". – Хеймердингер","Заклинание",[],["Пилтовер и Заун"],"РЕДКОЕ"],"01PZ059":["Золотой бот-крушитель","","","УБИТЬ. СОКРУШИТЬ. УНИЧТОЖИТЬ. ПОВТОРИТЬ.","Боец",["ТЕХНИКА"],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"01PZ001":["Поиски полезного","Чтобы сыграть, сбросьте до 2 карт. Вытяните 1 карту за каждую сброшенную.","","\"Ого! ПЯТЬ БУГАЕВ И ГОЛЕМ? Погодите, у меня где-то была подходящая штука. Щас найду...\" – Джинкс","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"01PZ057":["Монтаж-кураж","Призовите 2 Утильных выползня.","","Два хрупких создания, некогда разделенных полоской суши, наконец нашли друг друга в теплой воде Сточных ям.","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"01PZ027":["Термогенный луч","Чтобы сыграть эту карту, потратьте всю ману.\nНанесите бойцу столько же урона.","","\"Луч работает, но время и ресурсы у нас закончились раньше, чем мы смогли отладить потребление энергии\". – Заунский экспериментатор","Заклинание",[],["Пилтовер и Заун"],"РЕДКОЕ"],"01PZ055":["Сообразительная ученая","Вытянув карту, дайте мне +1|+0 до конца раунда.","","Великие изобретения появляются благодаря искре воображения. Но чтобы разжечь из нее костер, нужно провести научную работу.","Боец",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"01PZ014":["Незарегистрированное изобретение","Призовите карту Незаконное устройство.","","\"Их промашки оборачиваются то дрожью далеких взрывов, то едкими выхлопами из трещин. В один прекрасный день эти идиоты подорвут весь город!\" – Пилтоверский филантроп","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"01PZ034":["Щипач-добытчик","Верность: создайте в руке карту Карта щипачей. В этом раунде ее стоимость равна 0.","","Вскоре заунские оборванцы начали лазить по старым шахтам и тоннелям под Линиями. Они открыли для себя новый мир и нашли новых друзей.","Боец",[],["Пилтовер и Заун"],"РЕДКОЕ"],"01PZ003":["Бот-сборщик","Разыграв заклинание, даруйте мне +1|+1.","","\"Собрать механизм может любой дурак, но чтобы подарить механическому разуму способность к развитию, нужна незаурядная острота ума! Скоро проклятые бюрократы приползут ко мне на коленях…\" – Клаус Хенвик","Боец",[],["Пилтовер и Заун"],"РЕДКОЕ"],"01PZ044":["Химпанк-гитарист","Разыгрывая карту: нанесите 1 ед. урона всем врагам.","","\"…Его соло быстро уходит в гармоническую минорную гамму, а затем арпеджирует – да, это так называется – перед интерлюдией. Вам не понять его произведений\". – Макс Блифф, привратник","Боец",[],["Пилтовер и Заун"],"РЕДКОЕ"],"01PZ029":["Известный меценат","Разыгрывая карту: воплотите эпическую карту из ваших регионов.","","\"Я был человеком жестоким и ломал конкурентов в погоне за богатством и славой. Теперь я трачу накопленные средства на добрые дела и надеюсь, что покаяние на закате дней искупит ошибки юности\".","Боец",[],["Пилтовер и Заун"],"РЕДКОЕ"],"01PZ051":["Оружейница-затейница","Все ваши заклинания и способности наносят на 1 ед. урона больше.","","\"Хочешь, чтобы жахнуло посильнее? Тогда ты по адресу!\"","Боец",[],["Пилтовер и Заун"],"РЕДКОЕ"],"01PZ023":["Профессор фон Ипп","Призвав союзника стоимостью 1, даруйте ему +2|+2.","","\"Сегодня я представляю комиссии мое новейшее изобретение, которое только что любезно продемонстрировал мой коллега…\"","Боец",["КОШКА"],["Пилтовер и Заун"],"РЕДКОЕ"],"01PZ024":["Самоделкин","Впервые разыграв заклинание стоимостью 6+, даруйте мне +4|+0 и Быструю атаку.","","Имя: Клаус Хенвик. Возраст: 51 год. Тип лицензии: временная. Статус: отозвана. Примечания: злостно игнорировал требования снизить активность после взрыва лаборатории (дело 13X764NM). НЕ ВПУСКАТЬ.","Боец",[],["Пилтовер и Заун"],"РЕДКОЕ"],"01PZ049":["День Прогресса!","Вытяните 3 карты и уменьшите стоимость каждой на 1.","","ДЕНЬ ПРОГРЕССА!\nПразднуйте на площади у Врат Солнца!\nУзрите ЧУДЕСА ХЕКСТЕКА!\nПосмотрите на ОТВАЖНУЮ ПОРО!\nПослушайте, что ЧЕЛОВЕК БУДУЩЕГО скажет о НАСТОЯЩЕМ!\nВход СВОБОДНЫЙ! \nПриглашаем пилтоверских детей!","Заклинание",[],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"01PZ006":["Страж площади","Моя стоимость снижается на 1 за каждое заклинание, разыгранное вами в этом матче.","","У вас двадцать секунд на то, чтобы сдаться.","Боец",[],["Пилтовер и Заун"],"РЕДКОЕ"],"01PZ053":["Свора вумпов","Когда меня призывают, создайте в руке карту Грибное облако.","","\"Вот именно! Шастают целыми бандами. Они только кажутся безумными, а на самом деле у них большие планы! Громадные! Сыр… щербет… Хм... на чем я остановился?\" – Торговец грибами","Боец",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"01PZ012":["Огненные кусаки!","Когда я попадаю в сброс, призовите меня.","","\"ФАС, КУСАКИ!\" – Джинкс","Боец",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"01PZ039":["Бодрячком!","Чтобы сыграть, сбросьте 1 карту.\nНанесите 3 ед. урона любой цели.","","\"ЛОЖИ-И-ИСЬ!\" – Джинкс","Заклинание",[],["Пилтовер и Заун"],"РЕДКОЕ"],"01PZ016":["Озарение","Создайте в руке случайное заклинание стоимостью 6+ из своих регионов.\nВосполните свою ману заклинаний.","","Чтобы войти в историю, достаточно одного озарения.","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"01PZ058":["Большая вумпа","Когда меня призывают, создайте в руке 2 Грибных облака.","","\"Я такую вумпу видел! Тяжелая, как лошадь, и хитрая, как краг. С ней надо держать ухо востро! Она не за красивые глазки стала царицей!\" – Торговец грибами","Боец",["ЙОРДЛ"],["Пилтовер и Заун"],"РЕДКОЕ"],"01PZ009":["Воздухоплаватель-любитель","","","\"Персональные летательные аппараты? Что за дикий бред? Я только что заставил подмастерье выбросить последний прототип такого устройства. Кстати, куда подевался этот мальчишка?\" – Пилтоверский инженер","Боец",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"01PZ042":["Бесстрашная морячка","Поддержка: до конца раунда дайте Изворотливость союзнику, которого я поддерживаю.","","Большинство пилтоверцев исследуют непознанное научными методами в своих уютных лабораториях в Городе прогресса. Лишь единицы покидают городские стены – и предметом их исследований становится весь мир.","Боец",[],["Пилтовер и Заун"],"РЕДКОЕ"],"01PZ026":["Карта щипачей","Даруйте союзнику Изворотливость.","","\"Пилтошки думают, что все знают, но на картах у них только те места, о которых мы им рассказали. То ли дело – местные. Все покажут… но не бесплатно\". – Аджуна Лем, щипач-добытчик","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"01PZ043":["Химпанк-карманник","Удар по нексусу: создайте в руке точную копию случайного заклинания из вражеской колоды.","","Пилтоверцы думали, что изгнанные из Города прогресса перегрызутся между собой. Но они сплотились и построили себе новый дом. Не шикарный, зато свой собственный: Заун.","Боец",[],["Пилтовер и Заун"],"РЕДКОЕ"],"01PZ047":["Капсула с кислотой","Предсмертный вздох: нанесите 1 ед. урона ОБОИМ нексусам.","","\"Можешь надеть комбинезон, но внизу душно, как у вумпа под мышкой. А вот перчатки нужны. Если на тебя все-таки брызнет – молись, чтоб это была не особо нужная часть тела\". – Зил, заунский бригадир","Боец",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"01FR024":["Анивия","Атака: нанесите 1 ед. урона всем врагам и вражескому нексусу.\nПредсмертный вздох: я возрождаюсь как Яйценивия.","Вы достигли Просветления.","\"Я родилась в этом суровом краю и обязана его беречь. В этом мне не помешают ни время, ни войны, ни даже сама смерть\".","Боец",["ПТИЦА"],["Фрельйорд"],"Чемпион"],"01FR039":["Триндамир","","Вместо того чтобы погибнуть, я повышаю уровень.","\"Не умирай за свое дело. Живи за него!\"","Боец",[],["Фрельйорд"],"Чемпион"],"01FR006":["Наследие Хладорожденных","Даруйте союзнику и всем его союзным копиям везде +2|+2.","","\"Хладорожденных мало, но в наших жилах течет магия Фрельйорда. Наши предки заточили во льдах древнее зло, и мы должны следить, чтобы оно не вырвалось на волю\". – Страж Грегор","Заклинание",[],["Фрельйорд"],"ОБЫЧНОЕ"],"01FR022":["Сокол знамения","Призвав меня, даруйте двум верхним бойцам в вашей колоде +1|+1.","","\"Наши разбойники трижды добирались до ворот аваросан, но каждый раз их встречали с луками наготове. Какая ворожба помогает им предвидеть наши атаки?\"\n– Стеффен, вождь шрамов","Боец",["ПТИЦА"],["Фрельйорд"],"ОБЫЧНОЕ"],"01FR042":["Холодные ветра","Заморозьте 2 врагов.","","\"Бросаешь мне вызов на моих же землях? Плохая идея, малявка\". – Анивия","Заклинание",["СТИХИЯ"],["Фрельйорд"],"РЕДКОЕ"],"01FR009":["Браум","Когда я впервые получаю урон и выживаю, призовите карту Могучий поро.","Мне удалось выжить, получив 10+ ед. урона.","\"Папа, а расскажи про Браума и его дверь!\"\n\"Или про то, как он упал и расколол гору!\"\n\"Или как спас таверну от разъяренного йети!\"","Боец",[],["Фрельйорд"],"Чемпион"],"01FR018":["Снежнозубый волк","Удар: если я наношу удар по бойцу с силой 0, он умирает.","","Хищники крайнего севера давно поняли, что самая легкая добыча – та, что уже пострадала от суровой зимы.","Боец",["ПЕС"],["Фрельйорд"],"РЕДКОЕ"],"01FR036":["Стрелок племени аваросан","Разыгрывая карту: нанесите врагу 1 ед. урона.","","\"Во Фрельйорде ты или охотишься, или умираешь с голоду\".","Боец",[],["Фрельйорд"],"ОБЫЧНОЕ"],"01FR045":["Стеффен, вождь шрамов","Когда я выживаю, получив урон, даруйте мне +3|+0.","","\"Самый первый шрам мне подарила Седжуани: так я скрепил клятву верности Когтю Зимы. Все остальные шрамы я получил, служа ей\".","Боец",[],["Фрельйорд"],"ОБЫЧНОЕ"],"01FR008":["Одинокий поро","Призвав меня, создайте в руке другого случайного поро стоимостью 1.","","\"Я всю жизнь прожил во Фрельйорде, но при виде этого несчастного малыша меня впервые пробрал холод\".\n– Пастух поро","Боец",["ПОРО"],["Фрельйорд"],"ОБЫЧНОЕ"],"01FR055":["Разбивание","Нанесите врагу 4 ед. урона, если его сила равна 0. В противном случае заморозьте его.","","\"Когда приходит зима, сильные склоняются перед ней, а слабые падают ниц\". – Стеффен, вождь шрамов","Заклинание",["СТИХИЯ"],["Фрельйорд"],"ОБЫЧНОЕ"],"01FR038":["Эш","Атака: заморозьте сильнейшего врага.","Вы снизили силу 5+ противников до 0. Когда мой уровень повышается, создайте карту Ледяная стрела на верху колоды.","\"Окидывая взглядом родной край, я вижу, каков он сейчас и каким мог бы стать. Достаток и процветание не только для моего народа, но и для всех, кто придет с миром. Объединенный Фрельйорд\".","Боец",[],["Фрельйорд"],"Чемпион"],"01FR029":["Призыв","Вытяните карту чемпиона.","","\"Разбойники приближаются! Зажигайте костры, трубите общий сбор! Нам нужна каждая пара рук!\" – Стражник племени аваросан","Заклинание",[],["Фрельйорд"],"РЕДКОЕ"],"01FR035":["Разбойница без шрамов","Когда я выживаю, получив урон, даруйте мне +3|+0.","","\"В племени аваросан детей балуют, так что те растут слабыми и не подготовленными к бою. Наши же дети рождаются в огне войны\". – Вринна, мать шрамов\n","Боец",[],["Фрельйорд"],"ОБЫЧНОЕ"],"01FR020":["Лавина","Нанесите 2 ед. урона ВСЕМ бойцам.","","В сердце каждой лавины – один маленький камешек, которому не сиделось на месте.","Заклинание",["СТИХИЯ"],["Фрельйорд"],"РЕДКОЕ"],"01FR014":["Годовалый йети","Предсмертный вздох: создайте в колоде 2 Разгневанных йети.","","\"Он был таким маленьким и безобидным! Поверить не могу, что из него вырос такой… йети\". – Зверолов из племени аваросан","Боец",["ЙЕТИ"],["Фрельйорд"],"ОБЫЧНОЕ"],"01FR049":["Крадущийся волк","Когда меня призывают, ваш противник призывает карту Снежный заяц.","","\"Зайцу никогда не стать волком\".\n– Поговорка племени Коготь Зимы","Боец",["ПЕС"],["Фрельйорд"],"ОБЫЧНОЕ"],"01FR037":["Всадники племени аваросан","Верность: даруйте верхнему союзнику в своей колоде +3|+3 и Пробивание.","","\"Когда на гребне холма показалось подкрепление, всадники склонили головы перед ратной матерью. Она – воплощенная Авароса, королева Эш – несла обещание мира\".","Боец",[],["Фрельйорд"],"РЕДКОЕ"],"01FR026":["Когтерысь-альфа","","","Сила боевой лошади и жестокость дикой кошки.","Боец",["КОШКА"],["Фрельйорд"],"ОБЫЧНОЕ"],"01FR030":["Хрупкая сталь","Заморозьте врага с 3 и менее ед. здоровья.","","\"Холодно? Надеюсь, характер у вас крепче, чем ваши летние клинки!\" – Браум","Заклинание",["СТИХИЯ"],["Фрельйорд"],"ОБЫЧНОЕ"],"01FR013":["Вринна, мать шрамов","Когда я выживаю, получив урон, даруйте мне +3|+0.","","\"Я лучше умру, дрожа от холода, чем разделю очаг с заморышами Эш. Но если они хотят огонька, я им это устрою!\"","Боец",[],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"01FR019":["Дыхание зимы","Убейте всех врагов с силой 0, а затем заморозьте всех оставшихся врагов.","","Первый и последний враг, с которым сражаются горе-завоеватели Фрельйорда – это ратная мать Зима. Ее кровные воины – жестокие ветра и морозы.","Заклинание",["СТИХИЯ"],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"01FR041":["Дозорный племени аваросан ","Призвав меня, даруйте союзникам в вашей колоде +1|+1.","","\"Столько племен под одним стягом! Быть может, в один прекрасный день Фрельйорд объединится\".","Боец",[],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"01FR025":["Пастух поро","Призвав меня, вытяните поро, если владеете поро.","","\"Стаду нужны только любовь и внимание. Все остальное – приятное дополнение\".\n","Боец",[],["Фрельйорд"],"РЕДКОЕ"],"01FR054":["Разбойница со шрамами","","","\"Слабые пожинают, сильные забирают. Эти недомерки из племени аваросан скоро узнают, к кому относятся\".","Боец",[],["Фрельйорд"],"РЕДКОЕ"],"01FR021":["Тарказ Бесплеменный","Атака: нанесите 1 ед. урона ВСЕМ бойцам в бою.","","\"Тарказ дрался лучше и яростнее многих и, как мне казалось, умел принимать поражение. По большей части…\" – Триндамир","Боец",[],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"01FR043":["Сердце фляфа","Разыгрывая карту: ваши сторонники-поро объединяются в Фляф поро, а их характеристики и полезные навыки суммируются и даруются.","","\"Ладно, еще одна сказка – но только тихо, а то мама услышит!\nОднажды разбойники напали на поселок Аваросы. Воинов у нее было мало, и казалось, что все потеряно. Но вдруг появился поро и пообещал помочь Аваросе…\"","Боец",["ПОРО"],["Фрельйорд"],"РЕДКОЕ"],"01FR033":["Камни преображения","Начало раунда: получите дополнительный кристалл маны в этом раунде.","","\"Древние курганы напоминают о том, сколько племен покоряло эти земли задолго до нас\". – Эш","Боец",[],["Фрельйорд"],"ОБЫЧНОЕ"],"01FR011":["Лучник ледяной долины","Разыгрывая карту: заморозьте врага.","","Племя аваросан гордится тем, что выживает в морозы на ледяных пустошах. А их зоркие защитники заходят еще дальше. ","Боец",[],["Фрельйорд"],"ОБЫЧНОЕ"],"01FR050":["Добрый трактирщик","Разыгрывая карту: восстановите союзнику или своему нексусу 3 ед. здоровья.","","\"Этот старинный трактир называется \"Пьяная Сова\". Скорее проходите внутрь и согрейтесь тем, что тут подают и наливают!\"","Боец",[],["Фрельйорд"],"ОБЫЧНОЕ"],"01FR052":["Блуждающая","Разыгрывая карту: уничтожьте ВСЕХ бойцов с силой не более 4 в руках и на поле.","","\"Когда я выбрался из-под обломков, земля вокруг была обезображена шрамами. От моих соратников осталась лишь горстка дымящегося праха, а вдалеке двигался грозный силуэт…\" – Бьорг Скиталец","Боец",[],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"01FR016":["Поро-снэк","Даруйте союзным поро везде +1|+1.","","\"Они глотают их не жуя, а потом смотрят на тебя, вывалив языки, – довольные, как элнуки после стрижки. Попробуй откажи, когда такие милахи просят еще!\"\n– Изготовитель лакомств из племени аваросан","Заклинание",[],["Фрельйорд"],"ОБЫЧНОЕ"],"01FR005":["Боевой раж","Даруйте союзнику +8|+4.","","\"Мне часто говорят, что у меня... сложный характер\". – Триндамир","Заклинание",[],["Фрельйорд"],"РЕДКОЕ"],"01FR023":["Призыв ратной матери","Призовите верхнего союзника из своей колоды сейчас и в начале каждого раунда.","","\"Наступит день, когда по Фрельйорду разнесется клич, означающий, что наши древние враги воспряли ото сна. И тогда все откликнутся на него, как один\".","Заклинание",[],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"01FR047":["Одичавший маг","Просветление: у меня +4|+4.","","\"Научившись реветь по-звериному, ты скоро забудешь родной язык\". – Анивия","Боец",[],["Фрельйорд"],"ОБЫЧНОЕ"],"01FR056":["Ледяной йети","Призвав меня, заморозьте врагов с 3 и менее ед. здоровья.","","\"А-а-а! А-а-а-а-а!\" – Бьорг Скиталец","Боец",["ЙЕТИ"],["Фрельйорд"],"РЕДКОЕ"],"01FR027":["Самец элнука","","","У племени аваросан есть сказки о Дядюшке Элнуке – старом ворчуне, который только и любил, что подремать на свежей травке и упереться рогом в каком-нибудь споре. ","Боец",["ЭЛНУК"],["Фрельйорд"],"ОБЫЧНОЕ"],"01FR057":["Стайное поведение","Дайте союзникам +2|+2 и Пробивание до конца раунда.","","\"Сначала мы услышали одного волка – но ему откликнулся один, потом второй, и вскоре кровожадно выла уже вся стая\".","Заклинание",[],["Фрельйорд"],"РЕДКОЕ"],"01FR004":["Эликсир стали","Дайте союзнику +0|+2 до конца раунда.","","\"В горле пересохло? Этому горю легко помочь. Старина Филин принесет тебе особую брагу – такую крепкую, что и холод из костей выгонит, и из юнца мужика сделает\". – Добрый трактирщик","Заклинание",[],["Фрельйорд"],"ОБЫЧНОЕ"],"01FR048":["Зверолов племени аваросан","Призвав меня, создайте карту Разгневанный йети среди верхних трех в колоде.","","\"За всю неделю никого не поймал! То ли зверь пошел хитрый, то ли что-то его отпугивает…\"","Боец",[],["Фрельйорд"],"ОБЫЧНОЕ"],"01FR017":["Стадо элнуков","Разыгрывая карту: просмотрите 6 верхних карт своей колоды, призовите каждого элнука, а остальные карты поместите в колоду.","","\"Воины племени аваросан похожи на элнуков: тупоголовые травоядные, которых легко одолеет даже воин без единого шрама. Они до сих пор живы только потому, что их много\". – Вринна, мать шрамов","Боец",["ЭЛНУК"],["Фрельйорд"],"ОБЫЧНОЕ"],"01FR046":["Воодушевление","Даруйте раненому союзнику +3|+3.","","\"…Хотя Браум был тяжело ранен, он запрокинул голову и расхохотался. Он знал, что именно в трудные времена люди становятся героями\".\n– Легенда о Брауме","Заклинание",[],["Фрельйорд"],"РЕДКОЕ"],"01FR012":["Катализатор эонов","Получите пустой кристалл маны и восстановите нексусу 3 ед. здоровья.","","Все рубины и сапфиры этого мира блекнут по сравнению с эонитом – легендарным драгоценным камнем с восстанавливающими свойствами.","Заклинание",[],["Фрельйорд"],"ОБЫЧНОЕ"],"01FR040":["Шаманка снежных бивней","Начало раунда: заморозьте сильнейшего врага.","","\"Чтобы почувствовать родство с дикой природой, нужно не бежать от холода, а радоваться его свирепости\".","Боец",[],["Фрельйорд"],"РЕДКОЕ"],"01FR031":["Древний йети","Конец раунда: моя стоимость уменьшается на 1.","","\"Что это было? Кто-то чихнул? Разве ледники... чихают?\" – Бьорг Скиталец\n","Боец",["ЙЕТИ"],["Фрельйорд"],"РЕДКОЕ"],"01FR053":["Могучий поро","","","\"Старина длиннорог лишился глаза, защищая самого короля поро от злобной когтерыси. В конце концов размер молота не имеет особого значения: важно, насколько храброе у тебя сердце\". – Пастух поро\n","Боец",["ПОРО"],["Фрельйорд"],"ОБЫЧНОЕ"],"01FR010":["Клятва кровного воина","Даруйте 2 союзникам +0|+3.","","\"Я стану факелом в твоем сердце, щитом в твоей руке. Позволь мне обрести силу, чтобы защищать нас и наших родных. Пусть наши жизни сольются, как капли крови, скрепляющие эту клятву\". – Триндамир","Заклинание",[],["Фрельйорд"],"РЕДКОЕ"],"01FR001":["Мгновенная заморозка","Заморозьте врага.","","Холод настигает без предупреждения, лишая сил даже самых сильных воинов.","Заклинание",["СТИХИЯ"],["Фрельйорд"],"РЕДКОЕ"],"01FR032":["Звездный оракул","Разыграв заклинание, даруйте верхнему союзнику в вашей колоде +1|+1.","","\"Даруй им острый слух, чтобы слышать приближение ветров, быстрые ноги, чтобы пройти по свежему снегу, и острое зрение, чтобы видеть сквозь пелену зимы\".","Боец",[],["Фрельйорд"],"РЕДКОЕ"],"01FR051":["Басни","Если у вас есть йети, призовите карту Разгневанный йети. В противном случае создайте ее на самом верху своей колоды.","","\"…Вся пасть усажена громадными кривыми клыками, кулаки здоровенные, глаза злющие, а от рыка деревья трясутся! Так мне рассказывал дядюшка Бьорг…\" – Ингвар младшая","Заклинание",[],["Фрельйорд"],"ОБЫЧНОЕ"],"01FR034":["Выжидающие","Призвав меня, даруйте мне +1|+1 за каждого уже погибшего союзника.","","\"Жизнь потрепала старого Бьорга. Он потерял команду на севере и вернулся много месяцев спустя, бормоча что-то об \"огромных чудищах\" и \"длинных когтях\". Вот бедолага!\" – Добрый трактирщик","Боец",[],["Фрельйорд"],"РЕДКОЕ"],"01FR007":["Бормочущий Бьорг","Призвав меня, вытяните карту бойца с силой 5+.","","\"Вы мне не верите? Он был огромный, просто огромный!\"","Боец",[],["Фрельйорд"],"ОБЫЧНОЕ"],"01FR003":["Стражник племени аваросан","Предсмертный вздох: вытяните 1 карту.","","\"Когда-то я рвался на поля далеких сражений, а теперь мое место – рядом с домом и родными. Я охраняю их покой, берегу их от опасности\".","Боец",[],["Фрельйорд"],"ОБЫЧНОЕ"],"01SI038":["Призрачная шутница","Когда погибнет другой союзник, нанесите 1 ед. урона вражескому нексусу.","","Перебить солдат, поспешивших на плач маленькой девочки, было жестоко. Но еще бесчеловечнее было заронить сомнение в сердца выживших – вернувшись, они уже не внимали мольбам собственных дочерей.","Боец",[],["Сумрачные острова"],"РЕДКОЕ"],"01SI049":["Нечто за гранью","Убейте союзника, чтобы вытянуть 2 карты.","","\"Я заблуждался. Нам не следовало заглядывать за бледную пелену. Слишком дорого обходятся откровения, лежащие по ту сторону!\" – Ари Ренс, Поборник справедливости","Заклинание",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"01SI053":["Элиза","Атака: призовите атакующего бойца Паучок.","Начало раунда: у вас 3+ других пауков.","Возглавив один из влиятельных домов Ноксуса, Элиза без колебаний воспользовалась своими тайными связями с Сумрачными островами, чтобы получить нечеловеческую красоту и юность в обмен на души нескольких несчастных жертв.","Боец",["ПАУК"],["Сумрачные острова"],"Чемпион"],"01SI057":["Древний кроколит","Чтобы сыграть меня, убейте 2 союзников.","","\"В клетку запереть их, хей-хой…\nДуши выдирать по одной…\nИ не выпускать их, да-да!\nА не то случится бе-да…\"","Боец",["РЕПТИЛИЯ"],["Сумрачные острова"],"РЕДКОЕ"],"01SI023":["Проводница душ","Призывая эфемерного союзника, даруйте ему +1|+1.","","Только павшие знают, что она была не одна. Лишь они видели бессчетных спутников, что следовали за ней в земли по ту сторону жизни.","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"01SI010":["Натиск теней","Призовите 2 Призрачных всадников.","","Они живут так же, как умерли: храня абсолютную верность.","Заклинание",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"01SI042":["Гекарим","Атака: призовите 2 атакующих Призрачных всадников.","Вы отправили в атаку 7+ эфемерных союзников.","Это не гром. Это Призрак войны появился на горизонте.","Боец",[],["Сумрачные острова"],"Чемпион"],"01SI027":["Свежая жертва","Если в этом раунде погибло 3+ союзников, призовите карту Вайлмо.","","\"Склонись перед своим хищным божеством. А еще лучше – умри на его глазах!\" – Элиза","Заклинание",[],["Сумрачные острова"],"РЕДКОЕ"],"01SI048":["Проклятый хранитель","Предсмертный вздох: призовите карту Сбежавшее отродье.","","Безумие и время. Нет более страшного сочетания.","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"01SI018":["Певец печали","Призвав меня, создайте в руке копию погибшего в этой игре союзника.","","\"Ваш покорный слуга и не подозревал, что вскоре Погибель… нет-нет-нет, опять я пролил чернила! Ваш покорный слуга… нет-нет-нет!\"","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"01SI030":["Калиста","","На моих глазах погибли 3+ союзника.","При жизни она была генералом, героем, защитницей своей державы. Лишившись бренной плоти, она стала бессмертным духом возмездия, воплощенной жаждой мести.","Боец",[],["Сумрачные острова"],"Чемпион"],"01SI035":["Раза Сокрушитель","Разыгрывая карту: если в этом раунде погиб союзник, убейте 2 слабейших вражеских бойцов.","","\"Нам обещали путешествие, о котором сложат легенды. Мы должны были защищать… будущее Демасии. Мы вышли из порта, окрыленные надеждой. А что в результате? Столько людей погибло… ради чего?\" – Ари Ренс, демасийский солдат","Боец",[],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"01SI005":["Призрачный ползун","Моя стоимость снижается на 1 за каждого союзника, погибшего в этом матче.","","Это вьючное животное канувшего в вечность королевства теперь пасется на полях забытых сражений, укрепляет свой панцирь мусором и кормится душами погибших.","Боец",[],["Сумрачные острова"],"РЕДКОЕ"],"01SI037":["Зловещий поро","","","Есть куда более неприятные способы умереть.","Боец",["ПОРО"],["Сумрачные острова"],"ОБЫЧНОЕ"],"01SI052":["Треш","","На моих глазах погибли 6+ бойцов.","\"Скорее беги, на месте не стой. Страж цепей идет за тобой.\nТы от ужаса еле живой. Он уже у тебя за спиной...\"","Боец",[],["Сумрачные острова"],"Чемпион"],"01SI033":["Командир Ледрос","Разыгрывая карту: нанесите вражескому нексусу урон, равный половине его здоровья (значение округляется вверх).\nПредсмертный вздох: верните меня в руку.","","Время подтачивает память, и большинство призраков утратили свои личности. Но для Ледроса боль и страдание стали якорем, который не дает позабыть прошлое.","Боец",[],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"01SI003":["Страховин","Оживите 6 сильнейших союзников, погибших за эту игру. Они будут эфемерными.","","Бывают ночи, когда черный туман густеет от потока голодных душ. Туман несет их над морем, и они охотятся на живых, чтобы пополнить растущую тьму новыми полчищами нежити.","Заклинание",[],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"01SI041":["Неумирающий","Предсмертный вздох: воскресите меня в начале следующего раунда и даруйте мне +1|+1 за каждую мою смерть.","","Старый мученик помнил, как в роковой час призывал соратников сражаться. А вот за что – это он позабыл много лет назад.","Боец",[],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"01SI045":["Поглощение души","Истощите союзника на 4 ед. здоровья.","","\"То, что вас убивает, делает меня сильнее\". – Треш","Заклинание",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"01SI036":["Мурашки","Если в этом раунде погиб союзник, призовите 2 Паучков.","","Мурашки по коже – еще полбеды. Главное – не задумываться о том, что ползет ПОД кожей.","Заклинание",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"01SI051":["Страдающий виртуоз","Предсмертный вздох или когда умирает другой союзник: восполните ману заклинаний.","","Он сутки напролет не отходил от фортепьяно, доводя сонату до совершенства. Когда в мгновение ока все вокруг накрыла тьма и тишина, другие закричали и побежали сломя голову. Но он ничего не заметил.","Боец",[],["Сумрачные острова"],"РЕДКОЕ"],"01SI012":["Рассеянный островитянин","Разыгрывая карту: сделайте союзника в руке эфемерным и уменьшите его стоимость на 1.","","Бедолага…","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"01SI031":["Железный предвестник","Атака: даруйте мне +1|+0 за каждого своего эфемерного союзника.","","После смерти, как когда-то при жизни, Гекарим выкрикивает жестокие приказы – и, как и тогда, его призрачные рыцари мчатся изрубить противника.","Боец",[],["Сумрачные острова"],"РЕДКОЕ"],"01SI034":["Черное копье","Если в этом раунде погиб союзник, нанесите бойцу 4 ед. урона.","","\"Наши копья поют о павших\". – Калиста","Заклинание",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"01SI043":["Невезучий аристократ","Предсмертный вздох: призовите карту Паучок.","","\"Г-госпожа Элиза? Где... Где же вы?\"","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"01SI009":["Духи старого разлива","Поддержка: даруйте союзнику, которого я поддерживаю, +2|+0 и Эфемерность.","","Некоторые видят в Погибели лишь беды и несчастья. Для других же стакан наполовину полон.","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"01SI007":["Проклятая реликвия","Призовите 3 Яростных духов.","","Живые мечтают заполучить эти древние артефакты, но мертвые отказываются с ними расставаться.","Заклинание",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"01SI056":["Обезумевший ловчий","Призвав меня, дайте другим союзным паукам +1|+0, а врагам -1|-0 до конца раунда.","","\"Они могут соткать сеть в человеческий рост меньше, чем за минуту. Хочешь посмотреть?\" – Элиза","Боец",["ПАУК"],["Сумрачные острова"],"РЕДКОЕ"],"01SI001":["Возмездие","Убейте бойца.","","Жертвы предательства перед смертью взывают к Калисте, чтобы та отомстила за них своими призрачными копьями.","Заклинание",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"01SI019":["Короб","Нанесите по 3 ед. урона всем врагам, призванным в этом раунде.","","\"Никто не уйдет\". – Треш","Заклинание",[],["Сумрачные острова"],"РЕДКОЕ"],"01SI011":["Ненасытный мясник","Чтобы сыграть меня, убейте союзника.","","Ты – то, что ты ешь.","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"01SI014":["Туманный дух","Призвав меня, другие союзные Туманные духи получают везде +1|+0.","","Эти призраки с Сумрачных островов давно утратили свои личности и стали воплощением неутолимого голода.","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"01SI022":["Метка Островов","Даруйте союзнику +2|+2 и Эфемерность.","","Cила, но какой ценой?","Заклинание",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"01SI006":["Одержимость","Украдите вражеского сторонника на этот раунд. Нельзя использовать, если у вас уже есть 6 союзников или мест силы.","","Когда он проснулся, на руках блестело что-то красное, а в лагере было непривычно тихо. ","Заклинание",[],["Сумрачные острова"],"РЕДКОЕ"],"01SI028":["Расколотая душа","Призовите точную копию союзника. У нее будет Эфемерность и 1|1.","","\"Я поднял тело из воды, чтобы опознать несчастного. Я перевернул его и увидел лицо… мертвыми глазами на меня смотрел я сам\". – Ари Ренс, демасийский солдат","Заклинание",[],["Сумрачные острова"],"РЕДКОЕ"],"01SI025":["Зверство","Убейте союзника, чтобы нанести равный его силе урон любой цели.","","Для тех, кто не может познать смерть, убийство ничего не значит.","Заклинание",[],["Сумрачные острова"],"РЕДКОЕ"],"01SI046":["Зов тумана","Воскресите союзника, случайно выбранного из погибших в этом раунде.","","\"Туман отрывает дух от плоти, оставляя лишь жалкое подобие жизни. Я видел, как он губит мой родной край, и отправляюсь на эти проклятые острова, чтобы покончить с ним\". – Ари Ренс, поборник справедливости","Заклинание",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"01SI050":["Паучий выводок","Призовите 3 Паучков, а затем даруйте союзникам-паукам +1|+0.","","Вылупляются они зверски голодными.","Заклинание",[],["Сумрачные острова"],"РЕДКОЕ"],"01SI016":["Созывающая призраков","Верность: призовите карту Туманный дух.","","Она является бесшумно. Следующие за ней порождения кошмара совсем не так деликатны.","Боец",[],["Сумрачные острова"],"РЕДКОЕ"],"01SI021":["Колесница, запряженная акулами","Предсмертный вздох: в следующий раз, когда будет атаковать эфемерный союзник, воскресите меня и тоже отправьте в атаку.","","\"Что ей привиделось, лекарь? М-да, душевная болезнь – штука серьезная. По крайней мере, остальные несут не такую околесицу\". – Демасийский хирург","Боец",[],["Сумрачные острова"],"РЕДКОЕ"],"01SI032":["Летописец Погибели","Разыгрывая карту: убейте союзника, а затем воскресите его.","","Когда-то она сидела возле отца – лорда-куратора – пока тот листал страницы древних фолиантов. Он хотел, чтобы она стала его преемницей… но не в такой форме.","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"01SI058":["Эфирный проводник","Разыгрывая карту: убейте союзника, чтобы призвать случайного сторонника стоимостью на 2 больше.","","О, духи, пусть ваши голоса сольются в общий хор! Вместе мы опустим на землю вечную тьму!","Боец",[],["Сумрачные острова"],"РЕДКОЕ"],"01SI054":["Хватка нежити","Истощите бойца на 3 ед. здоровья.","","Больше всего на свете мертвым хочется, чтобы затихло бесконечное биение пульса жизни.","Заклинание",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"01SI044":["Призрачная дама","Разыгрывая карту: выберите союзника в руке и призовите его точную копию. Она будет эфемерной.","","Погибель исказила всех, кому не повезло оказаться рядом. Добрые стали жестокими. Храбрые – злыми. Рассудительность сменилась бездумным гневом.","Боец",[],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"01SI039":["Паучий кошмар","","","Ища вдохновения в природе, зловредные духи преобразуют обычную фауну в нечто кошмарное.","Боец",["ПАУК"],["Сумрачные острова"],"ОБЫЧНОЕ"],"01SI020":["Зажигающий свечи","Призвав меня, оживите своего сильнейшего погибшего чемпиона.","","Гаснущая свеча служит одной цели: от нее зажигают следующую.","Боец",[],["Сумрачные острова"],"РЕДКОЕ"],"01SI029":["Иссушающий вопль","Нанесите 1 ед. урона всем врагам и восстановите 3 ед. здоровья своему нексусу.","","То, что убивает нас, делает нас сильней.","Заклинание",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"01SI004":["Темные глубины","","","Спасаясь от Погибели, некоторые ныряли в море в надежде, что тьма не просочится на глубину. Они ошибались.","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"01SI026":["Жертва Стража","Предсмертный вздох: создайте в руке другого случайного сторонника с предсмертным вздохом стоимостью не более 3.","","Он устал от погони и старался не дышать, молясь, чтобы страж прошел мимо. Бедняга не подозревал, что это лишь начало любимой игры Треша – веселой для него и мучительной для жертвы.","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"01SI040":["Мерзкий пир","Истощите бойца на 1 ед. здоровья, чтобы призвать карту Паучок.","","\"М-моя госпожа! Я и не подозревал, что вы так… любите пауков. Вы не могли бы убрать их от меня? Г-госпожа Элиза? Прошу вас!\" – Лорд Сассен, невезучий аристократ","Заклинание",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"01SI015":["Погибель","Убейте ВСЕХ бойцов.","","Удивительно, что столь чистое чувство, как любовь, привело к таким жестоким и необратимым последствиям. ","Заклинание",[],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"01SI055":["Пожиратель душ","","","\"Наши корабли подходят к населенным призраками берегам, а я размышляю: всегда ли кошмарные создания проклятых островов были такими? Вели ли они когда-то нормальную жизнь?\" – Ари Ренс, демасийский солдат","Боец",[],["Сумрачные острова"],"РЕДКОЕ"],"01SI047":["Отголоски воспоминаний","Выберите сторонника. Создайте в руке его эфемерную копию.","","На краткий миг она вспомнила, как играли на коже солнечные лучи, падавшие сквозь кроны деревьев, как лопалась во рту сочная ежевика, как ветерок доносил тонкую мелодию поляны. А потом… все снова забылось.","Заклинание",[],["Сумрачные острова"],"РЕДКОЕ"],"02PZ001":["Субмуррина","Призвав меня, вытяните 1 карту.\nЗатем, если в этом матче вы сыграли 10+ других новых карт, даруйте мне +4|+0.","","Ничто не помешает ему сбежать от этих жалких человечков. Подумаешь, немного воды…","Боец",["КОШКА"],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"02PZ010":["Опытный дознаватель","Когда меня призывают, ВСЕ игроки вытягивают по 1 карте.","","Одни раскрывают дела благодаря чутью. Другие используют связи. А офицер Джей-Эс Харкнор полагается только на свою дотошность и привычку вести подробные записи. Очень, очень подробные записи.","Боец",["ЙОРДЛ"],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"02PZ006":["Получай!","Когда меня вытягивают, моя стоимость в этом раунде снижается на 2.\nНанесите любому бойцу 3 ед. урона.","","\"Не примерите пару наручников, мистер Берц?\"\n\"Какая мне с этого польза?\"\n\"Можете оставить их себе\".\n\"Ну ладно\".\n\"Вы арестованы. Уведите его!\"","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"02PZ004":["Вскрыватель хранилищ","Дайте союзнику +2|+0 до конца раунда.\nСоздайте в руке мимолетную карту Вскрыватель хранилищ.","","\"Мои руки все скажут за меня\". – Вай","Заклинание",[],["Пилтовер и Заун"],"РЕДКОЕ"],"02PZ007":["Проницательная дознавательница","Сыграв карту стоимостью 2, вытяните 1 карту и даруйте ей Мимолетность.","","\"Все сыщики выполняют свою работу, но хороший специалист предугадывает преступления, а образцовый – заранее их предотвращает\". – Из устава патрульных","Боец",[],["Пилтовер и Заун"],"РЕДКОЕ"],"02PZ002":["Главный механик Зеви","Вытянув карту, даруйте ей Мимолетность и создайте в руке ее точную копию.","","В пять лет она смастерила первый в истории звуковой нож, работавший на разных частотах. И хотя с его помощью она в основном делала бутерброды, это стало первым шагом к работе в отделе элитного вооружения патрульных Пилтовера.","Боец",[],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"02PZ008":["Вай","Если я в руке или на поле боя, даруйте мне +1|+0 всякий раз, когда разыгрываете другую карту (до +8|+0).","Мой удар нанес 10+ ед. урона за один удар.","\"Миротворица Вай, я взываю к твоему разуму! Подумай о людях! О случайных пострадавших! О КУЧЕ ЖАЛОБ НА МАТЕРИАЛЬНЫЙ УЩЕРБ!\"\n– Проницательная дознавательница","Боец",[],["Пилтовер и Заун"],"Чемпион"],"02PZ009":["Цепочка улик","Создайте в руке случайную карту из своих регионов стоимостью 2. Стоимость в этом раунде снижается на 2.","","\"Итак… – объявил патрульный Харкнор, – след ведет нас к…\"","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"02PZ003":["Приоденься!","Когда меня вытягивают, моя стоимость в этом раунде снижается на 2.\nУвеличьте характеристики союзника до 4|4.","","\"В доках беспорядки! Вот, возьми это и передай нашим ребятам привет\". – Главный механик Зеви","Заклинание",[],["Пилтовер и Заун"],"РЕДКОЕ"],"02PZ005":["Патрульные","Когда меня вытягивают, моя стоимость снижается на 1 до конца раунда.","","В отделении часто подшучивают над тем, как бегает патрульный Мир. Но патрульная Кеппл этих шуток не понимает.","Боец",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"02BW040":["Черепашья артиллерия","","","\"МАЯ ГЛАВНАЯ СИЛА ЭТА УМЕНЕЕ КАМАНДОВАТЬ. А ИЩО Я ПЕШУ БЕЗ АШИБАК!\" – Надпись на песке","Боец",[],["Билджвотер"],"ОБЫЧНОЕ"],"02BW057":["Проворный волногон","","","\"Клянусь, капитан, я видел над рифами странные вещи… Хотел бы я знать, что этот охламон добавляет в свои апельсины!\" – Младший офицер","Боец",[],["Билджвотер"],"ОБЫЧНОЕ"],"02BW041":["Зверь из глубин","","","\"Знакомых чудовищ страшиться нелепо:\nВедь кто-то же выжил, чтоб байку поведать.\nПодумай о том, кто пробил борт галеры\nИ всех утащил в темноводную бездну\". – Выцарапано на притолоке в билджвотерской таверне","Боец",["МОРСКОЕ ЧУДОВИЩЕ"],["Билджвотер"],"ОБЫЧНОЕ"],"02BW013":["Крадущийся головорез","","","\"…этот дурак сказал, что мои бедра 'перекатываются, как волны'. Я пригрозила отрезать его льстивый язык, если он не заткнется\".","Боец",[],["Билджвотер"],"ОБЫЧНОЕ"],"02BW034":["Обезьяний истукан","Начало раунда: нанесите мне 2 ед. урона и призовите карту Пороховая обезьяна.","","\"Это так, сувенирчик. Команда умыкнула его у одного моего чокнутого конкурента. Оказалось, что он все-таки не спятил, а его слова о 'древней мистической силе' не так уж далеки от истины\". – Мисс Фортуна","Боец",[],["Билджвотер"],"РЕДКОЕ"],"02BW056":["Пожиратель из глубин","Разыгрывая карту: уничтожьте врага, у которого меньше здоровья, чем у меня.","","\"Раз в билджвотерский залив вышел, парус распустив,\nМой кораблик, а из моря следом –\nТа, с кем встречи я не ждал, покидая свой причал,\nС затонувшей Крылоухой леди\". – из \"Баллады о затонувшей Крылоухой леди\"","Боец",["МОРСКОЕ ЧУДОВИЩЕ"],["Билджвотер"],"ЭПИЧЕСКОЕ"],"02BW060":["Снайпер-корсар","Когда атакует любой союзник, включая меня, нанесите 1 ед. урона вражескому нексусу.","","\"У подстреленных есть одно неожиданное преимущество. Обычно в драке никто не смотрит вниз!\"","Боец",["ЙОРДЛ"],["Билджвотер"],"ОБЫЧНОЕ"],"02BW011":["Йордл-жулик","Верность: когда меня призывают, украдите 1 карту и создайте в руке карту Предупредительный выстрел.","","\"Друзья выручают друг друга, верно? Мне нравится, как блестят твои глаза и твоя сабля. Очень хорошая, годная сабля\".","Боец",["ЙОРДЛ"],["Билджвотер"],"РЕДКОЕ"],"02BW030":["Страж затонувших кораблей","Призвав меня, выбросьте из колоды 2 карты и создайте в своей колоде 2 сокровища.","","\"Спорю, на дне морском сейчас больше сокровищ, чем на суше. Мы бы мигом разбогатели, если б не эта зверюга!\"\n– Мясник из \"Ржавых крючьев\"","Боец",["МОРСКОЕ ЧУДОВИЩЕ"],["Билджвотер"],"ЭПИЧЕСКОЕ"],"02BW019":["Пузырьковый мишка","","","Змеиные острова омывают магические потоки, дарящие жизнь удивительным обитателям рифов.","Боец",[],["Билджвотер"],"ОБЫЧНОЕ"],"02BW007":["Азартный игрок","Чтобы сыграть меня, сбросьте 2 карты.\nАтака: вытяните 2 карты и даруйте им Мимолетность.","","\"Обычно ничего сложного. Садится за стол куча дураков, которые горланят песни вместо того, чтобы следить за игрой. Но я не жалуюсь. Деньги есть деньги, и пусть лучше они будут в моем кошельке, чем в чужом\".","Боец",[],["Билджвотер"],"РЕДКОЕ"],"02BW014":["Живые кораллы","Призвав меня, создайте в руке случайное заклинание из своих регионов стоимостью 1.","","На мелководье всегда кипит жизнь, но ничто не сравнится с рифами Лазурного Пути. Это по-настоящему волшебное место, богатое на чудеса.","Боец",[],["Билджвотер"],"РЕДКОЕ"],"02BW055":["Старпом из \"Ржавых крючьев\"","Разграбление: даруйте +1|+0 союзникам стоимостью 1 везде.","","После ее выстрела команда \"Крючьев\" должна действовать быстро, ведь кровь в воде привлекает тех, с кем лучше не сталкиваться.","Боец",[],["Билджвотер"],"ЭПИЧЕСКОЕ"],"02BW017":["Разносчик цитрусов","Разграбление: восстановите союзникам и своему нексусу по 3 ед. здоровья. Затем активируйте Рвение.","","\"Моряки думают, они круче всех! Якорь то, морской дьявол се. А куда они без апельсинов? Апельсины нужны всем! Кожа станет гладкая, зубы не выпадут, а я буду доволен. Ешь или сваливай за борт. Все просто\".","Боец",[],["Билджвотер"],"РЕДКОЕ"],"02BW038":["Шустрая плавунья","Призвав меня, вытяните из своей колоды заклинание стоимостью 3 или меньше.","","Однажды Плавунья промчалась по всему Лазурному пути меньше, чем за три минуты. В конце ей пришлось обогнуть разбитый остов \"Джиллдоу\". Течение в тот день было просто шикарное!","Боец",[],["Билджвотер"],"ЭПИЧЕСКОЕ"],"02BW021":["Шипохвост-охотник","Разыгрывая карту: даруйте вражескому бойцу Уязвимость.","","\"Говорят, в поисках добычи он может проплыть много миль, а когда найдет ее, то ни за что не промахнется. Не знаю, человек это или тварь морская, но эти воды он знает лучше нас\". – Мясник из \"Ржавых крючьев\"","Боец",[],["Билджвотер"],"РЕДКОЕ"],"02BW035":["Шериф Лариет Роуз","Призвав меня, даруйте всем врагам Уязвимость.","","В Билджвотере нет законов, но несколько храбрецов в этом оживленном городе не боятся вершить правосудие – в своем понимании этого слова.","Боец",[],["Билджвотер"],"ЭПИЧЕСКОЕ"],"02BW058":["Мясник из \"Ржавых крючьев\"","Разграбление: даруйте мне +1|+1.","","Попасть в банду \"Ржавые крючья\" не так-то просто. Моряк должен доказать, что он умеет поднимать парус, драться и разделывать мясо. Самые неудачливые кандидаты выполнят все три задачи одновременно.","Боец",[],["Билджвотер"],"ОБЫЧНОЕ"],"02BW028":["Король сейсмической волны","Разграбление: 7 раз примените заклинание Пушечный обстрел к случайным врагам.","","\"Разбив корабль врага в труху,\nЛюдей спасать мы не должны.\nУ всех сегодня на слуху\n\"Король сейсмической волны\"! – \"Пора домой, Салли\"","Боец",[],["Билджвотер"],"ЭПИЧЕСКОЕ"],"02BW037":["Глубинное око","Удар по нексусу: вытяните 1 карту.","","\"Как-то наши морячки в Нашраме поплыли.\nНо жара и стихия там многих сгубили.\nА над выжившими рок подшутил жестоко:\nПоджидало в глубине Всевидящее Око\". – Песенка о Всевидящем оке","Боец",["МОРСКОЕ ЧУДОВИЩЕ"],["Билджвотер"],"РЕДКОЕ"],"02BW008":["Младший офицер","Разыгрывая карту: призовите карту Пороховая бочка или случайного сторонника стоимостью 1.","","Он быстро постиг простую истину: мало что оказывает на ленивого моряка такой же тонизирующий эффект, как зажженный фитиль.","Боец",["ЙОРДЛ"],["Билджвотер"],"РЕДКОЕ"],"02BW047":["Роющие дно","Призвав меня, выбросьте из колоды 3 карты.","","Сделать из отличных снастей непригодный мусор – это надо уметь. И они умеют это лучше всех…","Боец",[],["Билджвотер"],"ОБЫЧНОЕ"],"02BW004":["Матрос с \"Кошмара\"","Призвав меня, призовите карту Пороховая бочка.","","\"Конечно, можно атаковать врага на рассвете, когда матросы не спят, а пушки заряжены. А можно тихонько подложить подарочек ночью…\"","Боец",[],["Билджвотер"],"ОБЫЧНОЕ"],"02BW002":["Кошмар","Призвав меня, вытяните карту Гангпланк.\nУдвойте урон от всех ваших заклинаний, способностей и союзников.","","\"Последние шлите любимым приветы:\nЗа вами идет \"Кошмар\"!\nНа дне, в глубине станет больше скелетов.\nЗа вами идет \"Кошмар\"! – \"За вами идет Кошмар\"","Боец",[],["Билджвотер"],"ЭПИЧЕСКОЕ"],"02BW016":["Игровой автоматон","Призвав меня или в начале раунда: даруйте мне +0|+1 за каждую карту, вытянутую вами в прошлом раунде, а затем перемешайте мои характеристики.","","Прототип взорвался после третьего снаряда. В более поздних моделях от этой \"особенности\" удалось избавиться.","Боец",[],["Билджвотер"],"РЕДКОЕ"],"02BW027":["Охотничий флот","Когда меня призывают, ваш противник призывает карту Золотой нарвал.","","\"Что золотится в толще воды? Это не монеты и не золотые слитки, а сверкающий рог хитрой бестии, которую выслеживает капитан Охотничьего флота\".","Боец",[],["Билджвотер"],"ОБЫЧНОЕ"],"02BW050":["Талантливая солистка","Разграбление: снизьте стоимость союзников в руке и в колоде на 2.","","\"Приглашаем вас совершить музыкальное путешествие. Музыка со всех уголков Рунтерры! Монетка за вход, чаевые приветствуются…\"\n– Зазывала","Боец",[],["Билджвотер"],"РЕДКОЕ"],"02BW015":["Сирена","Призвав меня, вытяните чемпиона Мисс Фортуна.\nКогда я атакую, все ваши заклинания и способности наносят на 1 ед. урона больше.","","\"Сирену\" ни с чем ни спутаешь. Широкие жемчужные паруса и полированное дерево бортов выглядят такими же лощеными, как ее капитан.","Боец",[],["Билджвотер"],"ЭПИЧЕСКОЕ"],"02BW010":["Жадный поро","Разграбление: даруйте мне 2 случайных навыка.","","\"Его портрет очень давно висит на доске розыска. Это жадный и безжалостный демон, который никому не дает спуску. Но хуже всего то… что он еще и милый!\" – Гангпланк","Боец",["ПОРО"],["Билджвотер"],"ОБЫЧНОЕ"],"02BW009":["Проныра","Призвав меня, вытяните 1 карту в начале следующего раунда и даруйте ей Мимолетность.","","\"Ничего не понимаю. Я легко всех уделала, но последний никак не хотел сдаваться... Наверное, просто не мой день\". – Азартный игрок","Боец",[],["Билджвотер"],"ОБЫЧНОЕ"],"02BW005":["Наемница","Призвав меня, сделайте сильнейшего врага уязвимым.","","\"Это твой портрет? М-да, в жизни ты даже страшнее, чем на картинке… Надеюсь, награда за твою голову стоит моих трудов\".","Боец",[],["Билджвотер"],"ОБЫЧНОЕ"],"02BW039":["Охотники на челюстозубов","Когда меня призывают, создайте в руке случайное морское чудовище.","","Корабли один за другим покидают безопасное мелководье в надежде найти сокровища. Эти несчастные моряки еще не знают, как опасна глубокая вода и почему возвращаются лишь немногие.","Боец",[],["Билджвотер"],"РЕДКОЕ"],"02BW006":["Мистический маг","Разыгрывая карту: превратите союзника в случайного сторонника стоимостью 5.","","\"Марволио? Где… где мои руки?\"\n\"Сейчас они снова появятся! Абра… кадабра… Хм-м... Та-да!\"\n\"…ГДЕ МОИ РУКИ?!\"\n\"ВСЕ, МНЕ ПОРА! ВСЕМ СПАСИБО!\"","Боец",[],["Билджвотер"],"РЕДКОЕ"],"02BW036":["Золотой нарвал","","","Если верить легенде, Бородатую Леди когда-то обокрал белый кит-единорог. В наказание она покрыла его золотой чешуей, чтобы он навсегда стал объектом алчности других.","Боец",[],["Билджвотер"],"ОБЫЧНОЕ"],"02BW033":["Торговец с черного рынка","Вытянув карту противника, уменьшите ее стоимость на 1.\nРазграбление: украдите 1 карту.","","\"У меня есть все, что душе угодно. Даже 'особые товары'. Но если кто спросит, ты не у меня покупал!\"","Боец",[],["Билджвотер"],"РЕДКОЕ"],"02BW032":["Гангпланк","Призвав меня, призовите карту Пороховая бочка.","Вы повреждали вражеский нексус в 5+ раундах.","\"Не смотри на него пристально, иначе он почувствует. Не говори о нем дурного – он слышит каждый шепоток в Билджвотере. Вон он идет. Опусти голову. А взгляд еще ниже\". – Матрос с \"Кошмара\"","Боец",[],["Билджвотер"],"Чемпион"],"02BW022":["Мисс Фортуна","Когда атакуют союзники, нанесите 1 ед. урона всем врагам в бою и вражескому нексусу.","На моих глазах вы атаковали 4 раза.","\"Мисс Фортуна? В море зови меня капитаном!\"","Боец",[],["Билджвотер"],"Чемпион"],"02BW046":["Физз","Разыграв заклинание, остановите все нацеленные на меня вражеские заклинания и способности и дайте мне Изворотливость до конца раунда.","Вы разыграли 6+ заклинаний.","Из всех мифических существ Билджвотера Физз – самый непредсказуемый. Некоторые моряки винят его в многочисленных кораблекрушениях у самого берега…","Боец",["ЙОРДЛ"],["Бандл Сити","Билджвотер"],"Чемпион"],"02BW026":["Твистед Фэйт","Разыгрывая карту: сыграйте Карту судьбы.","На моих глазах вы вытянули 9 карт.","\"Считайте карты и следите за руками. Помните…\"","Боец",[],["Билджвотер"],"Чемпион"],"02BW053":["Наутилус","","Вы на глубине. Когда мой уровень повышается, скопируйте в свою колоду выброшенных из колоды союзников стоимостью 4+.","\"Борт 'Злобы' пробил якорь. Финн и все остальные потонули. Нас осталось полтора человека, а скоро придет ночь… и холод. Прости меня, мам. Ты была права. Титан и правда существует\".\n– Записка из моря","Боец",[],["Билджвотер"],"Чемпион"],"02BW061":["Тузы в рукаве","Когда меня вытягивают, моя стоимость в этом раунде снижается на 1. Даруйте союзнику +2|+1.","","\"Когда удача на моей стороне, фишки сами идут мне в руки\". – Твистед Фэйт","Заклинание",[],["Билджвотер"],"ОБЫЧНОЕ"],"02BW024":["Двойные неприятности","Призовите 2 случайных сторонников стоимостью 1.","","\"Эй, Гэв! Вон парень, которого мы выслеживаем. Похоже, у него появился приятель\".\n\"Это... Это что, человек-акула, Баз?\"\n\"Не дрейфь, партнер! За двоих дадут больше золота!\" – Баз и Гэв, начинающие охотники за головами","Заклинание",[],["Билджвотер"],"РЕДКОЕ"],"02BW003":["Принуждение","Разграбление: верните в свою руку ЛЮБОГО сторонника.","","\"Теперь ты работаешь на нас, салага!\" – Младший офицер","Заклинание",[],["Билджвотер"],"РЕДКОЕ"],"02BW025":["Ловля на живца","Даруйте врагу Уязвимость и призовите карту Длиннозуб.","","\"Акула!\" – Физз","Заклинание",[],["Билджвотер"],"ОБЫЧНОЕ"],"02BW012":["Еще пороха!","Призовите 2 Пороховые бочки.","","\"Бочку!\" – Гангпланк","Заклинание",[],["Билджвотер"],"ОБЫЧНОЕ"],"02BW018":["Аррргумент","Нанесите 1 ед. урона любой цели. Если она погибнет, нанесите 1 ед. урона вражескому нексусу.","","Переговоры Гангпланка обычно заканчиваются быстро и кроваво.","Заклинание",[],["Билджвотер"],"ОБЫЧНОЕ"],"02BW048":["Побег из тюрьмы","Призовите случайного сторонника стоимостью 1.","","\"Что скажешь, Баз? На вид он вроде не особо страшный\".\n\"Ты уверен, Гэв? Этот парень сбежал из тюрьмы…\"\n\"Это значит, что он хитрый, а не сильный. Вперед!\" – Баз и Гэв, начинающие охотники за головами","Заклинание",[],["Билджвотер"],"ОБЫЧНОЕ"],"02BW043":["Выбор карты","Чтобы сыграть, уберите карту из руки в свою колоду.\nВытяните 2 карты в начале следующего раунда и даруйте им Мимолетность.","","\"Я кузнец собственной удачи\". – Твистед Фэйт","Заклинание",[],["Билджвотер"],"РЕДКОЕ"],"02BW051":["Игривый шутник","Выведите из боя атакующего союзника, чтобы активировать Рвение.","","\"Всегда на прыжок впереди!\" – Физз","Заклинание",[],["Билджвотер"],"РЕДКОЕ"],"02BW054":["Сейсмическая волна","Оглушите врага.\nУберите его в колоду противника, если у вас есть Наутилус.","","\"Утащу на глубину…\" – Наутилус","Заклинание",[],["Билджвотер"],"РЕДКОЕ"],"02BW042":["Слияние разумов","В этом раунде сила и здоровье союзников вырастут до количества остальных заклинаний, разыгранных вами за эту игру.","","Сильные течения у берегов Билджвотера круто меняют направление и по праву считаются опасными. Однако ни один моряк не знает истинной мощи, что скрывается под волнами.","Заклинание",[],["Билджвотер"],"ЭПИЧЕСКОЕ"],"02BW059":["Картечь","Выбросьте из колоды 3 карты.\nНанесите бойцу 7 ед. урона.","","\"Все, что топит врага, того стоит\". – Билджвотерская поговорка","Заклинание",[],["Билджвотер"],"РЕДКОЕ"],"02BW023":["Затонувшие сокровища","Снизьте стоимость всех союзных морских чудовищ везде на 1.\nВытяните морское чудовище.","","Моряки шепотом говорят о страшном дне, когда вздыбятся волны морские и неописуемый ужас восстанет из глубин.","Заклинание",[],["Билджвотер"],"РЕДКОЕ"],"02BW031":["Два по цене одного","Нанесите врагу 2 ед. урона.\nЕсли удар оказался смертельным, нанесите 4 ед. урона вражескому нексусу.","","\"Я всегда стреляю первой\". – Мисс Фортуна","Заклинание",[],["Билджвотер"],"РЕДКОЕ"],"02BW029":["Спасение груза","Выбросьте из колоды 2 карты.\nВытяните 2 карты.","","Смытые за борт грузы быстро тонут. Любой уважающий себя моряк умеет живо отделить ценности от мусора…","Заклинание",[],["Билджвотер"],"ОБЫЧНОЕ"],"02BW049":["Краденые товары","Украдите 1 карту.\nРазграбление: Украдите еще 1.","","Свое мы никому не отдадим. И чужое тоже.","Заклинание",[],["Билджвотер"],"ОБЫЧНОЕ"],"02BW001":["Вас предупреждали","Сделайте вражеского бойца уязвимым до конца раунда. Если в этом раунде он погибнет, вытяните одну карту.","","\"Держи хвост трубой, а нос по ветру! Если капитан заметит, что ты филонишь, он вздернет тебя на рее, выпустит тебе кишки и скормит их чайкам. За работу!\" – Матрос с \"Кошмара\"","Заклинание",[],["Билджвотер"],"ОБЫЧНОЕ"],"02BW063":["Ловкость рук","Разграбление: вытяните случайную карту, кроме чемпиона, из руки противника.","","\"В карточной игре главное не удача, а люди. Заставишь противников сомневаться – считай, они уже отдали тебе все, что у них есть\". – Твистед Фэйт","Заклинание",[],["Билджвотер"],"РЕДКОЕ"],"02BW045":["Свинцовый дождь","Нанесите 1 ед. урона трем случайным вражеским целям, среди которых может быть нексус.","","\"Пали!\" – Мисс Фортуна","Заклинание",[],["Билджвотер"],"ОБЫЧНОЕ"],"02BW020":["Предупредительный выстрел","Нанесите 1 ед. урона вражескому нексусу.","","\"Стрелять надо одновременно с нами, парень. Это называется 'залп'!\" – Младший офицер","Заклинание",[],["Билджвотер"],"ОБЫЧНОЕ"],"02BW044":["Сброс балласта","Выбросьте из колоды 4 карты.","","\"Все, что не стоит своего веса, – за борт! Вас самих это тоже касается. За работу!\" – Младший офицер","Заклинание",[],["Билджвотер"],"РЕДКОЕ"],"02BW062":["Островной штурман","Когда меня призывают, призовите случайного сторонника стоимостью 1 и даруйте ему Разведку.","","\"Сиянье Матери Змеи\nСпокойно небо озарит.\nОно себя в волнах узрит,\nЕе на время усмирит…\"\n– Молитва к Нагакейборос","Боец",[],["Билджвотер"],"РЕДКОЕ"],"02FR009":["Наездник на волке","Разграбление: получите пустой кристалл маны.","","В племени Коготь Зимы будущий всадник получает волчонка, как только становится способен держать оружие. Затем их обоих готовят к сражениям: волка учат рвать и калечить, а всадника – грабить и разорять.","Боец",[],["Фрельйорд"],"ОБЫЧНОЕ"],"02FR004":["Ледяная хватка","Заморозьте вражеского бойца и сделайте его уязвимым до конца раунда.","","\"Эти теплокровные не продержались бы во Фрельйорде и дня!\" – Седжуани","Заклинание",["СТИХИЯ"],["Фрельйорд"],"РЕДКОЕ"],"02FR002":["Седжуани","Разыгрывая карту: заморозьте вражеского бойца и сделайте его уязвимым до конца раунда.","Вы повреждали вражеский нексус в 5+ раундах.","Хлыст из Истинного льда впечатляет, но куда более страшное оружие – сама Седжуани, рожденная в лютом холоде Фрельйорда и закаленная его стужей.","Боец",[],["Фрельйорд"],"Чемпион"],"02FR001":["Дева тлеющих углей","Начало раунда: нанесите 1 ед. урона ВСЕМУ.","","\"Слабые пусть засевают поля,\nПолют и косят – они, а не мы.\nТолько все то, что рождает земля,\nСилой возьмет себе Коготь Зимы\". – Детский стишок племени Коготь Зимы","Боец",[],["Фрельйорд"],"РЕДКОЕ"],"02FR005":["Урсин – Странник духов","Разграбление: я превращаюсь в бойца Буранный урсин.","","Урсины когда-то были людьми, но отказались от привычной жизни смертных ради первобытной звериной мощи, которую дарует великий дух Волибир.","Боец",[],["Фрельйорд"],"ОБЫЧНОЕ"],"02FR010":["Раздел добычи","Даруйте трем верхним бойцам в вашей колоде +1|+1.\nРазграбление: вытяните одного из них.","","\"Все должны делиться\". – Безжалостная налетчица","Заклинание",[],["Фрельйорд"],"РЕДКОЕ"],"02FR008":["Хищный клык","Призвав меня, вытяните чемпиона Седжуани.\nРазграбление: удвойте силу и здоровье союзников в своей колоде.","","\"Весна приносит не только теплую погоду для сева, но и чужие драккары… И тогда зерно, которого было много, начинает быстро заканчиваться\". – Дозорный племени аваросан","Боец",[],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"02FR007":["Ярость севера","Дайте союзнику +3|+4 до конца раунда.","","\"Выпусти на волю внутреннего зверя!\" – Седжуани","Заклинание",[],["Фрельйорд"],"ОБЫЧНОЕ"],"02FR006":["Безжалостная налетчица","","","Весь Фрельйорд знает о жестоком племени Коготь Зимы – и о том, что при встрече с его кровожадными налетчицами остается лишь молить богов о быстрой смерти.","Боец",[],["Фрельйорд"],"ОБЫЧНОЕ"],"02FR003":["Северное сияние","Создайте в руке двух случайных поро и две карты Поро-снэк.","","\"Если ты увидишь поро\nНаяву или во сне –\nСбудется желанье скоро\nМилое, как поро-снэк!\" – Ингвар младшая","Заклинание",[],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"02NX001":["Левиафан","Призвав меня, вытяните чемпиона Свейн.\nНачало раунда: дважды нанесите 1 ед. урона вражескому нексусу.","","Когда он показался на горизонте, ионийцы поначалу приняли его за морское чудовище. Они были недалеки от истины: закованный в железо корабль был величайшим – и ужасающим – достижением ноксианского судостроения.","Боец",[],["Ноксус"],"ЭПИЧЕСКОЕ"],"02NX007":["Свейн","Удар по нексусу: нанесите вражескому нексусу 3 ед. урона.","Вы нанесли 14+ ед. небоевого урона.","\"Сила, которую смертным не понять, наделила меня особым даром. Я смотрю сквозь мрак, который вас пугает, и вижу то, что вы не замечаете\".","Боец",[],["Ноксус"],"Чемпион"],"02NX006":["Разрушитель городов","Начало раунда: нанесите 1 ед. урона вражескому нексусу.","","\"Скажите, – на удивление спокойно спросил старейшина, – зачем собирать камни для постройки более высоких стен, если ноксианцы их все равно сломают?\"","Боец",[],["Ноксус"],"РЕДКОЕ"],"02NX002":["Аурок Светлорог ","Атака: оглушите всех врагов, получивших повреждения.","","\"Многие поколения моих предков жили под гнетом. Вкус свободы мы почувствовали лишь после того, как нашей землей стали править ноксианцы. Вот почему я сражаюсь на стороне империи\".","Боец",[],["Ноксус"],"ЭПИЧЕСКОЕ"],"02NX009":["Ненасытная стая","Нанесите 4 ед. урона бойцу, если он ранен или оглушен.","","Прислушайся. Слышишь? Хлопанье тысячи крыльев!","Заклинание",[],["Ноксус"],"РЕДКОЕ"],"02NX004":["Имперская подрывница","Разыгрывая карту: нанесите союзнику 1 ед. урона, а затем 2 ед. урона вражескому нексусу.","","\"Быстро и тихо… пока не рванет!\"","Боец",[],["Ноксус"],"ОБЫЧНОЕ"],"02NX003":["Ноксианское рвение","Нанесите союзнику 3 ед. урона, чтобы нанести 3 ед. урона любой цели.","","\"Жертв не избежать\". – Джерико Свейн","Заклинание",[],["Ноксус"],"ОБЫЧНОЕ"],"02NX010":["Бронированный мастодонт","Враги с силой меньше 5 не могут нанести мне урон.","","\"Такого зверя на скаку не остановишь. Лучше просто убраться с дороги!\" – Наездник на василиске","Боец",[],["Ноксус"],"РЕДКОЕ"],"02NX008":["Рука смерти","Нанесите 2 ед. урона врагу и 1 ед. урона вражескому нексусу.","","\"Постарайся встретить смерть достойно\". – Свейн","Заклинание",[],["Ноксус"],"ОБЫЧНОЕ"],"02NX005":["Железная баллиста","","","\"Осада – дело несложное, если правильно подобрать орудия. Таран – чтобы враг вскочил на ноги. Баллиста – чтобы снова лег\". – Инженер","Боец",[],["Ноксус"],"ОБЫЧНОЕ"],"02DE003":["Верный барсук","","","Верно говорят: питомцы похожи на своих хозяев.","Боец",[],["Демасия"],"ОБЫЧНОЕ"],"02DE008":["Друг-большерог","","","Следопыты-новички проходят в лесу учения, которые длятся несколько месяцев. За это время нужно научиться предугадывать каждое движение своего оленя. Это требует терпения, но когда команда сформируется, их уже ничто не разлучит.","Боец",[],["Демасия"],"ОБЫЧНОЕ"],"02DE004":["Клыкастый страж","","","\"Я поклялся защищать этот лес и всех, кто ищет в нем прибежища\".","Боец",["ЭЛИТА"],["Демасия"],"ОБЫЧНОЕ"],"02DE006":["Квинн","Призвав меня, призовите карту Вэлор.","На моих глазах вы атаковали 4 раза.","\"Наша Квинн всегда была бесстрашным рыцарем-следопытом, а когда в небе ей помогает Вэлор, их дуэт и вовсе непобедим!\"\n– Женевьева Элмхарт, рыцарь-следопыт","Боец",[],["Демасия"],"Чемпион"],"02DE009":["Опытный следопыт","Предсмертный вздох: призовите карту Верный барсук.","","Бертран начинал свой путь в кружке юных следопытов Бандл-сити и получил все значки, кроме одного: \"За жизнерадостность\".","Боец",["ЙОРДЛ"],["Демасия"],"РЕДКОЕ"],"02DE005":["Несгибаемая воля","Даруйте союзнику особенность \"Я не получаю урон и не умираю\".","","Не обращая внимания на боль в раненой ноге, следопыт поднялась и вскинула меч. Она держалась на ногах, потому что сама Демасия дарила ей силу и стойкость.","Заклинание",[],["Демасия"],"ЭПИЧЕСКОЕ"],"02DE002":["Слепящий удар","Призыв: Вэлор.","","\"Он у меня в волосах! ПРЯМО В ВОЛОСАХ!\"\n– Ноксианский мародер","Заклинание",[],["Демасия"],"РЕДКОЕ"],"02DE010":["Женевьева Элмхарт","Призвав меня, дайте другим союзникам +1|+1 до конца раунда.","","Тот, кто видел следопытов Демасии в бою, никогда этого не забудет. Люди и их звери сражаются как единое целое, и ничто не может их разлучить.","Боец",[],["Демасия"],"ЭПИЧЕСКОЕ"],"02DE007":["Смелость следопыта","Дайте союзникам Стойкость до конца раунда.","","\"Когда враг уже близко, не пускай страх в свое сердце. Здесь сами деревья нас защищают\". – Клыкастый страж","Заклинание",[],["Демасия"],"РЕДКОЕ"],"02DE001":["Массированный удар","Выберите врага. Два союзника по очереди нанесут ему удар.","","\"За мной, дружно!\" – Клыкастый страж","Заклинание",[],["Демасия"],"ОБЫЧНОЕ"],"02SI005":["Вытягивание магии","Выбросьте из колоды 3 карты.\nВосстановите союзникам по 3 ед. здоровья.","","\"Я очищу Острова от скверны!\" – Маокай","Заклинание",[],["Сумрачные острова"],"РЕДКОЕ"],"02SI010":["Странник мертвого сада","Призвав меня, выбросьте из колоды 3 карты.","","\"Огромный энт продолжает демонстрировать… существа… следом за ним прорастают цветы… удивительно, как… Воистину, это Благословенные острова!\" – Обрывки дневниковых записей","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"02SI008":["Маокай","Впервые призвав другого союзника в каждом раунде, выбросьте из колоды 2 карты и призовите карту Саженец.","Ваши бойцы погибали или ваши карты были выброшены из колоды 25+ раз.","Проклятие этих земель не сломит Маокая. Слишком глубоко пустили в нем корни ярость и чувство долга. Теперь ничто не остановит злого энта.","Боец",[],["Сумрачные острова"],"Чемпион"],"02SI007":["Шипастая жаба","Предсмертный вздох: выбросьте из колоды 2 карты и восстановите 2 ед. здоровья своему нексусу.","","\"…удивительное создание... тот самый, которого я нашел в детстве… он нисколько не вырос. Интересно… в следующем городе. Быть может, эти дивные создания живут вечно!\" – Обрывки дневниковых записей","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"02SI003":["Гроза морей","Союзные морские чудовища получают Устрашение.\nАтака: дайте врагам -2|-0 до конца раунда.","","Они слишком поздно заметили опасность. Гигант ринулся к ним, широко распахнув пасть. Охотникам оставалось лишь смириться со своей судьбой, когда на бессчетных зубах захрустели доски их корабля.","Боец",["МОРСКОЕ ЧУДОВИЩЕ"],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"02SI001":["Сборщик с Неполяны","Когда погибнет другой союзник, истощите вражеский нексус на 1 ед. здоровья.","","\"…случайно встретил Нивена… новый паромщик. Он отвез нас в… кстати, он неплохо поет. Прежде чем… надо пригласить его на ужин\". – Обрывки дневниковых записей","Боец",[],["Сумрачные острова"],"РЕДКОЕ"],"02SI002":["Хищные лозы","Разыгрывая сторонника, убейте его, чтобы призвать карту Хищные лозы.","","\"Сегодня… еще один удивительный росток… появился возле… дети испугались. Но… был не опасен. Тыкался в ладонь… доверчивое создание. Надо собрать побольше ягод\".\n– Обрывки дневниковых записей","Боец",[],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"02SI004":["Оскверненный служитель","Разыгрывая карту: убейте союзника, чтобы призвать 2 Саженца.","","\"Каждое сердце – сад, в котором могут вырасти корни\".","Боец",[],["Сумрачные острова"],"РЕДКОЕ"],"02SI006":["Дух чащи","После гибели первого союзника даруйте мне +2|+2.","","Обитатели Сумрачных остров давно отбросили все сантименты. Главное – утолить голод.","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"02SI009":["Бросок саженца","В начале следующего раунда призовите карту Саженец.","","\"У-и-и!\" – Саженец","Заклинание",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"02IO008":["Звуковая волна","Дайте союзнику возможность выбирать противника до конца раунда.\nСоздайте в руке мимолетное заклинание Резонирующий удар.","","\"Победив себя…\" – Ли Син","Заклинание",[],["Иония"],"ОБЫЧНОЕ"],"02IO002":["Чешуя Дракона","Когда меня призывают, создайте в руке карту Драконья защита.","","\"Ученику следует проявлять сострадание, ибо Дракон вскормил Исконную землю и даровал ей тепло и жизнь\". – Из учений Дракона","Боец",[],["Иония"],"ОБЫЧНОЕ"],"02IO006":["Ли Син","Разыграв заклинание, дайте мне Выбор противника до конца раунда.\nРазыграв еще одно, дайте мне Щит до конца раунда.","Вы разыграли 8+ заклинаний.","\"Дракон помогает достойным. Усталым он дарует силы. Больным – утешение. Заблудшим – свет. Сбитым с толку – равновесие...\"","Боец",[],["Иония"],"Чемпион"],"02IO004":["Рога Дракона","","","\"Ученик должен стараться изо всех своих сил, как Дракон, который вытащил землю из моря и дал нам сушу, где мы смогли расселиться\". – Из учений Дракона","Боец",[],["Иония"],"ОБЫЧНОЕ"],"02IO003":["Око Дракона","Начало раунда: Прилив: призовите карту Дракончик.","","\"Ученику должна быть присуща ясность мысли, ибо Дракон влечет солнце по небу, позволяя видеть окружающий мир\".\n– Из учений Дракона","Боец",[],["Иония"],"ЭПИЧЕСКОЕ"],"02IO001":["Когти Дракона","Когда я в руке, призовите меня, разыграв 2 заклинания в одном раунде.","","\"Ученик должен слушать внимательно, ибо Дракон прорычал первые звуки, благословив юные души людей волшебным даром\". – Из учений Дракона","Боец",[],["Иония"],"ОБЫЧНОЕ"],"02IO005":["Удар ладонью","Оглушите врага и призовите карту Хвост Дракона.","","\"Никто не видел моего ухода… и не увидит возвращения\". – Хвост Дракона","Заклинание",[],["Иония"],"РЕДКОЕ"],"02IO010":["Отступление","Верните союзника, чтобы создать в руке мимолетную карту Зов долга.","","Первые ноксианцы, высадившиеся на берег Ионии, столкнулись со слабым и неподготовленным противником. Бессчетное множество ионийцев погибло, но горстке воинов удалось спастись…","Заклинание",[],["Иония"],"РЕДКОЕ"],"02IO007":["Ярость Дракона","Союзник наносит удар сначала врагу, а затем вражескому нексусу.\nЕсли враг выживет, верните его.","","\"Дракона нужно выпустить на волю, иначе он сожжет нас изнутри\". – Ли Син","Заклинание",[],["Иония"],"ЭПИЧЕСКОЕ"],"02IO009":["Глубокая медитация","Прилив: моя стоимость снижается на 2.\nВытяните 2 других заклинания.","","Медитация – это путешествие без конечной цели. Это путь, который можно пройти, лишь сойдя с него.","Заклинание",[],["Иония"],"РЕДКОЕ"],"03NX019":["Охота на слабых","Противник сбрасывает из руки слабейшего сторонника.","","\"В этом мире нет места для слабых. Каждый день приносит новые муки, все туже сжимая нас в тисках. Я дарую не смерть. Я дарую милосердие\".\n – Аррель, следопыт","Заклинание",[],["Ноксус"],"РЕДКОЕ"],"03NX022":["Дикие когти","Союзник наносит удар врагу. Если у этого союзника есть Пробивание, избыточный урон будет нанесен вражескому нексусу.","","\"О-о, похоже, наш дикарь сегодня особенно свиреп! Держитесь подальше от его когтей, ребятки!\" \n– Комментатор боев","Заклинание",[],["Ноксус"],"ЭПИЧЕСКОЕ"],"03NX007":["Ривен","Призвав меня, используйте перековку, если у вас есть жетон атаки, либо когда вы получаете жетон атаки.","Вы создали карту Клинок Изгнанницы.","\"Я не буду бежать от своего прошлого. Я дала обещание. Я восстановлю то, что сломала…\"","Боец",[],["Ноксус"],"Чемпион"],"03NX006":["Рукоять меча","Дайте союзнику +2|+0 до конца раунда. Используйте перековку.","","\"Чтобы понять врага, нужно присмотреться к его оружию. Оно расскажет, как он двигается, как думает и как наносит удар. Оружие – квинтэссенция своего владельца\". – Аррель, следопыт","Заклинание",[],["Ноксус"],"ОБЫЧНОЕ"],"03NX002":["Аррель, следопыт","Конец раунда: если в этом раунде вы разыграли заклинание, выбрав меня целью, я нанесу удар слабейшему врагу.","","\"Прячься – и мы тебя найдем.\nДыши – и мы тебя услышим.\nБеги – и мы тебя загоним\".","Боец",[],["Ноксус"],"ЭПИЧЕСКОЕ"],"03NX018":["Задержание","Оглушите врага.\nЕсли у вас есть чемпион Дариус, используйте Рвение.","","\"Я справлюсь сам\". – Дариус","Заклинание",[],["Ноксус"],"РЕДКОЕ"],"03NX009":["Гневная всадница","","","\"Ничто не сравнится с охотой на другую воительницу. Чтобы выследить ее, нужно думать и чувствовать, как она. Чтобы поймать – бояться ее так же, как она тебя. Мало кто чувствует такую связь, но для меня нет ничего желаннее\".","Боец",[],["Ноксус"],"ОБЫЧНОЕ"],"03NX017":["Кровожадный василиск","Разыгрывая карту: 4 раза нанесите союзнику и врагу 1 ед. урона.","","За несколько дней до сражения дрессировщики перестают давать василискам живой корм. Когда зверей наконец спускают на противника, они становятся совершенно неуправляемы и уже не разбирают, где свой, где чужой.","Боец",["РЕПТИЛИЯ"],["Ноксус"],"ЭПИЧЕСКОЕ"],"03NX015":["Навыки выживания","В этом раунде у союзников не может стать меньше 1 ед. здоровья.\nЕсли меня сбрасывают, у сильнейшего союзника не может стать меньше 1 ед. здоровья до конца раунда.","","\"Драконьи гончие взяли след. Они найдут ее, и мы призовем ее к ответу. Только так и никак иначе!\"\n – Аррель, следопыт","Заклинание",[],["Ноксус"],"РЕДКОЕ"],"03NX014":["Твердая решимость","Дайте союзнику +3|+2 до конца раунда.","","\"Я буду просто счастлив чистить ваше оружие, ухаживать за вашими зверями и стряпать для вас еду. Я же ни на что больше не гожусь, да?\" – Эраф, оруженосец","Заклинание",[],["Ноксус"],"ОБЫЧНОЕ"],"03NX003":["Оруженосец","Предсмертный вздох: используйте перековку.","","\"Все как обещали охотницы: сотня дней и столько же ночей. Сотня мозолей на ногах, сотня букашек в пайке, сотня фраз \"клинок то\" и \"возмездие се\". И явно больше сотни затрещин от этой троицы…\" ","Боец",[],["Ноксус"],"ОБЫЧНОЕ"],"03NX001":["Рунотворец","Призвав меня, используйте Перековку.","","\"Обычное оружие – грубый инструмент, предназначенный для таких же грубых рук. А вот клинок, наполненный рунной магией, – это уже не просто сталь\".","Боец",[],["Ноксус"],"ОБЫЧНОЕ"],"03NX005":["Жестокая охотница","Призвав меня, дайте мне Быструю атаку до конца раунда.","","\"Вот ты где. Мы ЗНАЛИ, что без боя ты не сдашься. Скорее даже надеялись...\"","Боец",[],["Ноксус"],"РЕДКОЕ"],"03BW006":["Джек Победитель","Начало раунда: создайте в руке карту Корм для рыб.","","Долгие годы на ринге стали для Джека школой жизни. Он узнал, как тесно связаны возможность пустить кровь и заставить себя бояться. Он научился подавлять волю одним взглядом. А еще – познал силу, которую дает неограниченная жестокость.","Боец",[],["Билджвотер"],"ЭПИЧЕСКОЕ"],"03BW010":["Завтрак на воде","Союзник берет в плен другого союзника и получает его характеристики.","","\"Заходи, дружок, – и все, о чем ты мечтал, станет твоим… навсегда\". – Таам Кенч","Заклинание",[],["Билджвотер"],"ОБЫЧНОЕ"],"03BW005":["Разбитые надежды","Уберите бойца или место силы в его колоду.","","\"Нет, дружок. Я дал тебе именно то, чего ты хотел. Но никто не обещал, что счастье будет длиться вечно…\"\n– Таам Кенч","Заклинание",[],["Билджвотер"],"РЕДКОЕ"],"03BW004":["Таам Кенч","Призвав меня или в начале раунда: создайте в руке карту Жор.","Мне удалось взять в плен 3+ бойцов. Когда мой уровень повышается, уничтожьте моих плененных врагов и освободите союзников.","\"По лицу вижу, о чем ты думаешь, дружок. Ты считаешь, что судьба сдала тебе не те карты, которые ты заслуживаешь. Ты хочешь лучшей жизни, правда? Позволь мне утолить твой голод – и ты насладишься всем, о чем когда-либо мечтал. Просто подпиши одну пустячную бумажку… и жизнь твоя станет счастливой\".","Боец",[],["Билджвотер"],"Чемпион"],"03BW002":["Светский ящер","Начало раунда: нанесите мне 2 ед. урона.","","\"Люди такие дураки! Усади их в тепло, налей в кружку чего-нибудь холодненького да улыбнись – и они тебе все секреты выложат. А кто улыбается обаятельнее юного Леонарда?\" – Ворожаба","Боец",[],["Билджвотер"],"ОБЫЧНОЕ"],"03BW014":["Обезьянничанье","Призовите карту Пороховая обезьяна.\nРазграбление: в начале следующего раунда призовите еще одну.","","\"Ах, вы считаете их милыми? Так вот: это НЕ ТАК. Они всюду лезут. Грязи от них больше, чем от курьера с морской болезнью. И они вообще НЕ ЗАТЫКАЮТСЯ. БОЛЬШЕ НИКАКИХ ОБЕЗЬЯН НА КОРАБЛЕ! Это не обсуждается!\" – Младший офицер","Заклинание",[],["Билджвотер"],"ОБЫЧНОЕ"],"03BW007":["Боксминог","Разыгрывая карту: нанесите мне 3 ед. урона.","","\"Может, Пабло сейчас и не в лучшей форме… Еще бы – его же сколько мутузили! Но знаете что? Больше вам тут ни один боец не покажет октокилл!\" – Сомодур","Боец",[],["Билджвотер"],"ОБЫЧНОЕ"],"03BW016":["Брандер","Нанесите бойцу 1 ед. урона.\nПризовите Пороховые бочки в количестве, равном нанесенному урону.","","\"Юный Герент закричал: 'Полундра!' – и в этот момент грохнул первый взрыв. Корпус встряхнуло, стаксель загорелся, но \"Джиллдоу\" выдержала. А потом я проследил за взглядом Герента и увидел, что к нам плывет еще четыре лодки, битком набитых порохом\".\n – Выживший с \"Джиллдоу\"","Заклинание",[],["Билджвотер"],"РЕДКОЕ"],"03BW001":["Кровавые доки","Начало раунда: выбросьте из колоды 1 карту. Если вы на глубине, разрушьте меня, чтобы призвать случайное Морское чудовище.","","Каждый день местные жители ходят в Кровавые доки поглазеть на чудовищ, выловленных билджвотерскими рыбаками. Как правило, чудовища уже мертвы. Как правило.","Место силы",[],["Билджвотер"],"ЭПИЧЕСКОЕ"],"03BW015":["Заноза","Разыгрывая карту: нанесите мне 2 ед. урона.","","\"СКОРЕЙ ЗВОНИТЕ В ГОНГ! Я ПОКАЖУ ЭТОЙ СТАРОЙ КОЛЮЧКЕ, КАК ПОЛУЧИЛ СВОИ ПРОЗВИЩА! МЕНЯ НАЗЫВАЮТ ПАБЛО ОСЬМИНОКАУТ! КРОСС-КРАКЕН! УБОЙНОЕ ЩУПАЛЬЦЕ! КОГДА Я С ТОБОЙ ПОКОНЧУ, ТЫ ПОБЕЖИШЬ К МАМОЧКЕ, ПОДЖАВ СВОЕ ЖАЛКОЕ ЖАЛО!\" – Боксминог","Боец",[],["Билджвотер"],"ОБЫЧНОЕ"],"03BW003":["Сомодур","Разыгрывая карту: нанесите 1 ед. урона всем остальным союзникам и даруйте мне +1|+0 за каждого.","","Борьба за власть зачастую ведется грязно, но редко – настолько бездарно.","Боец",[],["Билджвотер"],"РЕДКОЕ"],"03BW017":["Верткий бормотун","Моя стоимость снижается на 1 за каждое заклинание, разыгранное вами в этом матче.\nПризвав меня, создайте в руке случайное заклинание из своих регионов стоимостью 1.","","\"Стой сми'но, 'екрут! Твоя задача – п'оникнуть за линию ф'онта, 'азместить как можно больше пузы'иков и доложить обо всем, что ты увидишь! ОБО ВСЕМ! Это ясно?\" – Адмиял Шелли из Черепашьей артиллерии","Боец",[],["Билджвотер"],"ЭПИЧЕСКОЕ"],"03BW008":["Ворожаба","Разыгрывая карту: нанесите мне и союзнику 1 ед. урона, чтобы вытянуть 1 карту.","","\"Бывает и на нашу Бабулю проруха. В свое время она убила парочку местных, но, пожалуй, бурное прошлое ее только украшает\". – Светский ящер","Боец",[],["Билджвотер"],"ОБЫЧНОЕ"],"03BW020":["Пороховая феерия","Призовите карту Пороховая обезьяна за каждый раз, когда вы в этом матче активировали Разграбление.","","\"Эти чумазики могут быть полезны. Подсказка: они любят фейерверки. Нужно лишь взорвать пороховой склад противника – а обезьянки сделают остальное\". \n– Мисс Фортуна","Заклинание",[],["Билджвотер"],"ЭПИЧЕСКОЕ"],"03BW009":["Вымогательство","Нанесите союзнику 2 ед. урона, чтобы даровать двум врагам Уязвимость.","","\"Или ты признаешься, куда спрятал 'лишние бочки', Слим, или Джимбо проверит, насколько крепко твой язык держится за зубами. На твоем месте я бы не стал недооценивать Джимбо\". – Сомодур","Заклинание",[],["Билджвотер"],"РЕДКОЕ"],"03DE010":["Главная площадь","Призвав союзника, дайте ему +1|+1 и Выбор противника до конца раунда.","","Тианна окинула взглядом выстроившееся на площади войско. Единственным звуком был шелест ее знамени, развевавшегося на ветру. Тианна коротко кивнула и подняла знамя. \"Кто готов сразиться за Демасию?\" – крикнула она, и от мощного отклика собравшихся вздрогнули горы. ","Место силы",[],["Демасия"],"ЭПИЧЕСКОЕ"],"03FR009":["Воющая бездна","Начало раунда: создайте в руке случайного чемпиона 2 уровня, которого нет в руке, в колоде или на поле.","","Героев на этот мост приводит зов неизведанного. Они готовы идти по крошащимся камням навстречу холодному ветру, чтобы узнать, что ждет их впереди: победа или смерть.","Место силы",[],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"03MT005":["Расходящиеся пути","Вытяните место силы или разрушьте место силы.","","Таргон – непредсказуемое место, где ломается несокрушимое, а разбитое вновь становится целым.","Заклинание",[],["Таргон"],"ОБЫЧНОЕ"],"03SI009":["Хранилища Гелии","Начало раунда: Если это возможно, убейте самого дорогостоящего союзника, чтобы призвать из колоды союзника стоимостью на 1 больше.","","Души охотно стремятся в это проклятое место – стоит только пообещать им вечную жизнь и несметные богатства.","Место силы",[],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"03IO006":["Монастырь Хираны","Начало раунда: создайте в руке карту Святилище.","","В ионийских горах скрыто множество святилищ, где можно обрести внутреннее равновесие и собраться с духом.","Место силы",[],["Иония"],"ЭПИЧЕСКОЕ"],"03NX013":["Выжженная земля","Убейте раненого бойца или уничтожьте место силы.","","\"Драконьи гончие взяли след. Они найдут ее, и мы призовем ее к ответу. Только так и никак иначе!\" – Аррель, следопыт","Заклинание",[],["Ноксус"],"ОБЫЧНОЕ"],"03NX004":["Арена Нокскраи","Конец раунда: ваш сильнейший союзник и слабейший враг наносят друг другу удар.","","\"Поклонники ур-р-равнителей, вы готовы к НЕВЕРОЯТНОМУ зрелищу в КОЛЬЦЕ ОГНЯ? Фокус Покус сегодня вытянул несчастливый жребий! Ему придется сражаться с печально знаменитым ГРА-А-АНАКОМ ВЕЛИКИМ! Зовите лекарей! Этот бой будет быстрым!\" – Комментатор боев","Место силы",[],["Ноксус"],"ЭПИЧЕСКОЕ"],"03DE004":["Капитан Аррика","Разыгрывая карту: плените бойца или место силы.","","Ноксус разорил родные земли Аррики, когда она была маленькой девочкой. Девушка стала солдатом и поклялась, что больше не позволит Ноксусу поднять свой флаг над Демасией и оставить сиротой хотя бы одного ребенка.","Боец",["ЭЛИТА"],["Демасия"],"РЕДКОЕ"],"03IO005":["Возвращение домой","Верните своего бойца или место силы, чтобы вернуть вражеского бойца или место силы.","","\"Трев-в-в-ор! Верни-и-ись!\" – Жилище Тревора","Заклинание",[],["Иония"],"ОБЫЧНОЕ"],"03MT052":["Звездный родник","Конец раунда: восстановите раненым союзникам по 1 ед. здоровья. Вы выигрываете, если на моих глазах в сумме восстанавливаете союзникам 22+ ед. здоровья.","","\"Журчит родник священных звезд,\nСияя, как кометы хвост;\nОн лечит хвори и печали.\nПослушай, как река поет,\nЛаская склон горы кристальной\".\n– стихотворение оттрани","Место силы",[],["Таргон"],"ЭПИЧЕСКОЕ"],"03MT064":["Вершина Таргона","Начало раунда: уменьшите стоимость случайной карты в руке каждого игрока до 0 до конца раунда.","","Врата, за которыми вращаются небесные сферы, охраняет хрустальный страж Таргона. Он испытывает того, кто достиг вершины, пронзая взглядом все бренное; с души сходит шелуха страха, надежд и сомнений, открывая истинную сущность путника. Именно по ней великий Судия Вершины выносит свой вердикт. ","Место силы",[],["Таргон"],"ЭПИЧЕСКОЕ"],"03SI008":["Крах","Убейте союзника, чтобы убить бойца или разрушить место силы.","","Ничто не вечно на этих проклятых островах. Всему приходит конец.","Заклинание",[],["Сумрачные острова"],"РЕДКОЕ"],"03PZ001":["Пилтоверский университет","Начало раунда: сбросьте вашу руку. Создайте в руке 3 случайные карты. Они будут мимолетными.","","Славу профессору Сесилу Б. Хеймердингеру принесли изобретения, но именно его увлекательные лекции и непредсказуемые эксперименты произвели самое неизгладимое впечатление на лучшие умы Пилтовера.","Место силы",[],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"03FR003":["Смотрящее","Разыгрывая карту: Уничтожьте ВСЕ места силы или нанесите 3 ед. урона ВСЕМ остальным бойцам.","","\"Мы не успели ни вынести вещи, ни предупредить остальных. Только добежать до леса и оттуда наблюдать, как оно уничтожает наши дома\".\n – Дозорный племени аваросан","Боец",[],["Фрельйорд"],"РЕДКОЕ"],"03MT026":["Рахвун, Копье полудня","День: создайте в руке случайную дневную карту.\nДля нас всегда день.","","\"Держись своей веры, Ра-Хорак, и наш свет никогда не померкнет!\"","Боец",[],["Таргон"],"РЕДКОЕ"],"03MT067":["Кристальный козерог","Разыгрывая карту: даруйте союзнику Пробивание.","","Тем, кто хочет совершить восхождение на Таргон, стоит подружиться с местной живностью. Горные козлы быстрее всех скачут по обледеневшей земле и лучше всех знают опасности каменных склонов.","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"03MT084":["Сотворение звезд","Позовите творение небес стоимостью 7 или более, затем восстановите своему союзнику или нексусу 5 ед. здоровья.","","\"Посмотри на звезды. Если повезет, встретишь мой взгляд\". – Аурелион Сол","Заклинание",[],["Таргон"],"ОБЫЧНОЕ"],"03MT221":["Клыки","Разыгрывая карту: позовите творение небес стоимостью 3 или менее.","","\"Матерь луна, укажи мне путь,\nЗаставь небесную твердь разойтись\nИ позволь мне узреть, что лежит за ее пределами\".\n– Молитва Лунари","Боец",[],["Таргон"],"ЭПИЧЕСКОЕ"],"03MT093":["Лови звезду","Нанесите 5 ед. урона врагу, который атаковал в этом раунде или оглушен.","","\"БаБАХочки!\" – Зои","Заклинание",[],["Таргон"],"ОБЫЧНОЕ"],"03MT073":["Лунари – вестница заката","Когда меня призывают, создайте в руке карту Пыльца цветка заката.","","\"Цветок заката распускается с наступлением ночи, при свете полной луны. Мы, Лунари, с гордостью носим его изображение, ведь мы веками собирали его пыльцу – и никто, кроме нас, не умеет делать это без вреда для себя\".","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"03MT002":["Небо рушится на землю","Моя стоимость снижается на 2 за каждого имеющегося у вас союзного дракона или небесное создание. Нанесите 15 ед. урона всем врагам.","","\"Придет время, и я покараю Рунтерру в назидание другим. Быть может, буду носить ее тлеющую оболочку с собой, как игрушку… сломанную и никому не нужную. Пока не знаю, до конца еще не обдумал\". – Аурелион Сол","Заклинание",[],["Таргон"],"ЭПИЧЕСКОЕ"],"03MT217":["Афелий","Ночь: выберите, какое Лунное оружие создать в руке.\nВпервые сыграв 2 другие карты в каждом раунде, создайте в руке Лунное оружие текущей фазы, если его еще нет.","Вы разыграли 4+ Лунных оружия.","\"В каждом сражении мы учим Солари нас уважать. Мы показали им, что свет луны ничем не уступает солнечному, и что не следует пренебрегать тем, чего не знаешь. Что же до остальных уроков…\"  \n– Певец убывающей луны","Боец",[],["Таргон"],"Чемпион"],"03MT044":["Солнечный защитник","День или при использовании другого дневного эффекта: даруйте мне +1|+1.","","\"Сияющий страж, твой гнев обжигает, как полуденное солнце. Приди и покарай тех, кто посмел вторгнуться в это священное место\".\n– Надпись на постаменте Солнечного защитника","Боец",[],["Таргон"],"ЭПИЧЕСКОЕ"],"03MT056":["Диана","Ночь или срабатывание другого ночного эффекта: дайте мне Выбор противника до конца раунда.","Вы использовали навык Ночь 4+ раза.","Перед боем она стояла в своем сине-серебряном облачении, и глаза ее сияли, как звезды. Восходящая луна озарила ее, и присутствовавшие при этом Лунари прикрыли глаза, мысленно произнося слова благодарности и молясь о том, чтобы ей была дарована защита.","Боец",[],["Таргон"],"Чемпион"],"03MT020":["Великолепный звезднорог","Разыгрывая карту: восстановите союзнику и своему нексусу по 3 ед. здоровья.","","\"Видишь ту звездочку, что движется по ночному небу? Это взрослый звезднорог. Их детеныши дарят нам свою целебную магию, пока мы не возвращаем их на небосклон, а взрослые могут пользоваться ею сами. Увидеть звезднорога и понять, кого именно увидел, – великая удача. Еще большая удача – заботиться о таком существе\". – Лидари, Пастырь звезд","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"03MT091":["Крутая звездная карта","Позовите творение небес стоимостью 3 или менее.","","\"А эти три сверхъяркие звездочки я назову… созвездием Скакалки! А может, это перевернутый смайлик?\" – Зои","Заклинание",[],["Таргон"],"РЕДКОЕ"],"03MT047":["Сигнус, лунный следопыт","Ночь: дайте союзнику Изворотливость до конца раунда.","","Лунари дождались наступления сумерек, обещавших безопасность. Казалось, что впереди на тропе никого нет, но Сигнус знал, что лагерь Солари совсем рядом. По его жесту остальные тихо последовали за ним.","Боец",[],["Таргон"],"ЭПИЧЕСКОЕ"],"03MT094":["Разведчица Лунари","Ночь: даруйте мне Изворотливость.","","\"Обратим глаза к небесам, к солнцу, к нашей госпоже… Постойте, что это… что это такое?\" – Жрица Солари","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"03MT036":["Благословение Таргона","Даруйте союзнику +3|+3.","","\"Подарочек с Таргона\". – Тарик","Заклинание",[],["Таргон"],"РЕДКОЕ"],"03MT092":["Горный козел","Удар: создайте в руке карту Самоцвет.","","Таргонские козы опасней своих обычных сородичей, поскольку их рога состоят из кристаллов, которые при ударе откалываются и могут сильно поранить противника. ","Боец",[],["Таргон"],"РЕДКОЕ"],"03MT060":["Крепкий защитник","Начало раунда: восстановите 3 ед. здоровья своему нексусу. Нанесите мне урон, равный восстановленному здоровью.","","\"Никто не знает тропы Таргона лучше меня, поэтому мне доверяют самых, так сказать, самостоятельных звезднорогов. Хорошо, что у них есть я!\" ","Боец",[],["Таргон"],"ЭПИЧЕСКОЕ"],"03MT001":["Крылатые прохвостики","Разыгрывая карту: оглушите всех врагов с силой не более 2.","","На склоне горы в хрустальной тишине иногда был слышен звон падающих льдинок, а откуда-то сверху доносился звук, подозрительно напоминавший смех.","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"03MT055":["Сорака","Поддержка: восстановите мне и союзнику, которого я поддерживаю, 4 ед. здоровья.","Вы исцелили раненых союзников 4+ раза.","\"По сути своей исцеление бескорыстно. Вы не черпаете в других силу: они дают ее добровольно. Проявите сострадание – и увидите, как просияет лицо исцеленного\".","Боец",[],["Таргон"],"Чемпион"],"03MT048":["Дарительница","Когда меня призывают, создайте в руке карту Самоцвет.","","\"Говорят, сам Заступник благословил эти самоцветы. Носи их – и почувствуешь его присутствие\".","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"03MT082":["Утренний свет","Дайте союзникам +1|+1 до конца раунда.\nАктивируйте дневной эффект союзника.","","\"Мы встаем на заре и идем на свет!\" – Леона","Заклинание",[],["Таргон"],"РЕДКОЕ"],"03MT058":["Тарик","Поддержка: я и союзник, которого я поддерживаю, получаем Стойкость до конца раунда. Последнее заклинание, которое вы применили только ко мне в этом раунде, применяется и к этому союзнику (повторное копирование невозможно).","На моих глазах вы выбрали целью или поддержали союзников 7+ раз.","\"Ласковая доброта Тарика позволяет каждому, кто его встретит, найти тепло в собственной душе – а оно поддержит даже в самую холодную ночь\".\n– Горный гадатель","Боец",[],["Таргон"],"Чемпион"],"03MT062":["Сияющая хохотушка","Разыгрывая карту: если вы владеете творением небес, даруйте союзнику +1|+1 и Щит от магии.","","\"…а светульки похожи на звездную пыль, только они умеют взлетать обратно в небо, а вообще они ужасно хорошенькие, и я видела одного прошлой ночью – ой, я проголодалась – так вот, он взлетел к самым ЗВЕЗДАМ, а потом…\"","Боец",[],["Таргон"],"РЕДКОЕ"],"03MT040":["Светулек","","","\"Надежда – хрупкое создание, которое стремится взлететь все выше. Не пытайтесь его ловить\".\n– Жрица Лунари","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"03MT086":["Художница-чудачка","Разыгрывая карту: сбросьте 1 карту, чтобы позвать творение небес стоимостью 3 или менее.","","\"Это мое любимое созвездие! Я зову его \"Метафизическая сущность самопознания\". Хотя, если склонить голову вот так, оно больше похоже на пару ложек\".","Боец",[],["Таргон"],"РЕДКОЕ"],"03MT016":["Трогательный топотун","","","\"Топотун! Думаешь, ты такой большой, что не пролезешь в этот портальчик? Ну ничего, сейчас я тебя… ХА-ХА-ХА! Шучу. ВПЕРЕД!\" – Зои","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"03MT054":["Леона","День: оглушите сильнейшего врага.","Вы активировали навык День 5+ раз.","Перед боем она стояла в своем ало-золотом облачении, и глаза ее горели, как раскаленные угли. Восходящее солнце увенчало ее своими лучами, и присутствовавшие при этом Солари потупили взор – не от стыда, а от выражения величайшего почтения своей сияющей предводительнице.","Боец",[],["Таргон"],"Чемпион"],"03MT220":["Расколотый путь","Ночь: оглушите врага. Если это сторонник, вновь оглушите его в начале следующего раунда.","","\"Матерь луна, это наша ночь.\nПомоги остановить тех, кто хочет причинить нам вред,\nИ заставь их пожалеть об этом\".\n – Молитва Лунари","Боец",[],["Таргон"],"РЕДКОЕ"],"03MT021":["Раскалывающие разум","Разыгрывая карту: выберите 2 врагов.\nНачало раунда: оглушите их.","","Говорят, что путники, взглянувшие этому существу в глаза, постигли нечто столь значимое и вместе с тем пугающее, что их разум не выдержал и помутился.","Боец",["ДРАКОН"],["Таргон"],"ЭПИЧЕСКОЕ"],"03MT006":["Инвиолус Вокс","В каждом раунде, когда союзник с Яростью впервые убивает врага, создайте в руке случайного сторонника-дракона.","","\"Подними голову к небу и узри то, что вижу я. Сначала – сигнал, ибо ночью они сияют. Затем – ярость, ибо днем все полыхает. Ты увидишь! Все увидят!\" – Драконья вестница","Боец",["ДРАКОН"],["Таргон"],"ЭПИЧЕСКОЕ"],"03MT015":["Узрите бесконечность","Зов","","Над тобой распростерлось небо – необъятный черный гобелен с мерцающими звездами, на фоне которого ты кажешься себе маленьким и тусклым. Куда ты обратишь взор в первую очередь?","Заклинание",[],["Таргон"],"ОБЫЧНОЕ"],"03MT013":["Лунная болезнь","Примените к 2 вражеским бойцам Безмолвие до конца раунда.\nНочь: в этом раунде они не могут блокировать.","","\"Тому, кто не способен видеть при свете Луны, придется этому научиться – иначе он вовсе ничего не увидит\".\n– Диана","Заклинание",[],["Таргон"],"ОБЫЧНОЕ"],"03MT009":["Зои","Удар по нексусу: создайте в руке карту Крутая звездная карта. Если она у вас уже есть, уменьшите ее стоимость на 1.","На моих глазах вы разыграли 10 разных карт.","\"Приве-е-ет! А что это ты делаешь? Играешь в КАРТЫ? Можно мне тоже поиграть? Что? Я УЖЕ в игре? Какое смешное измерение!\"","Боец",[],["Таргон"],"Чемпион"],"03MT087":["Аурелион Сол","Разыгрывая карту: позовите творение небес стоимостью 7 или более.\nНачало раунда: создайте в руке случайное творение небес.","Конец раунда: у ваших союзников в сумме 20+ ед. силы.","\"Мне безразлично, что ты обо мне напишешь, жалкое создание! Только обязательно укажи, что я красивый. И величественный. И очень, очень умный. Ты знаешь, как пишется 'величественный'?\"","Боец",["ДРАКОН"],["Таргон"],"Чемпион"],"03MT019":["Бастион","Даруйте союзнику +1|+1 и Щит от магии.","","\"За честь Горы\". – Тарик","Заклинание",[],["Таргон"],"ОБЫЧНОЕ"],"03MT214":["Полет","Удар по нексусу: вытяните одну карту и поместите меня среди 3 верхних карт в колоде.","","\"Матерь луна, даруй мне твердость в убеждениях \nи уверенность в Полете.\nНаставь меня на путь истинный\".\n– Молитва Лунари","Боец",["ПТИЦА"],["Таргон"],"РЕДКОЕ"],"03MT071":["Пилигрим Тиари","Поддержка: даруйте союзнику, которого я поддерживаю, +0|+2.","","Отправляясь в дорогу, доверься ей, и она неизбежно изменит тебя. Ты возьмешь в путь что-то новое… и оставишь позади что-то, принадлежавшее тебе-прежнему. ","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"03MT008":["Желание","Полностью исцелите раненых союзников.","","\"За жизнь!\" – Сорака","Заклинание",[],["Таргон"],"РЕДКОЕ"],"03MT023":["Солнечная вспышка","Нанесите бойцу 6 ед. урона\nДень: вместо этого примените к нему Безмолвие до конца раунда и нанесите ему 6 ед. урона.","","Мало что выживает под пристальным взглядом Солнца.","Заклинание",[],["Таргон"],"РЕДКОЕ"],"03MT045":["Астральная защита","Восстановите союзнику 4 ед. здоровья и даруйте ему +0|+4.","","\"Думаешь, тебе удалось нас победить? Ну нет, это только начало!\" – Крепкий защитник","Заклинание",[],["Таргон"],"ОБЫЧНОЕ"],"03MT080":["Хранитель родника","Когда меня призывают, создайте в руке карту Целебная вода.","","\"Вообще-то моя главная обязанность – смотреть за родником, но часто приходится еще и за стадом приглядывать... Бывает трудно уследить за всем сразу\".","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"03MT042":["Маленькая хитрюга","Воплотите вражеское заклинание, примененное в этой игре.","","\"Это было потрясно! Но было бы намного лучше, если б это сделала я! СПАСИБОДОСВИДАНЬЯ!\" – Зои","Заклинание",[],["Таргон"],"РЕДКОЕ"],"03MT057":["Солнечный кузнец Солари","День: дайте мне Вампиризм до конца раунда.","","Солнечный кузнец высоко поднял свою линзу, подставляя ее под лучи солнца. С помощью этого артефакта Солари зачаровал оружие ярким солнечным светом.","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"03MT041":["Самоцветный мудрец","Поддержка: даруйте союзнику, которого я поддерживаю, +2|+2.\nПредсмертный вздох: создайте в руке 3 Самоцвета.","","\"Вы поняли хоть слово из того, что он наговорил?\"\n\"Нет, но он показался нам дружелюбным\".\nЭмир и Хейли, скалолазы","Боец",["ЙОРДЛ"],["Таргон"],"ЭПИЧЕСКОЕ"],"03MT027":["Клинок зенита","Даруйте союзнику +1|+2. Дайте ему Пробивание до конца раунда.\nДень: вытяните карту Клинок зенита.","","\"Пусть солнце наделит тебя своей силой!\"\n– Жрица Солари","Заклинание",[],["Таргон"],"ОБЫЧНОЕ"],"03MT096":["Жрица Солари","День: позовите творение небес стоимостью 4–6.","","Солари не меньше других таргонцев полагаются на звезды. Превыше всего они почитают Солнце, а оно – тоже звезда.","Боец",[],["Таргон"],"РЕДКОЕ"],"03MT028":["Щитоносец Солари","День: дайте мне +0|+4 до конца раунда.","","\"Что ж ты не явилась под покровом ночи? Как глупо. – Щитоносец выпрямилась. – Сложи оружие и сдавайся\".\nЛунари молча пригнулась к земле, держа наготове изогнутые клинки.\nПусть будет так.\nСолари тоже приготовилась к бою и подняла щит, в котором отразились лучи восходящего солнца. ","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"03MT089":["Страж полумесяца","Ночь: даруйте мне +2|+0.","","\"Надежный страж, пусть лунный луч восстановит твои силы ласковым прикосновением. Пробудись и защити нас от тех, кто дерзнет вторгнутся в наше святилище\".\n– Надпись на постаменте Стража полумесяца","Боец",[],["Таргон"],"РЕДКОЕ"],"03MT051":["Напутственное касание","Восстановите союзнику или своему нексусу 2 ед. здоровья. Вытяните 1 карту.","","Звезднороги светят ярче, когда им хорошо.","Заклинание",[],["Таргон"],"ОБЫЧНОЕ"],"03MT003":["Драконье гнездо","Вытяните 2 разных драконов или даруйте союзным драконам +1|+1 и Пробивание.","","\"Их крик похож на хриплый кошачий ор. Если услышите его – скорее бегите и приведите стражу. Ясно? Ведь где драконьи яйца, там и драконы\". – Таргонский добытчик","Заклинание",[],["Таргон"],"РЕДКОЕ"],"03MT098":["Солнечная бодрость","Даруйте союзнику +0|+2.","","\"Наш щит – это наша решимость, убежденность и вера в свет!\" – Щитоносец Солари","Заклинание",[],["Таргон"],"ОБЫЧНОЕ"],"03MT215":["Лунные дары","Выберите Лунное оружие и создайте его в руке.","","\"Протяни руку, Афелий\". – Алуна","Заклинание",[],["Таргон"],"ОБЫЧНОЕ"],"03MT063":["Лунная сновидица","Разыгрывая карту: используйте Зов.\nНочь: снизьте стоимость призванной карты на 1.","","\"Погляди на наших друзей на звездном небе! Видишь эту большую и яркую звезду? Это Гонец смотрит на нас блестящим глазом. А вон то туманное скопление? Это Ловкач прячется за тучами. А вон те яркие точки… КУЛУН! Ты не поймаешь их лапой!\"","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"03MT100":["Дракон затмения","День: снизьте стоимость следующего дракона или творения небес на 2.\nНочь: Создайте в руке случайного дракона и случайного сторонника – творение небес.","","Чешуйка дракона (Дракон затмения Draco Obscuratus)\nПримечания: чешуйка обладает невероятными оптическими свойствами. Под прямыми солнечными лучами становится зеркальной.\nПриписка: А НОЧЬЮ СВЕТИТСЯ!\n– Из заметок Андена Майна, ученого-яйцеведа","Боец",["ДРАКОН"],["Таргон"],"РЕДКОЕ"],"03MT076":["Горный гадатель","Стоимость ваших творений небес снижается на 1.\nВерность: используйте Зов.","","\"У звезд можно многому научиться. Они – незыблемый ориентир, позволяющий проложить путь\".","Боец",[],["Таргон"],"РЕДКОЕ"],"03MT029":["Пастушка звезд","Исцеляя раненого союзника, даруйте мне +2|+0.","","\"Я полюбила звезднорогов с тех самых пор, как впервые увидела падающую звезду. Кто бы мне тогда сказал, что их в моей жизни будет так много!\"","Боец",[],["Таргон"],"РЕДКОЕ"],"03MT219":["Заоблачный храм","Впервые сыграв две другие карты в каждом раунде, восполните 2 ед. маны и даруйте сильнейшему союзнику +1|+0.","","Именно отсюда, из мира духов, Алуна общается со своим братом Афелием. Она нашептывает безмолвному убийце слова утешения и сквозь пелену между мирами передает ему оружие возмездия.","Место силы",[],["Таргон"],"РЕДКОЕ"],"03MT079":["Звездный сорванец","Если вы владеете творением небес, моя стоимость снижается на 2.","","\"Взрослые такие ЗАНУДЫ! А вот Зои и ее друзья – ничего так. Это у них я учусь всякому полезному! А не у этой сияющей жрицы. Она БЕСИТ.\"","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"03MT007":["Малыш-звезднорог","","","\"Детенышам звезднорогов, как и всем птенцам, нужно совершить первый полет. Если крылышки не выдерживают, малыши падают с неба, как обычные звездочки. К счастью, мы всегда готовы поймать их и вернуть на небо, когда они немного подрастут\".\n– Лидари, Пастырь звезд","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"03MT038":["Защитник белого пламени","","","Юных, более покладистых драконов в стародавние времена приручили таргонские ребятишки. Возможно, молодые драконы почувствовали невинное любопытство детей и не тронули их, а напротив, начали опекать. ","Боец",["ДРАКОН"],["Таргон"],"ОБЫЧНОЕ"],"03MT014":["Драконья вестница","Стоимость союзных драконов снижается на 1.","","Облака заклубились вокруг их могучих тел, и небо вздрогнуло от пронзительных криков. Она знала, что грядет, но не чувствовала страха, готовясь отдаться в объятия судьбы.","Боец",[],["Таргон"],"РЕДКОЕ"],"03MT110":["Не стой на пути","Все усиления союзников, которые должны действовать один раунд (кроме щита), становятся постоянными. Вытяните 1 карту.","","\"Ты знаешь, слов на ветер не бросаю.\nНе стой на пути, за себя не отвечаю!\nПришла побеждать, пришла побеждать.\nЯ сильней, не стану отступать\".\n– Кай'Са, \"THE BADDEST\"","Заклинание",[],["Таргон"],"ЭПИЧЕСКОЕ"],"03MT017":["Знак Гонца","Создайте в колоде 5 Гонцов.","","\"Идет время, рисунок звезд меняется. Змей уходит, и его место занимает Гонец. Нас ждет сезон изобилия…\"\n– Жрица Лунари","Заклинание",[],["Таргон"],"РЕДКОЕ"],"03MT025":["Осколки Горы","Заполните свою руку картами Самоцвета.","","\"Поверни драгоценный камень к свету, и он засияет. Так и в жизни смертных есть свой внутренний огонь\".","Заклинание",[],["Таргон"],"ЭПИЧЕСКОЕ"],"03MT216":["Тени небесные","Призвав меня, восполните 2 ед. маны заклинаний, если вы владеете ночной картой.","","\"Матерь луна, не дай мне забыть,\nЧто даже когда я остаюсь один,\nДети твои танцуют в небе надо мной,\nА значит, я не одинок\".\n– Молитва Лунари","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"03MT012":["Судия вершины","Моя стоимость снижается на 1 каждый раз, когда вы поддерживаете или выбираете целью союзника в этом матче.","","Судия вершины – это последнее испытание, которое предлагает Гора, ведь только страж может видеть не только поступки паломника, но и порывы его души.","Боец",[],["Таргон"],"ЭПИЧЕСКОЕ"],"03MT085":["Тишина","Примените к бойцу Безмолвие до конца раунда.","","\"Я несу безмятежность\". – Сорака","Заклинание",[],["Таргон"],"РЕДКОЕ"],"03MT081":["Скалолазы","Поддержка: даруйте союзнику, которого я поддерживаю, +2|+2. Если у него тоже есть навык Поддержка, даруйте союзнику, которого он поддерживает, +2|+2, и так по цепочке.","","Восхождение на Таргон предпринимают по разным причинам: одни хотят что-то доказать окружающим, другие – самим себе.","Боец",[],["Таргон"],"ЭПИЧЕСКОЕ"],"03MT030":["Звездочет","Исцеляя раненого союзника, дайте ему Изворотливость до конца раунда.","","\"Звездочки не остаются здесь навсегда. Мы их выхаживаем, а потом я возвращаю их на небо – и они мчатся ввысь, высекая искры копытами\".","Боец",[],["Таргон"],"РЕДКОЕ"],"03MT088":["Воин Солари","День: дайте мне +1|+1 до конца раунда.","","Греясь в лучах солнца, он сторожил пленную еретичку, не обращая внимания на доносившиеся из камеры тихие мольбы, которые вскоре сменились озлобленным молчанием.","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"03MT033":["Дедушка Румул","Разыгрывая карту: даруйте 2 союзникам +0|+4.","","\"Слышишь, Осу? Звон колокольчиков! Дедушка вернулся!\" – Илли, Пастушка звезд","Боец",[],["Таргон"],"РЕДКОЕ"],"03MT035":["Бледный каскад","Дайте союзнику +1|+1 до конца раунда.\nНочь: вытяните 1 карту.","","\"Под покровом ночи, под присмотром бледной луны\". – Диана","Заклинание",[],["Таргон"],"ОБЫЧНОЕ"],"03MT075":["Жрица Лунари","Ночь: используйте Зов.","","\"О звезды подобные пилигримам, что держат путь по глади небосвода. Побудьте с нами еще немного. Расскажите обо всем, что вам встретилось\".\n– Вечерняя песнь","Боец",[],["Таргон"],"РЕДКОЕ"],"03MT218":["Звездная косточка","Если вы владеете творением небес, создайте карту Гонец в своей колоде и даруйте союзным творениям небес везде +1|+1.","","\"Пусть резвится Гонец\nи радостью своей зажигает звезды\".\n– Молитва Лунари","Заклинание",[],["Таргон"],"ЭПИЧЕСКОЕ"],"03MT074":["Тихий час","Оглушите врага. Создайте в руке мимолетную карту Лови звезду.","","\"Тебе пора спать! Один светулек, два светулька, три све… Ой, чтоэтотам?!\" – Зои","Заклинание",[],["Таргон"],"РЕДКОЕ"],"03MT072":["Огнедышащий исполин","","","Храбрецов, совершающих восхождение на Таргон, поджидает множество испытаний. Бесконечный подъем постепенно подтачивает силы, но вокруг есть и более осязаемые опасности.","Боец",["ДРАКОН"],["Таргон"],"ОБЫЧНОЕ"],"03MT039":["Летучий поро","","","В космосе никто не услышит, как ты пищишь.","Боец",["ПОРО"],["Таргон"],"ОБЫЧНОЕ"],"03PZ019":["Потрепанный поробот","Пока я в руке, мой навык каждый раунд меняется на случайный. Призвав меня, даруйте мне текущий навык.","","Не такой мягкий, как настоящий, но тоже очень милый.","Боец",["ПОРО"],["Пилтовер и Заун"],"РЕДКОЕ"],"03PZ005":["Расстрелятор","Начало раунда: создайте в руке карту Зажигание.","","\"Подопытный попросил не трогать только его разум, поскольку именно там он хранит все обиды\".\n– Из дневника улучшателя, запись 1011","Боец",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"03PZ004":["Луч смерти – Mk 1","Нанесите бойцу 1 ед. урона. Создайте среди 3 верхних карт своей колоды карту Луч смерти – Mk 2.","","\"Сегодня я успешно продемонстрировал, что исходящую энергию можно собрать в один мощный луч. Если устройство доработать, этот луч может стать высокоточным инструментом! Но мне предстоит еще много работы\".\n– Из рабочих записок Виктора","Заклинание",[],["Пилтовер и Заун"],"РЕДКОЕ"],"03PZ003":["Виктор","Призвав меня или в начале раунда: создайте в руке карту Улучшение хекстекового ядра.","Вы разыграли 7+ созданных карт.","\"Заун, ты повидал немало бед на своем веку, но пришло время перемен. А великие изменения всегда начинаются изнутри\".","Боец",[],["Пилтовер и Заун"],"Чемпион"],"03PZ010":["Механическая подражательница","Атака: даруйте мне навыки всех союзников.","","\"Я совсем как ты, только лучше\".","Боец",[],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"03PZ022":["По полной","Увеличьте силу и здоровье всех союзников до наивысшего показателя силы или здоровья среди союзников.\nДаруйте всем союзникам союзные навыки.","","\"Я знаю, я знаю:\nТы хочешь больше.\nЕсли ты готов, то вперед,\nВыложимся по полной\".\n– Серафина, \"MORE\"","Заклинание",[],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"03PZ014":["Продуманные творения","Создайте в руке карту Техноманьяк, Расстрелятор или Мяундроид и даруйте ей +1|+1.","","\"Человека отличает от животного рациональное мышление и способность делать выбор\". – Виктор","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"03PZ013":["Итерационное улучшение","Выберите сторонника. Создайте в руке его копию с +1|+1.","","\"Самосовершенствование – это игра, в которой ты одновременно и героиня, и злодейка. Придется побороться. Может быть, тебе даже покажется, что ты победила. Но в конечном итоге ты всегда будешь стоять у себя на пути\". – Механическая подражательница","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"03PZ025":["Испытание на прочность","Уберите Мимолетность у всех карт в руке. Когда меня сбрасывают, вытяните 1 мимолетную карту.","","\"Да всего делов-то! Я заменила стальной каркас на другой, из сплава собственного изобретения. Электрическую цепь увела подальше от петель, чтобы ее перестало коротить. Проще простого!\" \n– Главный механик Зеви","Заклинание",[],["Пилтовер и Заун"],"РЕДКОЕ"],"03PZ012":["Техноманьяк","","","\"Новая рука? Отлично! Всегда такую хотел. Что дальше? Гравиколеса вместо ног? Электропривод? СТАЛЬНЫЕ ЗУБЫ? Хотя стоп, лицо не трогайте. Оно мне нравится\".","Боец",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"03PZ020":["Хекстековое горнило","Начало раунда: оба игрока вытягивают по 1 карте.","","\"Пусть говорят о моих методах все, что им вздумается. Прогресс нельзя отрицать. Моя наука – луч света в темном царстве невежества!\" – Виктор","Место силы",[],["Пилтовер и Заун"],"РЕДКОЕ"],"03PZ002":["Мяундроид","","","\"Долгие годы научной работы в академии Пилтовера коту под хвост! Мои технологии считают \"слишком опасными\", а меня самого не воспринимают всерьез, потому что я \"слишком милый\"! Хорошо, что есть Заун, где как минимум один великий ум разделяет мои амбиции…\"","Боец",["КОШКА"],["Пилтовер и Заун"],"РЕДКОЕ"],"03PZ011":["Афтершок","Нанесите бойцу 3 ед. урона или разрушьте место силы.","","\"Этот луч света укажет нам путь в Пилтовер. Ничто не встанет на пути великой эволюции!\" – Виктор","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"03PZ017":["Трехлучевой невероятор","Нанесите бойцу 1 ед. урона. Призовите случайного сторонника стоимостью 1. Пока я в руке, увеличьте оба показателя на 1, сыграв карту стоимостью 3.","","\"На счет 'три'! Ой… Батюшки! Еще один непредвиденный результат?\" – Хеймердингер","Заклинание",[],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"03PZ018":["Поропушка","Чтобы сыграть, сбросьте 1 карту.\nСоздайте в руке 2 Отважных поро.","","Два пушистых существа взмыли над восторженной толпой и плавно пролетели мимо, оставив после себя облачко пуха и едва уловимый запах свежих булочек.","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"03SI004":["Крадущиеся тени","Выберите сторонника среди 4 верхних карт в вашей колоде.\nВытяните его, уберите остальные карты в вашу колоду, а затем создайте в руке точную эфемерную копию этого союзника.","","\"Ступайте… окружите их\". – Ноктюрн","Заклинание",[],["Сумрачные острова"],"РЕДКОЕ"],"03SI001":["Сумрачные ловцы","Ночь: создайте в руке мою копию.","","\"Сначала я увидел одну пару глаз, а в темноте раздался стрекот. Но каждый раз, когда я оглядывался, глаз становилось все больше. А голосов – целый хор. И злобных таких! Как только впереди показался 'Зуб', я рванул к нему что было сил!\"\n – Мародер из \"Китового зуба\"","Боец",[],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"03SI018":["Ненасытность","Убейте союзника с навыком Предсмертный вздох, чтобы призвать из своей колоды сторонника стоимостью на 1 больше.","","\"Обед по расписанию!\" – Ненасытный мясник","Заклинание",[],["Сумрачные острова"],"РЕДКОЕ"],"03SI012":["Без права прохода","Уничтожьте всех бойцов, которые были призваны, но не разыграны в этом раунде.","","\"Разумеется, мы видим смерть и в Демасии. Она забирает наших любимых, а когда-нибудь неизбежно придет и за нами. Но на этих островах… я с каждым вздохом ощущаю ее вкус и запах. Я слышу, как она шепчет мне на ухо. Это не абстрактное понятие. Она сидит рядом со мной. И заберет нас всех\".\n– Записки Йенса Томмена, историка","Заклинание",[],["Сумрачные острова"],"РЕДКОЕ"],"03SI014":["Подступающий сумрак","Даруйте ВСЕМ союзникам в своей колоде и руке +2|+2 и Эфемерность.","","\"Боюсь, что кошмары Сумрачных островов рано или поздно сломят и тело, и душу – и тогда навеки воцарится безумие\".\n– Записки Йенса Томмена, историка","Заклинание",[],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"03SI016":["Добиться своего","Истощите бойца на 1 ед. здоровья. Создайте в своей колоде 2 мои копии. Когда это происходит в третий раз, превращайте все мои копии везде обратно в Пакуй вещи.","","\"Мы готовы на все, лишь бы добиться своего.\nМы готовы на все, ведь это наше любимое дело.\nВедь мы поп-звезды, мы звезды!\nПоверь, мы всегда будем на троне.\nНас уже не остановить, нет-нет-нет\".\n– Эвелинн, \"ПОП/ЗВЕЗДЫ\"","Заклинание",[],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"03SI007":["Покров тьмы","Дайте следующему союзнику, которого вы призовете в этом раунде, +1|+0 и Щит от магии до конца раунда.","","\"Выйдешь за дверь 'Зуба' – и сразу их почувствуешь. Прикосновение пальцев на загривке, легче летнего дождика… Они от тебя не отпрянут, не жди. Эти твари не боятся ни огня, ни железа. Вообще ничего. Жуткие создания\". – Мародер из \"Китового зуба\"","Заклинание",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"03SI005":["Ноктюрн","Ночь: даруйте врагу Уязвимость и до конца раунда дайте врагам -1|-0.","Вы отправили в атаку 5+ ночных союзников или союзников с Устрашением.","\"Похоже, что чудовище может вторгнуться в наш мир, если поработит достаточно душ. Отправить его восвояси могла бы надежда, но надежда давно умерла – с последним вздохом королевы, с несмолкающим криком короля\".\n– Записки Йенса Томмена, историка","Боец",[],["Сумрачные острова"],"Чемпион"],"03SI006":["Служитель рока","Ночь: истощите вражеский нексус на 2 ед. здоровья.","","С каждой ночью путники теряют все больше сил: они ворочаются во сне, мучимые яркими грезами. Сон больше не приносит отдыха – напротив, он изнуряет и тело, и разум.","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"03SI015":["Докучливый дух","Предсмертный вздох: создайте в колоде противника 2 мои копии.","","Большинство призраков Сумрачных островов – на редкость жуткие и мерзкие создания. Но есть исключения. Те просто очень, очень надоедливые.","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"03SI003":["Жуткий наблюдатель","Ночь: дайте мне +2|+0 и Устрашение до конца раунда.","","Когда солнце растворяется в черной смоле ночи, пробуждаются живущие здесь кошмары. Они наблюдают… и выжидают.","Боец",["ПТИЦА"],["Сумрачные острова"],"ОБЫЧНОЕ"],"03SI002":["Невыразимый ужас","Истощите любую цель на 1 ед. здоровья.\nНочь: создайте в руке случайную ночную карту.","","\"С каждым днем силы тают, пропадает тот запал, что помог отыскать это место. В 'Китовом зубе' полно сломленных людей, утративших ко всему интерес. Боюсь, что стану таким же, если здесь задержусь\".\n– Записки Йенса Томмена, историка","Заклинание",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"03SI010":["Сумрачный скакун","Ночь: даруйте мне +1|+0 за каждый раз, когда вы использовали навык Ночь в этой игре.","","На закате ночь расправляет темные крылья, поглощая последние лучи надежды.","Боец",[],["Сумрачные острова"],"РЕДКОЕ"],"03SI013":["Восставший туман","Призовите карту Туманный дух.","","Туманные духи передвигаются незримо, появляются без предупреждения и причиняют страдания всем, кто их встретит.","Заклинание",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"03IO025":["Быстрые кулаки","Даруйте союзнику +1|+0 и быструю атаку. Если она уже есть, даруйте двойную атаку.","","\"Бей часто, бей быстро, бей больно\". – Рога Дракона","Заклинание",[],["Иония"],"РЕДКОЕ"],"03IO017":["Пикс!","Поддержка: до конца раунда дайте +2|+1 союзнику, которого я поддерживаю.","","\"Пикс замечательный! Такой маленький, а уже личность!\nБольше всего на свете он любит опоссумов и делать так: хрм-хрм-хрм!\" – Лулу","Боец",["ФАЭ"],["Иония"],"ОБЫЧНОЕ"],"03IO008":["Причуда","Превратите сторонника в карту Белка с 1|1 и примените к нему Безмолвие до конца раунда.","","\"Обожатикус!\" – Лулу","Заклинание",[],["Иония"],"ОБЫЧНОЕ"],"03IO001":["Лисичка с цветочком","Когда меня поддерживают, даруйте мне +2|+0.","","Всем хочется иметь фамилиара, но мало кому хочется с ним возиться, ведь его надо выгуливать, следить за правильным питанием, приучать к дому… в общем, это большая ответственность!","Боец",["ФАЭ"],["Иония"],"ОБЫЧНОЕ"],"03IO019":["Сила воли","Выберите союзника. Верните ВСЕХ остальных бойцов и места силы.","","\"Я выбрала путь одиночки.\" – Монашка-отшельница","Заклинание",[],["Иония"],"ЭПИЧЕСКОЕ"],"03IO002":["Лулу","Поддержка: в этом раунде союзник, которого я поддерживаю, усиливается до 4|4.","Союзники получали поддержку 3+ раза.","\"Не волнуйся, Пикс! Когда мы выйдем с Поляны, мы применим \"Обожатикус\" КО ВСЕМУ! Ты готов?\"","Боец",["ЙОРДЛ"],["Бандл Сити","Иония"],"Чемпион"],"03IO011":["Белка-боксер","Удар: удвойте мою силу.","","Секрет ее силы – коктейли из молотых желудей четыре раза в день.","Боец",["ФАЭ"],["Иония"],"РЕДКОЕ"],"03IO009":["Вкусные создания","","","Энергетическая ценность: 104 кДж (25 ккал). Углеводы: 5,88 г, из них сахар: 3,53 г, растительные волокна: 3 г, жиры: 0,18 г, белки: 0,98 г, вода: 92 г…","Боец",["ФАЭ"],["Иония"],"ОБЫЧНОЕ"],"03IO003":["Проводник с Поляны","Разыгрывая карту: даруйте союзнику Изворотливость.","","\"Тс-с! Сюда! После бродячего домика на дереве надо резко забрать влево, а потом пойдем прямо мимо говорящих цветов. Лу, ты меня слушаешь? Лу? ЛУ!!! Не надо. Их. Кормить. Ни в коем случае!\"","Боец",["ЙОРДЛ"],["Иония"],"РЕДКОЕ"],"03IO007":["Тревор Соннопупс","Поддержка: создайте атакующего бойца Мямлик с характеристиками союзника, которого я поддерживаю.","","Мечты надо воплощать в реальной жизни, а не во сне, бормоча случайные обрывки заклинаний и сонно паря по древнему волшебному лесу. Ну как так можно?","Боец",["ЙОРДЛ"],["Иония"],"ЭПИЧЕСКОЕ"],"03IO010":["Юная ведьмочка","Поддержка: до конца раунда дайте быструю атаку и +1|+0 союзнику, которого я поддерживаю.","","Мсье Квандрант Монтегю вышел из дома в надежде совершить какой-нибудь подвиг или оказать услугу знатному дому и снискать его милость. Однако судьба завела его в бандловый лес, где юная Бри живо превратила мсье Квадранта в лягушку и потащила на поиски приключений. Бедный Кван!","Боец",[],["Иония"],"ОБЫЧНОЕ"],"03IO020":["Отменикус!","Остановите Быстрое или Медленное заклинание стоимостью не более 3.","","\"Зачем ты так делаешь, глупышонок? Ты же можешь поранить антилоп!\" – Лулу","Заклинание",[],["Иония"],"РЕДКОЕ"],"03IO022":["Вперед!","Верните одного союзника и призовите вместо него его точную эфемерную копию. Его стоимость в этом раунде равна 0.","","\"Больше\nЯ могу дать больше.\nВот, пожалуйста,\nЯ знаю, тебе нужно больше\".\n– Акали, \"MORE\".","Заклинание",[],["Иония"],"ЭПИЧЕСКОЕ"],"03IO018":["Заботливый пушистик","Когда меня поддерживают, дайте мне +0|+3 до конца раунда.\nПоддержка: до конца раунда дайте +3|+0 союзнику, которого я поддерживаю.","","Эти лиловые создания очень милые. Все, кому они встретятся, их оберегают. Ну, или почти все…","Боец",["ЙОРДЛ"],["Иония"],"РЕДКОЕ"],"03DE008":["Лейтенант из Драконьей стражи","Когда меня призывают, если вы владеете драконом, даруйте мне Выбор противника.","","\"Я думал, моя решимость погибла вместе с соратниками при Ренуолле… Но оказалось, что новое сражение как ничто другое будит в старом воине боевой дух\".","Боец",[],["Демасия"],"ОБЫЧНОЕ"],"03DE001":["Противостояние","Даруйте союзнику Выбор противника.\nЕсли это дракон, вытяните 1 карту.","","\"От нас никто не уйдет!\" – Шивана","Заклинание",[],["Демасия"],"ОБЫЧНОЕ"],"03DE015":["Каменная смирительница","ВСЕ заклинания стоят на 1 кристалл маны больше.","","Под умелым резцом скульптора бесформенная глыба петрицита превращается в нечто совершенно иное, словно оживая на глазах.","Боец",[],["Демасия"],"РЕДКОЕ"],"03DE006":["Кричащий дракон","","","Любая тварь яростно защищает свое потомство, но мало кто делает это так же эффективно, как дракон.","Боец",["ДРАКОН"],["Демасия"],"ОБЫЧНОЕ"],"03DE025":["Огненное дыхание","Союзник с навыком Ярость по очереди наносит удар двум слабейшим врагам.","","Веками демасийцы знали драконью ярость только по легендам. Но при Ренуолле все изменилось.","Заклинание",["СТИХИЯ"],["Демасия"],"РЕДКОЕ"],"03DE002":["Огненный удар","Союзник и враг наносят удар друг другу. Затем, если этот союзник – дракон, восстановите ему 5 ед. здоровья.","","Когда рыцарь и дракон разошлись, тяжело дыша и страдая от ран, дракон пришел в себя первым. Он чуял кровь и хотел еще.","Заклинание",[],["Демасия"],"РЕДКОЕ"],"03DE011":["Шивана","Атака: дайте мне +1|+1 до конца раунда.","Союзники-Драконы нанесли 16+ ед. урона.","\"С одной стороны, по природе своей она наш злейший враг, ведь ее сородичи издревле приносили жителям Демасии только смерть и разрушения. С другой стороны, она доверенное лицо принца и, судя по всему, стойкий солдат и ценный союзник. Надеюсь только, что она не обманет оказанного ей доверия\".\n– Из записок лейтенанта Джерика о Ренуолле","Боец",["ДРАКОН"],["Демасия"],"Чемпион"],"03DE003":["Дозорная из Драконьей стражи","Когда меня призывают, если вы владеете драконом, используйте Рвение.","","\"Вон там, на горизонте… Это он?\"\n\"Похоже на то\".\n\"Откуда ты знаешь?\"\n\"Тут сложно ошибиться. Зажми уши. Будет громко\". – Анден и Ессения","Боец",[],["Демасия"],"РЕДКОЕ"],"03DE013":["Мать-драконица","","","\"Осторожно, бойцы! Если ступать тихо и не приближаться к гнезду, драконица продолжит охранять кладку. Если же мы ее потревожим… просто бегите\". – Анден Майн, ученый-яйцевед","Боец",["ДРАКОН"],["Демасия"],"ОБЫЧНОЕ"],"03DE005":["Ученый-яйцевед","Когда меня призывают, создайте в руке случайного дракона.","","Драконье яйцо (Кричащий дракон Draco Murmurationis)\nПроисхождение: обнаружено в экспедиции исследователем Анденом Майном.\nПримечания: время проклевывания неизвестно. Продолжается инкубация. Внутри скорлупы замечено движение. Яйцо реагирует на тепло, свет и молоточек. Нужно больше данных.\n– Из заметок Андена Майна, ученого-яйцеведа","Боец",[],["Демасия"],"ОБЫЧНОЕ"],"03DE007":["Кадрегрин Сжигатель","Когда меня призывают, даруйте остальным союзникам-драконам везде +4|+4.","","Шивана сразу поняла, что за участившимися драконьими налетами на Демасию стоит Кадрегрин по прозвищу Сжигатель. Его смелость и мощное пламя вдохновили других драконов, которые теперь наводят ужас на демасийцев. ","Боец",["ДРАКОН"],["Демасия"],"ЭПИЧЕСКОЕ"],"03DE012":["Во имя павших","Моя стоимость снижается на 1, когда вы призываете элитного бойца.\nЗа каждого союзника, погибшего в этом раунде, призовите карту Воин Бесстрашного авангарда.","","\"Если один воин погибнет – пусть другой займет его место. Наш стяг не должен опуститься!\" – Гарен","Заклинание",[],["Демасия"],"ЭПИЧЕСКОЕ"],"03DE014":["Бдительность","Дайте союзнику +1|+2 и Бдительность до конца раунда.","","Любого, кто дерзнет штурмовать стены Демасии, встретит тяжеловооруженный отряд в полной боевой готовности.","Заклинание",[],["Демасия"],"ОБЫЧНОЕ"],"03FR020":["Залы Шрамов","Когда союзник выживает, получив урон, даруйте ему +1|+0 и Стойкость.","","У племени Коготь Зимы много памятных мест, но особое место среди них занимают Залы Шрамов. Здесь для важных обсуждений собираются воины и их семьи, а роль залов собраний выполняют корабли, безнадежно поврежденные в набегах. Стойкость и умение приспосабливаться стали символом этого племени – и их корабли под стать людям.","Место силы",[],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"03FR007":["Тролль-следопыт","Если, когда меня призывают, вы владеете картой стоимостью 8+, даруйте мне +3|+0.","","Разведчик склонился над торчавшим из снега куском ткани, который пах человеческим потом и дымом от костра.\nПотянув за оборванный край, разведчик вытащил и лоскут, и кое-что еще: талисман, матово блеснувший под грозовым небом. Талисман племени аваросан.","Боец",[],["Фрельйорд"],"ОБЫЧНОЕ"],"03FR004":["Бодрящий рык","Выберите бойца из руки для показа. Восстановите своему нексусу столько единиц здоровья, сколько силы у этого бойца.\nПросветление: стоимость этого бойца равна 0.","","\"У взрослых троллей толстая кожа и крепкие кости, а раны на них быстро заживают. По этой причине тролли выносливы и очень опасны. Нужно убивать их сразу, пока они не восстановились и не напали снова\". – Стрелок племени аваросан","Заклинание",[],["Фрельйорд"],"РЕДКОЕ"],"03FR017":["Пророчица древних","Разыгрывая карту: если вы владеете картой стоимостью 8+, даруйте союзнику Пробивание и Восстановление.","","Говорят, что тролли обучают заклинаниям древних лишь избранных – зато те, кто их знает, способны взывать к предкам и наделять своих соплеменников необычайной силой.","Боец",[],["Фрельйорд"],"РЕДКОЕ"],"03FR006":["Трандл","Когда меня призывают, создайте в руке карту Ледяной столп.","На моих глазах вы разыграли карту Ледяной столп.","Вдоль тропы один за другим зажигались факелы, выхватывая из мрака силуэты сотен троллей – массивных, угрюмых и смертельно опасных.\n\"Спрашиваю в последний раз, – прорычал Трандл, вскидывая на плечо Костелом. – Сами сдадитесь или придется ломать вам черепа?\"","Боец",[],["Фрельйорд"],"Чемпион"],"03FR008":["Льдотрясение","Дайте ВСЕМ бойцам -3|-0 до конца раунда. Нанесите 3 ед. урона ВСЕМ бойцам.","","\"Похороним их заживо!\" – Трандл","Заклинание",["СТИХИЯ"],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"03FR002":["Тролльский напев","Дайте союзнику +0|+2, чтобы дать врагу -2|-0 до конца раунда.","","Заклинания одного племени троллей могут быть непонятны в другом: настолько они различаются. В одном они совпадают: обряды, для которых они используются, – всегда жуткое зрелище. ","Заклинание",[],["Фрельйорд"],"ОБЫЧНОЕ"],"03FR011":["Узгар Древний","","","Сначала они почувствовали, как под ногами дрожит земля, а скоро услышали и гром, который становится все громче.\nМейрик с круглыми от страха глазами вскинул голову и прислушался.\n\"Что это такое?\" – встревоженно прошептала Анья, натягивая тетиву лука, но Мейрик уже несся обратно к тропе.\n\"БЕГИ!\"","Боец",[],["Фрельйорд"],"РЕДКОЕ"],"03FR005":["Тролль-опустошитель","Если, когда меня призывают, вы владеете картой стоимостью 8+, даруйте мне Восстановление.","","Добравшись до хижин племени аваросан, они позвали Хгар. Смеясь, она подняла Снегогром, намереваясь разнести деревянные постройки в щепу.","Боец",[],["Фрельйорд"],"ОБЫЧНОЕ"],"03FR018":["Зов природы","Просмотрите 4 верхние карты своей колоды и вытяните каждого элнука, йети и поро. Остальные карты уберите в колоду.","","\"…а потом из леса как выбежит ОГРОМНЫЙ самец элнука с крохотулечкой-поро на спине, а за ними – ДРУЖЕЛЮБНЫЙ ЙЕТИ, который просто хотел поиграть с друзьями. Они носились по горному склону и рычали: А-Р-Р-Р! А потом…\" – Ингвар младшая","Заклинание",[],["Фрельйорд"],"ОБЫЧНОЕ"],"03FR010":["Лица предков","Начало раунда: если вы владеете картой стоимостью 8+, получите дополнительный кристалл маны в этом раунде.","","\"Встаньте, древние, проснитесь!/Правьте льдом, сломайте небо.\nВстаньте, древние, проснитесь!/Дайте сил нам и победу!\"\n– Заклинание троллей","Боец",[],["Фрельйорд"],"ОБЫЧНОЕ"],"03FR019":["Голоса Древних","Получите 2 пустых кристалла маны.\nПросмотрите 5 верхних карт своей колоды и вытяните каждую карту стоимостью 8+. Остальные уберите в колоду.","","Поселенцы из племени аваросан десятилетиями слышали в завывании зимней вьюги какие-то потусторонние звуки. Забравшись еще дальше на север, они наконец нашли их источник: это древние монолиты троллей что-то шептали на мертвых языках, когда ветер свистел в их раскрытых пастях.","Заклинание",[],["Фрельйорд"],"ОБЫЧНОЕ"],"03FR025":["Дары троллей","Даруйте союзнику Восстановление. Если оно уже есть, даруйте вместо этого +2|+2.","","Горе тем, кто надеется победить, пролив кровь троллей.","Заклинание",[],["Фрельйорд"],"РЕДКОЕ"],"03FR022":["Чувствуешь драйв?","Призовите 2 разных случайных чемпионов из руки и колоды. Увеличьте их характеристики до 10|10.","","\"Весь мир у наших ног.\nНе думай, что сможешь нас раскусить\".\n– Ари, \"ПОП/ЗВЕЗДЫ\"","Заклинание",[],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"04PZ001":["Экко","Удар: создайте в руке мимолетную карту Фокус со временем.","Вы сделали Предсказание 4+ раза. Когда мой уровень повышается, создайте в своей колоде 3 Управления временем.","Важно не сколько у тебя времени, а как ты его используешь.","Боец",[],["Пилтовер и Заун"],"Чемпион"],"04PZ005":["Щебетун-чернорабочий","Призвав еще одну карту Щебетун-чернорабочий, уничтожьте меня и превратите союзных Щебетунов-чернорабочих везде в Банды из Сточных ям.","","Обнаружив щебетунов, заунские шахтеры сперва решили, что это существа смирные и примитивные. Но прошли годы, щебетуны привыкли к людям и стали демонстрировать способность разбираться в технологиях и тесные социальные связи внутри стаи.","Боец",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"04PZ014":["Производственный бум","Чтобы сыграть эту карту, потратьте всю ману. Призовите случайные турели, стоимость которых в сумме равна потраченной мане.","","\"Мало материалов, говорите? Я собрал свой первый механизм из старых часов и ржавого термоконденсатора! Нужно уметь обходиться тем, что есть под рукой!\" \n– Хеймердингер","Заклинание",[],["Пилтовер и Заун"],"РЕДКОЕ"],"04PZ003":["Временной ключ","Чтобы сыграть, сбросьте 1 карту.\nНанесите 1 ед. урона вражескому бойцу или нексусу и 1 ед. урона другому бойцу.","","\"Берегись!\" – Экко","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"04PZ011":["Просчитанный маневр","Вытяните одну карту.\nСоздайте в колоде карту Параллельная конвергенция.","","\"Расщепляю время...\" – Экко","Заклинание",[],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"04PZ002":["Фиаскот","Призвав меня, создайте карту Хекситовый кристалл среди 10 нижних карт в колоде.","","\"НЕ-Е-ЕТ, МОЙ ПЛА-А-АН! МЯ-Я-А-А-А!\"","Боец",["КОШКА"],["Пилтовер и Заун"],"РЕДКОЕ"],"04PZ020":["Дефектный бот-разменщик","Разыгрывая карту: я меняюсь характеристиками с другим бойцом.","","\"Новый игровой автоматон? Я думал, фабрику по их производству давно прикрыли\".\n\"Я тоже слышала что-то про укатившиеся бомбы и ненамеренный поджог...\"\n\"Хм-м…\"\n\"Сыграем?\"\n\"Конечно!\"\n– Заунские игроки","Боец",[],["Пилтовер и Заун"],"РЕДКОЕ"],"04PZ013":["Подопытный элнук","Призвав меня, создайте случайного элнука среди верхних 6 карт в колоде.","","\"Так, дружок, постой-ка тут! Сейчас я тыкну эту кнопочку, и... БУМ! О ДА! ЭЛНУКИ РУЛЯТ! Так, нужно больше корма. И места\". – Практичная перфекционистка","Боец",["ЭЛНУК"],["Пилтовер и Заун"],"РЕДКОЕ"],"04PZ010":["Параллельные потоки","Даруйте сторонникам в своей руке особенность \"Разыгрывая меня, выберите 1 из 3 сторонников, чья стоимость равна моей, и превратите меня в этого сторонника\".","","\"Ты играешь по МОИМ правилам\". – Экко","Заклинание",[],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"04PZ016":["Взрывная мартышка","Призвав меня, создайте в руке карту Огненные кусаки!.","","Раньше у Джинкс был другой поставщик, но однажды они слегка повздорили, и его бизнес оказался в пролете. Точнее, взлетел на воздух. Вместе с ним самим.","Боец",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"04PZ007":["Фокус со временем","Сделайте Предсказание и вытяните карту.","","\"Я сам создаю свое будущее\". – Экко","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"04PZ012":["Практичная перфекционистка","Разыгрывая карту: сделайте Предсказание. Создайте в колоде 3 копии выбранной карты.","","\"Кей говорит, практика – это путь к совершенству, а практикуется она столько, что на двоих хватит. Она такая классная!\" – Шоми","Боец",[],["Пилтовер и Заун"],"РЕДКОЕ"],"04PZ017":["Великая эволюция","Ваши карты стоят на 1 меньше, имеют Улучшение, создаются картой Великая эволюция и считаются техникой.","","\"Прогресс превыше всего. Я приведу наш город в будущее – неважно, готов он к этому или нет\".  – Виктор","Заклинание",[],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"04PZ015":["Адаптатрон-3000","Когда вы призываете технику, мы делимся навыками.","","\"О да! Адаптатрон-3000! Инновационный, адаптируемый – и вообще красавчик! Если бы он мог говорить, мы СТОЛЬКО могли бы обсудить! Стольким поделиться друг с другом!\" – Хеймердингер","Боец",["ТЕХНИКА"],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"04PZ004":["Уличный лихач","Увидев меня в предсказании, призовите меня.","","\"Шоми просто ВИРТУОЗ на своем летающем скейте. Я видела, как она сделала заунский грайнд, переходящий в бэкслайд, а потом взлетела с трехчастного пилто-дипа! Или как это называется… в общем, я хочу сказать, что она очень крутая!\" – Практичная перфекционистка","Боец",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"04BW002":["Костяной гарпун","Союзник наносит удар врагу, а затем перемещается на верх колоды.","","\"Подарок на прощанье\". – Пайк","Заклинание",[],["Билджвотер"],"ЭПИЧЕСКОЕ"],"04BW007":["Челюстозуб","Разыгрывая карту: каждый союзный Охотник наносит удар случайному врагу.","","\"Только в брюхе у челюстозуба понимаешь, кто заслуживает доверия, а кто – смерти\". – Пайк","Боец",["ОХОТНИК"],["Билджвотер"],"ЭПИЧЕСКОЕ"],"04BW001":["Алый молотонос","Разыгрывая карту: даруйте врагу Уязвимость.","","Молотоносы часто таранят корабли и лодки, но не ради пропитания, а для развлечения. Обычно они не трогают оказавшихся в воде моряков, оставляя их на корм другим тварям.","Боец",["ОХОТНИК"],["Билджвотер"],"ОБЫЧНОЕ"],"04BW005":["Пайк","Когда я охочусь, превратите меня в карту Смерть из глубин.","Союзные Пайки нанесли 15+ ед. урона.","\"...меня мучают кошмары. Я снова вижу, как он с отчаянием смотрит на меня, как смыкаются над ним клыки челюстозуба. Мы пытались его вытянуть, но тварь нас чуть не потопила. Мне пришлось перерезать трос. У меня не было другого выбора. Не было выбора\".\n– Запятнанное кровью письмо","Боец",["ОХОТНИК"],["Билджвотер"],"Чемпион"],"04BW010":["Гарпун для чудовища","Разграбление: моя стоимость снижается на 2.\nНанесите бойцу 5 ед. урона.","","\"Мы уже попали в него, ребятки! Теперь ткнем его пару раз, чтобы перестал трепыхаться, а вода окрасилась в красный!\" – Старпом из \"Ржавых крючьев\"","Заклинание",[],["Билджвотер"],"ОБЫЧНОЕ"],"04BW014":["Бочки в ряд","Призовите карту Пороховая бочка. Создайте в руке карту Всем назад.","","\"Готово, капитан. Осталось только добавить огоньку – и тут мигом все взлетит на воздух\". – Матрос с \"Кошмара\"","Заклинание",[],["Билджвотер"],"ОБЫЧНОЕ"],"04BW011":["Шулерские кости","В следующем раунде крадите по 1 карте каждый раз, когда наносите урон вражескому нексусу.","","\"Что ты готов поставить на кон, друг мой?\" – Таам Кенч","Заклинание",[],["Билджвотер"],"ЭПИЧЕСКОЕ"],"04BW015":["Акуленыш","","","\"Они хоть и мелкие, но кровь чуют за версту. Попробуют каплю, запомнят и приплывут по твою душу, когда вымахают. Так что лучше носить перчатки\". – Охотник на челюстозубов","Боец",["ОХОТНИК"],["Билджвотер"],"ОБЫЧНОЕ"],"04BW003":["Стая смертогрызов","Разыгрывая карту: я отправляюсь в самостоятельную атаку.","","\"Кап-кап, кровь в воде показала путь.\nШлеп-шлеп, они плывут, лучше утонуть.\nЩелк-щелк, соли вкус, крик из глубины.\nНа дне мы навечно погрузимся в сны!\"\n– Билджвотерский детский стишок","Боец",["ОХОТНИК"],["Билджвотер"],"ОБЫЧНОЕ"],"04BW009":["Бухта Потрошителей","Когда атакуют союзники, до активации Охоты даруйте верхнему союзнику в своей колоде Охоту, чтобы он стал Охотником.","","В Билджвотере много опасных бухт, где обитают всевозможные морские твари. Затаившись, они поджидают глупцов, которые заплывают к ним несмотря на предупреждения капитана порта.","Место силы",[],["Билджвотер"],"РЕДКОЕ"],"04BW008":["Древний клад","Вытяните сокровище. Если в колоде его нет, создайте в ней 2 сокровища.","","\"Мы богаты!\" – Мясник из \"Ржавых крючьев\"","Заклинание",[],["Билджвотер"],"РЕДКОЕ"],"04BW013":["Разбойный ряд","Когда я отсчитываю раунд, призовите случайного сторонника стоимостью 1.\nОтсчитайте 2 раунда и даруйте +2|+1 и Устрашение союзникам стоимостью 1.","","\"Думаешь, ты достоин называться Крюком? Мы тебя испытаем, козявка! Либо ты заслужишь свое место на палубе, либо отправишься на дно с балластом, рыбам на корм!\" – Младший офицер","Место силы",[],["Билджвотер"],"РЕДКОЕ"],"04BW004":["Кровавая наживка","Создайте карту Стая смертогрызов наверху колоды.","","\"Хуже нет этих проклятых тварей! Лучше уж угодить в пасть к челюстозубу – тот хоть сразу прикончит, да и дело с концом. А эти будут жрать заживо, пока ты вопишь, умоляя товарищей тебя добить\". – Мясник из \"Ржавых крючьев\"","Заклинание",[],["Билджвотер"],"ОБЫЧНОЕ"],"04BW016":["Падший Рекс","Разыгрывая карту: примените заклинание Пушечный обстрел к случайным врагам столько раз, сколько карт вы вытянули в этом раунде (но не более 6).","","\"Рекс?..\" – Младший офицер","Боец",[],["Билджвотер"],"РЕДКОЕ"],"04BW006":["Список","Даруйте врагу Уязвимость. Если цель уже уязвима, сильнейший союзник идет в самостоятельную атаку, выбирая противником этого бойца.","","\"Назови свое имя – и я внесу его в список\". – Пайк","Заклинание",[],["Билджвотер"],"РЕДКОЕ"],"04IO008":["Дерзкий танец","Верните бойца.\nИспользуйте Танец с клинками (1).","","\"Расступитесь! Сейчас на сцену выйдет мастер!\"\n– Цинния, Стальное крещендо","Заклинание",[],["Иония"],"ОБЫЧНОЕ"],"04IO005":["Ирелия","Призвав меня или в начале раунда: если у вас есть жетон атаки, создайте в руке Безупречный дуэт.","Вы отправили в атаку 14+ союзников.","\"Когда-то мы изучали искусство и красоту, и у нас словно выросли крылья… А потом они сломали наши стены, пролили нашу кровь, и мы упали обратно на землю…\"","Боец",[],["Иония"],"Чемпион"],"04IO020":["Разбитый клин","Разыгрывая карту: вытяните Медленное, Быстрое или Взрывное заклинание.\nПросветление: у меня есть Изворотливость.","","Таинственные и прекрасные, словно сон, небесные песни Пьющих облака отчасти сдержали черный туман… но лишь на время.","Боец",[],["Иония"],"РЕДКОЕ"],"04IO004":["Цветущий клинок","Разыгрывая карту: используйте Танец с клинками (2).","","\"Некоторые считают цветы нежными и хрупкими. Они не понимают, сколько нужно сил, чтобы держаться за скудную почву и пробуждать надежду с каждым раскрывшимся бутоном\".\n– Цинния, Стальное крещендо","Боец",[],["Иония"],"ОБЫЧНОЕ"],"04IO003":["Острие авангарда","Выберите союзника, который атакует вместе с Клинками, а затем используйте Танец с клинками (3).","","\"Не дайте им уйти! Войну развязали ноксианцы, но закончим ее мы!\" – Ирелия","Заклинание",[],["Иония"],"РЕДКОЕ"],"04IO015":["Танцующая капля","Когда меня возвращают, вытяните 1 карту.","","\"Вода умеет приспосабливаться. Она принимает самую подходящую на данный момент форму, течет вперед или отступает от берега\". – Ионийский монах","Боец",[],["Иония"],"ОБЫЧНОЕ"],"04IO014":["Ученик Ордена Тени","Призывая эфемерного союзника, дайте мне +1|+0 до конца раунда.","","\"Будь как дым… как шепот на ветру. Твои кулаки должны стать продолжением самой тьмы, как тени становятся продолжением сумрака. Еще раз!\" – Госпожа Ши","Боец",[],["Иония"],"ОБЫЧНОЕ"],"04IO002":["Цинния, Стальное крещендо","Во время Танца с клинками я атакую вместе с Клинками.\nРазыгрывая карту: используйте Танец с клинками (1).","","\"Подойдите поближе, мои дорогие. Сегодня мы будем порхать над родной землей, исполняя танцы наших семей, наших предков. Мы – дети Ионии, и сегодня мы танцуем во имя искусства, свободы... и друг друга!\"","Боец",[],["Иония"],"ЭПИЧЕСКОЕ"],"04IO007":["Синкопирование","Поменяйте местами двух союзников.","","\"Танцуя, мы движемся в гармонии со всем сущим\".\n– Цинния, Стальное крещендо","Заклинание",[],["Иония"],"РЕДКОЕ"],"04IO011":["Вести и следовать","Верните союзника, чтобы создать в руке Безупречный дуэт.","","\"Наше выступление будет… незабываемым\". – Цинния, Стальное крещендо","Заклинание",[],["Иония"],"ОБЫЧНОЕ"],"04IO013":["Священный защитник","Разыгрывая карту: дайте союзнику Щит до конца раунда и вытяните чемпиона Шен.\nСоюзники с Щитом имеют Двойную атаку.","","\"Наши земли защищают нас – так же, как мы защищаем их. Мы черпаем силу в природе и обращаем ее в оружие против захватчиков. Мы поддерживаем баланс\".\n– Ионийский жрец","Боец",[],["Иония"],"ЭПИЧЕСКОЕ"],"04IO012":["Тени прошлого","Верните всех союзников и призовите вместо каждого карту Живая тень.","","\"Пусть сражаются с тенями – их клинки пронзят лишь воздух\". – Зед","Заклинание",[],["Иония"],"РЕДКОЕ"],"04IO009":["Танцующая с лентами","Разыгрывая карту: используйте Танец с клинками (1).","","\"Как же так, мальчики? Такая сила – и ни малейшего намека на ритм? Что ж, не каждый может быть звездой…\"","Боец",[],["Иония"],"РЕДКОЕ"],"04IO001":["Военные музыканты","В каждом раунде, призвав 3 других союзников, восполните ману заклинаний и вытяните 1 карту.","","Одним музыка помогает отвлечься от тягот и невзгод. Для других же это форма сопротивления.","Боец",[],["Иония"],"ЭПИЧЕСКОЕ"],"04IO006":["Защитник побережья","Призвав другого союзника, дайте мне +2|+0 до конца раунда.","","Дорогая Кей!\nСегодня утром череда чужих судов закрыла собой горизонт и затмила зарю. Их жуткие машины подожгли Серебряные равнины, и летний воздух стал горьким от дыма. Мы не можем больше оставаться в стороне. С лопатой или граблями, с серпом или мечом, – сегодня мы пойдем навстречу судьбе.\nЗнай, что я люблю тебя и наш дом так, что нельзя описать словами.\n– Обгоревшее письмо","Боец",[],["Иония"],"ОБЫЧНОЕ"],"04SH100":["Тщательная подготовка","Чтобы сыграть, уберите карту из руки в свою колоду.\nСделайте Предсказание, а затем создайте в руке точную копию выбранной карты.","","\"Наши действия в настоящем – это семена, из которых прорастет будущее\". – Тай, начинающий хрономант","Заклинание",[],["Шурима"],"ОБЫЧНОЕ"],"04SH070":["Недостойный","Дайте вражескому стороннику -4|-0 до конца раунда.\nЕсли у вас меньше кристаллов маны, чем у противника, вместо этого убейте его.","","\"Солнце снова взойдет над шуримской землей!\" – Глас восставших","Заклинание",[],["Шурима"],"ЭПИЧЕСКОЕ"],"04SH081":["Баккай – заклинательница песка","Разыгрывая карту: даруйте вражескому бойцу -1|-0 и Уязвимость.","","Она просеивает песок, и каждая песчинка – это миг отпущенного кому-то времени. Подобно ветру, она подтачивает чужие жизни.","Боец",[],["Шурима"],"РЕДКОЕ"],"04SH077":["Глас восставших","Если вы повышали уровень чемпиона, у союзников +2|+0.","","\"Давным-давно я слышал ее речь, – старый солдат улыбнулся, и на миг его внучка ярко представила себе картину: сияющая золотом Шурима, величественный Азир на пьедестале и провозглашающая его прибытие женщина, Глас восставших. – Она тронула даже те сердца, что, казалось, давно огрубели\".","Боец",[],["Шурима"],"ЭПИЧЕСКОЕ"],"04SH019":["Рек'Сай","Когда я охочусь или атакую, даруйте +1|+0 Охотникам везде.\nКонец раунда: уберите меня в колоду.","Я атакую, имея 10+ силы.","\"Юный Джура давеча исследовал пещеры и обнаружил в одной тайник с древними текстами! Если верить переводчику из Масломарка, в свитках описано ужасное чудовище, что охотилось на наших предков... королева зер'сай!\" – Фезаур, векауранский старейшина","Боец",["ОХОТНИК"],["Шурима"],"Чемпион"],"04SH138":["Каратель","Дайте союзнику +2|+1 до конца раунда. Если в этом матче вы повысили уровень чемпиона, создайте в руке Возвращение Карателя.","","\"Не бери Каратель, – говорили они. – Не для смертных рук это оружие.\" – Акшан","Заклинание",[],["Шурима"],"ОБЫЧНОЕ"],"04SH089":["Натуралистка из пустыни","Разыгрывая карту: разрушьте место силы. Если оно союзное, призовите карту Рассерженный камненосец.","","\"Кадира опять что-то разломала! На этот раз просто каменную стену... Но выглядела она древней – чей-то предок ее старательно строил! Кадира говорит, что привыкла к более крепким стенам в Терешни, а эту разворотила случайно. Бесит!\"\n– Из дневника Заифы","Боец",[],["Шурима"],"РЕДКОЕ"],"04SH015":["Разз Кровавая Грива","Атака: дайте врагам -2|-0 до конца раунда.","","\"Когда мой зубастый друг вылупился из яйца, парни делали ставки, как долго он протянет. Он был самым слабым в выводке, да еще и уродом. Кто ж знал, что он сожрет своих братьев и сестричек!\"","Боец",[],["Шурима"],"ЭПИЧЕСКОЕ"],"04SH058":["Ваятель песка","Атака: призовите атакующего бойца Песчаный солдат.","","Мало кто знает пустыню так же хорошо, как Азир, и никто не может повелевать песками столь же умело. Секреты этого мастерства – великий дар, которым Азир награждает своих самых верных и способных соратников.","Боец",[],["Шурима"],"ОБЫЧНОЕ"],"04SH080":["Сбор стаи","Чтобы сыграть, положите карту из руки на самый верх колоды.\nСоздайте в руке 2 случайных Охотников.","","\"Пусть ярко светит солнце и крепко спят зер'сай\".\n – Молитва торговцев","Заклинание",[],["Шурима"],"ОБЫЧНОЕ"],"04SH035":["Нажива","Создайте в руке карту Удачная находка.","","\"Как и у всех, у меня бывают удачные и неудачные дни. В нашем ремесле удача может принести сказочное богатство, а невезение – свести в могилу\". – Сивир","Заклинание",[],["Шурима"],"ОБЫЧНОЕ"],"04SH028":["Древние механизмы","Разыгрывая карту: сделайте Предсказание.\nОтсчитайте 2 раунда и призовите карту Маховичок.","","Может показаться, что время сгубило эти хитроумные приспособления, но они лишь дремлют под толстым слоем песка, стратегически размещенные так, чтобы пробудиться в нужный момент.","Место силы",[],["Шурима"],"ОБЫЧНОЕ"],"04SH054":["Охотница за сокровищами","Призвав меня, создайте в руке карту Пробуждение песков.","","\"Значит так, Даву. Сейчас ты туда залезешь, достанешь мне эту штучку, и мы с тобой разбогатеем. То есть я разбогатею. Понятненько? Заранее извиняюсь, если там окажется ловушка...\"","Боец",[],["Шурима"],"ОБЫЧНОЕ"],"04SH002":["Баккай-жнец","Сражая бойца, даруйте мне +1|+0.","","\"После неудавшегося Вознесения все баккай были помилованы или бежали. С тех пор их никто не видел. Кто знает, сколько они скрывались в этих темных гробницах, сгорая со стыда?\" – Из \"Истории армии вознесшихся\" летописца Ка'Нира","Боец",[],["Шурима"],"РЕДКОЕ"],"04SH042":["Спящий камненосец","Отсчитайте 3 раунда и призовите карту Рассерженный камненосец.","","\"МЕНЯ ЗОВУТ ЗАИФА И Я ЛЮБЛЮ ПИСАТЬ В СВОЕМ БЛОКНОТЕ ВСЯКУЮ ЕРУНДУ, ПОКА ВСЕ СПЯТ. СЕЙЧАС ЗАСНУЛ ДАЖЕ САМИ\".\n– Из дневника Заифы","Место силы",[],["Шурима"],"ОБЫЧНОЕ"],"04SH032":["Жестокая силачка","Репутация: моя стоимость снижается на 1. Призвав меня, даруйте мне Пробивание.","","Воин из последних сил потянулся к копью, но она лишь крепче придавила его грудь тяжелым ботинком. Бедняга застонал, а она укоризненно произнесла: \"Ну нет! Это теперь мое!\" – и улыбнулась, показывая заточенные клыки.","Боец",[],["Шурима"],"ОБЫЧНОЕ"],"04SH055":["Исследовательница руин","","","Прежде чем столкнуться с опасностями, подстерегающими в древних хранилищах, шуримским наемникам и расхитителям гробниц нужно сперва выжить в борьбе с более заурядными противниками: немилосердным зноем и многочисленными разбойниками, которые не пощадят никого.","Боец",[],["Шурима"],"ОБЫЧНОЕ"],"04SH039":["Зилеан","Разыгрывая карту: создайте в колоде 4 Бомбы замедленного действия, а затем сделайте Предсказание.","На моих глазах вы разрушили 2+ союзные Бомбы замедленного действия.","За долгие годы Зилеан создал сеть, связывающую талантливых юных магов из разных эпох. Каждый из них мог бы продолжить дело всей его жизни, случись вдруг непоправимое. Он был добрым и вдохновляющим наставником, но порой стремился к одиночеству – и тогда лоб его пересекали глубокие морщины, а в глазах читалась усталость человека, прожившего гораздо дольше отмеренного ему срока.","Боец",[],["Шурима"],"Чемпион"],"04SH073":["Талия","Разыгрывая карту: призовите точную копию союзного места силы.","Вы призвали 5+ мест силы.","\"Поступь кочевников легка, ведь их не удерживают корни, а дом – всегда где-то за горизонтом\".\n– Жители Шуримы","Боец",[],["Шурима"],"Чемпион"],"04SH091":["Кахири-ученик","Призвав меня, если вы уже делали Предсказание, даруйте мне +1|+1.","","\"Помни все, что нам удалось узнать, – напутствовал Зилеан с нехарактерной для него заботой. – Ты точно готов?\"\nКахири успокаивающе улыбнулся наставнику: \"Я скоро вернусь. Каждый день в течение многих лет я готовился к этому моменту. Когда, если не сейчас?\"","Боец",[],["Шурима"],"ОБЫЧНОЕ"],"04SH024":["Соляной шпиль","Отсчитайте 2 раунда и призовите карту Рассерженный камненосец. Затем, если за эту игру вы призвали 4+ места силы, даруйте сильнейшему союзнику +2|+2.","","Шуримские соледобытчики способны на глаз определить, в каком месторождении можно работать, а из какого лучше поскорее уйти.","Место силы",[],["Шурима"],"ОБЫЧНОЕ"],"04SH003":["Азир","Когда союзники атакуют, призовите атакующую карту Песчаный солдат.","Вы призвали 12+ союзников или мест силы.","\"Когда Азир взошел на трон Шуримы, он был заносчив. Слеп. Он копил мощь и готовился к Вознесению, чтобы стать правителем не только Шуримы, но и всего мира\". \n– Из \"Истории армии вознесшихся\" летописца Ка'Нира","Боец",["ВОЗНЕСШИЕСЯ","ПТИЦА"],["Шурима"],"Чемпион"],"04SH011":["Исследовательницы ксенотипов","Призвав меня, даруйте трем случайным союзникам в вашей колоде +3|+3.","","Бездна полна неожиданностей. С каждым днем она ширится и ищет новые лазейки, пытаясь проникнуть в башню. Она вездесуща, как колючие лозы слеповника, но неизмеримо опаснее. Изучать ее – задача не из легких, ведь исследователи должны быть достаточно находчивы и умны, чтобы вовремя распознать угрозу.","Боец",[],["Шурима"],"РЕДКОЕ"],"04SH130":["Акшан","Призвав меня либо когда я наношу удар: призовите карту Дворец военачальника или продвиньте ее счетчик на 1 раунд.","Дворец военачальника завершил обратный отсчет. Когда я повышаю свой уровень, призовите Сокровища военачальника.","\"Кодекс Стражей какой-то слишком заморочный. «Не отними жизнь ради мести», «Сражайся за мир, а не за себя». А мой кодекс…\"","Боец",[],["Шурима"],"Чемпион"],"04SH114":["Гнев пустыни","Даруйте союзным картам Песчаных солдат везде +1|+0.\nПризовите 2 Песчаных солдат.","","Им не нужен отдых. Они не знают сомнений. Им не ведома жалость. Они не отступят.","Заклинание",[],["Шурима"],"РЕДКОЕ"],"04SH067":["Ренектон","Когда я выбираю противника, дайте мне +2|+1 до конца раунда.","Мне удалось нанести 10+ ед. урона.","\"Легко забыть, что он когда-то был человеком, ведь его любовь к кровавым боям так хорошо сочетается с крокодильей пастью!\" – Из \"Истории армии вознесшихся\" летописца Ка'нира","Боец",["ВОЗНЕСШИЕСЯ","РЕПТИЛИЯ"],["Шурима"],"Чемпион"],"04SH120":["Потенциальные возможности","Создайте в руке случайное место силы со счетчиком или продвиньте счетчики союзных мест силы на 1 раунд.","","\"Время быстротечно\". – Зилеан","Заклинание",[],["Шурима"],"РЕДКОЕ"],"04SH119":["Рикошет","Репутация: моя стоимость снижается на 3.\nНанесите 1 ед. урона случайному врагу или вражескому нексусу 5 раз.","","\"Возможно, придется запачкаться\". – Сивир","Заклинание",[],["Шурима"],"ОБЫЧНОЕ"],"04SH068":["Зер'сай-разведчик","Разыгрывая карту: сделайте Предсказание.","","Не все зер'сай рождены для охоты. Есть среди них и разведчики, призывающие сородичей пронзительными криками, от которых дрожит песок и кровь стынет в жилах.","Боец",["ОХОТНИК"],["Шурима"],"ОБЫЧНОЕ"],"04SH093":["Выточенный камень","Дайте союзнику +1|+1 до конца раунда.\nЕсли вы уже призывали место силы, вместо этого дайте ему +2|+1.","","\"Земля нам поможет, и мы сумеем защититься!\" – Талия","Заклинание",[],["Шурима"],"ОБЫЧНОЕ"],"04SH079":["Вещие пески","Сделайте Предсказание.\nДайте врагу -2|-0 до конца раунда.","","\"Я видел свою судьбу, и на этот раз мне никто не помешает\". – Азир","Заклинание",[],["Шурима"],"РЕДКОЕ"],"04SH038":["Пустынный лихач","Призвав меня, призовите карту Бушующие пески.","","\"Сегодня мы отправились в Нашраме. Самир хочет пересечь Великую Сай до полнолуния и в спешке уже чего только не натворил! Кто же знал, что обычный сэндборд может обрушить целую дюну?.. К счастью, никто не пострадал\".\n– Из дневника Заифы","Боец",[],["Шурима"],"ОБЫЧНОЕ"],"04SH104":["Реставратор","Разыгрывая карту: продвиньте счетчик союзного места силы на 3 раунда.","","Когда Зилеан хочет побыть наедине, он бродит в последнем саду Икатии, который выглядит совершенно так, как он его помнит.","Боец",[],["Шурима"],"РЕДКОЕ"],"04SH128":["Векаурская воришка","Призвав меня, призовите Дворец военачальника или продвиньте его счетчик на 2 раунда.","","Увидев Акшана, зацепившегося за подоконник на четвертом этаже, Наджа выругалась себе под нос. Этот красавчик опять ее опередил! Задумчиво вращая в руке кинжал, она пыталась подобрать слова, которые наконец заставят Акшана с ней считаться.","Боец",[],["Шурима"],"ОБЫЧНОЕ"],"04SH109":["Зыбучий песок","Дайте врагу -4|-0 или 2 врагам -1|-0 и лишите полезных навыков до конца раунда.","","В этой части пустыни древние руины ушли в песок. Остались каверны, в которые незадачливый путник может упасть и разделить судьбу руин. ","Заклинание",["СТИХИЯ"],["Шурима"],"ОБЫЧНОЕ"],"04SH043":["Подвижный песок","Нанесите бойцу 4 ед. урона.\nПризовите 2 Песчаных солдат.","","\"Вперед. Окружите их. Им не одолеть саму пустыню\".\n– Азир","Заклинание",[],["Шурима"],"РЕДКОЕ"],"04SH099":["Восстань!","Призовите карту Песчаный солдат.\nСоздайте в руке мимолетную карту Восстань!.","","\"Выполняйте приказ\". – Азир","Заклинание",[],["Шурима"],"РЕДКОЕ"],"04SH048":["Внутреннее святилище","Репутация: моя стоимость снижается на 3.\nОтсчитав 1 раунд: создайте в руке 2 Удачные находки.","","\"Бывают такие карты сокровищ, которые приходится расшифровывать годами, ловушки, на обезвреживание которых уходят месяцы, хранилища, которые можно обшаривать пару недель. Но когда все получается, они с лихвой окупят потраченное время\". – Сивир","Место силы",[],["Шурима"],"ОБЫЧНОЕ"],"04SH056":["Перекупщица","Призвав меня, создайте в руке карту Удачная находка.","","\"Дорогуша, специально для тебя я добыла эту красивейшую вещицу из легендарной Гробницы императоров, вырвав ее из руки самого Ренектона. Когда я уезжала, меня окружили десять – нет, двадцать! – кровожадных наездников на ящерах. То, что это сокровище лежит теперь в твоей ладони, – настоящее чудо!\"","Боец",[],["Шурима"],"ОБЫЧНОЕ"],"04SH020":["Сивир","","Вы нанесли 30+ ед. урона.","Сивир выбрала путь наемницы со всеми его опасностями и наградами. Одна роковая экспедиция чуть не стоила ей жизни, но впитавшаяся в шуримский песок кровь Сивир пробудила древнюю силу, способную вернуть величие ее древней родине и вознести ее саму.","Боец",[],["Шурима"],"Чемпион"],"04SH057":["Вдохновляющий маршал","Призывая союзника, дайте ему +2|+0 до конца раунда.","","Получить благословение Азира – великая честь. Благословлять от его имени – честь величайшая.","Боец",[],["Шурима"],"РЕДКОЕ"],"04SH103":["Безжалостная охотница","Разыгрывая карту: даруйте врагу Уязвимость.","","\"Ну вот, надежно связан. Красота! Ренектон любит, когда обед еще трепыхается\".","Боец",[],["Шурима"],"ОБЫЧНОЕ"],"04SH065":["Зерза'рет, Подземный исполин","Атака: если у меня 8+ силы, дайте мне Устрашение, Пробивание и Щит от магии до конца раунда.","","\"Говорят, много веков назад на берегу реки Калик располагалось крупное торговое поселение Таралик. Но в один роковой день из-под песков вырвалось ужасное чудовище и уничтожило Таралик и всех, кто там жил. Боюсь представить, какой силой должен был обладать этот зверь\". – Шуримский историк","Боец",["ОХОТНИК"],["Шурима"],"ЭПИЧЕСКОЕ"],"04SH034":["Часовщик","Призвав меня, создайте в руке 2 Прыжка во времени.","","На нижних уровнях рокочут шестерни, которые раскручивает Часовщик – бессменный хранитель башни.","Боец",[],["Шурима"],"ЭПИЧЕСКОЕ"],"04SH082":["Гибельный путь","Вытяните 1 карту.\nЕсли в этом раунде вы сразили бойца, истощите вражеский нексус на 2 ед. здоровья.","","Наездники на крокодилах пополняют свои ряды в основном за счет врагов. Тем, кто выживает в схватке с ними, предлагается выбор: присоединиться или умереть.","Заклинание",[],["Шурима"],"РЕДКОЕ"],"04SH075":["Разделяй и властвуй","Дайте врагам Уязвимость до конца раунда и призовите 6 Песчаных солдат.","","\"Мои солдаты идут вперед\". – Азир","Заклинание",[],["Шурима"],"ЭПИЧЕСКОЕ"],"04SH018":["Ритуал подчинения","Убейте союзника или разрушьте свой кристалл маны, чтобы дать всем врагам -2|-0 до конца раунда.","","\"Мы сражаемся, они льют кровь!\" – Ренектон","Заклинание",[],["Шурима"],"РЕДКОЕ"],"04SH009":["Буйствующий баккай","Разыгрывая карту: если в этом матче вы сразили 4+ бойцов, я и противник наносим удар друг другу.","","Затаенная обида становится все глубже, даже если обидчик уже давно мертв.","Боец",[],["Шурима"],"РЕДКОЕ"],"04SH049":["Удачливый поро","Начало раунда: если вы повышали уровень чемпиона, превратите меня в карту Величественный поро.","","Она не знала, что именно нашла… но это \"что-то\" блестело и так и просилось на зуб.","Боец",["ПОРО"],["Шурима"],"ОБЫЧНОЕ"],"04SH045":["Изнурение","Дайте врагу -2|-0 и сделайте его уязвимым до конца раунда.","","Жители пустыни знают, как укрыться он палящего солнца и невыносимого жара; а вот те, кто приходит в Великую Сай без подготовки, обнаруживают, что силы их буквально тают.","Заклинание",[],["Шурима"],"ОБЫЧНОЕ"],"04SH037":["Вздыбленная земля","Призовите 2 карты Бушующие пески.\nВытяните 1 карту.","","Великая Сай может быть очень красива, но здесь не место слабым. Сколько их погибло среди барханов! Многих настигли зер'сай, но и сами пески тоже могут быть смертоносны.","Заклинание",["СТИХИЯ"],["Шурима"],"РЕДКОЕ"],"04SH107":["Торжество вознесшегося","Повысьте уровень всех вознесшихся союзников 1-го уровня.","","\"Теперь историю будут писать вознесшиеся\". – Азир","Заклинание",[],["Шурима"],"ЭПИЧЕСКОЕ"],"04SH047":["Насус","У меня +1|+1 за каждого сраженного вами в этом матче бойца.","Мой удар нанес 10+ ед. урона за один удар.","\"Дар, который получил Насус, позволил ему посвятить огромное количество времени изучению жизни и смерти, их природы и взаимодействия. Однако после падения Шуримы долгая жизнь показалась ему скорее проклятием, чем даром\". – Из \"Истории армии вознесшихся\" летописца Ка'нира","Боец",["ВОЗНЕСШИЕСЯ","ПЕС"],["Шурима"],"Чемпион"],"04SH097":["Хранительница святилища","Разыгрывая карту: убейте вражеского сторонника. Если в этом матче вы сразили 13+ бойцов, убейте всех вражеских сторонников, а затем вместо этого призовите мою копию.","","Баккай защищают внутреннее святилище и его древние сокровища от смертных, которые считают себя достаточно сильными или хитрыми, чтобы пережить суд Хранительницы.","Боец",[],["Шурима"],"ЭПИЧЕСКОЕ"],"04SH026":["Хранитель дюн","Призвав меня, призовите карту Песчаный солдат.","","\"Император приказывает – я повинуюсь и повинуются пески\".","Боец",[],["Шурима"],"ОБЫЧНОЕ"],"04SH102":["Золотая посланница","Верность: вытяните карту чемпиона и даруйте ему +2|+2.","","\"Наше светлое будущее лежит под барханами. Мы должны проложить путь Азиру. Золотая империя пустыни возродится!\"","Боец",[],["Шурима"],"ОБЫЧНОЕ"],"04SH001":["Начинающий хрономант","Разыгрывая карту: сделайте Предсказание.","","Пока Тай изучал магию времени, в его сердце боролись неуверенность и решимость. Куда приятнее надеяться на возможную победу, чем беспокоиться обо всем, что может пойти не так.","Боец",[],["Шурима"],"ОБЫЧНОЕ"],"04SH022":["Зер'сай-дюнорез","","","Все зер'сай умеют рыть туннели, но лишь могучие дюнорезы способны пробиться сквозь каменные массивы, делящие Великую Сай на части, и проложить сородичам путь к новым охотничьим угодьям.","Боец",["ОХОТНИК"],["Шурима"],"РЕДКОЕ"],"04SH030":["Временной сдвиг","До конца раунда дайте союзному чемпиону особенность \"Если я погибаю, вместо этого полностью исцелите меня и даруйте мне +3|+3\".","","\"Неизбежное нельзя предотвратить… но можно задержать\". – Зилеан","Заклинание",[],["Шурима"],"РЕДКОЕ"],"04SH013":["Заповедник","Призвав меня, вытяните 1 карту.\nОтсчитайте 2 раунда и вытяните еще 1.","","Впуская в башню новых исследователей, Зилеан показывает им то, что пытается воссоздать. В этом ему помогает Реставратор, который способен на краткий миг реконструировать прошлое.","Место силы",[],["Шурима"],"РЕДКОЕ"],"04SH062":["Погребенный солнечный диск","В начале игры: призовите 1 мою копию из колоды, если в ней карты только из Шуримы.\nОтсчитайте 25 раундов: восстановите Солнечный диск.\nПродвигайте счетчик на 9 раундов за каждое повышение уровня любого Вознесшегося союзника в этом матче.","","Когда взгляду Азира предстал Солнечный диск в шуримской столице, бог-император увидел возможность вернуть свою страну к былой славе.","Место силы",[],["Шурима"],"ЭПИЧЕСКОЕ"],"04SH016":["Вытягивающий удар","Союзник наносит удар бойцу.\nЕсли тот умрет, даруйте +2|+2 союзным чемпионам везде.","","\"Твою душу взвесят и измерят\". – Насус","Заклинание",[],["Шурима"],"РЕДКОЕ"],"04SH125":["Векаурская взломщица","Разыгрывая карту: дайте союзнику +2|+0, чтобы дать врагу -2|-0 до конца раунда.","","Тена терпеливо дожидалась, когда ядовитая слюна ее питомца проест позолоченную решетку на задних воротах дворца. Сегодня ей предстояло найти целую гору невероятно ценных сокровищ, которых хватило бы, чтобы вернуть Векауре былую славу.","Боец",[],["Шурима"],"РЕДКОЕ"],"04SH108":["Клинок-бумеранг","Союзник наносит удар сначала сильнейшему, затем слабейшему врагу.","","\"Пригнись!\" – Сивир","Заклинание",[],["Шурима"],"РЕДКОЕ"],"04SH066":["Время в бутылке","Сделайте Предсказание и продвиньте счетчик союзного места силы на 2 раунда.","","\"Если бы вы видели время так, как вижу его я, то не называли бы его течение бесповоротным \". – Зилеан","Заклинание",[],["Шурима"],"ОБЫЧНОЕ"],"04SH021":["Вернувшийся Кахири","Призвав меня, создайте в колоде мою копию. Увидев меня в предсказании, даруйте +2|+2 всем моим союзным копиям везде.","","Кахири исчез всего на миг – и тут же вернулся повзрослевшим лет на десять, с диковинным и опасным на вид оружием. Его встретили вздохами удивления и испуганными взглядами.","Боец",[],["Шурима"],"РЕДКОЕ"],"04SH101":["Верный вассал","Начало раунда: если вы повышали уровень чемпиона, исцелите своих чемпионов и нексус на 2 ед. здоровья.","","\"Я поклялся служить Азиру и Шуриме – своей родине. Следуйте моему примеру!\"","Боец",[],["Шурима"],"РЕДКОЕ"],"04SH012":["Почтенный иерофант","Призвав меня, продвиньте счетчик карты Погребенный солнечный диск на 3 раунда.","","\"Ого! Папа, это же Паджуман, старейшина из Нашраме! Кто только не прибыл сегодня в наш город!\"  \n– Взволнованный зевака","Боец",[],["Шурима"],"ОБЫЧНОЕ"],"04SH031":["Большое будущее","Даруйте союзному месту силы особенность \"Мой эффект отсчета срабатывает дважды\".","","\"Смертные столько времени проводят в ожидании. Я могу лишь надеяться, что их терпение будет вознаграждено\". \n– Зилеан","Заклинание",[],["Шурима"],"ЭПИЧЕСКОЕ"],"04SH004":["Взвешенное решение","Нанесите 2 ед. урона чемпиону или 4 ед. урона стороннику.","","\"Одна жизнь – за тысячу других. Одна жизнь – цена процветания множества\". – Насус","Заклинание",[],["Шурима"],"ОБЫЧНОЕ"],"04SH059":["Ритуал отрицания","Убейте союзника или разрушьте свой кристалл маны, чтобы остановить все вражеские способности, а также быстрые и медленные заклинания.","","В магии времени широко применяются аналитические методы, требующие остановки текущих процессов для решения проблем в будущем.","Заклинание",[],["Шурима"],"ЭПИЧЕСКОЕ"],"04SH044":["Заводной помощник","Разыгрывая карту: продвиньте счетчик союзного места силы на 2 раунда.","","Механизмы, охраняющие башню Зилеана, тысячелетиями выдерживают суровый климат пустыни, и дело не только в их хитром устройстве.","Боец",[],["Шурима"],"ОБЫЧНОЕ"],"04SH076":["Древние песочные часы","Уничтожьте союзника, чтобы призвать вместо него карту Изваяние стазиса, внутри которой он будет храниться.","","\"О, Тай! Иди-ка сюда! Помоги нам кое с чем\".\n– Зетса, исследовательница Бездны","Заклинание",[],["Шурима"],"РЕДКОЕ"],"04SH118":["Пробуждение песков","Призовите карту Песчаный скакун.","","\"Саркофаг наверняка представляет ценность, а вот то, что внутри, – точно нет. Поэтому лучше вообще не открывайте его. Я по опыту говорю\". – Сивир","Заклинание",[],["Шурима"],"ОБЫЧНОЕ"],"04SH072":["Прорицательница","Призвав меня, даруйте союзным чемпионам и местам силы Щит от магии.","","\"Удивлены, что посреди пустыни есть вода? Не тревожьтесь. Пейте сколько хотите, омойте усталые ноги, отдохните в тени. Новая Шурима Азира – цветущий оазис\".","Боец",[],["Шурима"],"ОБЫЧНОЕ"],"04SH041":["Разведчица Сай","Разыгрывая карту: сделайте Предсказание. Если вы выберете место силы, даруйте мне Изворотливость.","","\"Сегодня мы чуть не влипли. С запада шла сильная буря, но Талия провела нас по норам зер'сай к югу отсюда. Я высмотрела храм на севере, и теперь мы укрылись за его терракотовыми стенами. Все уже спят, да и меня клонит в сон. Огонь скоро погаснет. Надеюсь, мне будут сниться хорошие сны\".\n– Из дневника Заифы","Боец",[],["Шурима"],"ОБЫЧНОЕ"],"04SH005":["Кровожадный мародер","","","Наездники на крокодилах неразлучны со своими \"скакунами\". Они вместе сражаются, охотятся, убивают… и даже едят.","Боец",[],["Шурима"],"ОБЫЧНОЕ"],"04SH083":["Зловещее предзнаменование","Сделайте Предсказание.","","\"Гребень внушает страх, клыки сулят смерть\".\n– Шуримская поговорка","Заклинание",[],["Шурима"],"РЕДКОЕ"],"04SH092":["Время пришло","Призовите карту Маховичок.\nЕсли вы уже делали Предсказание, вместо этого призовите 2 таких карты.","","\"Подойди-ка сюда и перестань суетиться, а то песок в шестеренки забьется\". – Тай, начинающий хрономант","Заклинание",[],["Шурима"],"ОБЫЧНОЕ"],"04SH046":["Песчаная химера","Моя стоимость снижается на 1 каждый раз, когда союзник атакует в этом матче.","","После возвращения Азира шуримцы стали замечать в пустыне древних мифических тварей, состоящих из песка, но от этого не менее впечатляющих.","Боец",[],["Шурима"],"РЕДКОЕ"],"04SH105":["Гробница в песках","Когда атакуют союзники, призовите атакующего бойца Песчаный скакун.","","Идя по расщелине, Ваятель песка начала читать заклинания. По каньону тут же пронесся порыв ветра, в котором эхом гремел топот конских копыт.","Место силы",[],["Шурима"],"РЕДКОЕ"],"04SH131":["Зацепной пистолет","Союзник, которого вы уже выбирали целью в этом раунде, наносит удар врагу.","","\"Летящий крюк всегда застает врасплох\". – Акшан","Заклинание",[],["Шурима"],"РЕДКОЕ"],"04SH074":["Детеныш зер'сай","","","Иногда взрослые особи зер'сай нападают на караваны, опрокидывают повозки и отступают, чтобы детеныши могли поохотиться на выживших. Так молодняк оттачивает инстинкты и учится различать среди звуков пустыни те, что выдают добычу.","Боец",["ОХОТНИК"],["Шурима"],"ОБЫЧНОЕ"],"04SH137":["Гудящий рой","Когда меня призывают, создайте в руке мою копию, если в этом матче вы повысили уровень чемпиона.","","Считалось, что гигантские скарабеи вымерли, когда пала Шуримская империя. Но рыщущие щупальца тумана проникли глубоко в песок и поставили этих древних тварей на службу Виего.","Боец",[],["Шурима"],"ЭПИЧЕСКОЕ"],"04SH069":["Беспощадный хищник","Дайте союзнику +2|+0, чтобы дать врагу Уязвимость до конца раунда.","","\"Разорвать их!\" – Ренектон","Заклинание",[],["Шурима"],"ОБЫЧНОЕ"],"04SH121":["Ритуал призыва","Убейте союзника или разрушьте свой кристалл маны, чтобы вытянуть чемпиона.","","\"Необходимая жертва\". – Насус","Заклинание",[],["Шурима"],"ОБЫЧНОЕ"],"04SH110":["Прядение камней","Воплотите место силы, на которое вам хватает маны.","","\"Идем! Тут есть, на что посмотреть!\" – Талия","Заклинание",["СТИХИЯ"],["Шурима"],"ЭПИЧЕСКОЕ"],"04SH051":["Пьедестал императора","Когда атакуют союзники, призовите атакующего бойца Песчаный солдат.","","Ваятели песка воздели руки, силой мысли придавая песку знакомые формы закованных в броню безликих солдат. Не знающее устали войско было готово сражаться за своего бога-императора. ","Место силы",[],["Шурима"],"РЕДКОЕ"],"04SH106":["Призрачный огонь","До конца раунда дайте врагам -2|-0 и особенность \"В конце раунда нанесите мне 2 ед. урона\".","","\"Их души будут гореть\". – Насус","Заклинание",[],["Шурима"],"РЕДКОЕ"],"04SH129":["Векаурский воин","Удар: создайте в руке карту Удачная находка.","","\"Слушай внимательно, Шипик. На этом этаже охраны больше нет, но нам все равно надо вести себя потише\".\n\"БЛАРГХ-БЛА!\"\n\"Шипелла! Потише, говорю!\"\n\"Бларб\".\n\"Умница\".","Боец",[],["Шурима"],"РЕДКОЕ"],"04FR006":["Драклорн-инквизитор","Призвав меня, призовите карту Ледяной раб.\nВ конце раунда: если счетчик любого из ваших Ледяных рабов дошел до 4 или менее, продвиньте его до 0.","","\"Моя госпожа является мне во сне и еле слышно шепчет: 'Следуй за мной'. Этому приказу я не могу противиться\".","Боец",[],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"04FR012":["Ледяное погребение","Уничтожьте всех врагов, чтобы призвать вместо них карты Ледяная гробница, внутри которых они будут храниться.","","\"Рано или поздно холод одолеет любого\". – Лиссандра","Заклинание",["СТИХИЯ"],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"04FR016":["Трофеи","Даруйте союзнику +1|+2.\nРазграбление: вместо этого даруйте +2|+4.","","\"Племя аваросан превратилось в кучку мягкотелых слабаков! Что ж, продолжайте жиреть, собирая урожай со своих плодородных полей. Пока вы будете мечтать о завтрашней добыче, мы заберем ее!\" – Вринна, мать шрамов","Заклинание",[],["Фрельйорд"],"ОБЫЧНОЕ"],"04FR013":["Морозостойкость","Получите пустой кристалл маны и даруйте союзнику +0|+2.","","\"Берегитесь льда… а еще больше – того, что под ним скрыто!\" – Надпись, выцарапанная на стене постоялого двора во Фрельйорде","Заклинание",["СТИХИЯ"],["Фрельйорд"],"ОБЫЧНОЕ"],"04FR005":["Лиссандра","Призвав меня, призовите место силы Ледяной раб и продвиньте его счетчик на 2 раунда.","Вы призвали 2+ союзников стоимостью 8+. Когда мой уровень повышается, создайте в руке карту Наблюдатель.","\"За этими стенами ждут своего часа Наблюдатели, замершие во времени, застывшие во льду. И пока они выжидают, я должна осуществить свои планы…\"","Боец",[],["Фрельйорд"],"Чемпион"],"04FR011":["Объятия холода","Заморозьте врага.\nПризовите карту Ледяной раб.","","\"На холод все реагируют по-разному. Посмотрим, что будет с тобой!\" – Лиссандра.","Заклинание",["СТИХИЯ"],["Фрельйорд"],"ОБЫЧНОЕ"],"04FR001":["Ледяной раб","Отсчитайте 9 раундов и призовите карту Раб Морозных стражей.","","В трудноуправляемой орде Трандла хватало полудурков, которых не жаль было бросить на вражеские штыки. Но Лиссандре нужен был боец, который верно служил бы ей и только ей одной…","Место силы",[],["Фрельйорд"],"ОБЫЧНОЕ"],"04FR007":["Погребение","Уничтожьте бойца, чтобы призвать вместо него карту Ледяная гробница​, внутри которой он будет храниться.","","\"На колени! Не то заморожу\". – Лиссандра","Заклинание",["СТИХИЯ"],["Фрельйорд"],"РЕДКОЕ"],"04FR017":["Благословение предков","Даруйте верхнему союзнику в своей колоде +2|+2.\nПросветление: вместо этого даруйте всем союзникам в своей колоде +2|+2.","","Большинство путников гибнет в пустошах Фрельйорда от лютого мороза и снежных буранов. Те же, кому удается выжить, находят в себе внутреннюю силу, которая всю оставшуюся жизнь помогает им непреклонно двигаться к цели.","Заклинание",[],["Фрельйорд"],"ОБЫЧНОЕ"],"04FR014":["Проклятое ущелье","Призвав меня, восстановите 2 ед. здоровья своему нексусу.\nОтсчитайте 1 раунд и нанесите 2 ед. урона ВСЕМ бойцам.","","В этом ущелье повсюду возвышаются причудливые фигуры из темного льда; острые кристаллы, из которых они состоят, отпугивают чересчур любопытных путников.","Место силы",[],["Фрельйорд"],"РЕДКОЕ"],"04FR009":["Ледяной осколок","Нанесите 1 ед. урона ВСЕМУ.","","\"Я похороню мир под толщей льда\". – Лиссандра","Заклинание",["СТИХИЯ"],["Фрельйорд"],"ОБЫЧНОЕ"],"04FR015":["Легендарный поро","Призвав меня, даруйте всем союзным поро случайный навык.","","Каждый поро знает легенду о путешественнике, который дарит достойным пушистикам магические предметы собственного изготовления.","Боец",["ПОРО"],["Фрельйорд"],"РЕДКОЕ"],"04FR019":["Матерь снежнозубых","Призвав меня, призовите карту Снежнозубая стая.","","Настороженно пригибаясь к земле, снежнозубые волки окружили дрювасского хряка. Над ним уже витал запах смерти – тяжелый и резкий.","Боец",["ПЕС"],["Фрельйорд"],"РЕДКОЕ"],"04FR018":["Чудовищный страж","Когда я в руке, начало раунда: если у вас есть 2+ йети, призовите меня и создайте в своей колоде мою копию.\nРазыгрывая карту: вытяните йети.","","\"...и появляются будто из ниоткуда! Заплутал я как-то в их краях, забрел в пещеру, гляжу – а там детеныши спят. Отошел в сторонку, чтоб не потревожить, а за спиной у меня уже здоровяк стоит – вышиной с гору, весь инеем покрытый! Ты слушай, слушай, что дальше-то было...\"\n– Бормочущий Бьорг","Боец",["ЙЕТИ"],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"04FR010":["Три сестры","Создайте в руке мимолетную карту Мгновенная заморозка, Ярость севера или Погребение.","","Фрельйордские сестры Авароса, Серильда и Лиссандра были наделены огромной силой, но использовали ее по-разному, ведь одна была милосердна, другая воинственна, а третья – коварна.","Заклинание",[],["Фрельйорд"],"РЕДКОЕ"],"04NX002":["Вкрадчивый шепот","Репутация: моя стоимость снижается на 2.\nВытяните 2 карты.","","Новостям предшествуют слухи. Слухам – игра. Игре – замысел.","Заклинание",[],["Ноксус"],"РЕДКОЕ"],"04NX010":["Шип Розы","Когда меня призывают, создайте в руке карту Коварство.","","\"Моя дорогая Элана! Не видели ли вы лорда Дюина? Нет? Жаль, я так хотела с ним побеседовать. Надеюсь, он не совершил ничего опрометчивого... Не хотелось бы, чтобы с нашим старым другом что-нибудь случилось, правда, коллега?\" – Леди Оврей, шпионка Черной Розы","Боец",[],["Ноксус"],"ОБЫЧНОЕ"],"04NX021":["Уставший уравнитель","Выбирая меня целью, даруйте мне +1|+0.","","После бессчетных боев Берин поклялся никогда больше не поднимать меча, даже если от этого будет зависеть его жизнь. Но когда странный туман заполонил Ноксус и поработил Тею, Берин понял, что клятву придется нарушить. Он решил освободить боевую подругу любой ценой.","Боец",[],["Ноксус"],"РЕДКОЕ"],"04NX022":["Падшая уравнительница","Призвав меня, создайте в руке карту Ночной набег.","","Когда Теа вышла из заключения, путь домой был ей заказан. Война – и Ноксус – изменили ее, превратив в убийцу. Вернуться к мирной жизни она уже не смогла бы. И Теа нашла применение своим новым навыкам на арене, где можно было неплохо подзаработать.","Боец",[],["Ноксус"],"РЕДКОЕ"],"04NX015":["Дело крови","Репутация: моя стоимость снижается на 2.\nСоюзник с силой 5+ наносит удар врагу.","","\"Скрытые угрозы – самые опасные\". – Ле Блан","Заклинание",[],["Ноксус"],"ОБЫЧНОЕ"],"04NX019":["Неукротимый кусака","Когда меня блокирует враг, дайте мне +3|+0 до конца раунда.","","Это найденное на берегах Ионии существо доставили в империю по настоянию юного полководца, который был поражен его выносливостью и решил испытать его силу.","Боец",["РЕПТИЛИЯ"],["Ноксус"],"ЭПИЧЕСКОЕ"],"04NX008":["Проницательный стратег","Репутация: моя стоимость снижается на 2.\nПризвав меня, используйте Рвение.","","Во внутренних покоях Черной Розы ноксианские аристократы играют судьбами, словно пешками, – и смерть находит обреченных даже на большом расстоянии.","Боец",[],["Ноксус"],"РЕДКОЕ"],"04NX006":["Шпионка Черной Розы","Репутация: призвав меня, превратите меня в точную копию сильнейшего союзника, который нанес удар в этом раунде.","","\"Ценность секрета измеряется тем, на что вы готовы пойти, чтобы его сохранить\".","Боец",[],["Ноксус"],"ЭПИЧЕСКОЕ"],"04NX001":["Копия","Репутация: моя стоимость снижается на 3.\nРазыграв следующее заклинание в этом раунде, повторите его на тех же целях.","","Подражание – высшая форма лести, а лесть бывает смертельно опасной.","Заклинание",[],["Ноксус"],"РЕДКОЕ"],"04NX004":["Ле Блан","","На моих глазах вы нанесли 15+ ед. урона. Когда мой уровень повышается, создайте в руке карту Отражение.","\"Прошу вас, не нужно ссориться. Не будем действовать опрометчиво. Давайте соберемся снова, когда появятся вести от посла. Ведь, в конечном счете…\"","Боец",[],["Ноксус"],"Чемпион"],"04NX016":["Шипящий прядильщик","Атака: дайте союзникам-паукам +2|+0 до конца раунда.","","\"Ступай, мой милый. Пусть твой зов услышат остальные. Ты знаешь, как он их будоражит. И как мне это нравится\". – Элиза","Боец",["ПАУК"],["Ноксус"],"РЕДКОЕ"],"04NX007":["Атахан, Вестник гибели","Разыгрывая карту: оживите своего сильнейшего погибшего союзника.\nАтака: даруйте мне силу, равную суммарной силе всех союзников, включая мою.","","Зал заполнен клубящимся дымом. Маги нестройно распевают заклинания дрожащими от ужаса голосами, а над ними возвышается безымянное чудовище. Смакуя их нарастающий страх, оно делает глубокий вдох – и по его жилам струится ужасающая мощь.","Боец",[],["Ноксус"],"ЭПИЧЕСКОЕ"],"04NX018":["Алая кровопускательница ","Призывая следующего союзника, нанесите ему 1 ед. урона и даруйте мне +1|+1.","","\"Их редко держат в качестве питомцев… такими коготками можно и вену ненароком перерезать. Но я не боюсь\". – Клара, Алая ученица","Боец",["КОШКА"],["Ноксус"],"ОБЫЧНОЕ"],"04NX003":["Печать порока","Репутация: моя стоимость снижается на 2.\nНанесите 2 ед. урона любой цели.","","Выиграв бой, нельзя медлить. Нужно развить успех, преследовать и уничтожить врага.","Заклинание",[],["Ноксус"],"ОБЫЧНОЕ"],"04NX017":["Сила в количестве","Призовите 2 Ноксианских мародеров.","","Ноксианские солдаты мало кого оставляют в живых, а ноксианские мародеры – и того меньше.","Заклинание",[],["Ноксус"],"ОБЫЧНОЕ"],"04NX009":["Кинжал Черной Розы","Дайте союзнику +5|+0 до конца раунда.","","\"Обходитесь с целью вежливо и учтиво. Льстите, слушайте, учитесь. Докажите, что вам можно доверять. А затем, когда придет время, нанесите удар – в самое сердце\". – Ле Блан","Заклинание",[],["Ноксус"],"ОБЫЧНОЕ"],"04SI005":["Киндред","В каждом раунде, когда вы впервые сражаете бойца, я помечаю знаком слабейшего врага.\nКонец раунда: убейте бойцов с моим знаком.","На моих глазах вы сразили 2+ бойцов с моим знаком.","Жил-был на свете грустный человек.\nОн взял топор и поутру\nРассек себя на половинки две,\nЧтобы у них всегда был друг.","Боец",[],["Сумрачные острова"],"Чемпион"],"04SI055":["Виего","После гибели первого другого союзника в каждом раунде призывайте карту Подступающий туман.","На моих глазах погибли союзники с силой суммарно 20+.","\"Что-то в поведении юного короля вызывает у меня глубокую тревогу. Его душу словно жжет неутолимый голод, некая страсть, которая никак не насытится\". – Из записок Нуньо Некрита из Камавора","Боец",[],["Сумрачные острова"],"Чемпион"],"04SI016":["Душепийца ","Разыгрывая карту: убейте союзника, чтобы вытянуть 2 карты.","","Они рыскают среди теней, выжидая, когда сонно склонится голова, когда опустеет разум. И тогда – когти, зубастая пасть и, наконец, темнота.","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"04SI007":["Пожиратель памяти","Разыгрывая карту: убейте союзника, чтобы убить врага.","","\"Мне осталось на этом свете не так уж много, и я задумываюсь не столько о своей первой смерти, сколько о второй. Скоро ли меня забудут? Что случится со мной, когда умрет последний, кто помнил мое имя?\" \n– Известный меценат","Боец",["ПТИЦА"],["Сумрачные острова"],"РЕДКОЕ"],"04SI011":["В сумрак","Вытяните 1 карту.\nНочь: активируйте ночной эффект союзника, игнорируя ту часть эффекта, где нужно выбрать цель.","","\"Подойди, дитя. Бояться не нужно\". – Матерь масок","Заклинание",[],["Сумрачные острова"],"РЕДКОЕ"],"04SI018":["Проклятый лес","Когда на моих глазах атаковали 3+ устрашающих или ночных союзника, разрушьте меня, чтобы призвать карту Вайлмо.","","Забыты смерти алтари и заросла тропа,\nНо тварь, что рыщет в темноте, по-прежнему жива.","Место силы",[],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"04SI015":["Морской скарабей","Предсмертный вздох или когда умирает другой союзник: выбросьте из колоды 1 карту.","","\"Давайте, парни, поднимайте ловушки! Если увидите морского скарабея – сразу режьте веревку и двигайтесь дальше. Не хочу рисковать лодкой ради того, что они зажевали. Всем ясно?\" – Билджвотерский капитан","Боец",["МОРСКОЕ ЧУДОВИЩЕ"],["Сумрачные острова"],"РЕДКОЕ"],"04SI004":["Крылья и Волна","Разыгрывая карту: разыграйте меня как карту Первая волна или как карту Последний ветер.","","Кинку признают лишь двух богов: Первую волну, что бережно вынашивает жизнь в своих теплых водах, и Последний ветер, который отнимает жизнь финальным леденящим вздохом.","Боец",[],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"04SI017":["Песнь Островов","Даруйте союзнику Вампиризм, Устрашение и Эфемерность.","","\"Подойди, дитя. Ты увидишь то же, что и я. Почувствуешь то же, что и я. Не бойся темноты\". – Зажигающий свечи","Заклинание",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"04SI054":["Камаворская воительница","Призвав меня, призовите Подступающий туман.","","Камаворские воины сражались за Виего при жизни, а потом и после смерти. Даже она не пошатнула их преданности.","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"04SI001":["Милость Овечки","Дайте слабейшему союзнику особенность \"В этом раунде я не получаю урон и не умираю\".","","\"Вспыхни ярко, прежде чем погаснуть\". – Овечка","Заклинание",[],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"04SI056":["Иссушающий туман","Истощите 2 врагов на 2 ед. здоровья.","","\"Я возьму то, что мне нужно, а от ненужного избавлюсь без сожаления\". – Виего","Заклинание",[],["Сумрачные острова"],"РЕДКОЕ"],"04SI012":["Астральный лис","Разыгрывая карту: убейте союзника, а затем нанесите 3 ед. урона вражескому нексусу.","","Некоторые таргонские племена верят, что одинокая звезда в ночном небе – это бог смерти Лис. По легенде Лис спускается на гору за душами умерших, забирает их на небо и вплетает в свои темные созвездия.","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"04SI029":["Отчаяние","Выберите бойца, который нанесет вашему нексусу удар, а затем убейте его.","","\"Я отдал все, чтобы ее найти, но этого оказалось мало\".\n– Виего","Заклинание",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"04SI009":["Ткач душ","Призвав меня, даруйте мне +1|+1 и Устрашение, если в этом раунде погиб союзник.","","\"Жил-был незадачливый юноша, который решил поухаживать за паучихой, не подозревая, что попадет в ее сети…\"","Боец",["ПАУК"],["Сумрачные острова"],"ОБЫЧНОЕ"],"04SI013":["Матерь масок","Разыгрывая карту: убейте союзника, чтобы даровать мне его характеристики и навыки.","","Согласно легенде, Матерь масок создала Киндред, как и все остальные воплощения смерти. Но от кого же она получила собственную маску, если не создала ее сама?","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"04SI021":["Ползучий змей","Чтобы сыграть меня, я наношу удар союзнику или 3 ед. урона своему нексусу.","","Сперва демасийские солдаты подумали, что по вымощенной плиткой площади заскребли десятки когтистых лап. И лишь когда тварь прорвалась через сторожевую башню, стало ясно, что все эти лапы принадлежат одному существу.","Боец",["ДРАКОН"],["Сумрачные острова"],"ОБЫЧНОЕ"],"04SI002":["Духовное путешествие","Убейте бойца, а затем оживите его.","","\"Это только антракт\". – Овечка","Заклинание",[],["Сумрачные острова"],"РЕДКОЕ"],"04SI053":["Змеиные лозы","Призвав меня или в начале раунда: призовите Подступающий туман.","","Маокай без устали взращивал жизнь на Сумрачных островах. Но двойственная сущность тумана превратила все его труды в жестокий фарс.","Боец",[],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"04SI003":["Полузабытый божок","Призвав меня, призовите карту Добыча.","","Те, на ком лежит проклятье бессмертия, в конце концов забыли своего бога смерти. А для такого божества нет ничего страшнее забвения! ","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"04SI028":["Камаворский дракон","Чтобы сыграть меня, я наношу удар союзнику или 3 ед. урона своему нексусу.\nКогда я убиваю другого бойца, то истощаю вражеский нексус на 1 ед. здоровья.","","На протяжении столетий черный туман подбирался к самым разным созданиям, искажая и извращая их, так что они становились кошмарным отражением себя прежних.","Боец",["ДРАКОН"],["Сумрачные острова"],"РЕДКОЕ"],"04MT014":["Око Ра-Хорак","Отсчитайте 1 раунд и оглушите 2 слабейших врагов.\nДень: призовите мою копию с цифрой 2 на счетчике.","","\"Пусть солнце озарит нас своим светом! Пусть слабые и недостойные дрожат пред его ликом!\" – Жрица Солари","Место силы",[],["Таргон"],"РЕДКОЕ"],"04MT008":["Мальфит","Разыгрывая карту: оглушите врага.","Вы призвали места силы общей стоимостью 10+ ед. маны. Когда я повышаю свой уровень, создайте в руке карту Безудержная сила, если у вас есть жетон атаки.","\"А вот и конечная остановка нашей обзо'ной экску'сии по Та'гону! Это ПАПА! Он самый БОЙШОЙ из гигантов Та'гона, а еще он очень кьюто поет! Тойко не надо на него зайезать! Шипы его щекочут, а если ПАПА чихнет, пока вы заби'аетесь, вам не пон'авится, честно!\n– \"Путешествия со Сколом\", часть VI","Боец",[],["Таргон"],"Чемпион"],"04MT010":["Звездный пик","Отсчитайте 2 раунда и создайте в руке 2 случайных творения небес стоимостью 3 или менее.","","Паломники, совершающие восхождение на Таргон, уже в начале пути могут полюбоваться потрясающими видами. Мало что на Рунтерре сравнится с этим зрелищем. И чем выше удается подняться, тем щедрее вознаграждает Гора.","Место силы",[],["Таргон"],"РЕДКОЕ"],"04MT005":["Скол","Призвав место силы впервые за матч, даруйте мне +2|+2.","","\"Всем пьивет, меня зовут Скол, и сегодня я покажу вам Та'гон! Он о-о-очень бойшой и о-о-очень высокий! Надеюсь, у вас удобная обувь для подъема! ВПЕЬОД!\n– \"Путешествия со Сколом\", часть I","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"04MT009":["Лестница-серпантин","Отсчитайте 3 раунда и создайте в руке Росток силы.","","\"А вот и пе'вая остановка нашей обзо'ной экску'сии! Я называю ее \"койеноподгибайкой\", потому что тут много ступенек! Но очень кьютой вид! К'асиво, как и везде на Та'гоне. Что ж, ВПЕЙОД!\"\n– \"Путешествия со Сколом\", часть II","Место силы",[],["Таргон"],"РЕДКОЕ"],"04MT001":["Камнепад","Отсчитайте 2 раунда и уничтожьте слабейшего врага.","","\"Смот'ите под ноги: тут К'УТОЙ ОБ'ЫВ! Я уже нескойко 'аз падал, а йететь тут дайеко! Я-то каменный, я п'осто отскочил, а вы не каменные… так что поосто'ожней! О, смот'ите, Ска'а! Давайте поздо'оваемся!\"\n\"Путешествия со Сколом\", часть III","Место силы",[],["Таргон"],"ОБЫЧНОЕ"],"04MT018":["Напуганный козерог","Когда меня поддерживают, дайте мне и поддерживающему меня союзнику +1|+1 до конца раунда.","","\"Не бойся, если буря стонет\nИ мчится с гор с дождем и градом.\nТебя, родной, никто не тронет.\nСпи, мой малыш, ведь мама рядом\". – Таргонская колыбельная","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"04MT004":["Синий страж","Предсмертный вздох: призовите карту Знак озарения.","","\"А СЕЙЧАС МЫ ПОЗНАКОМИМСЯ С СИНИМ! Скажите: \"ПЬИВЕТ, СИНИЙ!\" Как-то йаз мне показа'ось, что он ответил: \"Пьивет, Синий\". Но сейчас я понимаю, что это п'осто эхо! Ну и йадно! Он такой магический, да еще и синий, что ему даже не надо говоьить! ЙАДНО, ПОКА, СИНИЙ! МЫ УХОДИМ!\n– \"Путешествия со Сколом\", часть V","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"04MT013":["Солнечный ястреб Солари","День: оглушите сильнейшего врага.","","Солари считают, что именно блистающие опереньем солнечные ястребы Таргона в свое время привлекли внимание Бессмертного Огня и запустили цикл его перерождений.","Боец",["ПТИЦА"],["Таргон"],"ОБЫЧНОЕ"],"04MT003":["Дух земли","Призвав 4+ места силы, даруйте мне +3|+0.","","\"Знакомьтесь: это Ска'а! Он очень бойшой! Ска'а тут давненько, он тут, знаете, ста'ожил! И да, он выгьядит к'уто, и даже очень добьенко выгьядит, но у него на спине очень тяже'ые штуки, и иногда они падают на йудей, так что поосто'ожней, пожауйста! А сейчас идем дайше!\"\n– \"Путешествия со Сколом\", часть IV","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"04MT002":["Камнелом","Разыгрывая карту: если за этот матч вы призвали 4+ места силы, нанесите 4 ед. урона врагу и 2 ед. урона вражескому нексусу.","","Иногда колоссы Таргона пробуждаются ото сна и ищут себе новые места на склоне. В горах в это время совсем не тихо и уж точно не безопасно.","Боец",[],["Таргон"],"ЭПИЧЕСКОЕ"],"04MT006":["Звездное откровение","Используйте Зов.\nЕсли у вас есть союзное творение небес, замените свою колоду 20 копиями карты Узрите бесконечность.","","\"В небе так много звезд, Кулун, и каждой есть что рассказать! Какую из этих историй мы послушаем сегодня?\" – Лунная сновидица","Заклинание",[],["Таргон"],"ЭПИЧЕСКОЕ"],"04MT012":["Зов судьбы","Даруйте союзнику в руке +8|+8.","","\"Прими свою судьбу и сияй ярче, чем от тебя могли ожидать\". – Тарик","Заклинание",[],["Таргон"],"ЭПИЧЕСКОЕ"],"04MT007":["Удар по земле ","Оглушите врага. Нанесите ему 3 ед. урона, если за эту игру вы призывали место силы.","","\"О-о да, это п'осто земья тьясется, а папа тут ни пьи чем, он вовсе ничего сейчас не девает! ОЙ, Я ОШИБСЯ. Давайте, быстьее, ВПЕЬОД И ВВЕ'Х!\" – Скол","Заклинание",["СТИХИЯ"],["Таргон"],"РЕДКОЕ"],"04MT015":["Небесный цикл","День: создайте в руке случайную ночную карту.\nНочь: создайте в руке случайную дневную карту.","","День сменяется ночью, ночь сменяется днем – да будет так во веки веков.","Заклинание",[],["Таргон"],"ОБЫЧНОЕ"],"04DE004":["Целеустремленная разведчица","Моя стоимость снижается на 1, когда вы призываете элитного бойца.","","Ноксианцы устроили засаду удачно, но никто не знал эти леса лучше демасийских разведчиков. Каждая сломанная ветка, каждый след на земле вели их все ближе к принцу.","Боец",["ЭЛИТА"],["Демасия"],"РЕДКОЕ"],"04DE014":["Драконья закуска","Когда вы разыгрываете дракона, он наносит мне удар, а вы вытягиваете 1 карту.","","\"Слышишь: высоко в небе раздался крик? Это, мальчик мой, не птица. Так кричит дракон на охоте\".\n– Демасийский земледелец","Боец",[],["Демасия"],"ОБЫЧНОЕ"],"04DE001":["Почтенный лорд","Когда я впервые выбираю противника, дайте мне Щит до конца раунда.","","Узнав о том, что его сын пропал, король Джарван III поручил организацию поисков своему другу, лорду Барретту Бювеллю. Принц вернулся живым и невредимым. А вот лорд Бювелль, к великой скорби короля, — нет.","Боец",["ЭЛИТА"],["Демасия"],"ОБЫЧНОЕ"],"04DE012":["Повышение в звании","Даруйте разведку следующему бойцу, которого сыграете в этом раунде. Он становится элитным.","","Демасийцы храбро встречают опасность и с честью держат удар.","Заклинание",[],["Демасия"],"ОБЫЧНОЕ"],"04DE003":["Катаклизм","Союзник самостоятельно идет в атаку, выбирая противника.","","\"За короля!\" – Джарван IV","Заклинание",[],["Демасия"],"РЕДКОЕ"],"04DE002":["Золотая эгида","Дайте союзнику Щит до конца раунда.\nИспользуйте Рвение.","","\"Будьте стойкими, воины Демасии!\" – Джарван IV","Заклинание",[],["Демасия"],"РЕДКОЕ"],"04DE006":["Военная выправка","Даруйте союзнику +1|+1.","","\"Смотри и учись\". – Лорд Бювелль","Заклинание",[],["Демасия"],"ОБЫЧНОЕ"],"04DE008":["Джарван IV","Атакуя, призовите меня за мою стоимость, и я выберу противником сильнейшего врага.","Союзники выжили, получив 3+ удара от блокирующих врагов.","Ноксианцы знали, куда принц Джарван отправится на охоту и скольких воинов возьмет с собой – как знали и то, что честь не позволит ему просто сбежать в случае опасности. И они устроили ему ловушку.","Боец",["ЭЛИТА"],["Демасия"],"Чемпион"],"04DE005":["Цитрия, Повелительница облаков","Призвав меня, удвойте силу и здоровье остальных союзников и даруйте им Выбор противника.","","\"Кого могла прислать Демасия на выручку своему принцу, как не Повелительницу облаков?\" – Король Джарван III","Боец",["ЭЛИТА"],["Демасия"],"ЭПИЧЕСКОЕ"],"04DE020":["Падший драконий страж","Когда союзник с яростью убивает бойца, даруйте ему дополнительно +1|+1.","","Туман отравил разум Грегема, заставляя вновь и вновь прокручивать в памяти события Ренуолла. Не в силах больше сдерживать горечь и гнев, Грегем поднял оружие на своих недавних соратников.","Боец",[],["Демасия"],"ОБЫЧНОЕ"],"04DE010":["Король Джарван III","Призвав меня, вытяните чемпиона Джарван IV.\nЕсли он уже в игре, вместо этого дайте союзникам Выбор противника и разведку до конца раунда.","","\"Скажи, чем готов пожертвовать отец ради спасения сына? Что отдаст король за своего принца?\" – Ле Блан","Боец",["ЭЛИТА"],["Демасия"],"ЭПИЧЕСКОЕ"],"04DE016":["Падший Кадрегрин","Разыгрывая карту: даруйте союзнику навык Выбор противника и +1|+1.","","Кадрегрин сеял ужас и смерть в Демасии задолго до того, как туда добрался черный туман. Теперь же он служит Виего, и его способности делают армию Падшего короля еще сильнее.","Боец",["ДРАКОН"],["Демасия"],"РЕДКОЕ"],"04DE013":["Гигантский кремнерог","Вражеские заклинания и способности не наносят мне урон.","","Говорят, великие кремнероги появились на Рунтерре, когда петрицитовый лес был еще совсем молодым. Их ветвистые рога по структуре напоминают эти ныне окаменевшие деревья.","Боец",[],["Демасия"],"ОБЫЧНОЕ"],"04DE015":["Всадник на быстрокрыле","Разыгрывая карту: создайте в руке карту Среброкрыл Авангарда, Слепящий удар или Легкокрылый охотник.\nАтака: дайте другим союзникам, выбирающим противника, +1|+1 до конца раунда.","","Завидев в облаках всадников на быстрокрылах, демасийские солдаты воодушевляются. Появление этих небесных союзников дарит наземным войскам надежду, и они начинают сражаться с удвоенной силой.","Боец",["ЭЛИТА","ПТИЦА"],["Демасия"],"ЭПИЧЕСКОЕ"],"04DE007":["Провинившаяся адъютантка","Когда меня призывают, создайте в руке карту Изорванный стяг, если вы владеете элитным бойцом.","","Она добежала до городских стен и рухнула без сил, зная, что теперь бойцы Бесстрашного авангарда передадут ее послание королю, а тот спасет принца. Значит, она искупит свою вину и сохранит воинскую честь.","Боец",[],["Демасия"],"ОБЫЧНОЕ"],"04DE009":["Благородный всадник","Когда я впервые выбираю противника, превратите меня в карту Конница Авангарда.","","На поиски принца были брошены все резервы демасийской армии. Важно было действовать быстро.","Боец",["ЭЛИТА"],["Демасия"],"РЕДКОЕ"],"05BC058":["Кеннен","Призвав меня, создайте в руке карту Знак бури.","Вы призвали одного и того же союзника 5+ раз.","Кеннен тоже услышал рык пока еще невидимого существа. Человека или монстра – это не имело значения. Кинку будут защищать свои земли любой ценой.","Боец",["ЙОРДЛ"],["Бандл Сити","Иония"],"Чемпион"],"05BC010":["Дрессировщик акул","Когда атакуют союзники, призовите атакующего бойца Короткозуб.","","Каждый вечер дрессировщик ужинает рыбой, запивая ее элем, пускает пузыри из своей трубки, а потом читает акулам сказки на ночь и целует их в зубастые мордашки.","Боец",["ЙОРДЛ"],["Бандл Сити","Билджвотер"],"РЕДКОЕ"],"05BC102":["Чернокнижник","В начале раунда: восполните 1 ману заклинаний.","","Если самая мерзкая боль – от пореза бумагой, то лучше всех в боли разбирается библиотекарь.","Боец",["ЙОРДЛ"],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC230":["Портал духов","Чтобы сыграть, сбросьте 1 карту. Даруйте союзникам +1|+1.","","\"Все время забываю, как ими пользоваться…\" – Поппи","Заклинание",[],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC099":["Накачанный скаут","Призвав меня, даруйте мне +1|+1 за каждого имеющегося другого союзника-йордла.","","\"В чем мой секрет? Спросите у моих бицепсов. Они лучше объяснят!\"","Боец",["ЙОРДЛ"],["Бандл Сити"],"РЕДКОЕ"],"05BC133":["Тристана","У меня +1|+0 за каждого мультирегионального бойца, призванного вами в этом матче.\nПризвав мультирегионального союзника, даруйте ему +1|+0.","Вы призвали 5+ мультирегиональных союзников.","\"Итак, план А: врываемся внутрь и открываем огонь. Если не получится, переходим к плану Б: выбираемся оттуда, продолжая огонь. Потом перегруппируемся и перейдем к плану В, который на самом деле как план А…\"","Боец",["ЙОРДЛ"],["Бандл Сити"],"Чемпион"],"05BC023":["Минитин","Конец раунда: если вы нанесли урон вражескому нексусу в этом раунде, превратите меня в карту Мегатин.","","Что любят минитины: спать на теплых камнях недалеко от владений племени накотак. Что не любят минитины: когда наглые йордлы спихивают их с этих камней…","Боец",[],["Бандл Сити"],"ЭПИЧЕСКОЕ"],"05BC029":["Юми","Начало раунда: даруйте +1|+1 союзнику, к которому я прикреплена. Если я не прикреплена, даруйте мне +1|+1.","Я или союзник, к которому я прикреплена, атаковали 3 раза.","Юми вынуждена была признать: несмотря на чрезмерную хлопотливость, Книга ей вообще-то нравилась. И запах, и картинки на страницах. И даже прыжки через порталы! Но все равно она предпочла бы снова оказаться дома с Норрой и не тревожиться за хозяйку.","Боец",["ФАЭ","КОШКА"],["Бандл Сити","Таргон"],"Чемпион"],"05BC078":["Электрогарпун","Чтобы сыграть, сбросьте 1 карту. Нанесите 2 ед. урона любой цели и 2 ед. урона вражескому нексусу.","","\"Устроим представление!\" – Рамбл","Заклинание",[],["Бандл Сити"],"РЕДКОЕ"],"05BC106":["Ворчец","","","\"Несмотря на свои малые размеры, ворчецы отличаются отменным аппетитом и прямо-таки непомерным самомнением\".\n– Из \"Экодневника\" конхиолога, день 17","Боец",[],["Бандл Сити","Билджвотер"],"ОБЫЧНОЕ"],"05BC161":["Гнар","Удар: создайте в руке карту Палка-тыкалка. Если она у вас уже есть, уменьшите ее стоимость на 2.","Конец раунда: вы нанесли урон вражескому нексусу в этом раунде.","Давным-давно Гнар и его сородичи жили в долине Накотак и не знали горя. Это было блаженное место, не испорченное современностью. К сожалению, время разлучило Гнара с его родной долиной. К счастью, в Бандл Сити время ведет себя совсем иначе.","Боец",["ЙОРДЛ"],["Бандл Сити","Фрельйорд"],"Чемпион"],"05BC073":["Талантливый химик","Призвав меня, призовите карту Самодельная бомба.","","Жизель была одной из лучших учениц Хеймердингера, но потом она прослышала о странных экспериментах Зиггса в Зауне и напросилась к нему на практику. С тех пор все ее мысли занимает хексчатка. ","Боец",["ЙОРДЛ"],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC039":["Суровый гренадер","Верность: призовите случайного сторонника-йордла стоимостью до 3.","","\"У Алисы две гранаты: одна для приветствия, другая для прощания. Хочешь познакомиться?\"","Боец",["ЙОРДЛ"],["Бандл Сити"],"РЕДКОЕ"],"05BC148":["Яростные создания","Призвав меня, четырежды даруйте мне Таран, если в этом матче вы нанесли урон вражескому нексусу 4+ раза.","","Съедобные снаружи, но жесткие внутри.","Боец",["ФАЭ"],["Бандл Сити","Пилтовер и Заун"],"ОБЫЧНОЕ"],"05BC119":["Миньон","Предсмертный вздох: создайте в руке мою копию в начале следующего раунда.","","\"Настоящий злодей от миньонов не отказывается! Эти коротышки знают свое место, выполняют приказы беспрекословно и всегда возвращаются за дальнейшими указаниями\".\n– Лорд Вейгар, \"Как стать суперзлодеем\", глава II","Боец",[],["Бандл Сити","Сумрачные острова"],"ОБЫЧНОЕ"],"05BC019":["Радужная рыбка","","","Радужная рыбка была совсем не против разведки с воздуха, даже если для этого пришлось бы прыгнуть выше головы. Она согласилась бы на что угодно, чтобы хоть на время спрятаться от голодного взгляда Юми.","Боец",["ФАЭ"],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC093":["Вейгар","Призвав меня, создайте в руке карту Тьма, если у вас ее нет. В начале раунда: даруйте своему заклинанию Тьма везде 1 доп. ед. урона.","Вы нанесли 12+ ед. урона с помощью Тьмы.","\"Я заставлю этот мир бояться! Он будет залечивать раны до скончания времен. Он содрогнется при виде моей огромной силы. Он померкнет в тени моей грандиозности!\n– Лорд Вейгар, \"Как стать суперзлодеем\", глава I","Боец",["ЙОРДЛ"],["Бандл Сити","Сумрачные острова"],"Чемпион"],"05BC007":["Каменщики","","","Йордлы не вполне понимают, как работает гравитация, но и гравитация не понимает, как работать в Бандл Сити.","Боец",["ЙОРДЛ"],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC174":["Дружба!","Дайте союзнику Щит или Щит от магии до конца раунда.","","\"Я защищу тебя своим диким, яростным… мявом!\"\n– Юми","Заклинание",[],["Бандл Сити"],"РЕДКОЕ"],"05BC185":["Игра в ракушки","Восполните ману заклинаний. Дайте союзнику Изворотливость и +1|+1 до конца раунда.","","\"Я ВИЖУ, что они в левой ракушке, но когда выбираю ее, внутри пусто. Начинаю подозревать, что кто-то мухлюет!\"\n– Из \"Экодневника\" конхиолога, день 14","Заклинание",[],["Бандл Сити"],"РЕДКОЕ"],"05BC096":["Тягостный тенор","Призвав меня, если вы уже разыгрывали созданную карту или убили бойца заклинанием, призовите карту Безрадостный бас.","","Когда Вейгару нужно было настроить кого-нибудь \"за\" или \"против\", эта парочка лучше всех справлялась с задачей. Дела всегда шли на лад, ведь все лады у них были записаны – кроме миксолидийского.","Боец",["ЙОРДЛ"],["Бандл Сити","Сумрачные острова"],"РЕДКОЕ"],"05BC088":["Рамбл","Разыгрывая карту: сбросьте до 3 карт, чтобы даровать союзным Рамблам везде Таран за 1-ю карту, Быструю атаку за 2-ю и Щит от магии за 3-ю.","На моих глазах союзные йордлы-пилоты нанесли 12+ ед. урона.","\"Должно сработать\".\n\"ОШИБКА\".\n\"В смысле? Я только что все починил!\"\n\"ОТКАЗ ВСЕХ СИСТЕМ ЧЕРЕЗ ПЯТЬ…\"\n\"Вырубай! ВЫРУБАЙ!\"\n– Рамбл и Тристи","Боец",["ПИЛОТ","ЙОРДЛ"],["Бандл Сити","Ноксус"],"Чемпион"],"05BC056":["Адепт ветра","Призвав меня, создайте в руке карту Облачная стойка.","","\"Техника нашей школы основана на управлении дыханием. Ведь из ветерка рождается буря\".","Боец",["ЙОРДЛ"],["Бандл Сити"],"РЕДКОЕ"],"05BC190":["Комментатор арены роботов","Атака: дайте другим атакующим союзникам +2|+0 до конца раунда.","","\"Как мне удается так орать каждый вечер? Я полощу горло машинным маслом! Пять минут с утра и еще пять – перед сном\".","Боец",["ЙОРДЛ"],["Бандл Сити","Ноксус"],"ЭПИЧЕСКОЕ"],"05BC042":["Фиолетово-ягодный коктейль","Увеличьте характеристики союзника до 3|3 до конца раунда.","","\"Когда-то я был таким же, как ты, и не мог поднять даже шляпку от гриба. А потом я открыл для себя \"Фиолетово-ягодный коктейль\". В нем содержится все, что нужно йордлу, чтобы выбиться в герои. Заправься \"Коктейлем\" после тяжелой тренировки и стань таким же качком,\nкак я!\" – Рекламная листовка","Заклинание",[],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC205":["Горизонт событий","Оглушите врага, а также всех врагов с силой не более 2.","","\"Просто… не двигайся…\" – Вейгар","Заклинание",[],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC223":["Обманка","Выберите 1 из 3 бойцов или заклинаний из колоды противника и прикрепите ко всем его копиям 3 Ядовитых гриба.","","\"Правило бандлскаута №986: ловушки – это не игрушки… но радости от них не меньше!\"","Заклинание",[],["Бандл Сити"],"РЕДКОЕ"],"05BC091":["Зазывала","Разыгрывая карту: сбросьте 1 карту, чтобы воплотить йордла-пилота и снизить его стоимость на 1.","","\"БИЛЕТЫ! ПОКУПАЙТЕ БИЛЕТЫ! ЗА ПОЛЦЕНЫ! УФ-Ф! Если я их не продам, начальник мне голову оторвет… и это не фигура речи!\"","Боец",["ЙОРДЛ"],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC163":["Зиггс","Атака: я наношу 1 ед. урона тому, кто меня блокирует, и вражескому нексусу.","Вы разрушили 4+ союзных места силы.","\"Мы должны произвести хорошее впечатление. К нам идет новый пожарный инспектор! Вы все знаете, что это значит.\"\n\"Что теперь нельзя взрывать?\"\n\"ЧТО?! Конечно можно. Но только там, где он не увидит. «Нельзя взрывать»… Надо ж было такое ляпнуть!\"\n– Зиггс и Отто","Боец",["ЙОРДЛ"],["Бандл Сити","Шурима"],"Чемпион"],"05BC151":["Заклинательница зеркал","Разыграв созданного сторонника, призовите его точную копию. Разыграв созданное заклинание, повторите его на тех же целях.","","\"О да, она очень искусно обращается с зеркалами! Мои модели в них выглядят еще элегантнее, а если правильно выставить свет, то даже удается визуально сделать выше кое-кого, кому это жизненно необходимо…\" – Кутюрье на котурнах","Боец",["ЙОРДЛ"],["Бандл Сити"],"ЭПИЧЕСКОЕ"],"05BC027":["Минное поле","Когда меня призывают или когда вы меня разрушаете, оглушите сильнейшего врага.","","\"В смысле «выглядит небезопасно»?!\" – Зиггс","Место силы",[],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC200":["Портал йордлов","Чтобы сыграть, сбросьте 1 карту. Воплотите йордла стоимостью 3 или менее и призовите его.","","\"Канонир канонира не бросит!\" – Тристана","Заклинание",[],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC021":["Прыгающая бомба","Нанесите 2 ед. урона бойцу или 1 ед. урона двум врагам.","","\"Сейчас рванет!\" – Зиггс","Заклинание",[],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC167":["Коммандос Бандла","Удар по нексусу: создайте в руке карту Голодная котосова.","","\"Мамочка выходит пострелять, чтоб малыши могли спокойно спать\".","Боец",["ЙОРДЛ"],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC179":["Йордл-рейнджер","Атака: даруйте +0|+1 союзникам, чья сила меньше или равна моей.","","\"Поппи! Ты безупречно реализовала нашу стратегию. Как мы ее назовем? Может быть, «Лещина в лощине»?\"\n\"Да я же просто стукнула плохого парня молотом. Давай назовем эту стратегию «Молот»?\"\n\"Так мы назвали последние три штуки!\" – Кип и Поппи","Боец",["ЙОРДЛ"],["Бандл Сити","Демасия"],"ЭПИЧЕСКОЕ"],"05BC214":["Страшно большая бомба","Нанесите всем врагам 1 ед. урона, затем сделайте это снова.","","\"Несите… «Здоровяка»!\" – Зиггс","Заклинание",[],["Бандл Сити"],"РЕДКОЕ"],"05BC221":["Грибное кольцо","Призвав меня или в начале раунда: дайте мне прибавку к силе до конца раунда. Прибавка равна числу других союзных фаэ на поле боя, включая прикрепленных к союзникам.","","Эти малявки и сейчас уже очень милые, а уж когда вырастут...","Боец",["ФАЭ"],["Бандл Сити","Иония"],"РЕДКОЕ"],"05BC041":["Поппи","Атака: даруйте +1|+1 союзникам, чья сила меньше или равна моей.","Я атаковала вместе с союзниками 3 раза.","Скромность часто идет рука об руку с героизмом, но многие историки согласятся, что у Поппи со скромностью вышел перебор.","Боец",["ЙОРДЛ"],["Бандл Сити","Демасия"],"Чемпион"],"05BC176":["Кошки-мышки","Даруйте союзнику +1|+0. Нанесите врагу 1 ед. урона.","","\"Вжух!\" – Юми","Заклинание",[],["Бандл Сити"],"РЕДКОЕ"],"05BC105":["Канониры Бандла","Каждый мультирегиональный союзник, призванный вами в этом матче, снижает мою стоимость на 1.\nПризвав меня, трижды даруйте мне Таран.","","Работа в команде.","Боец",["ЙОРДЛ"],["Бандл Сити"],"РЕДКОЕ"],"05BC066":["Самописец","","","\"Г… д… е… Н… о… р… р… а? Помилуйте, что же мне на это ответить?\" – Младший библиотекарь","Боец",["ФАЭ"],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC177":["Бумажный дракончик","","","\"Смотри, еще сгиб – и получится жираф! Назовем его Носочек\".\n\"Почему Носочек?\"\n\"Норре нравятся носочки – значит, и он понравится!\"\n– Младший библиотекарь","Боец",["ФАЭ"],["Бандл Сити"],"ЭПИЧЕСКОЕ"],"05BC136":["Металлолом","Чтобы сыграть, сбросьте 1 карту.\nВоплотите йордла-пилота.","","\"Утиль. Металлолом. Мусор... Ха! А вот ЭТО мне подойдет!\" – Рамбл","Заклинание",[],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC164":["Ядовитый дротик","Нанесите 1 ед. урона любой цели и прикрепите 3 Ядовитых гриба в колоде противника.","","\"Ха-ха! Прямо в цель!\" – Тимо","Заклинание",[],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC194":["Бандловое древо","Начало раунда: создайте в руке сторонника из нового региона. Вы выигрываете, если я увидело союзников из 10 регионов.","","Невероятное Бандловое древо – настоящее сердце города. Крона его уходит в небеса на невообразимую высоту. Для одних йордлов его толстые узловатые ветви стали символом надежды и дружбы, для других же Древо – это загадочный и зловещий монолит. Но все сходятся во мнении, что посмотреть на Бандловое древо – все равно что заглянуть в душу чему-то очень древнему и могущественному.","Место силы",[],["Бандл Сити"],"ЭПИЧЕСКОЕ"],"05BC127":["Риссу, Безмолвная буря","Призвав меня, призовите карту Грозовая туча.","","Чтобы соткать Грозовую тучу, нужно время. А времени у Риссу не было. Она лихорадочно совершала магические пассы: вот клочок облака, вот вспышка молнии… И наконец: ТРЕСК! ГРОМ! У нее получилось – но достаточно ли сильна эта Туча?","Боец",["ЙОРДЛ"],["Бандл Сити"],"ЭПИЧЕСКОЕ"],"05BC216":["Приспособление йордлов","Разрушьте место силы или создайте в руке двух случайных мультирегиональных сторонников.","","\"Держитесь! Мы уже едем!\" – Бомбардиры-близнецы","Заклинание",[],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC212":["Пожарный инспектор","Начало раунда: создайте в руке карту Инспекция пройдена!.","","Поначалу Уилфред был настроен скептически. Да и потом тоже. По правде говоря, он был настроен скептически до самого конца, но Зиггс и другие эксперты по хексчатке доказали, что умеют запускать первоклассный салют. ","Боец",["ЙОРДЛ"],["Бандл Сити"],"РЕДКОЕ"],"05BC141":["Героический рефрен","Дайте 2 союзникам +2|+1 до конца раунда.","","\"Герои стояли спиной к спине и…\"\n\"Попой к попе! Хи-хи-хи!\"\n\"Пеппи! Если так хочешь вставить словечко, делай это в менее драматичные моменты!\"\n– Сказки, рассказанные йордлами у костра","Заклинание",[],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC209":["Бегство от стресса","Дайте бойцу характеристики 1|6 до конца раунда.","","В обычных обстоятельствах Кукарек – спокойный и надежный скакун. Но в чрезмерно напряженной обстановке он может повести себя… непредсказуемо.","Заклинание",[],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC210":["Огнемет","Даруйте союзнику +2|+0 и Таран.","","\"Хе-хе. Сделаем погорячее, чтобы противник взвыл!\"\n– Рамбл","Заклинание",[],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC013":["Хитрые щупальца","Противник сбрасывает карту с самой низкой стоимостью.","","\"Себе за заметку: в следующей экспедиции надо положить все ценное в ПЕРЕДНИЕ карманы\".\n– Из \"Экодневника\" конхиолога, день 19","Заклинание",[],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC100":["Щенок-грибник","Удар: прикрепите 3 Ядовитых гриба в колоде противника.","","\"Что ты говоришь, малыш? Два новобранца пошли на разведку в лес, наткнулись на жуткого травяного монстра и теперь готовятся умереть страшной смертью? Скорей веди меня к ним!\" – Тимо","Боец",["ПЕС"],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC098":["Злой катализатор","Нанося удар: даруйте своему заклинанию Тьма везде 1 доп. ед. урона.","","Тьма бывает всех размеров и форм. И некоторые из них УДИВИТЕЛЬНО милые.","Боец",["ЙОРДЛ"],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC122":["Йордл-новичок","Призвав другого йордла, дайте мне +2|+0 до конца раунда.","","\"Гигантус травянискус. Эти страшные существа расстилаются по лужайке, притворяясь обычной травой, и хватают за ноги тех, кто на них наступит. При встрече бегите без оглядки!\" – Целеустремленная Эйва","Боец",["ЙОРДЛ"],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC120":["Йордл-капитан","Призывая союзника, чья сила меньше или равна моей, даруйте ему +1|+1.","","\"Хорошее приключение должно заканчиваться перевоспитанием злодея!\"","Боец",["ЙОРДЛ"],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC046":["Кулак грома","Когда меня призывают, если вы уже призывали Кулак грома в этом матче, превратите меня в карту Маса, Громовой раскат.","","Маса попал по манекену – и из его кулака тут же вырвалась молния, которая надвое расщепила деревянную фигуру и опалила шерсть на руках йордла. Он за веревки подтянул к себе бронзовые кулаки. После стольких тренировок он наконец чувствовал, что готов… И вдруг откуда-то донесся чудовищный рык.","Боец",["ЙОРДЛ"],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC018":["Напыщенный рыцарь","","","\"Девятьсот девяносто восемь… девятьсот девяносто девять… тысяча! Готово, Кукарек! Ты, как всегда, безупречен. А теперь ты меня причеши!\"","Боец",["ЙОРДЛ"],["Бандл Сити","Демасия"],"РЕДКОЕ"],"05BC132":["Вышибной заряд","Моя стоимость снижается на 2, если у вас есть Тристана либо если в этом матче вы разыграли карты из 4+ регионов.\nНанесите бойцу 3 ед. урона.","","В каждом \"бубухе\" таится \"бабах\".","Заклинание",[],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC168":["Пятнистая жаба","Конец раунда: если вы нанесли урон вражескому нексусу в этом раунде, превратите меня в карту Громп-гигант.","","Йордлы долины Накотак несколько поколений изучали своих соседей-громпов. Сначала вождь Хегабо тыкал их палочкой. Затем вождь Бабобу тыкал их палочкой. У вождя Накотака был новый план: он решил потыкать их палочкой.","Боец",[],["Бандл Сити"],"РЕДКОЕ"],"05BC014":["Минидактиль","Конец раунда: если вы нанесли урон вражескому нексусу в этом раунде, превратите меня в карту Террордактиль.","","В яркой долине Накотак фауна тоже пестрая, полная жизни… и такая же непредсказуемая!","Боец",["ПТИЦА"],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC138":["Латайки","Впервые сбрасывая карту или нанося урон вражескому нексусу, даруйте мне +2|+1.","","\"Бой получился зрелищный, все молодцы. А теперь за уборку! И помните: все, что еще можно залатать – латайте и тащите обратно в магазин, чтобы снова продать этим олухам! Ха-ха-ха!\" – Карл, владелец арены","Боец",[],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC198":["Групповой снимок","Нанесите бойцу 1 ед. урона. Если у вас 4+ союзника, вместо этого нанесите 2 ед. урона.","","\"Так, теперь для стенгазеты. На этот раз постарайтесь улыбнуться. Раз… два…три!\" – Тристана\n","Заклинание",[],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC181":["Облачная стойка","Дайте союзнику +2|+0 и особенность \"Конец раунда: верните меня\" до конца раунда.","","\"Сосредоточься на дыхании и отыщи свою силу!\" – Адепт ветра","Заклинание",[],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC160":["Первобытный поро","","","У древних поро череп был существенно толще, чем у современных особей, что делало их чуть глупее и значительно бодливее.","Боец",["ПОРО"],["Бандл Сити","Фрельйорд"],"ОБЫЧНОЕ"],"05BC005":["Ламинарии","Удар по нексусу: создайте в руке Шалость.","","\"Какой странный сон мне приснился! Пробираюсь я, значит, через водоросли, ищу свою шляпу-ракушку… и вдруг слышу чудесную песню! А в следующий миг я уже сижу здесь и записываю эти слова. Но главное: не помню, чтобы вообще останавливался подремать…\"\n– Из \"Экодневника\" конхиолога, день 22","Боец",[],["Бандл Сити"],"РЕДКОЕ"],"05BC020":["Младший библиотекарь","Удар по нексусу: вытяните заклинание стоимостью 3 или менее.","","\"Джил – моя ЛУЧШАЯ ПОДРУЖКА! После Книги. И после Норры. Ладно, Джил – моя лучшая подружка третьей степени. Это ведь тоже неплохо, правда?\" – Юми","Боец",["ФАЭ"],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC049":["Конхиолог","Разыгрывая карту: воплотите заклинание из ваших регионов стоимостью 3 и меньше.","","\"Сегодня у меня маленький праздник: я погружаюсь на глубину! Надеюсь, исследования будут протекать без проблем, хе-хе!\"\n– Из \"Экодневника\" конхиолога, день 1","Боец",["ЙОРДЛ"],["Бандл Сити"],"РЕДКОЕ"],"05BC001":["Миниморф","Превратите бойца в карту Мини-минитин с 3|3 и примените к нему Безмолвие.","","\"О-хо-хо! Какой милый! Какой забавный! Какой КРОХОТНЫЙ!\" – Вейгар","Заклинание",[],["Бандл Сити"],"РЕДКОЕ"],"05BC026":["Тайные тропы","Моя стоимость снижается на 2, если в этом матче вы создали 2+ карты. Вытяните 2 карты.","","Мало кто знает, как попасть в Бандл Сити, если там не родился. Но загадочные знаки на камнях и деревьях Рунтерры служат подсказками для тех, кто знает, куда смотреть.","Заклинание",[],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC152":["Недовольные путешественники","Когда меня призывают, все игроки вытягивают по 1 карте, а затем ваш противник сбрасывает самую дорогую карту.","","\"Худшее путешествие в моей жизни\". – Эл","Боец",["ЙОРДЛ"],["Бандл Сити","Пилтовер и Заун"],"ОБЫЧНОЕ"],"05BC070":["Целеустремленная Эйва","Призвав меня или в конце раунда: прикрепите 3 Ядовитых гриба в колоде противника.\nПри срабатывании число ловушек на картах противника удваивается.","","\"Правило бандлскаута №378: скаут всегда храбр, всегда готов, всегда идет на риск!\"","Боец",["ЙОРДЛ"],["Бандл Сити"],"ЭПИЧЕСКОЕ"],"05BC015":["Крохотная ящерка","Конец раунда: если вы нанесли урон вражескому нексусу в этом раунде, превратите меня в карту Магмаящер.","","Накотак протявкал: \"Съешь перчик!\" (наверное). Джо-джо ответил: \"Нет, это ты съешь перчик!\" (или что-то в этом роде). Пока они лаялись, мимо юркнула ящерка, гнавшаяся за мухой. Йордлы посмотрели на ящерку, потом на перец – и переглянулись. Если бы в этом мире существовали лампочки, то одна лампочка сейчас бы зажглась.","Боец",["РЕПТИЛИЯ"],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC145":["Йордл-оруженосец","Разыгрывая карту: создайте в руке Мини-дротик или Мини-щит.","","\"Мой дротик тоже когда-то принадлежал великому герою. Я давала его Поппи... подержать!\"","Боец",["ЙОРДЛ"],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC140":["Поро в санках","Атака: призовите случайного атакующего поро стоимостью 1.","","\"А потом этот поро Бобджим ка-а-ак помчится далеко-далеко! Да еще и крикнул «За мной!», и остальные поро заскакали следом, чтобы не отстать!\" – Ингвар младшая","Боец",["ПОРО"],["Бандл Сити","Фрельйорд"],"ЭПИЧЕСКОЕ"],"05BC129":["Владелец арены","","","\"В мире полно дурачков, и мы их раскрутим на все бабки. Эта арена для роботов – золотая жила!\"","Боец",["ЙОРДЛ"],["Бандл Сити","Ноксус"],"ОБЫЧНОЕ"],"05BC004":["Спрутовыдра","Призвав меня, создайте в руке Шалость.","","\"К кому относятся спрутовыдры: к выдрам или спрутам? Так или иначе, они очень игривы и любознательны! Хм, у меня же вроде было три бутерброда...\"\n– Из \"Экодневника\" конхиолога, день 7","Боец",[],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC155":["Адепт пламени","Призывая союзника, даруйте мне +1|+0.","","\"Из тлеющих углей разгорится ревущее пламя. Наши искры предрекают вам гибель!\"","Боец",["ЙОРДЛ"],["Бандл Сити"],"РЕДКОЕ"],"05BC104":["Первобытная сила","Даруйте союзнику +2|+2 и Таран.","","Да, он миленький. Но с характером. Нет, лучше его не дразнить.","Заклинание",[],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC218":["Помощь фаэ","Создайте в руке карту Голодная котосова, затем даруйте всем союзникам-фаэ в руке +1|+1.","","\"Кто кормит этих куриц?\" – Поппи","Заклинание",[],["Бандл Сити"],"РЕДКОЕ"],"05BC192":["Бомбардиры-близнецы","Призвав меня, создайте в руке случайное место силы стоимостью 2 или менее.","","Хитроступ-бомбардировщик Х прекрасно справляется со своей основной задачей: сеять хаос. А как его легко парковать! ","Боец",["ЙОРДЛ"],["Бандл Сити","Шурима"],"ОБЫЧНОЕ"],"05BC162":["Вождь Накотак","Когда союзник совершает превращение, полностью исцелите его и даруйте ему +1|+1 и Таран.","","Накотак провозгласил себя вождем после того, как нашел в сугробе на землях племени большую кость динозавра. Никто раньше не слышал о том, чтобы кость динозавра давала право быть вождем – но и возражать никто не стал. Так Накотак возглавил племя.","Боец",["ЙОРДЛ"],["Бандл Сити"],"РЕДКОЕ"],"05BC032":["Светящийся фонарик","В каждом раунде стоимость первого разыгранного фаэ снижается на 2.","","\"Фонарик следует за Норрой, лунные мотыльки – за фонарем, а за мотыльками – мышки! Скорее за ними!\"","Боец",["ФАЭ"],["Бандл Сити"],"РЕДКОЕ"],"05BC166":["Палка-тыкалка","Нанесите 1 ед. урона любой цели. Вытяните 1 карту.","","Первое правило экспериментатора: потыкай и посмотри, что будет.","Заклинание",[],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC006":["Арсенал","Призвав меня, даруйте мне случайный навык за каждое разрушенное союзное место силы.\nРазрушая союзное место силы, даруйте мне случайный навык.","","Арни повсюду следовал за Зиггсом, немного остужая его бешеный пыл своим неизменным спокойствием. Дел для Арни всегда хватало: он следил за пополнением боезапаса, тушил пожары, а еще закрывал ладонями уши Зиггса, когда тот снова забывал про беруши. ","Боец",["ЙОРДЛ"],["Бандл Сити"],"ЭПИЧЕСКОЕ"],"05BC110":["Ученый альпинист","","","\"Ты уже сто раз мне сказала, что она любит чай, носочки, тебя, пуговицы и коллекционировать безделушки – но ни словечка о том, как она выглядит!\" ","Боец",["ЙОРДЛ"],["Бандл Сити","Таргон"],"ОБЫЧНОЕ"],"05BC063":["Торнадо","Призвав меня, даруйте мне +1|+0 и случайный навык.\nЯ сохраняю это усиление и навыки, когда меня возвращают.","","Торнадо сохраняет спокойствие с помощью дыхательных упражнений… и умения превращать душевные бури в смертоносный вихрь острых сюрикенов. ","Боец",["ЙОРДЛ"],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC217":["Росток фаэ","Воплотите фаэ и даруйте ему +1|+1.","","Пища нужна всему живому. Фаэ – не исключение, хотя как именно они ее употребляют, остается загадкой.","Заклинание",[],["Бандл Сити"],"РЕДКОЕ"],"05BC180":["Ускорение","Верните бойца с силой не больше 3.","","\"Мы стремительны! Мы – ветер!\" – Кеннен","Заклинание",[],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC040":["Менялка","Воплотите бойца Спрутовыдра или одно из двух заклинаний из ваших регионов стоимостью 3 или меньше.","","\"Немедленно отдай мой бутерброд!\" – Конхиолог","Заклинание",[],["Бандл Сити"],"РЕДКОЕ"],"05BC213":["Бум","Нанесите врагу 1 ед. урона и оглушите его.","","\"Аханга!\" – Гнар","Заклинание",[],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC208":["Героический рывок","Союзник наносит удар врагу. Если враг выживет, оглушите его.","","\"Живее!\" – Поппи","Заклинание",[],["Бандл Сити"],"РЕДКОЕ"],"05BC085":["Понтовая крыса","Разыгрывая карту: сбросьте 1 карту, чтобы воплотить йордла-пилота и даровать ему Щит от магии.","","\"Эй, потише! Я сам себя не слышу. А я, между прочим, считаю деньги!\" – Карл, владелец арены","Боец",["ЙОРДЛ"],["Бандл Сити"],"РЕДКОЕ"],"05BC112":["Саженец взрывной шишки","Разыгрывая карту: дайте мне Щит до конца раунда, либо даруйте мне Таран.","","Саженцы взрывных шишек – существа пугливые и неагрессивные, но если их сильно напугать…","Боец",["ФАЭ"],["Бандл Сити","Иония"],"ОБЫЧНОЕ"],"05BC135":["Двустволка","Союзник наносит удар вражескому бойцу. Если союзник мультирегиональный, он снова наносит врагу удар.","","\"«Желудь M1-85» – это автоматическая винтовка с дубовым стволом, прицелом из бандловой древесины и пурпурно-ягодным покрытием. Сегодня мамочка повеселится!\" – Коммандос Бандла","Заклинание",[],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC084":["Визгун","Разыгрывая карту: сбросьте 1 карту, чтобы воплотить йордла-пилота.","","Сам он коротышка – зато как его слышно!","Боец",[],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC184":["Мямли-менестрели","Призвав меня, создайте в руке карту Голодная котосова.","","\"В этой песне бодрящей\nо Поппи, молот хранящей,\nрасскажем о настоящей\nгероине Бандла… вящей?\n– Строки, вычеркнутые из \"Песенника славных менестрелей Реджинальдактиля и Фальтимиска\"","Боец",["ЙОРДЛ"],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC116":["Мэр Бандл Сити","В каждом раунде стоимость первого разыгранного мультирегионального бойца снижается на 1.\nРазыгрывая карту: воплотите мультирегионального сторонника.","","Неизвестно, проводились ли когда-нибудь в Бандл Сити настоящие выборы мэра, но длиннющие усы точно стали бы залогом победы.","Боец",["ЙОРДЛ"],["Бандл Сити"],"ЭПИЧЕСКОЕ"],"05BC111":["Йордлы по оружию ","Дайте союзникам +2|+2 до конца раунда. Если в этом матче вы разыграли бойцов или заклинания из 4+ регионов, вместо этого дайте им +3|+3.","","\"Как же мы круто смотримся!\" – Тристана","Заклинание",[],["Бандл Сити"],"РЕДКОЕ"],"05BC224":["Перестановка","Верните союзника. Стоимость следующего союзника в этом раунде будет равна 0, если изначально она меньше или равна стоимости того, кого вы вернули.","","\"Быстрое тело, быстрый ум!\" – Кеннен","Заклинание",[],["Бандл Сити"],"РЕДКОЕ"],"05BC130":["Горячая голова","Атака: даруйте верхнему чемпиону в своей колоде +1|+1 и случайный навык.","","Кажется, все уже слышали о летних шашлыках у Отто. Чем они знамениты? Он так увлекается процессом приготовления, что может предложить гостям только два вида мяса: \"очень хорошо прожаренное\" и \"обугленное\".","Боец",["ЙОРДЛ"],["Бандл Сити","Шурима"],"ОБЫЧНОЕ"],"05BC191":["Вердикт Хранительницы","Поместите врага на верх колоды противника.","","\"И не возвращайся!\" – Поппи","Заклинание",[],["Бандл Сити"],"РЕДКОЕ"],"05BC052":["Сокровища свалки","Заполните свою руку случайными картами. Они мимолетны, а их стоимость равна 0. До конца раунда вы можете разыграть еще максимум 3 карты.","","Для йордла нет того дороже, про что другой сказал: негоже.\n","Заклинание",[],["Бандл Сити"],"РЕДКОЕ"],"05BC050":["Бенемон","Призвав меня, создайте в руке 2 Шалости.","","\"Если вас укачивает, приближайтесь к этому доброму гиганту КРАЙНЕ осторожно – поверьте, ваш желудок скажет вам спасибо! Я уже пожалел, что съел два бутерброда с грибами…\"\n– Из \"Экодневника\" конхиолога, день 3","Боец",[],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC094":["Черный плафон","Призвав меня, создайте в руке карту Тьма, если у вас ее нет.","","\"Наверняка у этого парня с крыши много любопытных историй. Он постоянно что-то рассказывает. Просто мы никак не можем разобрать, что именно\". – Кутюрье на котурнах","Боец",["ЙОРДЛ"],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC146":["Художница Бандла","Разыгрывая карту: сбросьте 1 карту, чтобы создать в руке мультирегионального сторонника и снизить его стоимость на 1.","","\"Рисовать – не значит просто копировать все, что видит глаз. Нужно показать свое видение мира. Ну вот, ты опять шевелишься! Стой смирно\".","Боец",["ЙОРДЛ"],["Бандл Сити","Пилтовер и Заун"],"ОБЫЧНОЕ"],"05BC235":["Йордл-кузнец","Атака: до конца раунда дайте Быструю атаку союзникам, чья сила меньше или равна моей.","","\"Поппи меня никогда не слушает, так хоть ты послушай. Дело не в молоте, а в йордле, который им размахивает.\"\n","Боец",["ЙОРДЛ"],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC175":["Гарцующий телескоп","Разыгрывая карту: воплотите творение небес стоимостью 3 или менее, либо эпического, либо мультирегионального сторонника.","","Самым странным было даже не то, что телескоп поднялся на ножки, потянулся и начал разгуливать вокруг, а то, что он непременно хотел одеться по погоде, и пришлось подбирать ему шарф!","Боец",["ФАЭ"],["Бандл Сити","Таргон"],"РЕДКОЕ"],"05BC182":["Молниеносный рывок","Верните союзника, чтобы нанести 2 ед. урона любой цели.","","\"Сначала треск, потом гром!\" – Кеннен","Заклинание",["СТИХИЯ"],["Бандл Сити"],"РЕДКОЕ"],"05BC069":["Йордл-зануда","Атака: создайте в руке мимолетную карту Ядовитый дротик.","","Только ни о чем его не спрашивайте – целую лекцию прочтет.","Боец",["ЙОРДЛ"],["Бандл Сити"],"РЕДКОЕ"],"05BC057":["Кутюрье на котурнах","Призвав меня, снизьте стоимость вашего заклинания Тьма везде на 1.","","\"Собирая суперзлодейскую свиту, важно найти безумных приспешников с разными талантами. Например, один из моих спутников сражает наповал чувством стиля.\n– Лорд Вейгар, \"Как стать суперзлодеем\", глава IV","Боец",["ЙОРДЛ"],["Бандл Сити"],"РЕДКОЕ"],"05BC108":["Йордл-исследователь","Призывая другого йордла, даруйте ему +1|+0.","","\"Слава исследователя бесценна, но самые великие открытия всегда приносят и более… весомую выгоду\".","Боец",["ЙОРДЛ"],["Бандл Сити"],"ОБЫЧНОЕ"],"05BC183":["Дед фаэ","Призвав меня, создайте в руке карту Голодная котосова.\nПризвав еще одного фаэ, даруйте ему +1|+0.","","\"Стар и млад! Садитесь в круг. Мы начинаем\nПоучительный рассказ о деде-фаэ.\nКаждый день кормил наш дед голодных пташек\nПшенкой, гречкой и зерном творожным даже\".\n– Басня из Бандл Сити","Боец",["ФАЭ"],["Бандл Сити","Иония"],"РЕДКОЕ"],"05BC188":["Обитатели ракушек","Выбирая карту, не являющуюся чемпионом, из случайной подборки, создайте в руке ее копию и уменьшите ее стоимость на 1.","","Известно, что эти создания очень застенчивы и обычно прячутся в своих ракушках, пока врожденное любопытство не заставит их вылезти наружу. Тогда и раскрывается их игривый характер, а в особенности – склонность шутить над окружающими, виртуозно подражая голосам других морских существ.","Боец",[],["Бандл Сити"],"ЭПИЧЕСКОЕ"],"05FR001":["Шаман волка мрака","Конец раунда: если вы нанесли урон вражескому нексусу в этом раунде, превратите меня в карту Берсерк волка мрака.","","\"Мы не умрем смертью трусов! Мы погибнем, выпустив когти и обнажив клыки. Так мы почтим великого Волка\". – Хиара Всевидящая","Боец",[],["Фрельйорд"],"ОБЫЧНОЕ"],"05FR002":["Шаман мамонта","Конец раунда: если вы нанесли урон вражескому нексусу в этом раунде, превратите меня в карту Берсерк мамонта.","","В случае нападения хищников мамонты встают в круг, в центр которого собираются беременные самки и молодняк. Шаманы, избравшие путь великого Мамонта, черпают силу не только в его звериной мощи, но и в потрясающем единстве, с которым мамонты защищают семью.","Боец",[],["Фрельйорд"],"РЕДКОЕ"],"05FR013":["Удир","Призвав меня либо когда я наношу удар: создайте в руке карту Смена стойки, а если она у вас уже есть, снизьте ее стоимость до 0.","Вы 3+ раза разыграли карту Смена стойки.","\"Духи создают этот мир так же, как этот мир и мы сами создаем духов. Получая силу от духов, мы черпаем ее внутри себя\".","Боец",[],["Фрельйорд"],"Чемпион"],"05FR016":["Зов шамана","Создайте в руке две мимолетные Смены стойки. Их стоимость равна 0.","","\"Вы их увидите… великих духов, покрытых перьями и чешуей, обнаживших клыки и когти. Вы задрожите от благоговейного ужаса и поймете, что древние боги нас не забыли\". – Хиара Всевидящая","Заклинание",[],["Фрельйорд"],"ОБЫЧНОЕ"],"05FR012":["Хиара Всевидящая","Призвав меня, создайте в руке карту Смена стойки.\nПервая Смена стойки в каждом раунде стоит 0.","","Шаманка Хиара Всевидящая пользуется огромным авторитетом. Много лет назад она утратила зрение, и ее глазами стали орлы и соколы, гнездящиеся неподалеку от ее хижины высоко в горах. Тревожные вести заставили пророчицу спуститься со склона… но она все еще надеется, что дурные знамения окажутся просто сном.","Боец",[],["Фрельйорд"],"РЕДКОЕ"],"05FR014":["Гнев Фрельйорда","Разыгрывая карту: заморозьте врага.\nПротивники с силой 3 и менее не могут блокировать.","","\"Это было много лет назад. Сперва пришел лютый холод. Потом налетела злая, беспощадная буря. Наконец, раздалось рычание, пробравшее меня до костей. Я упала на колени и молилась о том, чтобы наша затея не оказалась роковой. Взывая к великому духу, мы просим его гнева… и милосердия\". – Хиара Всевидящая ","Боец",[],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"05FR017":["Внутренний зверь","Дайте союзнику +1|+1 до конца раунда. Создайте в руке карту Смена стойки.","","\"Собирайтесь, духи. Собирайтесь\". – Удир","Заклинание",[],["Фрельйорд"],"ОБЫЧНОЕ"],"05FR006":["Оракул бивней","Разыгрывая карту: нанесите 1 ед. урона ОБОИМ нексусам.","","Лишь несколько шаманских родов служат Когтю Зимы так же долго, как род Чулуна. Будучи шаманом великого Моржа, он предвещает и привлекает морские дары… и связанные с ними опасности. ","Боец",[],["Фрельйорд"],"ОБЫЧНОЕ"],"05FR015":["Буйство духов","Даруйте союзникам везде +1|+1. Затем нанесите 1 ед. урона ВСЕМУ.","","\"О древние! Наделите нас силой, чтобы выдержать наступающий хлад, и прогоните врагов бурей изо льда и ветра! А мы не забудем воздать вам почести\".\n– Молитва шамана волка мрака","Заклинание",[],["Фрельйорд"],"РЕДКОЕ"],"05FR005":["Костяной гадатель","Когда я выживаю, получив урон, нанесите 1 ед. урона вражескому нексусу.","","Мало кто обладает такой же способностью заглядывать в будущее, как шаманы, что служат Костяному лосю. И еще меньше желающих видеть скорую гибель тех, кто пришел за предсказанием.","Боец",[],["Фрельйорд"],"ОБЫЧНОЕ"],"05FR004":["Лисья странница","Призвав меня, создайте в руке карту Смена стойки.","","\"Азартная, но осторожная. Быстрая, но тихая. Лисица видит, сама оставаясь незримой, и в этом главная прелесть ее Пути. И на войне, и в дороге мудрый правитель чтит последователей Лисицы. Ни одну битву не выиграть без разведчиков и проводников\". – Вринна, мать шрамов","Боец",[],["Фрельйорд"],"ОБЫЧНОЕ"],"05IO003":["Древний скиталец","Моя стоимость снижается на 2 за каждого возвращенного вами в этом раунде бойца.","","\"Химон'ши, идти рядом с тобой – большая честь, ведь о твоей мудрости ходят легенды. Скажи, куда мы держим путь?\"\n\"Вот незадача... Я ведь шел за тобой!\"\n– Ари и Древний скиталец","Боец",[],["Иония"],"ОБЫЧНОЕ"],"05IO004":["Ари","Атака: когда я впервые наношу удар во время атаки, поменяйте меня местами с союзником справа, а затем верните его.","Вы вернули 5+ бойцов.","Она искала себя в чужих тайнах. Видела себя множеством чужих глаз. Подходя к лесу, она гадала, станет ли он еще одной гранью для преломления – или она наконец найдет зеркало.","Боец",[],["Иония"],"Чемпион"],"05IO023":["Очарование","Верните союзника, чтобы дать врагу Уязвимость до конца раунда.","","\"Открой мне тайну\". – Ари","Заклинание",[],["Иония"],"ОБЫЧНОЕ"],"05IO020":["Певец ветра","Разыгрывая карту: верните бойца.","","Хаос встает на сторону слабых. Волку, преследующему добычу, преграждает путь упавшая ветка. Ястреба, пикирующего на жертву, сбивает порыв ветра. Мы – ветка. Мы – ветер.","Боец",[],["Иония"],"ОБЫЧНОЕ"],"05IO007":["Тысячехвостая сай'нен","Призвав меня, вытяните 2 карты и дайте союзникам +1|+1 до конца раунда.","","Лес щедро делится тайнами… но мало кому хватает смелости что-то у него спросить.","Боец",[],["Иония"],"ЭПИЧЕСКОЕ"],"05IO021":["Росток Бог-Ивы","Разыгрывая карту: верните союзника, чтобы призвать его эфемерную копию.\nОтсчитайте 3 раунда и призовите еще одну его эфемерную копию.","","Когда-то в Омикайялане росла Бог-Ива. То, что растет здесь теперь, может оказаться сильнее или слабее прежнего дерева. Важно то, что это новая поросль.","Место силы",[],["Иония"],"РЕДКОЕ"],"05IO024":["Дети леса","Верните союзника или потратьте 8 ед. маны, чтобы призвать эфемерные копии трех сильнейших сторонников, которых вы вернули в этом матче.","","Порой воспоминания таят угрозу.","Заклинание",[],["Иония"],"ЭПИЧЕСКОЕ"],"05IO001":["Хранительница леса","Призвав меня, дайте мне +1|+0 и Изворотливость до конца раунда.","","\"Я слышала, что ты хранишь молчание, чтобы не обременять других тяжестью знания. Но мне кажется... тебе просто надоело отвечать на вопросы\". – Ари","Боец",[],["Иония"],"ОБЫЧНОЕ"],"05IO025":["Лесной матриарх","Впервые возвращая сторонника в каждом раунде, призовите его точную эфемерную копию.","","Тайна – нечто большее, чем истина, которая за ней скрывается.","Боец",[],["Иония"],"РЕДКОЕ"],"05IO026":["Скорбь о погибших","Удар по нексусу: верните меня.","","Тот, кто чтит священные правила охоты, не забудет оплакать ее жертв.","Боец",[],["Иония"],"РЕДКОЕ"],"05IO006":["Девять жизней","Призовите карту Страж границ.","","Лесу требовался страж, который мог бы неподвижно стоять на страже его границ много лет, а то и веков. Гай'иш сам вызывался на эту роль и тут же доказал свою готовность, задремав на десяток лет.","Заклинание",[],["Иония"],"ЭПИЧЕСКОЕ"],"05IO002":["Плащ памяти","Выберите союзника и остановите направленные на него быстрые и медленные заклинания противника, либо навыки с одной союзной целью.","","Стреле неведомы ни намерения охотника, ни ценность добычи.","Заклинание",[],["Иония"],"ОБЫЧНОЕ"],"05SH014":["Зерат","Когда вы разрушаете союзное место силы, нанесите 1 ед. урона слабейшему врагу.","Вы разрушили 4+ союзных места силы.","\"Сначала они были просто друзьями, но со временем, благодаря сходству взглядов, стали близки, как братья. Бесспорно, Азир не смог бы добиться столь многого без помощи Зерата\".\n– Из \"Истории армии вознесшихся\" летописца Ка'нира","Боец",["ВОЗНЕСШИЕСЯ"],["Шурима"],"Чемпион"],"05SH017":["Вестница Мага","Призвав меня, если за этот матч вы разрушили 4+ союзных места силы, даруйте +2|+2 и Пробивание своим чемпионам везде.","","Вестница развела руки и обратила лицо к солнцу, висевшему над Шуримой кроваво-красным шаром. \"Слава Верховному магу!\" – благоговейно выдохнула она, и голос ее эхом отозвался в кольце разрушенных колонн. \"Слава Зерату!\"","Боец",[],["Шурима"],"РЕДКОЕ"],"05SH011":["Вечный последователь","Предсмертный вздох: призовите карту Саркофаг.","","Роскошное убранство гробницы ничем не могло помочь мертвецам и изгнанникам.","Боец",[],["Шурима"],"РЕДКОЕ"],"05SH022":["Поединок в пустыне","Дайте врагу -2|-0 до конца раунда. Союзник и враг наносят удар друг другу.","","\"Если путник не боится пустыни – он плохо ее знает\".\n– Шуримская поговорка","Заклинание",[],["Шурима"],"ОБЫЧНОЕ"],"05SH003":["Обелиск силы","Отсчитав 3 раунда либо когда меня призывают или когда вы меня разрушаете: даруйте сильнейшему союзнику +2|+0.","","Из песка поднялись сверкающие, потрескивающие энергией столпы – искаженные места силы, которые укрепили и без того могущественное войско Зерата.","Место силы",[],["Шурима"],"ОБЫЧНОЕ"],"05SH016":["Смертоносный аколит","Разыгрывая карту: разрушьте союзное место силы, чтобы даровать союзным Смертоносным аколитам везде +1|+1.","","Всем аколитам Зерата пришлось чем-то пожертвовать, чтобы получить силу. От самых же преданных его последователей остались лишь пустые оболочки – они служили одновременно источниками и проводниками новой силы своего повелителя.","Боец",[],["Шурима"],"ОБЫЧНОЕ"],"05SH018":["Служение пустоте","Призовите карту Изваяние стазиса, чтобы поместить в нее всех союзных бойцов и места силы, которые погибли или были разрушены в этом раунде.","","Магическая энергия не рассеивается, а всего лишь находит другое применение.","Заклинание",[],["Шурима"],"ЭПИЧЕСКОЕ"],"05SH012":["Воздвигнутый алтарь","Отсчитав 3 раунда или когда вы меня разрушаете: призовите карту Дами'йин Освобожденный.","","\"В каждом месте силы мы воздвигнем обелиск, через который Высший маг будет черпать силу, таящуюся под барханами\". – Вестница Мага","Место силы",[],["Шурима"],"ЭПИЧЕСКОЕ"],"05SH020":["Порождение пустоты","Создайте в руке карту Смертоносный аколит или Обелиск силы.","","\"Я создам новую Шуриму по своему замыслу!\" – Зерат","Заклинание",[],["Шурима"],"ОБЫЧНОЕ"],"05SH015":["Песчаная провидица","Призвав меня, вытяните 1 карту. Если вы вытянули место силы, повторите этот эффект.","","До самого горизонта земля пела от переполнявшей ее энергии. Там, где другие видели лишь песок и пыль, провидица различала сияющую сеть линий силы, которую можно было черпать бесконечно.","Боец",[],["Шурима"],"ЭПИЧЕСКОЕ"],"05SH004":["Освобожденная мощь","Дайте союзнику +2|+1 до конца раунда или разрушьте союзное место силы, чтобы дать союзнику +4|+2 до конца раунда.","","\"Я подчиню себе мощь пустыни и уничтожу любого, кто посмеет мне помешать!\" – Зерат","Заклинание",[],["Шурима"],"ОБЫЧНОЕ"],"05SH002":["Ходок пустоши","Когда вы разрушаете союзное место силы, даруйте мне +1|+1.","","Аколиты были хорошо подготовлены еще до встречи с Зератом. Затем они изучили все то, что некогда изучил он сам. Теперь их уже ничто не остановит.","Боец",[],["Шурима"],"ОБЫЧНОЕ"],"05SH007":["Мистический ритуал","Разрушьте свой кристалл маны или союзное место силы, чтобы нанести бойцу 4 ед. урона.","","\"Малая жертва ради великой силы.\" - Зерат","Заклинание",[],["Шурима"],"РЕДКОЕ"],"05NX009":["Потерянная душа","Призвав или сбросив меня, создайте в руке карту Восставший мечник.","","Демасийцы взобрались на свои укрепления, где их уже поджидала смерть. Несколько бойцов Серого легиона им удалось сразить, но вскоре стало очевидно, что темное течение войны не повернуть вспять.","Боец",[],["Ноксус"],"ЭПИЧЕСКОЕ"],"05NX006":["Возрожденный гренадер","Чтобы сыграть, сбросьте 1 карту.\nКогда меня сбрасывают, призовите мою точную копию.","","\"Зафиксирован случай отклонения от нормы. Большинству воскрешенных возвращение к жизни глубоко противно, но этот молодчик не только смирился со своей судьбой, но даже радуется открывшимся возможностям. Занятно\".\n– Из записок доктора Эслангера","Боец",[],["Ноксус"],"ОБЫЧНОЕ"],"05NX005":["Разжигатель войны","Когда меня сбрасывают, даруйте сильнейшему союзнику +2|+0.","","Могущество госпожи Норади росло, и она стала размышлять, сумеет ли воздействовать на тела, лежавшие в самых древних гробницах Ноксуса. Оказалось, что искра жизни в них едва теплится, но вокруг этого угасающего пламени все еще пляшут тени войны.","Боец",[],["Ноксус"],"РЕДКОЕ"],"05NX001":["Сион","Когда меня сбрасывают, даруйте сильнейшему союзнику Пробивание, а меня уберите в колоду.\nЗа каждую сброшенную вами карту у меня +1|+0 (но не более +7|+0).","Вы призвали или сбросили бойцов суммарно на 35+ ед. силы.","Сион видел лишь бесплотные тусклые вспышки воспоминаний. Выстроившиеся перед ним легионы. Хвалебные оды. Венцы. Сражения. Предсмертных хрип короля. Великое ничто. Кровь. Едва вспыхнув, воспоминания исчезли, как обрывки лент, которые треплет ветер.","Боец",[],["Ноксус"],"Чемпион"],"05NX003":["Соль и стежки","Чтобы сыграть, сбросьте 1 карту.\nПризовите карту Возрожденный гренадер и дайте ей +2|+0 до конца раунда.","","\"Восстань, дитя мое\". – Сумрачный доктор Эслангер","Заклинание",[],["Ноксус"],"РЕДКОЕ"],"05NX015":["Мертвый уравнитель","Призвав меня, даруйте слабейшему врагу особенность Не может блокировать.\nПредсмертный вздох: создайте в руке карту Оживленный уравнитель.","","\"Первые оживленные мной минотавры были послушными и совершенно бесполезными. Их не могли взбодрить ни ярость битвы, ни угроза повторной гибели\".\n– Из записок доктора Эслангера","Боец",[],["Ноксус"],"РЕДКОЕ"],"05NX019":["Ради славы!","Репутация: моя стоимость снижается на 3. Призовите 2 Трифарианских охотниц за славой.","","Ищущий славы не остановится ни перед чем!","Заклинание",[],["Ноксус"],"РЕДКОЕ"],"05NX013":["Мертвый всадник","Сбросив меня, создайте в руке карту Оживленный всадник.","","\"Василиск прекратил попытки сожрать всадника только после того, как мы натерли ему доспехи листьями чернодонны. Она растет в глухомани, где водятся василиски, и вонюча настолько же, насколько ядовита\".\n– Из записок доктора Эслангера","Боец",[],["Ноксус"],"ОБЫЧНОЕ"],"05NX012":["Рев мясника","Чтобы сыграть, сбросьте 1 карту. Убейте слабейшего врага.","","\"Друг, враг… какая разница?\" – Сион","Заклинание",[],["Ноксус"],"ОБЫЧНОЕ"],"05NX014":["Оружие павших","Нанесите бойцу 3 ед. урона и призовите карту Трифарианский щитолом.","","\"Щитолом!\" – Сион","Заклинание",[],["Ноксус"],"ОБЫЧНОЕ"],"05NX004":["Мрачный врач","Разыгрывая карту: сбросьте 1 карту, чтобы вытянуть бойца.","","За долгие годы прилежной работы доктор Эслангер заработал прекрасную репутацию, завоевал уважение пациентов и уже собирался было на покой. Однако истинная его служба Ноксусу началась в тот день, когда в его кабинет привели юную аристократку с черной от чужого предательства кровью.","Боец",[],["Ноксус"],"ОБЫЧНОЕ"],"05NX016":["Владычица крови","Сбрасывая из руки не мимолетного союзника, создайте в руке его мимолетную копию.","","Под покровом ночи госпожа Фарис Норади вывела из столицы свой Серый легион. Через три недели, полные крови и страданий, они подошли к небольшому демасийскому форпосту, о котором сообщали разведчики. Пришла пора испытать Легион в деле.","Боец",[],["Ноксус"],"ЭПИЧЕСКОЕ"],"05NX002":["Благородный бунтарь","Сбросив 3+ карты за игру, даруйте мне +2|+1.","","\"Ничто так не пробуждает верность в потенциальных предателях, как вид казненного заговорщика, которого оживили и вновь заставили сражаться за Ноксус. Так или иначе все послужат империи\". – Владычица крови","Боец",[],["Ноксус"],"ОБЫЧНОЕ"],"05BW005":["Нами","Разыграв заклинание, даруйте +1|+0 другому слабейшему союзнику, который не обездвижен.","Вы разыграли 5+ заклинаний, пока союзная Нами была на поле боя.","\"Ты со всеми попрощалась, юная Повелительница морей?\"\n\"Да, праматерь\".\n\"Тебе страшно?\"\n\"Да, праматерь\".\n\"Это хорошо. Страх пробуждает осторожность. Но все же постарайся поверить в себя так же, как верим мы. А теперь ступай, и да хранит тебя течение\".","Боец",[],["Билджвотер"],"Чемпион"],"05BW006":["Отлив","Нанесите 2 ед. урона врагу или вражескому нексусу (будет выбрано случайно) и создайте в руке карту Прилив.","","\"Почувствуй движение волн...\" – Нами.","Заклинание",["СТИХИЯ"],["Билджвотер"],"ОБЫЧНОЕ"],"05BW002":["Странствующий пескохвост","","","\"Конечно, некоторые из них охотятся на нас – как и на все живое. Но большинство двуногих, которых мне доводилось встречать, просто наслаждались морским простором, как и мы с вами. Не такие уж мы разные!\"","Боец",[],["Билджвотер"],"ОБЫЧНОЕ"],"05BW008":["Страж глубины","Разыграв заклинание, дайте мне +2|+0 до конца раунда.","","\"Многие мои соплеменники побаиваются Лото. Они видят лишь неутомимого бойца с отрешенным взглядом. Но я-то знаю, что он скрывает в глубине души. Страх, что ему не хватит сил нас спасти… и безграничную любовь\". – Тама, певунья мараи","Боец",[],["Билджвотер"],"ОБЫЧНОЕ"],"05BW011":["Адмирал Шелли","Разыграв 2 заклинания в каждом раунде, даруйте другим союзникам +1|+1.","","\"СТОЙ СМИ'НО, СОЙДАТ! ЧТОБ ТЫ ЗНАЛ, НА МОЕМ СЧЕТУ БОЙШЕ Т'ЕХСОТ ПОТОПЙЕННЫХ СУДОВ! Я – ЙУЧШИЙ АДМИЯЛ ВОЕННО-МО'СКОГО ФЙОТА! И ЕСЛИ Я ГОВО'Ю: П'ЫВИ, ЗНАЧИТ, П'ЫВИ!\"","Боец",[],["Билджвотер"],"ЭПИЧЕСКОЕ"],"05BW003":["Приливная волна","Нанесите 1 ед. урона двум разным случайным врагам и создайте в своей колоде карту Сокрушительная волна.","","\"Вздымайся, океан!\" – Нами","Заклинание",["СТИХИЯ"],["Билджвотер"],"РЕДКОЕ"],"05BW004":["Властитель волн","Вместо того, чтобы получить кристалл маны, восполните свою ману заклинаний. Разыгрывая заклинание, создайте в руке случайное заклинание стоимостью 3 или менее и даруйте ему Мимолетность.","","Мараи считают Лео'лея предвестником великих перемен. Каждым взмахом изящных крыльев он меняет направление течений.","Боец",[],["Билджвотер"],"ЭПИЧЕСКОЕ"],"05BW001":["Защитница мараи","Призвав меня, призовите случайного сторонника стоимостью 1.","","Мараи редко уплывают далеко от дома, но Ай'ла с самого детства была любопытной непоседой. Чувство долга удерживает ее среди соплеменников, но мечтает она лишь об одном: о настоящей свободе.","Боец",[],["Билджвотер"],"РЕДКОЕ"],"05BW010":["Праматерь мараи","Призвав меня, создайте в колоде 5 случайных заклинаний стоимостью 6+ и снизьте их стоимость до 3.","","Мараи живут под магической защитой лунного камня. Раз в сто лет его небесный свет начинает тускнеть, и новый Повелитель морей отправляется на поиски замены. Без лунного камня племя мараи погрузится во тьму и станет добычей рыщущих на глубине чудовищ.","Боец",[],["Билджвотер"],"ОБЫЧНОЕ"],"05BW013":["Певунья мараи","Призвав меня, даруйте мне Изворотливость, если вы разыгрывали заклинание в этом раунде.","","\"О берег волны бьются с ревом\nИ море делают счастливым.\nВолна всегда родится снова,\nКоль есть приливы и отливы\".\n– Куплет из \"Оды в честь Повелительницы морей\".","Боец",[],["Билджвотер"],"РЕДКОЕ"],"05PZ015":["Байкерша правосудия","Когда противник вытягивает карту, прикрепите 1 ловушку Световая бомба среди 8 верхних карт в колоде противника.","","\"Офицер на высокой скорости преследовала подозреваемую, загоняя в ловушку, которую та сама же и расставила. После ареста офицер сама выписала себе штраф за превышение скорости и весьма театрально заявила, что «Правосудие – это улица с двусторонним движением»\".\n– Из рапорта Стражей Пилтовера","Боец",[],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"05PZ012":["Участковый архивариус","Разыгрывая карту: выберите заклинание среди 5 верхних карт вашей колоды и создайте в руке его точную мимолетную копию, затем поместите эти 5 верхних карт в свою колоду.","","Детективу нужны зацепки. Архивариус скрупулезно собирает данные, открывая новые возможности для следствия.","Боец",[],["Пилтовер и Заун"],"РЕДКОЕ"],"05PZ026":["Конвейер","Призовите 2 Работяг из кузницы.","","\"Пересменка!\" – Бригадир","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"05PZ019":["Разыскивается!","Выберите, который игрок сбросит карту с самой низкой стоимостью и вытянет 3 карты.","","\"За все надо платить\". – Корина Вераза","Заклинание",[],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"05PZ031":["Альбус Феррос","Призвав меня, вытяните карту Джейс. Атака: нанесите 3 ед. урона вражескому нексусу. За каждое разыгранное вами заклинание стоимостью 6+ увеличьте это значение на 1.","","\"Благородный Альбус Феррос вновь привлек внимание общественности, перебив ставки кланов Кадвальдер и Джиопара на право финансировать исследования Джейса по улучшению хекстековых врат. Как говорится, хороший день для клана Феррос – хороший день для Пилтовера. А вчерашний день для клана Феррос стал просто замечательным\".\n– Из заказной статьи в \"Вечернем Пилтовере\".","Боец",[],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"05PZ027":["Шоковый заряд","Нанесите 3 ед. урона вражескому бойцу или нексусу и 3 ед. урона другому бойцу.","","\"Стреляю!\" – Джейс","Заклинание",[],["Пилтовер и Заун"],"РЕДКОЕ"],"05PZ022":["Джейс","Разыгрывая карту: даруйте мне Быструю атаку или Выбор противника.","Вы разыграли два заклинания стоимостью 6+. Когда мой уровень повысится, создайте в руке карту Врата ускорения.","\"Технология силообразования изменит мир! Верно, Роза?\"\n\"Это настоящий прорыв в науке, Джейс! А как припаяны взаимостабилизаторы! Просто дух захватывает\".\n\"Да уж. Это все Аксель придумал! Верно говорю?\"\n\"Ты меня знаешь, приятель. Не люблю хвастаться…\"","Боец",[],["Пилтовер и Заун"],"Чемпион"],"05PZ017":["Сточные миазмы","Нанесите бойцу 2 ед. урона. Если вы добавили в руку 2+ карты в этом раунде, вместо этого нанесите 3 ед. урона.","","\"Ты им дай немного проветриться. Новичков запах с ног валит. Но когда привыкнешь… ничего другого уже не захочешь!\" – Торговец грибами","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"05PZ013":["Пилтоверский миротворец","Нанесите бойцу 2 ед. урона и прикрепите 2 Световые бомбы среди 8 верхних карт в колоде противника.","","\"А вот МОЯ визитная карточка\". – Кейтлин","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"05PZ020":["Засада","Дайте союзнику +2|+0 до конца раунда. Если вы добавили в руку 2+ карты в этом раунде, дайте ему Изворотливость до конца раунда.","","\"Используем дымовые шашки, чтобы скрыть наше перемещение, пока мы окружаем здание…\" – Кейтлин","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"05PZ024":["Финансист Ферроса","Разыгрывая карту: воплотите заклинание стоимостью 6+ из своих регионов.","","\"Все минусы работы на деньги Ферроса искупает знакомство с Реджи. Он один из лучших профессионалов, с которыми мне когда-либо приходилось иметь дело, да и вообще отличный парень\".\n– Из записок Джейса","Боец",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"05PZ010":["Данные разведки","Прикрепите 2 Световые бомбы среди 8 верхних карт в колоде противника.\nВытяните 1 карту.","","\"По моей команде\". – Кейтлин","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"05PZ014":["Корина, преступный гений","Разыгрывая карту: прикрепите 5 Световых бомб среди 5 верхних карт в колоде противника или активируйте все ловушки на 5 верхних картах в колоде противника.","","Корина с улыбкой наблюдала за тем, как Стражи Пилтовера ломают ее дверь, топчут ботинками ее драгоценные цветы, поднимая в воздух облачка ядовитой пыли. Все шло точно по плану.","Боец",[],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"05PZ002":["Секретные данные","Все игроки вытягивают по 2 карты.","","\"Этим делом все интересуются. Один парень его уже сегодня запрашивал. Приятного прочтения!\"\n– Участковый архивариус","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"05PZ021":["Кузница завтрашнего дня","Призвав меня, призовите карту Работяга из кузницы. Разыграв заклинание стоимостью 6+, разрушьте меня и восполните свою ману заклинаний.","","Если Пилтовер – город прогресса, то кузницы можно считать двигателями этого прогресса.","Место силы",[],["Пилтовер и Заун"],"РЕДКОЕ"],"05PZ025":["Бригадир","Удар: восполните 1 ед. маны заклинаний.","","\"Чтобы воплотить чертеж в реальность, нужны две вещи: солидное финансирование и хорошая кузня – причем я говорю не только об инструментах и оборудовании. Если бригадир неумелый, идея так и останется на бумаге\".\n– Джейс","Боец",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"05PZ006":["Кейтлин","Удар: прикрепите 2 Световые бомбы среди 8 верхних карт в колоде противника.","Сработало 5+ ваших ловушек.","Кейтлин всегда была хорошим следователем и благодаря своей дотошности быстро сделала карьеру в миротворческих силах Пилтовера. Взявшись за дело К. – таинственного преступника, против которого оказались бессильны лучшие детективы, – она решила, что наконец-то встретила ровню… или почти ровню.","Боец",[],["Пилтовер и Заун"],"Чемпион"],"05PZ004":["Полицейский отряд","Призвав меня, создайте в руке карту Разыскивается!.","","Тихо разгрузить и подготовить таран было несложно. Мы быстро управились. Оставалось только дождаться сигнала Кейтлин.","Боец",[],["Пилтовер и Заун"],"РЕДКОЕ"],"05PZ009":["Детектив-провокатор","Удар по нексусу: прикрепите 2 Световые бомбы среди 8 верхних карт в колоде противника.","","Как и всем заунским детям, выросшим на опасных темных улицах, Зейну Асако пришлось быстро повзрослеть. Когда его брат погиб из-за жестокого произвола банд, Зайн решил стать пилтоверским миротворцем. Он надеется, что закон и здравый смысл наконец сделают его родной город безопасным.","Боец",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"05PZ016":["Удар милосердия","Уберите вражеского сторонника в колоду противника. Затем противник вытянет 1 карту.","","В великом городе Пилтовере живут лучшие умы Рунтерры. А еще лучшие умы Рунтерры живут в пилтоверских тюрьмах.","Заклинание",[],["Пилтовер и Заун"],"РЕДКОЕ"],"05PZ030":["Хекстековая аномалия","Вытягивая меня или создавая в руке, либо в начале каждого раунда: пока я в руке, превратите меня в случайное заклинание стоимостью 6+.","","\"…Труднее всего было стабилизировать хекстек. Хексит и кристаллы как будто нарочно не слушались и ежедневно строили мне козни. Только методом многочисленных проб и ошибок я наконец заставил все элементы работать как нужно…\"\n– Из записок Джейса","Заклинание",[],["Пилтовер и Заун"],"РЕДКОЕ"],"05PZ028":["Небоход Ферроса","Впервые разыграв заклинание стоимостью 6+, даруйте мне +2|+0.","","\"Пилтоверцы преклоняются перед интеллектом. Но что может великий ум, лишенный средств к самовыражению? Я покажу им настоящие величие! Оно вознесется над городом и затмит солнце. Под моим именем!\" – Альбус Феррос","Боец",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"05PZ038":["Ракетный обстрел","Нанесите 4 ед. урона одному врагу и 1 ед. урона всем остальным врагам.","","\"Они должны лететь вверх, а не КУДА ПОПАЛО! Ох, батюшки!\" – Хеймердингер","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"05PZ035":["Вонючий вумп","Предсмертный вздох: создайте в колоде противника мою копию, прикрепив к ней 2 Ядовитых гриба.","","В грибной сезон вумпы воняют просто невообразимо. Представьте себе открытую канализацию, забитую тухлыми яйцами и гниющей рыбой… и помножьте на два.","Боец",[],["Пилтовер и Заун"],"РЕДКОЕ"],"05PZ029":["Хекстековый погрузчик","Впервые разыграв заклинание стоимостью 6+, даруйте союзной технике везде +1|+0.","","Изначально хекстековый погрузчик был простым механизмом, доставлявшим сырье в мастерские Пилтовера. Но он полюбился местным жителям, рабочие из кузницы Джейса прозвали его Самородком, а дворовые детишки стали украшать всем, что попадется под руку.","Боец",["ТЕХНИКА"],["Пилтовер и Заун"],"РЕДКОЕ"],"05SI014":["Каталог сожалений","Начало раунда: создайте в руке мимолетную копию немимолетного заклинания, разыгранного вами в прошлом раунде.","","Благословенные острова забывают. Сумрачные острова помнят. Сумрачные острова забывают. Благословенные острова помнят.","Место силы",[],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"05SI013":["Ловцы тумана","В каждом раунде, впервые убив бойца заклинанием, призовите эфемерного бойца Туманный дух.","","Черный туман заключает жертву в бесконечный цикл самоистязания. С помощью ловушек для тумана Тек и Кана дают пленным душам возможность прервать этот цикл.\n","Боец",[],["Сумрачные острова"],"РЕДКОЕ"],"05SI009":["Сенна","Призвав меня или атакуя: создайте в руке карту Тьма, если у вас ее нет. Ваши убивающие и наносящие урон заклинания ускоряются до быстрых.","На моих глазах погиб союзный Люциан, либо вы убили 3+ бойцов с помощью заклинаний.","\"Быть Стражем значит сражаться. Потерять себя или тех, кто тебе дорог. Но это еще не все. Быть Стражем значит жить. Ради себя… и тех, кто тебе дорог\".","Боец",[],["Сумрачные острова"],"Чемпион"],"05SI016":["Тенесвет","Убейте бойца и дайте всем врагам -2|-0 до конца раунда.","","\"Нет тени без света. Нет смерти без жизни\". – Сенна","Заклинание",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"05SI004":["Смотритель Островов","В каждом раунде, впервые убивая бойца заклинанием, нанесите 2 ед. урона вражескому нексусу.","","\"Щенки есть щенки\". – Мудрость из глубины души","Боец",[],["Сумрачные острова"],"РЕДКОЕ"],"05SI012":["Страж Солари","Призвав меня, создайте в руке карту Тьма, если у вас ее нет.","","\"Я больше не вижу и не чувствую Солнце… но храню память о нем, и этого мне достаточно\".","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"05SI008":["Страж Ишталя","Призвав меня, создайте в руке карту Тьма, если у вас ее нет. Разыгрывая карту Тьма в следующий раз в этом раунде, скопируйте ее, применив к вражескому нексусу.","","\"Спрашиваешь, что меня сюда привело, Сенна? Черный туман не отнимал у меня близких, он не грозит моей родине. Но он существует, хотя не должен. Я хочу узнать причину! Необязательно же стремиться к личной мести, чтобы вам помочь?\"","Боец",[],["Сумрачные острова"],"РЕДКОЕ"],"05SI003":["Пронзающая тьма","Истощите бойца на 5 ед. здоровья.","","\"Смерть тянется к жизни\". – Сенна","Заклинание",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"05SI010":["Десс и Ада","Призвав меня, создайте в руке карту Тьма, если у вас ее нет. Ваша следующая Тьма в этом раунде стоит 0 и получает особенность \"Я наношу урон всем вражеским целям\".","","\"Снова приснился кошмар?\"\n\"Не очень страшный. Тебя не было рядом\".\n\"Ну ты и дурочка. А что было самым страшным?\"\n\"Тебя не было рядом\".","Боец",[],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"05SI011":["Деятельный Страж","Впервые убив бойца заклинанием, даруйте мне +2|+1.","","Что видит туман, когда смотрит на Мэйв? Энтузиазм, уверенность… непрошибаемую веру в лучшее. Как ему, должно быть, хочется погасить этот дразнящий огонек – ведь смерть больше всего боится жизни.","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"05SI015":["Страж бухру","Впервые убив бойца заклинанием, даруйте мне +2|+1.","","В идеологии бухру и Стражей есть принципиально важное совпадение: все должно когда-то заканчиваться. Иногда принудительно.","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"05MT004":["Камфор, демон сомнений","Призвав меня, если вы выбирали целью союзников в 4 разных раундах, даруйте мне Щит от магии, Пробивание и Выбор противника.","","Долгие века демоница Камфор охотилась на Таргоне, вытягивая из своих жертв то, что определяло их суть. Человека могущественного она лишала силы, мудрого – знаний. Сами эти дары ее не интересовали; она питалась сомнениями и страданиями, которые причиняла, забирая их. Камфор была чудовищем в полном смысле этого слова.","Боец",[],["Таргон"],"ЭПИЧЕСКОЕ"],"05MT006":["Раненый защитник пламени","","","\"Разве нужны таргонцам иные доказательства жестокости богов? Посмотрите, что они сделали с нами – и с нашими самыми прекрасными соратниками\".\n– Пантеон","Боец",["ДРАКОН"],["Таргон"],"РЕДКОЕ"],"05MT008":["Щит воина","Даруйте союзнику +1|+1 и оглушите врага.","","Пантеон был искусным воином. По опыту бессчетных сражений он знал, что враг обычно следит за движением копья, а не щита.","Заклинание",[],["Таргон"],"РЕДКОЕ"],"05MT014":["Небесное чудо","Оглушите двух врагов.","","\"Ночное небо над Таргоном – невероятно красивое зрелище. Можно позабыть обо всем и утонуть в этом бескрайнем просторе, наполненном звездами, насколько хватает взгляда. Кто знает, какие загадочные создания смотрят на нас в ответ?\" – Таргонский скалолаз","Заклинание",[],["Таргон"],"ОБЫЧНОЕ"],"05MT003":["Пантеон","","Вы выбирали целью союзников в 5+ раундах.","Смотрите: это Атрей, потерявший свободу по воле Сущностей, которых он чтил. Это тлеющие угли Войны, которая оставила Атрею дары, непостижимые для смертных. Это человек, готовый сразиться и умереть во имя тех, кто ему дорог.","Боец",[],["Таргон"],"Чемпион"],"05MT013":["Иула","Разыгрывая карту: даруйте союзнику Щит от магии или Пробивание. Если не стали, даруйте мне.","","Иула помнит жгучее горе, которое охватило ее после известия о гибели мужа. Когда Пантеон попросил помочь ему уничтожить демоницу, которая питалась этой болью, Иула долго не раздумывала.","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"05MT009":["Воинские узы","Даруйте 2 союзникам +2|+2.","","Воевать с богами казалось безнадежным делом, но ценой боли и шрамов горстка храбрецов усвоила важный урок. Боги сражались каждый сам за себя, ради собственной выгоды, позабыв о товариществе. Эта слабость стала оружием храбрецов, их надежным доспехом.","Заклинание",[],["Таргон"],"ОБЫЧНОЕ"],"05MT010":["Ослепленный оракул","Разыгрывая карту: даруйте союзнику +1|+1 и примените Безмолвие к вражескому стороннику.","","Раньше Эшима была провидицей, и люди чтили ее, ведь с помощью своего дара она помогала тем, кто нуждался в совете. Камфор отняла у нее это особое зрение, желая насытиться горечью, которую должна была почувствовать Эшима… но демоница сильно недооценила храбрую провидицу.","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"05MT002":["Сила в единстве","Дайте 2 союзникам +1|+2 до конца раунда.","","\"Узы родства дают нам силу\". – Пантеон","Заклинание",[],["Таргон"],"РЕДКОЕ"],"05MT012":["Освобожденный колосс","Призвав меня, либо когда я атакую: создайте в руке карту Самоцвет.","","Колоссы – это древние защитники священных мест Таргона. Тот, кто посмеет причинить им вред, оскорбит саму гору. Истязать их – значит совершить тягчайшее преступление в глазах любого таргонца.","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"05MT011":["Наперекор всему","Если у вашего противника больше бойцов, чем у вас, даруйте союзнику +1|+1 за каждого бойца, создающего численный перевес.","","Это была горстка отчаянных храбрецов. Они понимали, что бросают вызов бесконечно могущественным сущностям. Что их ждет верная смерть. И все же эти воины не отступили.","Заклинание",[],["Таргон"],"ЭПИЧЕСКОЕ"],"05MT005":["Герой саги","","","Он чувствовал, как с каждым ударом сердца жизнь покидает его, однако в надвигающейся тьме не почувствовал ожидаемого ужаса – напротив, он обрел смысл. Он не только бесстрашно встретит смерть, но и захватит с собой демоницу, посмевшую отнять у него остаток жизни. Вот каким его запомнят! Вот какой будет сага о Торе!","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"05DE003":["Горлит неприступный","Разыгрывая карту: поменяйте местами показатели здоровья: мой и вашего нексуса.\nВраги, у которых меньше здоровья, чем у меня, не могут меня блокировать.","","\"Это дань тем, кто ушел из этого мира, но остался в памяти людской. Демасийцы обретут надежду, когда увидят, как лучи солнца озаряют монумент. В нем будет жить несломленный дух, вдохновивший скульптора на эту грандиозную работу\".\n– Табличка на мастерской Дюранов","Боец",[],["Демасия"],"ЭПИЧЕСКОЕ"],"05DE009":["Галио","Призвав меня, даруйте другим союзникам +0|+3.","Конец раунда: у ваших союзников в сумме 25+ здоровья.","Долгие годы после своего создания Галио провел в спячке, не видя окружающего мира и не зная, что в нем происходит. Когда его пробудила магия, он впервые почувствовал боевой азарт и познал радости жизни. Теперь он жалеет, что пропустил так много прекрасного, пока спал!","Боец",[],["Демасия"],"Чемпион"],"05DE020":["Щит Дюрана","Даруйте союзнику +0|+3. В начале следующего раунда даруйте ему +0|+2.","","Одним своим видом Галио вдохновляет отважных демасийцев.","Заклинание",[],["Демасия"],"РЕДКОЕ"],"05DE021":["Мощь Авангарда","Чтобы разыграть, потратьте всю ману. Призовите карту Воин Бесстрашного авангарда и увеличьте ее характеристики до того же значения. Если потрачено 9+ ед. маны, даруйте остальным союзным элитным бойцам +2|+2.","","Когда кажется, что надежды нет, демасийские солдаты обращают взгляды на Авангард.","Заклинание",[],["Демасия"],"ЭПИЧЕСКОЕ"],"05DE017":["Ветра войны","Полностью исцелите союзника. Затем этот союзник и враг нанесут удар друг другу.","","\"Сокрушим врага!\" – Галио","Заклинание",[],["Демасия"],"РЕДКОЕ"],"05DE010":["Скульптор Дюран","Призывая союзника, даруйте ему +0|+1.","","\"Настоящий мастер знает, что шедевры не рождаются в одночасье: они создаются постепенно, многими движениями резца\".","Боец",[],["Демасия"],"ОБЫЧНОЕ"],"05DE013":["Петрицитовый рогач","Поддержка: до конца раунда я получаю весь урон за союзника, которого поддерживаю.","","Прообразом для петрицитового стража стал олень рейнджера, казавшийся теперь совсем маленьким по сравнению с каменным защитником.","Боец",[],["Демасия"],"ЭПИЧЕСКОЕ"],"05DE015":["Горный дракон","Ярость дарует мне +0|+2 вместо +1|+1.","","Грозные с виду горные драконы на самом деле довольно терпеливы. Благодаря спокойному нраву они служат природными защитниками для уязвимых стад, которые иначе страдали бы от нападений других хищников.","Боец",["ДРАКОН"],["Демасия"],"ЭПИЧЕСКОЕ"],"05DE019":["Архитектор Дюран","Поддержка: до конца раунда дайте союзнику, которого я поддерживаю, +0|+2 и Громадность.","","\"Рейнджер Элмхарт принесла нам печальные вести, – сказал архитектор ровным тоном, сосредоточенно сворачивая пергамент, чтобы скрыть дрожь в пальцах. Затем он повернулся к скульпторам и коротко им кивнул. – Этот день настал. Пора незримым защитникам Демасии выйти из тени\".","Боец",[],["Демасия"],"РЕДКОЕ"],"05DE014":["Протеже Дюранов","Разыгрывая карту: даруйте союзнику +0|+1 и Стойкость.","","Услышав топот копыт, Ширен отвлекалась от работы и подняла голову. Когда рейнджер промчался мимо, девушка почувствовала тревогу… и любопытство. Тогда она послала вслед разведчику свою петрицитовую птичку.","Боец",[],["Демасия"],"ОБЫЧНОЕ"],"05DE012":["Петрицитовый летун","Призывая союзника, даруйте мне Выбор противника.","","Измученные боем демасийские солдаты встретили пронесшегося над головами летуна ликующими криками: один только взгляд на него дарил уверенность в победе.","Боец",[],["Демасия"],"РЕДКОЕ"],"05DE018":["Петрицитовая гончая","","","\"Всегда радостно смотреть, как они оживают! Даже забываешь иногда, насколько они все разные, а ведь у каждой скульптуры характер под стать создателю\".\n– Скульптор Дюран","Боец",[],["Демасия"],"ОБЫЧНОЕ"],"06NX024":["Лорд Бродмейн","Разыгрывая карту: нанесите врагу 2 ед. урона.\nВаши быстрые и медленные заклинания, а также способности получают особенность \"Нанося урон оглушенному или раненому врагу, я его убиваю\".","","\"Действие второе. Двуличный лорд, размахивая украденной в Касури перчаткой, пытается запудрить мозги ионийцам. Но его маска слишком груба, и под ней легко разглядеть истинную сущность. Лорд просит пощады, уверяя, что сам стал жертвой обмана. Железная длань, с помощью которой он хотел править, пуста\".","Боец",[],["Ноксус"],"РЕДКОЕ"],"06NX033":["Стратегическое планирование","Оглушите 2 врагов или потратьте 6 ед. маны, чтобы призвать карту Легат.","","Распределение боевых задач лежит в основе грамотного планирования любой битвы. Хороший командир знает, что ключ к победе – это…","Заклинание",[],["Ноксус"],"РЕДКОЕ"],"06NX012":["Энни","Атака: я наношу 2 ед. урона тому, кто меня блокирует. Если блокирующего нет или он погиб, вместо этого я наношу 2 ед. урона вражескому нексусу.","На моих глазах вы разыграли 6 быстрых либо медленных заклинаний или способностей. Когда я повышаю свой уровень, создайте в руке карту Тибберс.","Более десяти лет назад Эмолайн Киосар украла из Школы Рейвенблум бесценный пламенный артефакт. Беглянку искали по всей империи, но сплетни и слухи так и не вывели разведчиков на ее след. Когда много лет спустя с северных склонов Железных гор пришли вести о некой пылающей гневом девочке, Финну Ретрику пришлось возобновить расследование и отправиться в путь. Он был уверен, что ничего там не найдет. Как же он ошибался!","Боец",[],["Ноксус"],"Чемпион"],"06NX029":["Мрачный лекарь","Когда умирает союзник с силой 5+, создайте в руке случайного сторонника с силой 5+.","","\"Сегодня я вспоминал свой маленький лазарет в Пенроуз-Хилл, где много лет пытался раскрыть секреты человеческого тела. Теперь же, проведя на службе госпожи Норади всего лишь несколько месяцев, я понял, что за все предыдущие годы не узнал ничего. Каким же я был наивным. И каким счастливым…\"\n– Из записок доктора Эслангера","Место силы",[],["Ноксус"],"ЭПИЧЕСКОЕ"],"06NX032":["Послушная драконья гончая","Когда атакует союзник, я атакую вместе с ним.","","\"Натаскивать драконьих гончих – сплошное удовольствие. Они так стараются угодить хозяину. Так быстро приспосабливаются. Жаль, что враги не отличаются такими качествами\". – Шип Розы","Боец",["ПЕС"],["Ноксус"],"ОБЫЧНОЕ"],"06NX030":["Легионер-дезертир","Я получаю все усиления союзников с пометкой \"везде\".","","\"Действие первое. Солдат оставляет свой пост, прихватив с собой древний артефакт из Касури. Теперь он сидит в таверне в Кайанви, раздувшись от самонадеянности и дешевой выпивки. Он не подозревает, что украденное сокровище шепчет обо всем происходящем своему истинному владельцу. Жизнь дезертира утекает, как вино – алая ноксианская кровь на ионийском золоте\".","Боец",[],["Ноксус"],"РЕДКОЕ"],"06NX013":["Метатель заклинаний","Разыгрывая карту: оглушите врага. Если он уже оглушен, вместо этого нанесите ему 2 ед. урона.","","\"Студент: Сайделл Китера Преподаватель: Дж. Виллоу Инцидент: в левое предплечье меня укусил паук. Китера утверждает, что это вышло случайно, но наглая улыбка выдает злой умысел.\nМера наказания: 2 недели дежурства в столовой\".\n– Дисциплинарное замечание из школы Рейвенблум","Боец",["ПАУК"],["Ноксус"],"ОБЫЧНОЕ"],"06NX040":["Трифарианский тренировочный ринг","В каждом раунде, когда впервые атакует союзник с силой 5+, используйте Рвение.","","\"По моему приказу начать бой! Если убьете партнера по тренировке, ищите другого. Если погибнете – знайте, что своей смертью вы сделали сильнее другого воина Ноксуса. Трифарианцы! Начали!\" – Трифарианский инспектор","Место силы",[],["Ноксус"],"ЭПИЧЕСКОЕ"],"06NX028":["Школа Рейвенблум","Отсчитайте 11 раундов и создайте в руке карту Тайболк.\nМой счетчик продвигается на 1 раунд за каждое сыгранное вами в этом матче быстрое либо медленное заклинание или способность.","","\"…скорее всего, до вас уже дошли вести о том, что академия Роузгард не справилась со своей задачей. Надеюсь, вы научитесь на ошибках ваших коллег и будете управлять вверенным вам учреждением так, чтобы его выпускники как можно лучше служили империи\".\n– Из обгоревшего письма, найденного на развалинах хранилища.","Место силы",[],["Ноксус"],"РЕДКОЕ"],"06NX014":["Расщепление","Выберите бойца. В следующий раз, когда он получит 1 и более ед. урона в этом раунде, убейте его.","","Директриса Телси долго и подробно рассказывала о принципах силы Ноксуса, чем вконец утомила учеников. Большая часть класса все же сидела смирно, а вот заскучавшая Энни решила действовать. Сначала с помощью дыма, а потом и пламени.","Заклинание",["СТИХИЯ"],["Ноксус"],"ОБЫЧНОЕ"],"06NX031":["Пленный йети","Репутация: моя стоимость снижается на 4.","","Толпа ахнула, когда в легендарную бойцовскую яму Бордента ввели двух йети, закованных в цепи. Никто не ожидал, что эти звери способны разорвать оковы, ведь никто прежде не был свидетелем их ярости.","Боец",["ЙЕТИ"],["Ноксус"],"ОБЫЧНОЕ"],"06NX009":["Пленный секиронос","Атака: я наношу 3 ед. урона тому, кто меня блокирует. Если блокирующего нет или он погиб, вместо этого я наношу 3 ед. урона вражескому нексусу.","","\"Действие третье. Жестокая хозяйка и ее питомец. Не стоит винить секироноса: магический амулет заставляет его повиноваться приказам. Когда бывшую хозяйку отдают ему на растерзание, она сжимает зубы и не издает ни звука. Если бы все ноксианцы принимали смерть так же благородно!\"","Боец",[],["Ноксус"],"ОБЫЧНОЕ"],"06NX015":["Ученик-чародей","В каждом раунде, когда вы впервые разыгрываете быстрое либо медленное заклинание или способность, я разыгрываю Отблески магии.","","\"С Даани мы познакомились пару лет назад. Приятный юноша из хороший семьи. Когда во время прошлой поездки я остановился в его родном селе, Даани в одиночестве сидел на площади – он сказал, что ждет возвращения родных. Должно быть, бедный мальчик просидел там не один месяц. У меня не хватило духу рассказать ему, что я видел по дороге…\" – Финн Ретрик","Боец",[],["Ноксус"],"ОБЫЧНОЕ"],"06NX037":["Ноксианские камни судьбы","Создайте в руке мимолетную карту Твердая решимость, Кружащаяся смерть или Оружие павших.","","\"Дорогая Клара, потрудись отмыть кровь с жетонов\".\n– Офелия Норади, Алая аристократка","Заклинание",[],["Ноксус"],"РЕДКОЕ"],"06NX008":["Староста","Разыгрывая быстрое либо медленное заклинание или способность, даруйте мне +1|+0.","","\"Большинство учеников сейчас в том возрасте, когда хочется идти против всего, чему учат в школе. Нам повезло, что старшая из них не только стала кумиром для младших, но и склоняется к нашим идеям. Если ученики будут пренебрегать обычными уроками, мы сможем обучать их с ее помощью\". – Директриса Телси","Боец",[],["Ноксус"],"ЭПИЧЕСКОЕ"],"06MT044":["Звезднорог Солари","День: дайте прочим союзникам +0|+2 до конца раунда.","","Все звезднороги рождены среди звезд, но некоторые из них светятся ярче других.","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"06MT036":["Воззвание к небесам","Полностью исцелите всех союзников, затем увеличьте их силу до значения их здоровья.","","\"Сначала нужно научиться милосердию. Остальное приложится\". – Сорака","Заклинание",[],["Таргон"],"ЭПИЧЕСКОЕ"],"06MT039":["Обитель драконов","Отсчитайте 3 раунда и призовите карту Инвиолус Вокс.","","\"Если верить легенде, небесные драконы рождаются сразу взрослыми из звездной пыли и туманностей. Но откуда простым смертным знать, так ли это? С огромного расстояния нам виден только их свет\".\n– Драконья вестница","Место силы",[],["Таргон"],"ЭПИЧЕСКОЕ"],"06MT045":["Небесная триада","Позовите творение небес с низкой, средней и высокой стоимостью.","","\"Звезды предвещают нечто великое. Интересно, что это будет? Я даже представить не могу. А ты что думаешь, Кулун?\" – Лунная сновидица","Заклинание",[],["Таргон"],"РЕДКОЕ"],"06MT043":["Таргонские камни судьбы","Создайте в руке мимолетную карту Узрите бесконечность, Тишина или Благословение Таргона.","","\"Веришь или нет, Шорин, но я знаю, какое созвездие изображено на каждом камне, даже не переворачивая их\". – Пилигрим Тиари","Заклинание",[],["Таргон"],"РЕДКОЕ"],"06MT029":["Эсмус, Дыхание мира","Призвав меня, прикрепите Колокольчик к верхней карте своей колоды.\nПоддержка: даруйте союзнику, которого я поддерживаю, +1|+1.","","\"…я слышала, что сам Странствующий хранитель создал Эсмус, и вместе с ней в мир пришел звук\".\n\"А вот и нет! Всем известно, что у Эсмус лик древней певицы с чистым сердцем, которая отдала своей голос мертвым, и тогда Бард выковал для нее новый – несравненной красоты\".\n\"А вот и нет! Эсмус – это…\"\n– Популярная игра менестрелей \"Рождение Эсмус\".","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"06MT038":["Спираль света","Ночь: дайте остальным союзникам +2|+1 и Пробивание до конца раунда.","","\"Матерь луна, даруй нам силу!\nКогда нас окружает тьма,\nтвой свет поможет ее превозмочь\".\n– Молитва Лунари","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"06MT047":["Мистический вихрь","Призвав меня, либо когда я отсчитываю раунд, прикрепите 3 Колокольчика в своей колоде. Отсчитайте 2 раунда и вытяните 1 карту.","","\"И тут я их увидел! Многие тысячи – и все напевают да пляшут, кто так, кто сяк. А потом чего-то вспыхнуло, и все пропало. Даже храм! Весь, до последнего камушка. А у старого Гэффа в руках остался колокольчик\". – Рассказ старого Гэффа, часть 3","Место силы",[],["Таргон"],"РЕДКОЕ"],"06MT041":["Стая звездных гончих","Союзные Стаи звездных гончих везде получают усиления Избранных.","","Зря скалолазы пытались приманить звездных гончих. Собаки их игнорировали, а магия горы, кажется, не оказывала на них никакого действия\".","Боец",["ПЕС"],["Таргон"],"ОБЫЧНОЕ"],"06MT049":["Благословение Микаэля","Даруйте союзнику +1|+2 и лишите его всех вредных навыков.","","Те, кто слышал звон колокола, были поражены чистотой этого звука.","Заклинание",[],["Таргон"],"РЕДКОЕ"],"06RU025":["Эвелинн","Исток: Объятия агонии.\nПризвав меня, призовите случайную Оболочку.","Когда на моих глазах вы или союзник убиваете союзную Оболочку, дайте мне ее полезные навыки до конца раунда и повысьте мой уровень.","Жрица смотрела на нее широко распахнутыми глазами. Руки ее дрожали от волнения. Она была готова. Это был самый сладкий момент для Эвелинн. Она оскалилась и медленно сбросила личину. А потом, как всегда, жертва начала кричать.","Боец",[],["Рунтерра"],"Чемпион"],"06RU001":["Бард","Исток: Странствующий хранитель.\nАтака: прикрепите 3 Колокольчика в своей колоде.","Вы увеличили характеристики союзников в руке или в игре в сумме на 20+ ед.","\"Да, старый Гэфф за свою жизнь немало чудес повидал! В первый раз аж сам хранитель явился! Свалился с неба, как звезда падучая – и сразу все кругом замерло, и мы с ним как будто остались одни на всем свете…\" – Рассказ старого Гэффа, часть 1","Боец",[],["Рунтерра"],"Чемпион"],"06RU002":["Джин","Исток: Виртуоз.\nАтака: нанесите 2 ед. урона всем оглушенным врагам.","Вы применили 12+ быстрых либо медленных заклинаний или способностей.","\"Увертюра. Мы в городе Кайанви, где старый учитель поручает юному ученику избавиться от группы злодеев и вернуть священный артефакт, который они похитили. Исполнитель главной роли в нетерпении, но ему еще рано выходить на сцену. Он готовится за кулисами\".","Боец",[],["Рунтерра"],"Чемпион"],"06FR029":["Леденящий ужас","Заморозьте врага и призовите карту Снежнозубая стая.","","Вместе с холодами приходят снежнозубые волки. Им не нужно загонять добычу. Достаточно просто подождать.","Заклинание",["СТИХИЯ"],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"06FR033":["Охотящийся вепрь","Предсмертный вздох: получите пустой кристалл маны.","","Во Фрельйорде особый цикл рождения и смерти. В суровых условиях тундры почти ничего не пропадает зря.","Боец",[],["Фрельйорд"],"ОБЫЧНОЕ"],"06FR038":["Крылья Криофеникса","Нанесите 3 ед. урона ВСЕМ бойцам.\nПросветление: вместо этого нанесите 3 ед. урона всем врагам и восстановите 3 ед. здоровья своему нексусу.","","Под тенью огромных крыльев Криофеникса ее союзники ликовали, а враги дрожали от страха.","Заклинание",["СТИХИЯ"],["Фрельйорд"],"РЕДКОЕ"],"06FR030":["Вестник оттепели","Разыгрывая карту: призовите карту Ледяной раб или продвиньте всех своих Ледяных рабов на 1 раунд.","","Над головами разведчиков пронеслась тварь, издавая свистящий крик, который сперва показался тихим, но, отразившись от каменных стен ущелья, зазвучал так, что у всех кости загудели. Поверхность льда тут же пошла трещинами, многие из которых стали быстро расти.","Боец",["ПТИЦА"],["Фрельйорд"],"ОБЫЧНОЕ"],"06FR039":["Ярость когтерыси","Превратите союзного сторонника в карту Когтерысь-альфа.","","\"Великий дух когтерыси, даруй нам свою силу!\" – Удир","Заклинание",[],["Фрельйорд"],"РЕДКОЕ"],"06FR028":["Ревна, хранительница преданий","Призвав меня, даруйте бойцам в своей колоде мои характеристики, а затем вытяните бойца с силой 5+.","","Хранителями преданий в племени аваросан обычно становятся опытные воины, которые также являются талантливыми рассказчиками. Через легенды и песни они передают новому поколению традиции войны и охоты. ","Боец",[],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"06FR037":["Треснувший лед","Даруйте врагу особенность \"В начале следующего раунда заморозьте меня\".","","Ступая на лед, нужно сперва проверить его на прочность, каким бы крепким он ни казался.","Заклинание",["СТИХИЯ"],["Фрельйорд"],"ОБЫЧНОЕ"],"06BC045":["Чихучая пыльца","Дайте союзникам +1|+1 до конца раунда. Если эти союзники созданные, вместо этого дайте им +2|+2.","","\"ПРИВЕТ. Я ГРИБ. ГОВОРЯЩИЙ. НЕ ЗНАЮ, КАК И ПОЧЕМУ. ЧТО СЛУЧИЛОСЬ. ДАЙТЕ МНЕ ПРОСТО БЫТЬ ГРИБОМ. СПАСИБО. ДО СВИДАНЬЯ\". – Гриб","Заклинание",[],["Бандл Сити"],"ЭПИЧЕСКОЕ"],"06BC036":["Великий Папаро","Разыгрывая карту: воплотите йордла.\nАтака: даруйте союзникам-йордлам +1|+0.","","\"ВСЕ обожают Папаро! Каждое лето он привозит нам сувениры со всего света – что-то вкусненькое, или красивенькое, или совершенно безумное!\"\n– Целеустремленная Эйва","Боец",["ЙОРДЛ"],["Бандл Сити"],"ЭПИЧЕСКОЕ"],"06BC040":["Бандловые камни судьбы","Создайте в руке мимолетную карту Приспособление йордлов, Героический рефрен или Электрогарпун.","","Йордлы всегда готовы поиграть… но не удивляйтесь, если они изменят правила на ходу!","Заклинание",[],["Бандл Сити"],"РЕДКОЕ"],"06BC039":["Бросок бомбы","Нанесите бойцу 2 ед. урона и призовите карту Самодельная бомба.","","\"Кажется, плохо дело\", – тихо сказала Жизель, прячась в укрытии.","Заклинание",[],["Бандл Сити"],"ОБЫЧНОЕ"],"06BC044":["Оковы Вселенной","Нанесите одному врагу 2 ед. урона и оглушите другого. Прикрепите 6 Колокольчиков в своей колоде.","","\"Мам, а где странствует хранитель?\"\n\"Везде, где только можно представить, солнышко\".\n\"А зачем он это делает?\"\n\"Не задумывайся об этом. Даже мудрейшим старейшинам неведомы пути хранителя…\"\n– Мать и дитя","Заклинание",[],["Бандл Сити"],"РЕДКОЕ"],"06BC026":["Звонарь Бирд","Призвав меня, прикрепите Колокольчик к верхней карте своей колоды.","","\"Второй раз вообще невесть что творилось! Подметал я, значит, полы, и тут вижу: ужин мой по столу расплескался, а кастрюли со сковородками ножки отрастили, да шасть за дверь! Ну я, не будь дурак, за ними. Они в храм, и я в храм! А они там по полкам шарятся, будто ищут чего-то\". – Рассказ старого Гэффа, часть 2","Боец",[],["Бандл Сити"],"ОБЫЧНОЕ"],"06BC030":["Взрывоопасный гриб","Нанесите бойцу 1 ед. урона. Если в этом раунде сработала ваша ловушка или поощрение, вместо этого нанесите 3 ед. урона.","","\"Если засветилось – значит, сейчас рванет!\" – Правило бандлскаута №463","Заклинание",[],["Бандл Сити"],"ОБЫЧНОЕ"],"06BC031":["Мадули, хранитель врат","Призвав меня, прикрепите Колокольчик к верхней карте своей колоды, затем удвойте число поощрений в своей колоде.","","\"То-то я страху натерпелся! Рук у него столько, что не сосчитать, а каждый зуб размером с булыжник. Когда оно провело по зубам молоточком, я думал, на месте окочурюсь, такая жуткая вышла мелодия. Побежал я без оглядки, но сперва успел увидеть, что все небо стало в дырку!\"\n– Рассказ старого Гэффа, часть 4","Боец",[],["Бандл Сити"],"РЕДКОЕ"],"06BC035":["Бумажное дерево","Когда атакует союзник с прикреплением, даруйте этому прикреплению +1|+0.","","Листья бумажного дерева светятся магией фаэ, которая его сотворила. Они напоминают птиц не только формой, но и пристрастиями: обожают все блестящее!","Место силы",[],["Бандл Сити"],"РЕДКОЕ"],"06IO005":["Жуткий театр","Верните бойца, у которого не более 3 очков здоровья.","","\"Творца нельзя торопить\". – Джин","Заклинание",[],["Иония"],"ОБЫЧНОЕ"],"06IO038":["Моральная поддержка","Моя стоимость снижается на 2, если в этом матче вы поддерживали союзника. Дайте союзнику Щит до конца раунда.","","\"Верь в равновесие. Пройди по грани\". – Шен","Заклинание",[],["Иония"],"ОБЫЧНОЕ"],"06IO012":["Зов Кинку","Сейчас или в начале следующего раунда призовите карту Хранительница масок. Вытяните 1 карту.","","\"Древние маски открывают глаза молодым\".\n– Хранительница масок","Заклинание",[],["Иония"],"ОБЫЧНОЕ"],"06IO009":["Драконья засада","2 карты Дракончиков идут в самостоятельную атаку.","","\"Желания воплощаются\".\n– Повелитель драконов","Заклинание",[],["Иония"],"ОБЫЧНОЕ"],"06IO033":["Вихрь клинков","До конца игры, используя Танец с клинками, призовите еще один атакующий Клинок.\nИспользуйте Танец с клинками (1).","","\"Начинай танец, а я подхвачу\". – Танцующая с лентами","Заклинание",[],["Иония"],"ЭПИЧЕСКОЕ"],"06IO004":["Создательница","Разыгрывая карту: верните бойца, чья сила меньше моей.","","\"Создательница – гениальный творец! Живая легенда! Каждая ее работа безупречна! Даже просто увидеть ее лично – великая честь, я уж не говорю о том, чтобы владеть инструментом, созданным ее руками\".\n– Свидетельница из Касури","Боец",[],["Иония"],"РЕДКОЕ"],"06IO010":["Вершина ветров","Призвав меня, вытяните чемпиона Ясуо и оглушите сильнейшего врага.\nПолучив жетон атаки, оглушите сильнейшего врага.","","Большинство людей под \"мирной жизнью\" понимают уютный дом и теплые объятия любимых. Для Ясуо же это тот редкий момент, когда стихают ветра, и на смену воспоминаниям приходят надежды. ","Место силы",[],["Иония"],"ЭПИЧЕСКОЕ"],"06IO036":["Ионийские камни судьбы","Создайте в руке мимолетную карту Жуткий театр, Ритуал обновления или Плечом к плечу.","","\"Научиться угадывать намерения противника жизненно важно, и игра отлично для этого подходит. Но нельзя забывать и о том, что играть должно быть весело! А теперь приготовь мне ванну для ног\". – Вдохновляющий наставник","Заклинание",[],["Иония"],"РЕДКОЕ"],"06IO003":["Работница сцены","Разыгрывая карту: оглушите врага.","","\"Действие четвертое. На сцене появляется юная жрица. Ее трагичную историю рассказывают бескровные губы тех, кого она предала. Жрица отчаянно желает искупить свою вину и несет в руках тяжкое бремя, золотой дар для ноксианцев, которых она сама привела на родную землю. Остается лишь гадать, что же разбило ее сердце: скорбь или пуля?\"","Боец",[],["Иония"],"ОБЫЧНОЕ"],"06IO035":["Ученица ордена Кинку","Когда другой союзник получает Щит, дайте мне Щит до конца раунда, если у меня его еще нет.","","\"Стремись к гармонии на каждом уровне: гармонии разума, тела и духа. Сдерживай порывы юности. Учись мыслить шире\". – Шен","Боец",[],["Иония"],"РЕДКОЕ"],"06PZ032":["Шипящий песнефон","Создайте в руке одно из двух новых заклинаний стоимостью 2 на выбор. В этом раунде его стоимость равна 0. Повторите еще дважды.","","Первый заунский песнефон работал на удивление хорошо. Его единственным минусом была невозможность регулировать громкость.","Заклинание",[],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"06PZ042":["Безумная бракоделка","Разыгрывая карту: выберите карту в руке. Создайте в своей колоде 4 ее точные копии и снизьте их стоимость на 1.","","\"Сегодня все могло бы сложиться гораздо удачнее. Подробности излишни. Будущей мне: ты помнишь, что я имею в виду\".\n– из дневника Кей","Боец",[],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"06PZ025":["Тоска","Призвав меня, призовите случайную Оболочку.\nПризывая союзника стоимостью 1, даруйте ему случайный навык.","","\"Возвращаясь домой с Антресольного уровня, я увидела, как в переулке плачет бедная бродяжка. Сердце разрывается от того, что все обходят ее стороной, хотя она в таком отчаянном положении! Если завтра снова ее встречу, то попробую помочь в меру своих возможностей\".\n– Из дневника госпожи Семпеску","Боец",[],["Пилтовер и Заун"],"РЕДКОЕ"],"06PZ043":["Пилтоверские камни судьбы","Создайте в руке мимолетную карту Афтершок, Хекстековый преобразователь или День Прогресса!.","","\"Более элегантного набора вы больше нигде не найдете, уважаемый. Моя дочь вложила душу в каждую фишку\". – Корин Ревек ","Заклинание",[],["Пилтовер и Заун"],"РЕДКОЕ"],"06PZ027":["Тайное приглашение","Создайте в руке мимолетную карту Подозрительная личность или Химпанк-гитарист и уменьшите ее стоимость на 1.","","В Зауне на лучшие ночные вечеринки можно попасть только по приглашению. Если вы сами не играете в музыкальной группе, попытайтесь достать билет через знакомых. А может, вам посчастливится просто его найти.","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"06PZ038":["Трофейный камуфляж","Даруйте союзнику Изворотливость и особенность \"Удар по нексусу: вытяните 1 карту\".","","\"Вы просто не поверите, что я сегодня нашел!\" – Щипач-добытчик","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"06PZ039":["Полезный утиль","Чтобы разыграть, сбросьте до 2 карт. Создайте столько же сторонников из ваших регионов стоимостью на 1 больше и снизьте их стоимость на 1.","","Обитателям нижних уровней Зауна приходится обходиться тем, что выбросили другие. За долгие годы они научились находить что-то полезное в любой куче мусора.","Заклинание",[],["Пилтовер и Заун"],"РЕДКОЕ"],"06BW006":["Иллаой","Атака: используйте Порождение, а затем прибавьте силу своего сильнейшего щупальца к моей до конца раунда.","На моих глазах я или союзные Щупальца нанесли 15+ ед. урона.","\"Око Нагакейборос\" – всего лишь название, но Иллаой старается жить так, словно богиня действительно наблюдает за каждым действием, и ее нужно развлекать.","Боец",[],["Билджвотер"],"Чемпион"],"06BW036":["Кривохвост","У меня +1|+0 за каждый раунд, в котором вы повреждали вражеский нексус.","","\"Бухта – самое кровавое место в Билджвотере. Вы только гляньте на тамошних крыс. С рождения кровь лакают, и все им мало. Жуткие тварюшки\". – Мясник из \"Ржавых крючьев\"","Боец",[],["Билджвотер"],"ЭПИЧЕСКОЕ"],"06BW038":["Мегарог","Уйдя на Глубину, исцелите союзников и нексус на 3 ед. здоровья.","","\"Что ему от нас нужно?\"\n\"Кажется… оно учуяло апельсины\".\n\"Во имя Бородатой Леди, СКИНЬТЕ ЕМУ ВЕСЬ БОЧОНОК!\" – Невезучие моряки","Боец",["МОРСКОЕ ЧУДОВИЩЕ"],["Билджвотер"],"ОБЫЧНОЕ"],"06BW030":["Око Нагакейборос","Используйте Порождение х2.\nВытяните 2 карты.","","Нагакейборос – богиня провидения… но лишь для тех, кто выживает в процессе поклонения.","Заклинание",[],["Билджвотер"],"ОБЫЧНОЕ"],"06BW011":["Нагакейборос","Призвав меня или в начале раунда: используйте Порождение х2. Затем, если ваше сильнейшее Щупальце имеет 12+ силы, создайте в руке карту Гнев Нагакейборос.","","\"Мать Змея. Матерь Глубин. Бородатая Леди. Не имеет значения, как вы назовете Нагакейборос. Имена ее интересуют не больше, чем беспокойные мертвецы\".\n– Иллаой","Боец",[],["Билджвотер"],"ЭПИЧЕСКОЕ"],"06BW021":["Урок подводных течений","Нанесите 3 ед. урона вражескому бойцу.\nИспользуйте Порождение (3).\nНанесите 1 ед. урона вражескому нексусу.","","\"Мы с детства учимся плыть по течению, ведь бороться с бурными волнами – верная смерть. Неудивительно, что первое испытание для будущей жрицы – забыть этот урок и плыть против потока, бросив на это все силы! Ибо Вестница – не пловчиха. Она сама и есть течение.","Заклинание",[],["Билджвотер"],"ЭПИЧЕСКОЕ"],"06BW045":["Кровь в воде","Нанесите 1 ед. урона любой цели, а затем используйте Рвение.","","На акул, кружащих в Бухте Потрошителей, нет никакой управы. Попробовав кровь, они непременно захотят еще.","Заклинание",[],["Билджвотер"],"ОБЫЧНОЕ"],"06BW028":["Удар щупальцем","Используйте Порождение х2. Затем ваша сильнейшая карта Щупальце и враг наносят удар друг другу.","","\"Жизнь – это испытание. Боль – учитель, который преподает уроки чаще, чем хотелось бы\". – Иллаой","Заклинание",[],["Билджвотер"],"РЕДКОЕ"],"06BW035":["Голос моря","Атака: используйте Порождение и дайте вашему сильнейшему щупальцу Пробивание до конца раунда.","","Нагакейборос нельзя призвать обрядами и ритуалами. Она откликается на молитвы тех, чья душа созвучна океану, взлетает и падает вместе с каждой волной. Мало кто способен выдержать прикосновение стихии.","Боец",[],["Билджвотер"],"РЕДКОЕ"],"06BW015":["Услышанные молитвы","Используйте Порождение х2 или заплатите 5 маны, чтобы использовать Порождение х4.","","Богиню Нагакейборос не просят о милости или дарах. Ее благословение подобно самой жизни: она посылает испытания и борьбу, чтобы вы прошли свой путь и сами заслужили награду.","Заклинание",[],["Билджвотер"],"ОБЫЧНОЕ"],"06BW007":["Бдительный идол","Начало раунда: нанесите мне 2 ед. урона и используйте Порождение.","","Когда с Сумрачных островов надвигаются призраки, идол ярко сияет, становясь маяком надежды.","Боец",[],["Билджвотер"],"ОБЫЧНОЕ"],"06BW037":["Щедрый выкуп","Воплотите сторонника, на которого вам хватает маны.","","\"Ну что, Баз, попробуем снова?\"\n\"На этот раз должно повезти, Гэв! Мне кажется, мы уже дрались со всем, с чем можно драться в этом вонючем городе\".\n\"Дрались и проиграли, Баз\". – Баз и Гэв, начинающие охотники за головами","Заклинание",[],["Билджвотер"],"ЭПИЧЕСКОЕ"],"06BW041":["Мухлеж","Выберите 1 из 2 карт (не чемпионов) из руки противника и создайте копию в своей руке. Разграбление: моя стоимость снижается на 1.","","\"Пять тузов?! Похоже, я снова выиграл!\" – Проныра","Заклинание",[],["Билджвотер"],"РЕДКОЕ"],"06BW016":["Дозорная бухру","Призвав меня, используйте Порождение х3.","","Красота жизни раскрывается в самых простых вещах. Соленый ветер в лицо, птичьи трели поутру… и вполне ожидаемый враг на горизонте.","Боец",[],["Билджвотер"],"ОБЫЧНОЕ"],"06BW009":["Старейшина бухру","Разыгрывая карту: союзник стоимостью 1 идет в самостоятельную атаку.","","\"Вспомни мудрость океана! Если не будешь двигаться сам, тебя сдвинут другие! Иди на мой голос, если ты сбился с пути – ведь враги не сбились со следа!\" ","Боец",[],["Билджвотер"],"РЕДКОЕ"],"06BW043":["Билджвотерские камни судьбы","Создайте в руке мимолетную карту Еще пороха!, Игривый шутник или Ловля на живца.","","\"Когда играешь в камни судьбы в Билджвотере, даже не мечтай поймать кого-нибудь на блефе. Тут врут как дышат. Если хочешь выиграть, следи за руками\".\n– Твистед Фэйт","Заклинание",[],["Билджвотер"],"РЕДКОЕ"],"06BW018":["Стим","Призвав меня, призовите случайную Оболочку.\nПризвав союзника стоимостью 1, даруйте сильнейшему врагу Уязвимость.","","Первая встреча Эвелинн и Стима была жестокой и бурной. Эвелинн запомнила, с каким нескрываемым наслаждением улыбался Стим, когда она истязала его, и как охотно он отплатил мучениями ей самой. Наконец поборов младшего демона, Эвелинн решила не уничтожать его, а навеки привязать к себе. Возможно, таким образом она хотела нести в мир их общую любовь к кровавым расправам.","Боец",[],["Билджвотер"],"ОБЫЧНОЕ"],"06SH014":["Отродье Бездны","Призвав меня, даруйте мне все полезные навыки, которыми обладали союзники в этом матче.\nЕсли у союзника появляется новый полезный навык, даруйте его мне.","","\"Мы слышали о других прорывах Бездны и о том, какие страшные разрушения она оставляет за собой. Теперь я увидела все собственными глазами и не знаю, смогу ли когда-нибудь забыть пережитый ужас\".","Боец",[],["Шурима"],"ЭПИЧЕСКОЕ"],"06SH016":["Вестник роя","Разыгрывая карту: даруйте бойцу и мне полезные навыки друг друга.","","\"Он говорил со мной так, словно мы знакомы. Словно он хотел подготовить меня ко встрече… с чем-то\". – Кай'Са","Боец",[],["Шурима"],"РЕДКОЕ"],"06SH009":["Кай'Са","Призвав меня или в начале раунда: если у вас есть жетон атаки, создайте в руке карту Вторая кожа.","Вы эволюционировали.","Несколько дней назад вторая кожа Кай'Сы пришла в движение и все настойчивее стала тянуть ее к шуримскому побережью. Кай'Са понимала, что это дурной знак, но лишь добравшись до Белвета осознала чудовищный масштаб катастрофы.","Боец",[],["Шурима"],"Чемпион"],"06SH048":["Обряд посвящения","Воплотите разрушенное в этом матче союзное место силы и призовите его.","","\"Время застыло\". – Зилеан","Заклинание",[],["Шурима"],"ОБЫЧНОЕ"],"06SH037":["Баккай – иссушающий коготь","Разыгрывая карту: даруйте врагу Уязвимость.\nВыбирая противника, дайте ему -2|-0 до конца раунда.","","Последние крупицы их разума исчезали, как песок на ветру, обнажая семена гнева. Из них выросла ярость, которую не утолят все воды пустыни.","Боец",[],["Шурима"],"ОБЫЧНОЕ"],"06SH008":["Старейшина Белвета","","","Шалати в ужасе отшатнулась. Перед ней лежала мертвая Ферай, дочь доброго мясника. Ужасная сила сокрушила ее тело. Рядом был Горруб, сын рыбака. Безжизненными руками он даже в смерти тянулся к своей возлюбленной. Сколько воспоминаний исчезло навсегда. Сколько жизней потеряно! Оскалившись, Шалати повернулась к незваному кошмару, готовясь отдать свою жизнь за еще не погибших соплеменников.","Боец",[],["Шурима"],"ОБЫЧНОЕ"],"06SH042":["Шуримские камни судьбы","Создайте в руке мимолетную карту Беспощадный хищник, Взвешенное решение или Призрачный огонь.","","\"В камнях судьбы важна не победа, а то, насколько круто ты выглядишь во время партии!\" – Акшан","Заклинание",[],["Шурима"],"РЕДКОЕ"],"06SH050":["Пески времени","Дайте врагам -2|-0 до конца раунда. Создайте в руке мимолетную карту Прыжок во времени.","","Пески времени струятся бездумно и бесстрастно. Но не все подвластны этому жестокому безразличию.","Заклинание",[],["Шурима"],"РЕДКОЕ"],"06SH049":["Зов славы","Моя стоимость снижается на 2 за каждого призванного вами в этом матче уникального вознесшегося союзника.\nВоплотите карту из колоды императора стоимостью 9 или менее.","","\"Это плоды наших трудов! Вот чего мы добились вместе!\" – Азир","Заклинание",[],["Шурима"],"РЕДКОЕ"],"06SH036":["Камера обновления","Призвав чемпиона, уничтожьте меня, чтобы даровать ему +2|+1 и Щит от магии.","","Когда Насус поднялся из саркофага, его разум прояснился, а раны затянулись. Он сделал несколько заметок и поднял взгляд к висевшим наверху саркофагам, гадая, о чем думают заключенные в них чудовища. Только время покажет, исцелят ли безумных баккай эти чары, против которых в свое время выступали другие вознесшиеся. Теперь вознесшихся не осталось, а безумный Ренектон был рядом. Насус записал еще несколько слов, надеясь, что наконец нашел способ спасти брата.","Место силы",[],["Шурима"],"ЭПИЧЕСКОЕ"],"06SH011":["Сверхзаряд","Даруйте союзнику Пробивание и Щит от магии.","","\"Я покажу, как надо сражаться\". – Кай'Са","Заклинание",[],["Шурима"],"ОБЫЧНОЕ"],"06SH017":["Ловчая из Бездны","Нанесите стороннику 1 ед. урона. Если вы эволюционировали, вместо этого нанесите 3 ед. урона бойцу.","","\"Больно, правда?\" – Кай'Са","Заклинание",[],["Шурима"],"РЕДКОЕ"],"06SH007":["Войдлинг","Пока я в руке, мой навык каждый раунд меняется на случайный. Призвав меня, даруйте мне текущий навык.","","Дхарна помнила, как утром распахнула окна, и с улицы донесся запах свежеиспеченного хлеба. Рыбаки уже несли на полуденный базар свой улов. Она помнила, как улыбнулась. Казалось, день будет хорошим…","Боец",[],["Шурима"],"ОБЫЧНОЕ"],"06SH010":["Оружие Бездны","","","Прорыв Бездны в Белвете был быстрым и кошмарным. Большинство жителей в ужасе бежали со всех ног, надеясь спастись от чудовищной силы, поглощавшей город. Большинство – но не Койеми.","Боец",[],["Шурима"],"ОБЫЧНОЕ"],"06SH034":["Власть","Призвав меня, призовите случайную Оболочку.\nПризывая союзника стоимостью 1, даруйте ему +1|+0.","","Иногда сильному хочется почувствовать себя слабым.","Боец",[],["Шурима"],"ЭПИЧЕСКОЕ"],"06DE045":["Вдохновляющий свет","Даруйте союзникам Мужество.","","\"Больше не нужно скрываться! Выходите на свет и сияйте вместе со мной!\" – Люкс","Заклинание",[],["Демасия"],"ОБЫЧНОЕ"],"06DE038":["Лорд Элдред, глава охотников на магов","У других союзников и вашего нексуса есть Стойкость.\nКогда союзник выживает, получив урон, даруйте ему +1|+1.","","\"Я невольно услышал твой громкий шепот, любезная супруга. Рекомендую впредь соблюдать осторожность, обсуждая семейные дела в общественном месте. Никогда не знаешь, кто может подслушать\".","Боец",[],["Демасия"],"ЭПИЧЕСКОЕ"],"06DE037":["Королевский указ","Дайте союзнику +2|+2 и Выбор противника до конца раунда или призовите карту Почтенный лорд.","","\"Приказ будет исполнен, король Джарван. Любой ценой\". – Барретт Бювелль, почтенный лорд","Заклинание",[],["Демасия"],"РЕДКОЕ"],"06DE035":["Петрицитовый столп","ВСЕ заклинания стоят на 2 кристалла маны больше. Отсчитайте 2 раунда.","","В тюрьмах для магов устанавливают высокие петрицитовые обелиски, которые лишают сил даже самых могущественных заключенных.","Место силы",[],["Демасия"],"ОБЫЧНОЕ"],"06DE042":["Демасийские камни судьбы","Создайте в руке мимолетную карту Призматический барьер, Арест или За Демасию!.","","\"Королевский гамбит – не совсем справедливое название. Королевы тоже идут на риск!\" – Цитрия из Клаудфилда","Заклинание",[],["Демасия"],"РЕДКОЕ"],"06DE036":["Отец-дракон","Атака: вытяните бойца. Если это дракон, призовите его сразу в атаку.","","\"К счастью для нас, мои исследования наводят на мысль о том, что драконы-отцы большую часть времени охотятся вдали от гнезда. Разумеется, если бы самец вернулся, мы все стали бы драконьим обедом! Ха-ха!\" – Анден Майн, ученый-яйцевед","Боец",["ДРАКОН"],["Демасия"],"ЭПИЧЕСКОЕ"],"06DE030":["Обольщение","Призовите случайную Оболочку и даруйте ей +1|+0.","Missing Translation","\"Ближе, радость моя…\" – Эвелинн","Заклинание",[],["Демасия"],"ОБЫЧНОЕ"],"06SI012":["Гвен","Атака: когда другой союзник получает усиление Благих, я тоже его получаю. Истощите вражеский нексус на 2 ед. здоровья.","Мне удалось нанести 10+ ед. урона.","Чик-чик! Гвен прорезала черный туман, поражаясь тому, как плотно он устилал все вокруг. Когда туман распался на лоскутки, она увидела зачарованный особняк, который сиял среди блеклого леса, как маяк. Какой причудливый и великолепный! Неудивительно, что он так манил к себе Гвен!","Боец",[],["Сумрачные острова"],"Чемпион"],"06SI020":["Всплеск ненависти","Убейте союзника, чтобы нанести бойцу 3 ед. урона и, если в начале матча в вашей колоде была карта Эвелинн, призвать случайную Оболочку.","","\"Кричи сколько хочешь\". – Эвелинн","Заклинание",[],["Сумрачные острова"],"РЕДКОЕ"],"06SI013":["Вечно танцующие","Атака: оживите и отправьте в атаку эфемерную копию сильнейшего погибшего союзника, кроме карты Вечно танцующие, с силой меньше или равной моей.","","Присоединиться к танцующим проще, чем выходить первым. А вот близнецы всегда готовы подать пример другим.","Боец",[],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"06SI037":["Сумрачные камни судьбы","Создайте в руке мимолетную карту Метка Островов, Духовное путешествие или Крах.","","\"Красивые полированные фишки. Нужно изучить правила. Интересная игра. Захватывает дух. Непревзойденное искусство… незабываемое\".\n– Из найденного дневника","Заклинание",[],["Сумрачные острова"],"РЕДКОЕ"],"06SI040":["Погибельное возвращение","Воскресите сильнейшего погибшего союзного сторонника и даруйте ему Эфемерность и Устрашение. Дайте врагам -1|-0 до конца раунда.","","Призрака можно изгнать лишь на время. Они всегда возвращаются.","Заклинание",[],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"06SI027":["Сквозь игольное ушко","Убейте союзника, чтобы нанести равный его силе урон врагу.","","\"Иголки наготове!\" – Гвен","Заклинание",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"06SI018":["Глада","Призвав меня, призовите случайную Оболочку.","","В отличие от других демонов, заманивающих жертв обманом, Глада настолько одержима своим желанием, что действует максимально прямолинейно. Это не хищница, выжидающая в засаде, а обезумевший от голода зверь, которого нужно накормить немедленно.","Боец",[],["Сумрачные острова"],"РЕДКОЕ"],"06SI015":["Пусть играет оркестр!","Призовите 2 Призрачных оркестра.","","\"Живее! В темпе, в темпе!\" – Дирижер туманов","Заклинание",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"06SI030":["Официальное приглашение","Создайте в руке копии 2 союзных сторонников, погибших в этом матче.","","\"Вот мы и прибыли, дорогая! Прием обещает быть блистательным! Не сомневаюсь, мы встретим здесь множество знакомых\". – Призрачный гость","Заклинание",[],["Сумрачные острова"],"РЕДКОЕ"],"06SI026":["Дирижер туманов","Предсмертный вздох: создайте в руке карту Призрачный оркестр.","","\"Играйте, друзья! Пусть это будет самый веселый концерт в истории!\"","Боец",[],["Сумрачные острова"],"РЕДКОЕ"],"06SI033":["Гробница с призраками","Отсчитайте 2 раунда и оживите своего сильнейшего погибшего союзника.","","Меч ударял о щит с погребальным звоном, созывая призраков, чья связь с миром еще не вполне оборвалась, чью волю не сломила и не стерла даже смерть.","Место силы",[],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"06SI016":["Веселый хозяин","","","\"РАДЫ ПРИГЛАСИТЬ вас на событие века – ПОЛНОЧНЫЙ БАЛ. В ФАРФОРОВОМ ПОМЕСТЬЕ вас ждут напитки, угощение, танцы и другие приятные вещи. Праздник продлится ровно до часа ночи\".\n– Приглашение, написанное от руки изящным почерком","Боец",[],["Сумрачные острова"],"РЕДКОЕ"],"06SI028":["Призрачный дворецкий","","","Что за званый вечер без изысканного угощения?","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"06SI043":["Фантомная флора","Выбросьте из колоды 3 карты.\nИстощите бойца на 2 ед. здоровья.","","На суровых Сумрачных островах старые побеги находят новое применение.","Заклинание",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"06SI022":["Призрачный кавалер","","","Был ли он призраком, сном, воспоминанием? В любом случае, было в его облике что-то знакомое.","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"06SI019":["Сультур","Призвав меня, призовите случайную Оболочку.","","\"Остерегайся тех обитателей этих призрачных островов, которые способны улыбаться. Быть может, они оказались здесь недавно и еще не осознали всей жестокости этого места. Может, они сошли с ума. А может – ни то, ни другое. В любом случае, остерегайся\".\n– Из записок Йенса Томмена","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"06NX022":["Легионерский призыв","Вытяните союзника с силой 5 либо увеличьте силу союзника до 5 до конца раунда.","","\"Немногим выпадает возможность служить в Трифарианском легионе. Не упустите свой шанс\". \n- Трифарианский инспектор","Заклинание",[],["Ноксус"],"ЭПИЧЕСКОЕ"],"06NX019":["Ноксианский дезертир","Атака: увеличьте мою cилу до показателя сильнейшего снаряженного союзника до конца раунда.","","\"Снова видел эти грезы, слышал тот голос из тьмы. Десять лет... Десять треклятых лет я прожил послушным псом империи. Пойди туда, убей вон того... И чего ради? Ради славы Ноксуса? Слава – изрядная обманка, и я на нее купился. Хватит с меня. Каин показал мне иной путь – и ведет он к отмщению\".\n- Ройс, дневник Мясника","Боец",["КУЛЬТИСТ"],["Ноксус"],"ОБЫЧНОЕ"],"06NX023":["Ионийская удильщица","Призвав меня, посмотрите, как я применяю Импровизацию.","","Жизнь Триск перевернулась с ног на голову, когда она в последний раз – как ей тогда казалось – участвовала в состязании по рыбной ловле. Тогда ей случилось выудить барахтающегося Джакса. Сам он отказывается обсуждать тот случай, однако морское чудовище, от которого его спасла Триск, становится все больше с каждым ее пересказом той истории.","Боец",["МАСТЕР ОРУЖИЯ"],["Ноксус","Иония"],"ОБЫЧНОЕ"],"06NX044":["Закулисный кукловод","Атака: увеличьте силу остальных атакующих союзников до моего значения до конца раунда.","","\"Хорошая мать учит своих деток охотиться. Но идеальная мать... Она устраивает для деток охоту\". - Элиза","Боец",["ПАУК"],["Ноксус"],"ОБЫЧНОЕ"],"06NX041":["Алый голубь","Поддержка: нанесите 1 ед. урона союзнику, которого я поддерживаю, чтобы дать мне +1|+1 до конца раунда.","","\"Кормление птиц – недурная забава. Я заключил пари с беднягой Феовардом, что кровь они отведают так же охотно, как бордентский василиск. А теперь полюбуйтесь – эти голуби явно из Ноксуса!\" - Эдвин Кортейн, Алый хранитель","Боец",["ПТИЦА"],["Ноксус"],"ЭПИЧЕСКОЕ"],"06NX020":["Баллиста даркинов","Вы можете потратить 8 ед. маны, чтобы сыграть меня в виде карты Наганика из Зуретты.","","Степи на востоке Валорана были известны своей пустынностью. Там ноксии не могли найти ни кров, ни пищу. Но по прошествии веков там была основана новая империя, жаждавшая разрастись. Благодаря новым методам земледелия целинная почва стала плодородной – и оружие, считавшееся надежно захороненным, вновь увидело свет.","Снаряжение",["ДАРКИН"],["Ноксус"],"ЭПИЧЕСКОЕ"],"06NX039":["Разгульный пир","Нанесите одному союзнику 2 ед. урона, чтобы дать всем союзникам +2|+0 до конца раунда.","","\"Пиршество – не пиршество, пока никто не вопит. Так что вопи, мальчик\". - Владимир","Заклинание",[],["Ноксус"],"ОБЫЧНОЕ"],"06NX026":["Великие молоты","","","Вессида нельзя назвать быстрейшим из уравнителей Бордента, но когда его великие молоты добираются до цели, от противника в драке остается не так уж и много.","Снаряжение",[],["Ноксус"],"ОБЫЧНОЕ"],"06NX034":["Яростный повелитель","Снаряженный союзник наносит удар врагу.","","\"Братья по крови – снова вместе!\" - Ноксианский дезертир","Заклинание",["КУЛЬТИСТ"],["Ноксус"],"РЕДКОЕ"],"06NX036":["Руновладелец","Призвав меня, используйте Перековку.","","Много месяцев подряд он пробивался сквозь холод и дождь – неблагодарное дело, конца которому не было видно. Но конец все же настал. В итоге ему предстояло добиться успеха.","Боец",[],["Ноксус"],"ОБЫЧНОЕ"],"06NX027":["Ожесточенная стычка","Разрушьте снаряжение врага. Союзник и этот враг наносят удар друг другу.","","\"Один-два-три, чей слышен крик?\nСъело солдатика пламя.\nЧетыре и пять, идем мы гулять\nС Тибберсом между кострами!\" - Энни","Заклинание",[],["Ноксус"],"РЕДКОЕ"],"06MT035":["Золаани, Кровавая ткачиха","У меня +2|+2 за каждого союзника, погибшего с увеличенной силой.\nУкрепление от 16: превратите меня в карту Золаани, Гроза Сущностей.","","Золаани продолжала наблюдать, как Анаакко ползает на коленях, подчинившись тому самому врагу, которого он так безнадежно мечтал стереть с лица земли. Ритм его сердцебиения понемногу зазвучал в унисон с остальными. Еще одно сердце в подчинении. Еще одно тело под командой.","Боец",["ДАРКИН"],["Таргон"],"ЭПИЧЕСКОЕ"],"06MT007":["Серафическая виверна","Укрепление от 5: Пробивание.","","\"А, теперь понятно... Те контуры на горе – наверняка отпечатки. То есть ходы для существ, явившихся из измерения дальних звезд...\" - Хранитель преданий Скей'ен","Боец",["ДРАКОН"],["Таргон"],"РЕДКОЕ"],"06MT037":["Стальной каземат","Уничтожьте союзника и создайте карту Поврежденная форма с его характеристиками.","","Не так-то просто было одолеть падших богов-воителей, заточенных внутри оружия, поэтому было решено их сдерживать.","Заклинание",[],["Таргон"],"РЕДКОЕ"],"06MT031":["Михира, Сущность правосудия","Конец раунда: даруйте союзникам на поле боя и в руке +1|+1.\nУкрепление от 5: Изворотливость, Вампиризм и Пробивание.","","\"Одни почитают Сущности наравне с богами. Другие видят в них вестников из запредельных миров. Третьи боятся их... и пожалуй, правильно делают\". - Хранитель преданий Скей'ен","Боец",[],["Таргон"],"ЭПИЧЕСКОЕ"],"06MT010":["Божественный приговор","Дайте союзнику особенность \"Я не получаю урон и не умираю\" до конца раунда.\nДайте всем союзникам +1|+0 до конца раунда.","","\"Под защитой праведного пламени!\" - Кейл","Заклинание",[],["Таргон"],"РЕДКОЕ"],"06MT016":["Крылатый вестник","Укрепление от 3: Изворотливость.","","\"Да... Я узнаю тебя. Весть, которую ты несешь... Это может быть только призыв\". - Райз","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"06MT015":["Очищающее пламя","Даруйте 2 союзникам в руке +2|+2.","","\"Зло канет в огне!\" - Кейл","Заклинание",[],["Таргон"],"ОБЫЧНОЕ"],"06MT042":["Покровительница сумерек","День: дайте дневным союзникам +1|+1 до конца раунда.\nНочь: даруйте ночным союзникам +1|+0.","","В час сумерек и прямо перед рассветом слышен голос совы. Ее зов напоминает о пограничных мгновениях между тьмой и зарей.","Боец",["ПТИЦА"],["Таргон"],"РЕДКОЕ"],"06MT008":["Кейл","У меня +1|+0 каждый раз, когда союзник атакует с увеличенной силой.\nПризвав меня, даруйте союзникам +1|+0.\nУкрепление от 6: Быстрая атака.","Начало раунда: у меня 11+ ед. силы.","\"Демасийцы знают ее под именем Крылатой Защитницы, но те из нас, кто живет под звездным куполом на Таргоне, знают ее как дочь Справедливости, ведающую божественный замысел и несущую меч из звездного огня\". - Хранитель преданий Скей'ен","Боец",[],["Таргон"],"Чемпион"],"06MT004":["Странствующий пастух","Разыгрывая карту: выберите союзника, чтобы тот применил Импровизацию. В противном случае посмотрите, как я применяю Импровизацию.","","Джакс помог Часке спасти стадо от разъяренных созданий. А затем уже Часке пришлось спасать Джакса от разъяренных созданий. Они путешествуют вместе, куда бы любого из них ни занесло.","Боец",["МАСТЕР ОРУЖИЯ"],["Таргон","Бандл Сити"],"ОБЫЧНОЕ"],"06MT017":["Высший клирик","Укрепление от 3: Вампиризм.","","\"Говорят, когда Михира покинула здешние места, она оставила частицу себя – ярко пылающее священное пламя. Многие годы мое семейство поддерживало этот огонь, чтобы он горел и дарил надежду на ее возвращение\".","Боец",[],["Таргон"],"РЕДКОЕ"],"06MT040":["Покровительство простора","Если вы в этом матче снаряжали союзника, моя стоимость снижается на 2.\nДайте союзнику Щит от магии до конца раунда.","","Посмотри в ночное небо и найди взглядом маленькую полоску тверди. Теперь представь себе всех тех, кто жил в ее пределах, все накопленные там знания и весь опыт, прошедший сквозь бесчисленные тысячелетия. Представь себе всю информацию, сжатую в одном осколке, который можно уместить в твоей ладони. Подумай о том, сколько мудрости будет тогда у тебя в руках. И сколько силы.","Заклинание",["КУЛЬТИСТ"],["Таргон"],"РЕДКОЕ"],"06MT034":["Небесный таран","Уничтожьте бойца или место силы. Восстановите 3 ед. здоровья вашему нексусу.","","\"Кто явится в наш горестный час?\" - Шуримский старец","Заклинание",[],["Таргон"],"РЕДКОЕ"],"06MT033":["Драконьи ленты","Мой носитель становится Драконом.","","Многие полагаются на мощь драконов, хотя в различных частях Рунтерры она проявляется по-разному. Заручившиеся поддержкой небесного дракона могут обнаружить, что те обладают внутренней силой, которая пылает ярко и жарко, словно звезда.","Снаряжение",[],["Таргон"],"ОБЫЧНОЕ"],"06MT053":["Щедрая самоцветница","Разыгрывая заклинание, даруйте случайному союзнику в руке +1|+1.","","Глядя беззлобно, но пряча лицо под покровом ткани, она предлагает хрустальные четки тем, кто готовится отправиться в паломничество. Взамен она не просит ничего, ибо цена будет возмещена на самой Горе.","Боец",[],["Таргон"],"ЭПИЧЕСКОЕ"],"06MT006":["Магнит даркинов","Поддержка: даруйте союзнику, которого я поддерживаю, +1|+1.\nВы можете потратить 8 ед. маны, чтобы сыграть меня в виде карты Хорази.","","Возможно, те, кто заключил даркинов в темницу, думали, что если спрятать легендарную воительницу Хорази внутри сферы из звездного металла, то это наверняка притушит ее вспыльчивый нрав. Но стоило пробудиться ее генералу, как то же случилось и с Хорази, которая обнаружила, что даже древние покровители Таргона поддаются искусам обещаний, нашептанных далекими голосами.","Снаряжение",["ДАРКИН"],["Таргон"],"ЭПИЧЕСКОЕ"],"06MT018":["Законодержец","Разыгрывая карту: оглушите врагов, чья сила меньше моей.","","\"Боюсь, что этот день наконец настал... Справедливость возвращается на златых крыльях – и сияющее войско с нею!\" - Хранитель преданий Скей'ен","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"06MT052":["Благословение небес","Даруйте союзнику на поле боя и союзнику в руке Мужество.","","\"Милостью божества\". - Кейл","Заклинание",[],["Таргон"],"ОБЫЧНОЕ"],"06MT032":["Культистка Лунари","Когда меня призывают либо как только вы снарядили союзника в этом матче, создайте в руке карту Самоцвет.","","Дни и ночи напролет она искала способ положить конец конфликту между Солнцем и Луной. Лук давал ей силу, но доставалась та ужасной ценой. Но она дала зарок довести дело до конца – в надежде, что это остановит войну раз и навсегда. ","Боец",["КУЛЬТИСТ"],["Таргон"],"ОБЫЧНОЕ"],"06RU008":["Джакс","Исток: Великий мастер оружия.\nАвто-снаряжение: Свет Икатии.","Снаряженные союзники атаковали с суммарным значением силы 16+.","Много веков назад родина Джакса досталась Бездне. Теперь он бродит по свету, собирая воинов с силой воли и неутоленной обидой, чтобы однажды выступить против жуткого врага.","Боец",["МАСТЕР ОРУЖИЯ"],["Рунтерра"],"Чемпион"],"06RU006":["Райз","Исток: Рунный маг.\nПризвав меня или в начале раунда: создайте в вашей колоде 2 карты Экскурс в прошлое.","Я вижу 3+ уникальные Мировые руны.","Райз взобрался на горный хребет в сопровождении молчаливой слуги Кейл. Он смотрел вниз, на земли, обезображенные войной, и заметил чудовищных даркинов, бившихся у подножья горы. Вот уже много веков он наблюдал, как человечество бредет от одной катастрофы к другой. Он подумал: а что если усилия бесполезны? Что если Рунтерра обречена на гибель?","Боец",[],["Рунтерра"],"Чемпион"],"06RU005":["Каин","Исток: Сумеречный жнец.\nАвто-снаряжение: Коса даркинов.\nКогда я убиваю врага, восстановите мне 2 ед. здоровья.","Я нанес удар дважды. Верните меня после того, как мой уровень повысится.","Когда рухнуло очередное тело, Каин радостно рассмеялся, так как знал, что вскоре он пустит в ход второе оружие даркинов, спрятанное в глубине. Между тем внутри него росло предвкушение Рааста, понимавшего, что гибель Каина уже очень близка.","Боец",["ДАРКИН"],["Рунтерра"],"Чемпион"],"06RU026":["Атрокс","Исток: Губитель миров.\nАвто-снаряжение: Клинок даркинов.\nПризвав меня или когда я наношу удар: восстановите 2 ед. здоровья вашему нексусу и создайте в руке карту Губитель миров, если у вас ее нет.","Вы сыграли карту Губитель миров.","Даже находясь на другом материке, Атрокс почувствовал ее пробуждение. Как же воспылала его ненависть! Он уже разбил все ее изваяния, теперь же он мог развязать последнюю войну против Трусливой души Икатии. Он мог уничтожить ее и тем самым положить конец этой жалкой вселенной.","Боец",["ДАРКИН"],["Рунтерра"],"Чемпион"],"06RU009":["Варус","Исток: Стрела возмездия.\nАвто-снаряжение: Лук даркинов.","Вы выбрали целью 7+ союзников.","Что если со временем тот, кто стал даркином, начнет вспоминать себя, наслушавшись смертных голосов внутри? Что если вместо полного подавления этих голосов, он начнет в них верить?","Боец",["ДАРКИН"],["Рунтерра"],"Чемпион"],"06FR004":["Ученица оружейника","Впервые снарядив союзника, примените к нему Кузницу.","","Много-много лет тому назад Орн создал живую кузницу – и лишь недавно отправился ее проведать. До этого он и не думал, что та может уйти на поиски нового владельца, плутая сама по себе.","Боец",[],["Фрельйорд"],"ОБЫЧНОЕ"],"06FR011":["Орн","Разыгрывая карту: снарядите меня точной копией снаряжения союзника или сильнейшим снаряжением из руки.\nАтака: дважды примените ко мне Кузницу.","Союзник нанес удар на 8+ ед. урона за один удар.","Спроси кто Орна, почему у того так мало терпения, он бы услышал простой ответ: терпения, мол, полно. На самом деле его терпение было колоссальным – вот почему работал он непревзойденно. Просто его терпения не хватало на ЛЮДЕЙ. Однако никто так и не спросил. Поэтому Орн ничего и не отвечал.","Боец",[],["Фрельйорд"],"Чемпион"],"06FR035":["Помощь близко","Дайте союзнику +0|+3 до конца раунда. Если он ранен, вместо этого дайте ему +2|+3.","","\"Не волнуйся, малыш поро. Я с тобой!\" - Браум","Заклинание",[],["Фрельйорд"],"ОБЫЧНОЕ"],"06FR034":["Безжалостный холод","Заморозьте сильнейшего врага. Если вы в этом матче снаряжали союзника, скопируйте меня.","","Анаакка двигалась с такой скоростью, что казалось, будто весь Фрельйорд летит за ней вслед. Те, кто выживал в устроенной ею бойне, вскоре чувствовали, как их кожа леденеет, а сердца замирают.","Заклинание",["КУЛЬТИСТ"],["Фрельйорд"],"ОБЫЧНОЕ"],"06FR018":["Копье даркинов","Атака: даруйте двум верхним бойцам в вашей колоде +1|+1.\nВы можете потратить 8 ед. маны, чтобы сыграть меня в виде карты Анаакка.","","\"Ратная мать, хватка зимы окрепла. Аваросан покинули заставы. На севере – море... У нас один путь – на восток\".\n\"Не слушай его, ратная мать. На том пути ждут Бледноликие, а в конце него – шепчущие дебри. Как по мне – лучше умереть, чем идти в те проклятые земли\".\n\"Как же вам повезло, что никто из вас не должен решать судьбу моего народа\".\n\"Воистину, ратная мать. Однако возможен и третий путь. Разреши мне отбыть на восток. Лучше потерять во тьме одного разведчика, чем целый народ\".\n- Ратная мать Седжуани на совете с генералами","Снаряжение",["ДАРКИН"],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"06FR012":["Избранный мастеровой","Призвав меня, создайте в руке карту Время и упорство.","","\"Об Орне мне рассказывала мать, а ей – ее мать, а той – ее мать... Теперь и я тебе расскажу. Внимательно слушай. Не перебивай. Давным-давно по ту сторону огромного, горячего, бурливого моря...\"","Боец",[],["Фрельйорд"],"ОБЫЧНОЕ"],"06FR005":["Кузница Орна","Призвав меня или в начале раунда: создайте в руке мимолетную карту Время и упорство.","","Уединенно жить в кузнице Сердца Горы, слыша лишь ленивое журчание расплавленной реки да звяканье Молотом о наковальню?.. Такое ему по нраву.","Место силы",[],["Фрельйорд"],"РЕДКОЕ"],"06FR040":["Страж племен","Призвав меня, даруйте союзникам +1|+1 за каждый отдельный подтип, призванный в ходе матча.","","\"...И было, значит, такое БОЛЬШОЕ создание, которое заботилось обо всех-всех-всех МАЛЮСЕНЬКИХ созданиях...\" - Ингвар младшая","Боец",[],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"06FR020":["Разрыв","Нанесите 1 ед. урона ВСЕМУ либо разрушьте снаряжение бойца.","","Холод не щадит никого и ничего.","Заклинание",["СТИХИЯ"],["Фрельйорд"],"РЕДКОЕ"],"06FR027":["Шерстистый улиткопотам","Укрепление от 8: Восстановление.","","Хотя обычно тролли не блещут интеллектом, они могут быть на удивление сообразительными.","Боец",[],["Фрельйорд"],"РЕДКОЕ"],"06FR032":["Дар Огненной Крови","Исцелите свой нексус на 4 ед. здоровья и даруйте +1|+1 всем союзникам и снаряжению в своей колоде. Вытяните 1 из этих карт.","","\"Подходи погреться у огня\". - Починщик Огненной Крови","Заклинание",[],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"06FR022":["Дыхание мехов","Примените к союзнику Кузницу и нанесите 1 ед. урона ВСЕМ бойцам, затем сделайте это снова.","","\"Железную волю нужно ковать!\" - Орн","Заклинание",["СТИХИЯ"],["Фрельйорд"],"РЕДКОЕ"],"06FR021":["Капризный поро","Укрепление от 3: Пробивание, Восстановление и Стойкость.","","\"Ну-ка давай-ка, лекарство надо скушать! Не скушаешь – не поправишься!\" - Ингвар младшая","Боец",["ПОРО"],["Фрельйорд"],"ОБЫЧНОЕ"],"06FR023":["Литой колосс","Впервые снарядив меня, создайте в руке мою копию стоимостью 4. Даруйте ей характеристики снаряжения.","","Хотя Орн никогда в этом не признается, но ему очень понравились колоссы. Они выполняли именно то, что он им приказал, а самое главное – не разговаривали.","Боец",[],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"06FR008":["Починщик Огненной Крови","Разыгрывая карту: дважды примените к союзнику Кузницу и восстановите ему и своему нексусу по 3 ед. здоровья.","","Весь народ Огненной Крови сгинул, и Орн решил оставить этот мир. Сменялись поколения, и имя народа почти забылось. Однако недавно сказания об Орне зазвучали вновь. Поговаривают, что некоторые начали возвращаться на путь Огненной Крови.","Боец",[],["Фрельйорд"],"ОБЫЧНОЕ"],"06FR009":["Умелый оружейник","Разыгрывая карту: примените к союзнику Кузницу.","","Когда Фиск впервые задумался о том, чтобы взять ученика, он представлял себе кого-то прилежного, преданного ремеслу, дюжего и умелого. Киндра не подходила ни по одному пункту. Она только и делала, что витала в эмпиреях. Работе она предпочитала игры. Она вечно возилась с этой своей глупой черепашкой. И тем не менее... она училась. Это было важнее всего.","Боец",[],["Фрельйорд"],"ОБЫЧНОЕ"],"06FR024":["Костяная дубина","","","\"Хрясь!\" - Тарказ Бесплеменный","Снаряжение",[],["Фрельйорд"],"ОБЫЧНОЕ"],"06FR017":["Культист ледяной долины","У снаряженных союзников есть Пробивание.","","Люди Когтя Зимы оказались правы. Аваросан были слишком мягки. Пора было найти нового предводителя – человека, который не пытался бы объединить Фрельйорд мирным путем, а возглавил бы его. ","Боец",["КУЛЬТИСТ"],["Фрельйорд"],"РЕДКОЕ"],"06FR041":["Прикосновение зимы","Получите пустой кристалл маны. Просветление: моя стоимость равна 1. Вытяните 1 карту.","","Грани самоцвета, лежащего в вашей ладони, пульсируют странными руническими рисунками. Их отсвет призрачной вспышкой поднимается над поверхностью камня, обвиваясь вокруг руки холодящим вихрем. Но этот холод не обмораживает, а придает сил – будто бы наполняя вас своим естеством. ","Заклинание",["СТИХИЯ"],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"06FR036":["Необузданная магия","Получите пустой кристалл маны.\nПризовите карту Одичавший маг.","","\"Призраки и звезды... Они снова свели нас вместе\".\n- Хиара Всевидящая","Заклинание",[],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"06BC015":["Норра","Удар по нексусу: прикрепите Таинственный портал к 1 из 4 верхних карт в своей колоде.","Вы призвали 6+ созданных союзников.","Норра принялась работать споро, мыслями она была уже дома. Создание порталов было делом еще каким тонким – а ведь она даже первую чашку чая не успела допить. Однако Норра любила хорошие головоломки – особенно в тех случаях, когда она оказывалась в каком-нибудь пространственном кармане вне времен и измерений безо всякой надежды на помощь. Она работала все быстрее, с теплотой вспоминая свою кошечку: та наверняка волнуется и ждет, когда ее покормят.","Боец",["ЙОРДЛ"],["Бандл Сити"],"Чемпион"],"06BC043":["Истории о поро","Создайте в руке 3 случайных поро стоимостью 1.","","\"...И ТУТ ЭТОТ ПОРО ТАКОЙ: \"ЭЙ ВЫ, Я ТОЖЕ СНЭКА ХОЧУ!\", И ВСЕ ПОРО СОБРАЛИСЬ ВМЕСТЕ НА БОЛЬШУЩИЙ СОВЕТ, СТАЛИ ОБГОВАРИВАТЬ ИХНИЕ ПОРОВСКИЕ ВОПРОСЫ – ПРО ТО, ГДЕ ДОБЫТЬ СНЭК, ПРО ТО, ПОЧЕМУ КРУГОМ БОЛЬШЕ НЕТ ПОРО, И ТУТ...\" - Ингвар младшая","Заклинание",[],["Бандл Сити"],"ОБЫЧНОЕ"],"06BC051":["Банановый подрывник","Разыгрывая карту: нанесите бойцу урон, равный моей cиле.","","\"ЭЙ! КОМУ-НИБУДЬ НУЖЕН КАЛИЙ?\" - Наннерс, за считанные секунды до того самого \"инцидента\" ","Боец",["ЙОРДЛ"],["Бандл Сити"],"РЕДКОЕ"],"06BC047":["Разделяшки","Дайте союзнику с прикреплением характеристики и навыки его прикрепления до конца раунда и перенесите прикрепление на другого союзника.","","Вы могли решить, что пастуху не место на поле боя, однако его навыки там на удивление полезны. Достаточно лишь думать, будто все сражающиеся – это овцы, которых нужно согнать в стадо.","Заклинание",["МАСТЕР ОРУЖИЯ"],["Таргон","Бандл Сити"],"РЕДКОЕ"],"06BC019":["Чайный мастер","Призвав меня, прикрепите Таинственный портал к 1 из 4 верхних карт в своей колоде.","","Прежде чем очутиться на Мировом пределе, Ашейн была известным чайным мастером. Во время эксперимента с новыми сортами неудачное сочетание двух из них погрузило ее в глубокий сон. Ей привиделись странные грезы о причудливых существах и неправдоподобных постройках на фоне бесконечно далекого горизонта... Когда же Ашейн проснулась, то обнаружила, что это был вовсе не сон.","Боец",["ФАЭ"],["Бандл Сити"],"ОБЫЧНОЕ"],"06BC029":["Посох даркинов","Удар: восполните 1 ед. маны заклинаний.\nВы можете потратить 8 ед. маны, чтобы сыграть меня в виде карты Баалкукс.","","Бандловый лес идеален для того, чтобы спрятать оружие даркинов. Так уж они рассудили. Природа бандлового леса такова, что в нем нельзя отыскать дорогу, а йордлы умеют держаться подальше от зловредных кладов. Но таргонцы не учли эффективность столь странной магии и то действие, которое она может оказывать на местную флору.","Снаряжение",["ДАРКИН"],["Бандл Сити"],"ЭПИЧЕСКОЕ"],"06BC038":["Внезапный всплеск","Если вы в этом матче снаряжали союзника, моя стоимость снижается на 2. Увеличьте характеристики союзника до 4|4 до конца раунда.","","\"Внутри нас столько cилы\". - Варус","Заклинание",["КУЛЬТИСТ"],["Бандл Сити"],"РЕДКОЕ"],"06BC017":["Портальное раздолье","Прикрепите Таинственные порталы (2) к 4 верхним картам в своей колоде. Вытяните 1 карту.","","\"Мне стоит почаще ходить по Тайным тропам! Вот я глупая, вечно забываю, что надо беречь голову...\"\n- Норра","Заклинание",[],["Бандл Сити"],"РЕДКОЕ"],"06BC020":["Резак оригами","Дайте мне +1|+0 за каждую ловушку или поощрение, активированное в этом раунде.","","Магия бумажных фигурок может оказаться непредсказуемой. Тут все дело не только в замысле создания чего-то нового, но и в желании создаваемого принять свою форму.","Снаряжение",[],["Бандл Сити"],"РЕДКОЕ"],"06BC028":["Расцветший культист","Если вы в этом матче снарядили союзника, даруйте мне Изворотливость.","","Человек, растение, животное... Скверна даркинов не щадит никого и ничего.","Боец",["КУЛЬТИСТ"],["Бандл Сити"],"ОБЫЧНОЕ"],"06BC021":["Утильное создание","Предсмертный вздох: прикрепите Таинственный портал к 1 из 4 верхних карт в своей колоде.","","Марв – как его ласково прозвала Норра – родился только вчера и должность ее помощника счел немалой честью. При этом он твердо настоял на том, чтобы его звали словом \"утиль\" – но никак не словом \"хлам\". Второе для него звучало слишком обидно.","Боец",["ФАЭ"],["Бандл Сити"],"ОБЫЧНОЕ"],"06BC042":["Любопытные подменыши","Когда союзный сторонник превращается в другого сторонника, превратите меня в его точную копию.","","Что вижу, тем и стану.","Боец",[],["Бандл Сити"],"РЕДКОЕ"],"06BC023":["Головоломные указатели","Верните в руку быстрое или медленное заклинание либо разрушьте снаряжение бойца. Вытяните 1 карту.","","\"Да что ж такое! Тут надо было вот так? Или эдак? Или... как-то так и эдак? Никак не запомню!\" - Норра","Заклинание",[],["Бандл Сити"],"РЕДКОЕ"],"06BC041":["Запчастилище Скрэппи","Когда я попадаю в сброс, призовите меня. Призывая йордла-пилота, даруйте ему случайный навык.","","Если хотите найти какую-нибудь штуковину — большую или маленькую, неодушевленную или живую – то обращайтесь к Скрэппи! Только не спрашивайте Скрэппи, откуда берутся эти штуковины, потому что она не сторонник каталогов.","Место силы",[],["Бандл Сити"],"РЕДКОЕ"],"06BC011":["Волшебное путешествие","Прикрепите Таинственный портал к 1 из 4 верхних карт в своей колоде и прикрепите Колокольчик к верхней карте в своей колоде.","","Перемещаясь между разными мирами по своему хотению, Бард прислушивается, ибо он знает, что близится великая схватка, способная заглушить песнь творения.","Заклинание",[],["Бандл Сити"],"ОБЫЧНОЕ"],"06BC032":["Пестрая коллекция","Для каждого союзника прикрепите Таинственный портал и 3 Колокольчика к 10 верхним картам в своей колоде, а также прикрепите карту Световая бомба и 3 Ядовитых гриба в колоде противника.","","\"Порталы, всюду порталы!\"\n- Норра","Заклинание",[],["Бандл Сити"],"ЭПИЧЕСКОЕ"],"06BC024":["Мировой смотритель","В каждом раунде, когда впервые активируется какая-либо из ваших ловушек или поощрений, дайте союзникам +1|+1 и Таран до конца раунда.","","Гаспар был первым йордлом, прибывшим к Мировому пределу. На протяжении многих лет он одиноко плутал среди извилистых троп и порталов, которые, как казалось, никуда не вели. Решив, что больше никому не стоит повторять его скитания, теперь он помогает другим заблудившимся путникам найти дорогу домой.","Боец",["ФАЭ"],["Бандл Сити"],"РЕДКОЕ"],"06BC033":["Шагающий распылитель","Чтобы сыграть, сбросьте 1 карту.","","\"Узрите! Из обломков затонувшего парома добыл я боксерскую перчатку. Из глубин города, что зовется Зауном, извлек я пружины, а в печах Демасии отыскал я металл! Воистину – так творится мир!\" - Великий Папаро","Снаряжение",[],["Бандл Сити"],"ОБЫЧНОЕ"],"06BC016":["Ожившая библиотека","Призвав меня, вытяните 1 карту, если в этом раунде была активирована одна из ваших ловушек или поощрений.","","Считая своим долгом накопление неимоверных знаний, он собирает книги разных путешественников, прошедших сквозь Мировой предел. К несчастью, все эти знания, как видно, здорово ударили ему в голову.","Боец",["ФАЭ"],["Бандл Сити"],"ОБЫЧНОЕ"],"06IO044":["Безмятежный глас небес","Призвав меня, вдвое снизьте стоимость заклинаний в вашей колоде (значение округляется вверх).","","\"Одни ищут покоя в медитации. Другие ищут мудрости в самосозерцании. Те же, кто обретает свою суть в самовыражении, в творчестве, тоже могут даровать другим покой\". - Карма","Боец",[],["Иония"],"ЭПИЧЕСКОЕ"],"06IO013":["Стиль вуджу","Дайте союзнику +2|+0 до конца раунда.\nСоздайте в руке карту Медитация.","","\"Лишь один порез из многих\".\n- Мастер Йи","Заклинание",[],["Иония"],"РЕДКОЕ"],"06IO023":["Веер даркинов","Атака: призовите атакующего бойца Дракончик.\nВы можете потратить 9 ед. маны, чтобы сыграть меня в виде карты Праа Проломщик.","","\"На мосту между мирами я уже давно ощутил присутствие тени, пульсировавшей немой яростью. Я понимал, что не стоит разыскивать ее во тьме, однако в последнее время этот пульс стал отчетливее, быстрее... Боюсь, что создания из мира призраков скоро сами начнут искать его\". - Шен","Снаряжение",["ДАРКИН"],["Иония"],"ЭПИЧЕСКОЕ"],"06IO029":["Дух вуджу","Прилив: моя стоимость снижается на 2.\nПризвав меня, вытяните заклинание.","","\"Мастер Доран верил, что в каждом оке духа вуджу кроется уникальная возможность заглянуть в самую суть человека. Но как бы я ни старалась, в линзах моего шлема видны лишь разные оттенки зеленого. В чем мой промах?\" - Луи, Ученица Дорана","Боец",[],["Иония"],"ОБЫЧНОЕ"],"06IO037":["Черное пламя","Разыгрывая карту: плените союзника. Впервые идя в атаку в каждом раунде, призывайте его атакующую эфемерную копию и отправляйте ее в атаку.","","\"Что такое одна жизнь? Лишь тень бытия. Стань частью тьмы – и живи вечно\". - Зед","Место силы",[],["Иония"],"ЭПИЧЕСКОЕ"],"06IO031":["Меч души","Прилив: моя стоимость снижается на 2.","","\"Клинок и тело\". - Мастер Йи","Снаряжение",[],["Иония"],"ОБЫЧНОЕ"],"06IO014":["Ученик вастайи","Удар по нексусу: верните меня и превратите в заклинание Ветер шимонов.","","Увидев, как в храм хлынули нападавшие, Тинг ухмыльнулся. Наконец-то выпал шанс проявить себя! Сперва Вуконг, потом Йи... Оба не оценили его талантов. Пусть другие пробуют найти себе \"учителя\"! Он был готов. Он стал Ветром шимонов. ","Боец",[],["Иония"],"ЭПИЧЕСКОЕ"],"06IO008":["Мастер Йи","Начало раунда: снизьте стоимость заклинания в вашей руке на 1; при активации прилива: даруйте +2|+0 всем союзным Мастерам Йи везде.","Союзные карты Мастер Йи нанесли 12+ ед. урона.","Мысли Мастера Йи сосредоточились на оружии даркинов. Дурное предчувствие не отпускало его с тех самых пор, как это оружие нашли. Кое-кто из учеников проявлял пылкий – слишком пылкий! – интерес, поэтому ему пришлось усилить охрану комнаты с изогнутыми клинками в недрах храма. Приложив немало усилий, он изгнал эти мысли из своего разума и продолжил медитировать. Важнее всего была преемственность учения вуджу – и Джун подавала большие надежды.","Боец",[],["Иония"],"Чемпион"],"06IO040":["Техника сдвоенного ветра","Выберите сторонника. Призовите его точную эфемерную копию. Если это враг, оглушите его.","","Самой капризной стихией у ионийцев считается ветер. Капризной – но все же приручимой. ","Заклинание",[],["Иония"],"РЕДКОЕ"],"06IO011":["Джун, Юное дарование","Впервые снарядив меня, дайте мне Щит и Вампиризм до конца раунда.","","По сигналу Джун выбросила град ударов, каждый из которых по точности не уступал ударам самого Йи. Хотя мастер ловко уклонился от атаки, он наградил ученицу поклоном, улыбнувшись не без гордости.","Боец",[],["Иония"],"РЕДКОЕ"],"06IO015":["Свидетельница","Прилив: моя стоимость снижается на 2.\nРазыгрывая карту: оглушите врага.","","Какова ее роль в этом странном и жутком представлении? Ах, она нечто большее, чем публика. Она – наблюдательница, линза, сквозь которую проходят все вещи и которой поверяются истина и красота. Свидетельница!","Боец",[],["Иония"],"ОБЫЧНОЕ"],"06IO030":["Туманная падь","Призвав меня, вытяните снаряжение.\nВ каждом раунде, когда союзник без снаряжения впервые снаряжается, восполните 2 ед. маны заклинаний.","","\"Туманная падь – святая земля. Мечи на этом месте находятся уже много веков... И я верю, что тот, кто оставит здесь клинок с начертанными на рукояти виршами, созовет духов павших воинов, чтобы те наделили его своим благословеньем\".\n- Ученица Дорана, рукописный свиток","Место силы",[],["Иония"],"РЕДКОЕ"],"06IO034":["Судьбоносный выбор","Если вы в этом матче снаряжали союзника, моя стоимость снижается на 1.\nДайте союзнику +2|+0 или +0|+2 до конца раунда.","","Когда Джун оглядела разбросанные по земле тела, по ее лицу потекли слезы гнева. Она подвела их. Она подвела учителя. Теперь оставался единственный выбор…","Заклинание",["КУЛЬТИСТ"],["Иония"],"РЕДКОЕ"],"06IO028":["Завораживающая приманка","Дайте союзнику Выбор противника до конца раунда. Если он снаряжен, вытяните 1 карту.","","На правильную наживку клюнет кто угодно.","Заклинание",["МАСТЕР ОРУЖИЯ"],["Иония","Ноксус"],"РЕДКОЕ"],"06IO025":["Фанатик Клинка тени","Как только вы снарядили союзника в этом матче, создайте в руке карту Зловещая тень.","","Во тьме он видел его – оружие, разрезающее тени. И в этот миг он услышал, как его зовет далекий, но властный голос. Он шагал на голос и пришел к Каину, ведомый истиною его слов.","Боец",["КУЛЬТИСТ"],["Иония"],"ОБЫЧНОЕ"],"06IO039":["Хвостатик из Навори","Разыгрывая карту: призовите карту Грабитель из Навори или дайте другим союзникам +1|+1 до конца раунда.","","Хвостатик сдружился с Грабителем одним зимним вечером, когда обоим пришлось греться у недотушенного костра. В течение следующей недели эти двое выяснили, что разделяют одну и ту же тягу к проказам, а также явный интерес к золотому блеску монет.","Боец",[],["Иония"],"ОБЫЧНОЕ"],"06IO032":["Недостойная душа","Прилив: моя стоимость снижается на 2.\nВерните бойца или место силы. Если у него есть прикрепления, сперва разрушьте их.","","\"Ты не достоин той силы, которой обладаешь\". - Рааст","Заклинание",[],["Иония"],"РЕДКОЕ"],"06IO001":["Ученица Дорана","Призвав меня, создайте в руке карту Подготовка.","","\"Чтобы стать продолжательницей этого священного искусства, я впитала всю мудрость, какую только могла. Что касается Дорана, и его наставника, и наставника, который был до того... Надеюсь, их духи направят мой молот\".\n- Ученица Дорана, рукописный свиток","Боец",[],["Иония"],"ОБЫЧНОЕ"],"06IO016":["Драконий кликун","Начало раунда: Прилив: призовите карту Эмпиреец и даруйте ей эфемерность.","","\"Форма воды есть отражение формы твоих желаний. Скажи мне, странник... что ты видишь?\"","Боец",[],["Иония"],"ЭПИЧЕСКОЕ"],"06PZ034":["Хексничтожитель","Нанесите бойцу 6 ед. урона. Если он погибнет, вместо этого уничтожьте его.","","Для некоторых созданий одной смерти недостаточно.","Заклинание",[],["Пилтовер и Заун"],"РЕДКОЕ"],"06PZ006":["Выход на бис","Создайте в руке случайное новое заклинание стоимостью 2, снизьте его стоимость на 2 и даруйте ему Мимолетность.","","Ничто не сравнится с мощным ревербератором.","Заклинание",[],["Пилтовер и Заун"],"РЕДКОЕ"],"06PZ021":["Серафина","Призвав меня, создайте в руке случайное новое заклинание стоимостью 2.","Вы сыграли 9+ новых заклинаний.","Серафина никогда не обсуждала с отцом свои тайные отлучки в Нижний город – как и те тонкие улучшения, что она вносила в свои инструменты. Она была уверена, что он запретит ей выступать в самом неприглядном музыкальном конкурсе Зауна. Но однажды вечером он сам подсунул рекламную листовку ей под дверь. Серафина сумела лишь улыбнуться – и вновь принялась за работу.","Боец",[],["Пилтовер и Заун"],"Чемпион"],"06PZ040":["Злачное местечко","Призвав меня, призовите карту Хозяин злачного местечка.\nСтоимость ваших новых карт снижается на 1.","","Протерев последний бокал, хозяин бара успел окинуть взглядом свое заведение. В этом зале, который был для него вторым домом, многие незнакомцы стали друг другу друзьями, а стены были покрыты рисунками и вмятинами – следами бурных вечеринок. Хозяин невольно улыбнулся. Это место не было лучшим в мире, но зато принадлежало ему.","Место силы",[],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"06PZ008":["Арфа даркинов","Вы можете потратить 8 ед. маны, чтобы сыграть меня в виде карты Стайраату.","","Пока таргонцы пытались сообразить, где им разбросать оружие с даркинами, один из них предложил местность, которая позже станет известной как Заун. Захоронить оружие в скальных стенах извилистых ущелий казалось идеальным выбором. Подальше от людей... Но не от щебетунов.","Снаряжение",["ДАРКИН"],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"06PZ018":["Высокая нота","Нанесите бойцу 2 ед. урона. Если в этом матче вы разыграли 6+ других новых заклинаний, нанесите 1 ед. урона еще одному бойцу.","","Просто и чисто.","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"06PZ014":["Глава фан-клуба","Разыгрывая карту: воплотите заклинание стоимостью 5 и сделайте его стоимость равной 2.","","\"Дело не в громкости голоса, дело в умении вложить все сердце!\" - Глава фан-клуба","Боец",[],["Пилтовер и Заун"],"РЕДКОЕ"],"06PZ030":["Гениальная задумка","Атака: создайте в руке новое заклинание стоимостью 2 и даруйте ему Мимолетность.","","\"Слышишь, милая, как будто дождь начался?\"\n\"Да ладно? Пап, там вообще-то солнечно\".\n\"Скорее накрой чем-нибудь чертежи! Сейчас хлынет ПОТОК ИДЕЙ!\"\n\"Ну па-а-а-а-ап...\"\n- Серафина и ее отец","Снаряжение",[],["Пилтовер и Заун"],"РЕДКОЕ"],"06PZ046":["Формула","Вытяните 2 карты. Восполните свою ману заклинаний.","","\"Магия – это научный факт, который только предстоит открыть\". - Джейс","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"06PZ007":["Амбициозный культист","Если вы в этом матче снарядили союзника, создайте в руке новое заклинание стоимостью 2 и уменьшите его стоимость до 0 до конца раунда.","","\"Я всегда мечтал пожертвовать собой во имя науки. Никакая опасность не страшна, если наградой будет безграничная, неисчерпаемая сила, которую мне даст такой обмен\".","Боец",["КУЛЬТИСТ"],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"06PZ041":["Хитроумный котофей","Если я создан, то, призвав меня, вытяните 1 карту и даруйте мне +2|+1.","","Если кот не дремлет среди бела дня и не дает концерт среди ночи, то он не прочь провернуть какую-нибудь шалость.","Боец",["КОШКА"],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"06PZ036":["Заунская Дива","Разыгрывая карту: нанесите 1 ед. урона всем врагам. Если в этом матче вы сыграли 6+ новых заклинаний, вместо этого нанесите 3 ед. урона.","","\"Заун! Надеюсь, вы готовы кричать, потому что мы сейчас снова разнесем этот зал!\" - Заунская Дива","Боец",[],["Пилтовер и Заун"],"РЕДКОЕ"],"06PZ010":["Звукач","Удар: создайте в руке случайное новое заклинание стоимостью 2.","","Когда-то он мечтал удрать из Зауна и странствовать по свету с сердцем, полным песен. Теперь свет в его комнатушке словно замер в ожидании песен, что зазвучат завтра.","Боец",[],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"06PZ022":["Соло на ударных","Вытяните 2 карты.\nПрилив: уменьшите стоимость каждой на 1.","","Секрет музыки – в ритме. Но иногда с ним нужно просто не заморачиваться.","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"06PZ029":["Игра на публику","Дайте союзнику +2|+0 и Быструю атаку до конца раунда.\nПрилив: создайте в руке новое заклинание стоимостью 2.","","\"Заун, я вас не слышу!\" - Серафина","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"06PZ020":["Желудь, Хекстехник","Удар по нексусу: снизьте стоимость самого дорогого заклинания в своей руке на 1.","","Его имени нет в чертежах, и среди авторов песен он не указан. Но посвященные в курсе, что Желудь был мозгом всего мероприятия.","Боец",[],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"06PZ009":["Качающий рифф","Прилив: моя стоимость снижается на 2.\nНанесите 1 ед. урона всем врагам.","","Чтобы пробиться сквозь заунский грохот и лязг, звук нужен особенный. И Дива знает, как его добыть.","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"06PZ037":["Вопиющий диссонанс","Нанесите 1 ед. урона бойцу. Если вы в этом матче снаряжали союзника, повторите меня на той же цели.","","Если диссонанс – это какофония разрушения, тогда продолжим побоище.","Заклинание",["КУЛЬТИСТ"],["Пилтовер и Заун"],"РЕДКОЕ"],"06PZ019":["Заунский вышибала","Начало раунда: Прилив: восполните 2 ед. маны заклинаний.","","Если так и дальше дело пойдет, то не впустим НИКОГО.","Боец",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"06PZ033":["Гатализатор 1.0","Ваши заклинания и способности наносят на 1 ед. урона больше.","","\"Местонахождение: Сектор 3, Проход 19B\nОбъект: незаконное огнестрельное оружие\nПримечания: конфисковано в ходе операции \"Свет в Стоках\". Оружие крайне опасно. Обращаться с предельной осторожностью\".\n- патрульный отчет Стража Пилтовера","Снаряжение",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"06BW029":["Пилтоверский изгой","Призвав меня, посмотрите, как я применяю Импровизацию.","","Пеш и Джакс познакомились во время портовой потасовки, и их совместное бегство было скорее расчетливым компромиссом, нежели началом партнерства. Однако Пеш с тех пор сопровождает Джакса, потому что рядом с Джаксом все ломается. А сильнее доброй драки Пеш любит лишь одно – когда\nчто-то поломалось и требует починки.","Боец",["МАСТЕР ОРУЖИЯ"],["Билджвотер","Пилтовер и Заун"],"ОБЫЧНОЕ"],"06BW034":["Тяжелый металл","Разрушьте снаряжение бойца и нанесите ему 2 ед. урона.","","\"ЭТО КТО ДОДУМАЛСЯ В КАБАЦКОЙ ДРАКЕ ШВЫРЯТЬСЯ ЯКОРЕМ?! НАРОД, ЧТО С ВАМИ НЕ ТАК?!!\" - Билджвотерский трактирщик","Заклинание",[],["Билджвотер"],"РЕДКОЕ"],"06BW027":["Целое из частей","Чтобы сыграть, сбросьте 1 карту. Вытяните 2 карты и, если вы сбросили снаряжение, призовите карту Икатийский мираж.","","Бригада Джакса – доказательство того, что целое может быть больше, чем сумма его частей. Тем не менее, Пеш придерживается другой философии: иногда части и сами по себе неплохи.","Заклинание",["МАСТЕР ОРУЖИЯ"],["Билджвотер","Пилтовер и Заун"],"РЕДКОЕ"],"06BW039":["Бесконечная волна","Если вы в этом матче снаряжали союзника, моя стоимость снижается на 2.\nВытяните 2 карты и даруйте им Мимолетность.","","Хотя старые кости Ибаароса двигались с трудом, хлынувшая перед ним вода неслась с непостижимой скоростью.","Заклинание",["КУЛЬТИСТ"],["Билджвотер"],"РЕДКОЕ"],"06BW026":["Культистка бухру","Когда атакуют снаряженные союзники, нанесите 1 ед. урона вражескому нексусу.","","Не имеет значения, откуда приходит сила. Богине все равно. Что действительно важно – это слава, которую можно заслужить, убивая чудовищ.","Боец",["КУЛЬТИСТ"],["Билджвотер"],"ОБЫЧНОЕ"],"06BW014":["Гарпун даркинов","Атака: вытяните 1 карту в начале следующего раунда и даруйте ей Мимолетность.\nВы можете потратить 9 ед. маны, чтобы сыграть меня в виде карты Ибаарос.","","\"Подальше держись, подальше держись от пролива Дарая,\nГде шепчет вода и ветер морочит тебя, привирая,\nГде звери морей не плывут и птиц не покажется стая,\nВедь тьма стережет в глубокой воде под проливом Дарая\".\n- билджвотерская песенка","Снаряжение",["ДАРКИН"],["Билджвотер"],"ЭПИЧЕСКОЕ"],"06BW004":["Испытание духа","Дайте врагу Уязвимость до конца раунда. Если в этом раунде он погибнет, нанесите 1 ед. урона вражескому нексусу.","","\"Будешь сражаться или дрожать?\" - Иллаой","Заклинание",[],["Билджвотер"],"РЕДКОЕ"],"06BW044":["Хваткая рыба-тритон","Удар по нексусу: вытяните 1 карту и даруйте ей Мимолетность.","","\"Мерзкие вороватые монстрики, вот кто они. Но их хотя бы легко выследить, когда они стибрят что-нибудь\".","Боец",["РЕПТИЛИЯ"],["Билджвотер"],"ОБЫЧНОЕ"],"06BW047":["Мараи-непоседа","Разыграв заклинание, призовите карту Пороховая бочка.","","\"Биби, конечно, слегка... чокнутая. Но это нам в ней и нравится!\" - Ай'ла, Защитница мараи","Боец",[],["Билджвотер"],"РЕДКОЕ"],"06BW023":["Зазубренная сабля","Разграбление: моя стоимость снижается на 2.","","\"Как гласит поговорка, билджвотерскую свару быстрее всего окончит сабля\".\n\"Или все-таки пистолет...\"\n\"Заткнись, Баз\".\n- Баз и Гэв, начинающие охотники за головами","Снаряжение",[],["Билджвотер"],"ОБЫЧНОЕ"],"06BW042":["Груженое судно","Нанесите 2 ед. урона бойцу. Вытяните 1 карту в начале следующего раунда за каждую единицу нанесенного урона и даруйте этим картам Мимолетность.","","\"Рекс позаботится о взрыве, не волнуйтесь... А я позабочусь о сокровище. Долю Рекса я тоже беру на себя, а не то он попытается запихнуть ее в пушку – и будет тот еще кавардак\". - Младший офицер","Заклинание",[],["Билджвотер"],"ЭПИЧЕСКОЕ"],"06BW040":["Око богини","Атака: используйте Порождение x2.","","\"Не дрогни под взором богини!\" - Иллаой","Снаряжение",[],["Билджвотер"],"РЕДКОЕ"],"06SH032":["Спрятанная оружейня","Отсчитайте 2 раунда: создайте в руке карту Сокровище песков.","","\"Вот надо тебе все потрогать?\"\n\"А что? Думаешь, тут ловушка? Типа выкатится какой-нибудь валун и...\"\n\"БЕЖИ-И-И-ИМ!\"\n- Аргус и Сильвио, бугровщики","Место силы",[],["Шурима"],"ОБЫЧНОЕ"],"06SH035":["Алтарь крови","Сразив бойца, уменьшите стоимость следующего разыгрываемого бойца-даркина на 1.","","Алтарь снова затрясся, отчего песок вокруг начал медленно, но размеренно вздрагивать. Каждый из учеников Золаани почувствовал в своем сердце тот же ритм. Каждым мускулом, каждой мыслью, каждую секунду... Они полностью отдались ее воле.","Место силы",[],["Шурима"],"РЕДКОЕ"],"06SH046":["Реликварий аколита","Призвав меня, создайте в руке карту Смертоносный аколит. Разрушив меня, создайте карту Реликварий аколита среди верхних 5 карт в вашей колоде.","","\"Наши руки создают пустыню!\" - Смертоносный аколит","Место силы",[],["Шурима"],"РЕДКОЕ"],"06SH033":["Проклятие гробницы","Примените Предсказание. Дайте бойцу особенность \"Я получаю двойной урон, и если я погибаю, вместо этого уничтожьте меня\" до конца раунда.","","\"Только глупцы стремятся к cиле, которой не могут управлять\". - Зерат","Заклинание",[],["Шурима"],"РЕДКОЕ"],"06SH028":["Врата Бездны","Призвав союзника или когда погибает союзник, даруйте каждый его полезный навык 3 союзникам в вашей колоде.","","Вестник роя воздел руки к колоссальной конструкции, возвышавшейся над ним. \"ТРОН, – закричал он, – ДЛЯ ИМПЕРАТРИЦЫ!\" Во Вратах Бездны запульсировала жизнь. Скоро все случится.","Место силы",[],["Шурима"],"ЭПИЧЕСКОЕ"],"06SH005":["Отверженный баккай","Разыгрывая карту: сделайте предсказание. Если вы выбираете даркина или снаряжение, даруйте мне +1|+1.","","В руке он сжимал плетеный пояс – подарок его друга Рааста, врученный перед их церемонией Вознесения. Но даже при всем благоговении перед силой даркинов, в своем жестоком сердце он таил обиду.","Боец",["КУЛЬТИСТ"],["Шурима"],"ОБЫЧНОЕ"],"06SH056":["Бичевание","Убейте ВСЕХ сторонников.","","Иногда вас влечет к свету, а иногда его влечет к вам.","Заклинание",[],["Шурима"],"РЕДКОЕ"],"06SH040":["Необдуманное воскрешение","Если вы в этом матче снаряжали союзника, моя стоимость снижается на 2. Оживите сильнейшего погибшего союзного чемпиона.","","\"Ты никогда не умрешь, потому что я тебе не позволю\".\n- Золаани","Заклинание",["КУЛЬТИСТ"],["Шурима"],"ЭПИЧЕСКОЕ"],"06SH021":["Замаскированный ужас","Разыгрывая карту: я наношу удар врагу.","","Натиск усиливался, и из расширяющихся врат высыпали все более крупные и свирепые создания. Город Белвет сгинул навсегда. Но хотя жестокая судьба забрала его, имя его будет жить в веках.","Боец",[],["Шурима"],"РЕДКОЕ"],"06SH051":["Чабан камненосцев","Призвав другого союзника, продвиньте на 1 раунд счетчик вашего места силы с наивысшим значением.\nПризвав меня, призовите место силы Спящий камненосец.","","\"Камненосцы принимают Садиру за свою. Она бы убежала с ними в два счета, если бы я ей позволила. Вот оторва!\" - Кадира, Натуралистка из пустыни","Боец",[],["Шурима"],"РЕДКОЕ"],"06SH055":["Жрица света пустыни","Начало раунда: нанесите мне 4 ед. урона. Вытяните карту чемпиона и даруйте ей +2|+2. Если в вашей колоде было 6+ разных чемпионов, вместо этого призовите карту чемпиона.","","Когда кругом зло, те, кто тверд в своей вере, стоят до конца, отдавая последние силы ради поддержания света справедливости. Они знают, что их отчаянный призыв к спасению не останется без ответа, – даже перед лицом всепоглощающей тьмы.","Боец",[],["Шурима"],"ЭПИЧЕСКОЕ"],"06SH004":["Кровопускатели даркинов","Предсмертный вздох: если мой носитель – не Пленник даркинов, призовите карту Пленник даркинов.\nВы можете потратить 6 ед. маны и убить союзника, чтобы сыграть меня в виде карты Золаани.","","Когда разгорелась схватка, Джун, израненная и потерявшая надежду, обратилась к голосу, что шептал в ее голове. \"Ты никогда не умрешь, – сказал голос, нежный как летний дождь, – потому что я тебе не позволю\".","Снаряжение",["ДАРКИН"],["Шурима"],"ЭПИЧЕСКОЕ"],"06SH038":["Раскачивающаяся глефа","Удар: создайте в руке карту Удачная находка.","","\"Желаемое – преследуй. Безо всякой пощады\".\n- Исследовательница руин","Снаряжение",[],["Шурима"],"ОБЫЧНОЕ"],"06DE048":["Барсук-преградитель","","","\"Если друг ты, то здесь тебе рады. Но горе тому, кто вторгнется в сей предел, в сердце своем затаив зло, ибо придется ему изведать возмездия могучего охранителя!\"","Боец",["ЭЛИТА"],["Демасия"],"ОБЫЧНОЕ"],"06DE024":["Лови!","Дайте союзнику +1|+1 до конца раунда или снарядите его снаряжением из руки стоимостью 2 или менее.","","Ход будет более болезненным, если компания еще не успела поесть.","Заклинание",["МАСТЕР ОРУЖИЯ"],["Демасия","Фрельйорд"],"РЕДКОЕ"],"06DE025":["Добросердечный новобранец","Призвав меня, дайте снаряженным союзникам Щит до конца раунда.","","\"Этот мальчик стал обузой. Я был решительно против его участия в нашей охоте, так как он все еще называет мерзкое создание своей сестрой. Глубина его наивности столь велика, что откровенно возмущает. Полагаю, впрочем, что я был к нему довольно сострадателен. По меньшей мере, все это послужит ему важным уроком\". \n- Выдержки из личного дневника Сириуса Ровилла, Истового рыцаря-рейнджера","Боец",[],["Демасия"],"РЕДКОЕ"],"06DE033":["Безмолвие и подавление","Разрушьте снаряжение бойца и, если это сторонник, примените к нему Безмолвие.","","\"Вы сами это накликали\". - Лорд Элдред, глава охотников на магов","Заклинание",[],["Демасия"],"РЕДКОЕ"],"06DE039":["Рык Икатии","Призовите 2 Икатийских миража, снаряженных 1 или 2 снаряжениями из руки стоимостью 2 или менее.","","Джакс видел несчетное число снов, в которых он сражался рядом с погибшими сородичами. В одних битвах они побеждали, в других – проигрывали, но главное, что они всегда были вместе.","Заклинание",["МАСТЕР ОРУЖИЯ"],["Демасия"],"РЕДКОЕ"],"06DE011":["Щит даркинов","Вы можете потратить 5 ед. маны, чтобы сыграть меня в виде карты Джораал.","","\"Послушай, сынок. К этому щиту нельзя притрагиваться. Даным-давно его подарили нашему семейству на том условии, что мы будем бережно хранить его – и более ничего. Это моя ответственность, и когда меня не станет, она будет твоей. Ты слышишь меня? Никогда больше на него не забирайся. Никогда не прикасайся к нему\".\n\"Но, мама, голос внутри... я слышу, как он плачет. Ему так грустно\".\n\"...Тогда тем более, сынок\".\n- Леди Фортис и ее сын","Снаряжение",["ДАРКИН"],["Демасия"],"ЭПИЧЕСКОЕ"],"06DE021":["Вейн","Призвав меня или в начале раунда: создайте в руке карту Кувырок. Если она у вас уже есть, снизьте ее стоимость на 1.","На моих глазах вы атаковали 4 раза.","\"Наша цель когда-то была человеком. Это значит, что она умнее обычного чудовища. Один неверный шаг может навлечь гибель на всех нас. Держите друг друга в поле зрения, при любой опасности зовите подмогу – но прежде всего помните...\"","Боец",[],["Демасия"],"Чемпион"],"06DE043":["Преданный тарантерьер","Впервые призвав элитного бойца, даруйте мне +2|+2.","","\"Он не так быстр, как среброкрыл, но вы удивитесь, как резво он передвигается на своих ножках\". - Цитрия, Повелительница облаков","Боец",["ПЕС"],["Демасия"],"ОБЫЧНОЕ"],"06DE018":["Приговор","Если в этом раунде вы атаковали 2+ раза, моя стоимость снижается на 5.\nСоюзник наносит удар врагу.","","\"Очистительные стрелы\". - Вейн","Заклинание",[],["Демасия"],"ОБЫЧНОЕ"],"06DE041":["Сила чемпионов","Дайте союзникам +4|+4 до конца раунда и используйте Рвение.","","\"Свет сердец ведет нас в бой!\" - Люкс","Заклинание",[],["Демасия"],"ЭПИЧЕСКОЕ"],"06DE026":["Икатийские мифы","Создайте в руке карту Икатийский мираж стоимостью 0 до конца раунда либо создайте в руке карту Золотая лопатка.","","В легендах говорится, что изначальным владельцем Золотой лопатки было морское чудище, обладавшее незаурядным мастерством кулинара. Это существо стремилось стать сильным и бесстрашным воином, подобным Джаксу.\n\nДругие, более правдоподобные легенды утверждают, что та первая легенда была полностью выдумана неким поваром, который очень, ОЧЕНЬ любил понавешать лапши.","Заклинание",[],["Демасия"],"РЕДКОЕ"],"06DE044":["Петрицитовый тур","Вражеские заклинания и способности не наносят мне урон.","","\"Крепче петрицита нет ничего\". - Архитектор Дюран","Боец",[],["Демасия"],"РЕДКОЕ"],"06DE017":["Рыбный бой","Союзник и враг наносят удар друг другу, либо снаряженный союзник наносит удар врагу, после чего лишается снаряжения.","","\"Рыба, познакомься с лицом!\" - Ионийская удильщица","Заклинание",["МАСТЕР ОРУЖИЯ"],["Демасия"],"ОБЫЧНОЕ"],"06DE040":["Заманчивая перспектива","Выберите сторонника или снаряжение среди 4 верхних карт в вашей колоде. Вытяните его, уберите остальные карты в вашу колоду.","","Мягкий и манящий шепот зарождает в глубинах души новое желание. Затем оно, подобно занозе, начинает терзать – и перерастает в голод. Голод приводит к проступку, который в свою очередь влечет гибель. Далее цикл повторяется.","Заклинание",["КУЛЬТИСТ"],["Демасия"],"ОБЫЧНОЕ"],"06DE028":["Проклятая гарпия","Разыгрывая карту: снарядите меня снаряжением из руки стоимостью до 2. Когда я впервые погибаю, имея снаряжение, вместо этого полностью исцелите меня и разрушьте снаряжение.","","\"Киан, если ты читаешь это... то меня, надеюсь, уже нет в живых. Я не могу справиться с происходящим. Кровь под моими ногтями уже не отмыть. У меня зудит повсюду. Я чешусь не переставая, но толку никакого. Все болит. Я просто хочу, чтобы это закончилось. Если я каким-то образом еще останусь на этом свете, пообещай мне, что не будешь меня искать.\n\nМне стоило бы попросить о прощении, но я его не заслуживаю. Будь подобрее с матушкой, хорошо?\"\n- Скомканное письмо, найденное в разорванной сумке","Боец",[],["Демасия"],"ЭПИЧЕСКОЕ"],"06DE027":["Истовый рыцарь-рейнджер","Атака: дайте снаряженным союзникам +1|+1 до конца раунда.","","\"Что говоришь, Джанан? Можешь что-то рассказать про Сириуса?\"\n\"А, про рыцаря-рейнджера Ровилла? Несколько лет назад его лишили звания. Судя по всему, он умышленно пренебрегал любыми приказами. Кажется, он делает лишь то, чего ему хочется, и не принимает отказов.\"\n\"Вот как\".\n\"Итак... все же почему ты позволила ему присоединиться к охоте?\"\n\"Я не позволяла.\"\n\"Тогда почему... а, понятно. Великолепно\".\n- Вейн и Джанан, Овдовевшая охотница","Боец",[],["Демасия"],"РЕДКОЕ"],"06DE019":["Овдовевшая охотница","Разыгрывая карту: снарядите меня снаряжением из руки стоимостью до 2.","","\"Хотя эта женщина выглядит достаточно умелым бойцом, ее печаль еще свежа и потому может подавить ее. Разумеется, отчаяние тоже может быть убедительной движущей силой – мне ли не знать! Но чтобы доходило до такого буйства?.. Не исключаю, что ей хочется умереть...\" - Выдержки из личного дневника Сириуса Ровилла, Истового рыцаря-рейнджера","Боец",[],["Демасия"],"ОБЫЧНОЕ"],"06DE032":["Демасийская сталь","","","Обычные щит и меч, которые предпочитают шлемоносные братья по оружию из Демасии.","Снаряжение",[],["Демасия"],"ОБЫЧНОЕ"],"06DE029":["Стойкий элкин","Когда впервые снаряжают союзника, даруйте мне Стойкость.","","\"Назад, мерзкое создание! Если хоть один волосок упадет с безупречного покрова Чистоты, я обреку тебя на ВЕЧНЫЕ МУКИ!\" - Сириус Ровилл, Истовый рыцарь-рейнджер","Боец",[],["Демасия"],"ОБЫЧНОЕ"],"06DE010":["Сбежавший рыцарь-рейнджер","Как только вы снарядили союзника в этом матче, даруйте мне Разведку.","","Пока она много лет подавляла свои магические способности, внутри нее созрела бездонная ненависть к себе, которую она со злобой изливала на своих жертв. С тех пор как она дезертировала из отряда рыцарей-рейнджеров, ее гнев не имел цели – пока ее не призвал голос в темноте. Голос говорил о новом порядке вещей, при котором она смогла бы высвободить свою жестокость.","Боец",["КУЛЬТИСТ"],["Демасия"],"РЕДКОЕ"],"06DE006":["Боевой повар","Призвав меня, посмотрите, как я применяю Импровизацию, затем примените ко мне Кузницу.","","Отслужив срок в демасийском войске, Бриши думал, что теперь-то он уйдет на покой, чтобы кухарить в тихой сельской таверне. Мечту о покое разрушил Джакс – всего-то одной потасовкой в той самой таверне, а также крайне нелестным отзывом о тамошних яйцах вкрутую. Тогда-то Бриши и принял свою новую судьбу – прививать Джаксу хоть какой-то вкус.","Боец",["МАСТЕР ОРУЖИЯ"],["Демасия","Фрельйорд"],"ОБЫЧНОЕ"],"06DE034":["Верная волкособака","Если в этом раунде погиб союзник, моя стоимость снижается на 2.\nРазыгрывая карту: снарядите меня снаряжением из руки стоимостью до 2 ед. маны и примените ко мне Кузницу.","","\"Мэгги у меня появилась еще крохой. Песок из нее, может, уже и сыплется, но она все еще востра как свежезаточенный клинок. Я за нее жизнь отдам – и знаю, что и она за меня умрет\". - Джанан, Овдовевшая охотница","Боец",["ПЕС"],["Демасия"],"ОБЫЧНОЕ"],"06SI045":["Расщепление души","Убейте союзника, чтобы призвать 2 его эфемерные копии.","","Им она все равно не была нужна.","Заклинание",[],["Сумрачные острова"],"РЕДКОЕ"],"06SI007":["Алебарда даркинов","Чтобы сыграть меня, убейте союзника.\nВы можете потратить 10 ед. маны, чтобы сыграть меня в виде карты Таарош.","","Вытянувшись в тесной камере, Таарош слышал зов своего генерала. Он должен был на него ответить – так или иначе.","Снаряжение",["ДАРКИН"],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"06SI034":["Призрак отзвуков","Конец раунда: за каждого союзника, погибшего в этом раунде, даруйте всем его союзным копиям +1|+1 везде.","","\"Я не знаю, что за злобную магию они используют, и НЕ ХОЧУ знать. Все, что мне нужно знать, – если они восстанут из мертвых, сможем ли мы их убить. Снова\".\n- Смотритель Островов","Боец",[],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"06SI029":["Пагубное копье","Если в этом раунде погиб союзник, моя стоимость снижается на 2.","","\"Правосудия нет. Есть только месть\". - Калиста","Снаряжение",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"06SI032":["Упокоение","Убейте бойца с суммарным значением силы и здоровья не больше 4 либо разрушьте снаряжение бойца.","","В каком бы облике смерть ни явилась на Сумрачных островах, пусть она будет милосердно быстрой.","Заклинание",[],["Сумрачные острова"],"РЕДКОЕ"],"06SI031":["Клинки Павших","Дайте союзнику \"Предсмертный вздох: призовите карту Икатийский мираж с моим снаряжением\" до конца раунда.","","Иногда лучшее, что ты можешь сделать для павшего союзника, – это взять его оружие и продолжить бой.","Заклинание",["МАСТЕР ОРУЖИЯ"],["Сумрачные острова","Шурима"],"РЕДКОЕ"],"06SI014":["Шикарный салон","Призвав меня, призовите карту Призрачный оркестр.\nНачало раунда: если у вас есть жетон атаки, призовите карту Призрачный оркестр.","","\"Музыканты готовы, сцена в порядке, публика ждет\n– маэстро, прошу вас!\" - Веселый хозяин","Место силы",[],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"06SI038":["Освобожденный виртуоз","Атака: призовите атакующего бойца Призрачный оркестр.","","Стремление к совершенству стало обузой, ярмом. В совершенстве нет жизни, нет свежего воздуха. Однако совершенное несовершенство – вот то, к чему стоит стремиться. ","Боец",[],["Сумрачные острова"],"РЕДКОЕ"],"06SI003":["Фирет, Жница песков","Призвав меня, посмотрите, как я применяю Импровизацию.","","За первые пару недель совместного путешествия Джакс раз тридцать спросил у Фирет, как ее зовут. Но каждый раз в ответ она рычала: \"Я Жница!\" Бриши придумал обходной маневр: он, понимаете ли, всего лишь приготовит призовой тортик, на котором нужно будет написать имя того, кто в их группе сильнее всех.","Боец",["МАСТЕР ОРУЖИЯ"],["Сумрачные острова","Шурима"],"ЭПИЧЕСКОЕ"],"06SI006":["Хранительница Короба","Как только вы снарядили союзника в этом матче, даруйте мне Вампиризм.","","\"Короб не выдает тайны просто так, Шида Каин. За них платят суровую цену. Но если у тебя хватит смелости вглядеться в тень теней, ты обнаружишь, что внутри скрыты чудесные и ужасные вещи\". - Исдра, Хранительница Короба","Боец",["КУЛЬТИСТ"],["Сумрачные острова"],"ОБЫЧНОЕ"],"06SI039":["Силуэт страха","Убейте союзника, чтобы призвать карту Подступающий туман.","","Лишь глупец станет вглядываться в Черный туман, надеясь распознать знакомый силуэт.","Заклинание",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"06SI042":["Посмертный рыцарь","Когда я должен стать эфемерным, вместо этого даруйте мне +1|+1.","","Солдаты, которых при жизни учили стойко принимать тяготы, и после смерти оказались более старательными и умелыми, не зная боли, холода и страха.","Боец",[],["Сумрачные острова"],"РЕДКОЕ"],"06SI036":["Полное опустошение","Убейте ВСЕХ бойцов кроме союзных даркинов и союзников со снаряжением.","","Стоило ей завладеть оружием, как вся ее человечность испарилась. Вместо этого прохудившийся сосуд, когда-то бывший ученицей по имени Джун, стал наполняться концентрированной ненавистью. Ненависть лилась сквозь нее, поверх нее и струилась во внешний мир, беспокоя дремлющего даркина.","Заклинание",["КУЛЬТИСТ"],["Сумрачные острова"],"РЕДКОЕ"],"06SI046":["Бессменный часовой","Предсмертный вздох: вытяните 1 карту.",""," \"...и я буду стоять на страже целую вечность, ибо долг мой больше жизни и больше смерти\".","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"06SI041":["Хранитель лунной лощины","Призывая эфемерного союзника, даруйте ему +1|+0.\nНочь: призовите карту Саженец.","","Вдали от побережья Сумрачных островов торчат останки деревьев – вроде бы давно погибших. Они изуродованы и неподвижны, но внимательный наблюдатель заметит, что в напоенной лунным светом почве теплится новая жизнь.","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"07PZ009":["Аугментированный маховичок","Разыгрывая карту: сделайте Предсказание, затем вытяните 1 карту и снизьте ее стоимость на 1.","","\"Этому парнишке нужен был легкий ремонт. Тут шестерни поменять, там приладить руку – и вот он уже как новенький. Время – это благо, которого у каждого должно быть побольше, так я считаю\". - Экко","Боец",[],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"07PZ017":["Разносчик световых бомб","Разыграв заклинание, прикрепите 1 ловушку Световая бомба среди 8 верхних карт в колоде противника.","","\"...Знаешь, чем еще эти крошки лучше грибов? Ты сам решаешь, когда им взорваться! Как не заплатить за ТАКОЕ?\"","Боец",[],["Пилтовер и Заун"],"РЕДКОЕ"],"07PZ005":["Обратка","Нанесите 1 ед. урона врагу и вражескому нексусу. Сбросьте 1 или 2 карты, чтобы увеличить урон на 1 ед. за каждую сброшенную карту.",""," \"Ладно-ладно! Это, наверное, сработает всего один раз, но уж поверь – рванет как надо!\" – Джинкс","Заклинание",[],["Пилтовер и Заун"],"РЕДКОЕ"],"07NX009":["Стильный выстрел","Нанесите 1 ед. урона вражескому нексусу. В следующий раз, когда союзник в этом раунде нанесет удар нексусу, создайте в руке карту Стильный выстрел.","","\"Даже если бы у меня были только камни и палки, со мной все равно никто бы не смог равняться. А при полном комплекте... Даже не пробуй\". - Самира","Заклинание",[],["Ноксус"],"ЭПИЧЕСКОЕ"],"07NX008":["Сама Элегантность","Разграбление: даруйте мне +2|+0.","","\"Мои гонорары заоблачны, и я не работаю на кого попало. Если уж тебе посчастливилось нанять меня, на твоей стороне изящество, самообладание и клинки, которые всегда найдут свою жертву. Но прежде всего – стиль. Разве кому-то не по вкусу эффектное убийство?\"","Боец",[],["Ноксус"],"ОБЫЧНОЕ"],"07NX014":["Пируэт","Разграбление: моя стоимость снижается на 2.\nНанесите 1 ед. урона любой цели и оглушите врага.","","\"Что? Я просто делала зарядку. Только не говори, что тебя убила зарядка\". - Сама Элегантность","Заклинание",[],["Ноксус"],"РЕДКОЕ"],"07NX007":["Самира","Разграбление или нанося удар: создайте в руке карту Чутье, если у вас ее еще нет.","На моих глазах вы разыграли 6 карт. Обнуляется, когда вы начинаете раунд с жетоном атаки.","\"Я всегда иду навстречу тем, кто влез в долги, которые нечем оплатить. А вот уходя от выплаты долгов, ты наживаешь себе врагов худшего сорта – тех, что нанимают меня\".","Боец",[],["Ноксус"],"Чемпион"],"07NX006":["Щеголеватый денди","Разграбление: удвойте мою cилу.",""," \"Слушай, обычно я устанавливаю кое-какие правила. Например – лапы прочь от прически и лица. Но кого я обманываю? Ты-то до меня и пальцем дотронуться не успеешь\".","Боец",[],["Ноксус"],"ОБЫЧНОЕ"],"07NX015":["Дама-Налетчица","Разграбление: даруйте союзникам +1|+0.","","\"Ах, Дама... У нее чутье на драматизм. Некоторые воротят нос даже от малейшей театральности, но если она в своей стихии, никто не останется внакладе\". - Сама Элегантность","Боец",[],["Ноксус"],"ОБЫЧНОЕ"],"07NX003":["Карт-бланш","Дайте союзнику +2|+0 до конца раунда.\nРазграбление: вместо этого дайте ему +2|+1.","","\"Индари задействовала кое-какие связи, чтобы мы прошли без лишнего шума. А с этим есть надежда, что на обратном пути у меня все же будет время пошуметь\".\n- Самира","Заклинание",[],["Ноксус"],"ОБЫЧНОЕ"],"07NX004":["Искусный техник","Призвав меня, активируйте эффекты Разграбления всех союзников.","","\"Открыть свою лавку – это не так уж и просто. Но стоит посетителям увидеть наш с Лани ассортимент, как монета сама прыгает в руки. Нашу цель среди клиентов я не заметила. Зато уйма тех, у кого тоже сегодня заваруха на уме. В конце концов, если знаешь, кто кого хочет грохнуть, то у тебя есть четкое понимание ситуации\".\n- Миель.","Боец",[],["Ноксус"],"РЕДКОЕ"],"07NX001":["Дерзкая разрушительница","Разыгрывая карту: нанесите 1 ед. урона вражескому нексусу или активируйте эффект Разграбления союзника.","","\"Если твой бизнес связан с оружием, тебе нужно дружить с данными. Разработка концепта, испытания, переоснастка, модифицирование – все это требует массы информации. Ничто не сравнится с маленьким полевым испытанием – если хочешь сделать оружие нужных габаритов... и еще пару воронок!\" - Лани","Боец",[],["Ноксус"],"РЕДКОЕ"],"07NX005":["Капитан Индари","Призвав меня, посмотрите, как я применяю Импровизацию.\nРазграбление: примените Кузницу к остальным союзникам.","","\"Мне приходилось работать со многими тайными агентами. С одними было легко, с другими посложнее... А потом появилась Самира. Я смирилась с тем, что обуздать ее невозможно. Вместо этого я направляю весь этот бедлам, навожу его на цель. Ну и время от времени присоединяюсь\".","Боец",["МАСТЕР ОРУЖИЯ"],["Ноксус"],"РЕДКОЕ"],"07BW018":["Спятившая Старушка Бэбс","Восполняя ману, даруйте мне +1|+0 за каждую восполненную единицу маны.","","\"Малыш Джек, дорогуша! Гляди сюда! Моя найти вещь, которая тебе интересовать, верно?\"","Боец",[],["Билджвотер"],"ОБЫЧНОЕ"],"07BW021":["Бесцеремонная буканьерша","Разграбление: призовите случайного сторонника стоимостью 1 и даруйте ему Вспыльчивость.","","\"На твоем месте я бы держалась от нее подальше. У нее есть весьма мерзкая привычка превращать собственные проблемы в проблемы окружающих\". - Самира","Боец",[],["Билджвотер"],"ОБЫЧНОЕ"],"07BW002":["Джек","Удар: создайте в руке карту Монета.\nВосполняя ману, восстановите мне 1 ед. здоровья за каждую восполненную единицу маны.","Вы потратили 12+ ед. маны в одном раунде.","\"Раз ты идешь против меня, то ты, должно быть, или смел, или туп. Но итог в любом случае один. Мой тебе совет – позаботься о том, как уйти живым\".","Боец",[],["Билджвотер"],"Чемпион"],"07BW040":["Накл","Призвав меня, создайте в руке мимолетную карту Мако.","","\"Тут подрежем, там подсечем, унывать нам ни к чему. Маленечко крови в воде не повредит. Мне-то уж точняк\". - Накл","Боец",[],["Билджвотер"],"РЕДКОЕ"],"07BW001":["Вероломный промоутер","Восполняя ману, создайте в руке мимолетного случайного сторонника, стоимость которого равна количеству вашей маны.","","\"Если хочешь крови, то тебе нужен Джек. Хочешь знать, что, когда, где и почем? Обращаешься ко мне\".","Боец",[],["Билджвотер"],"РЕДКОЕ"],"07BW003":["Карманник","Предсмертный вздох: создайте в руке карту Монета.","","\"Эй, ну-ка вернись, слизеныш! Там денег только на еду!\"\n- Ангел","Боец",[],["Билджвотер"],"ОБЫЧНОЕ"],"07BW014":["Пабло Пятихлоп","Призвав меня, создайте в руке мимолетную карту Профессиональный бой.","","\"Вот так-то, малыш Джекки! Излучай-ка и дальше фирменное билджвотерское обаяние – а я позабочусь о твоей бойцовской форме. Эх, и как тут не вспомнить золотые денечки, когда меня звали \"Расписной красавец Пабло\"... Не было такого, говоришь? А я тебе отвечаю – было! Выхватил в башку – вот и не помнишь ни черта!\"\n- Пабло Пятихлоп","Боец",[],["Билджвотер"],"ОБЫЧНОЕ"],"07BW013":["Ангел","Разграбление: создайте в руке 3 Монеты.","","\"Это все, что ты можешь? Мило. Теперь моя очередь\".","Боец",[],["Билджвотер"],"ОБЫЧНОЕ"],"07BW006":["Рискованное дельце","Нанесите бойцу 3 ед. урона. Если он погибнет, создайте в руке 2 Монеты.","","\"Ничем не рискнул – ничего не добился. А ведь эти челюсти созданы для риска\". - Джек","Заклинание",[],["Билджвотер"],"ЭПИЧЕСКОЕ"],"07BW026":["Зазубренная цепь","Разграбление: моя стоимость снижается на 2.\nВытяните 2 карты в начале следующего раунда и даруйте им Мимолетность.","","Когда вы услышите звон, бежать будет уже поздно.","Заклинание",[],["Билджвотер"],"РЕДКОЕ"],"07BW027":["Папаша Гнев","Разграбление: восполните 1 ед. маны заклинаний и создайте в руке случайное заклинание стоимостью 1 из ваших регионов.","","Происхождение Папаши Гнева туманно как горизонт поутру. Даже если поспрашивать местных, прямого ответа не жди. Либо его попросту не расслышишь за грохотом творимого разрушения.","Боец",[],["Билджвотер"],"РЕДКОЕ"],"07BW008":["Профессиональный бой","Союзник и враг наносят удар друг другу. После удара у них остается не менее 1 ед. здоровья.","","Иногда предметами сделки становятся монета и лампадное масло, а иногда – кулак и зубы. Так повелось испокон, но равноценный ли это размен? Это хороший бизнес!","Заклинание",[],["Билджвотер"],"ОБЫЧНОЕ"],"07BW041":["Ракушечный кастет","Удар: создайте в руке карту Монета.","","\"Гм-м-м, теперь я знаю, что это не самое обычное снаряжение, это уж точно. Но попробовать стоит, будет сидеть как вросший\". - Булл","Снаряжение",[],["Билджвотер"],"РЕДКОЕ"],"07BW004":["Королевский двор","Призвав меня, вытяните карту Джек.\nПризывая союзника, создайте в руке мимолетную карту Профессиональный бой.\nКогда союзник выживает, получив урон, даруйте ему Вспыльчивость.","","Личный корабль возит Джека и его шайку по водам Рунтерры – от Билджвотера до Ионии. Никто не знает, как он умудряется перемещаться под водой и при этом не тонуть. Однако поговаривают, что как раз под поверхностью воды и таится главная опасность...","Боец",[],["Билджвотер"],"ЭПИЧЕСКОЕ"],"07BW025":["Инферна","Активируя Разграбление, вытяните 1 карту и даруйте ей Мимолетность.","","\"Став поджигателем на море, получаешь кое-какие выгоды. Вода не дает огню выйти из-под контроля. Да и долю он требовать не станет\".","Боец",[],["Билджвотер"],"РЕДКОЕ"],"07IO020":["Вам на выход!","Верните союзника и создайте в руке карту Монета, либо потратьте 5 ед. маны, чтобы вернуть врага и создать в руке карту Монета.","","\"Я вступаю в дело только при двух условиях. Первое: если твой противник чересчур задорно тебя валтузит. Второе: если тебе самому слишком весело. Я тоже хочу долю веселья!\" - Боец-профессионал","Заклинание",[],["Иония"],"РЕДКОЕ"],"07IO014":["Мастер Бингвен, Селекционер","Разыгрывая карту: при следующем розыгрыше любого бойца в этом раунде призовите его точную эфемерную копию.","","Птаха Бингвен когда-то был бойцом. Свое прозвище он получил за журавлиную стойку и проворство. Уйдя на покой, он облачился в тренерский халат, используя свой зоркий глаз и твердую руку, чтобы отыскивать яркие таланты среди толп посредственностей.","Боец",[],["Иония"],"ЭПИЧЕСКОЕ"],"07IO023":["Старожил","Разыгрывая карту: верните сильнейшего врага. Если в этом раунде вы потратили 16+ ед. маны, вместо этого верните всех врагов.","","\"Маска не снимается, барышня. И если ты не хочешь выглядеть как вот это вот, больше не заводи таких разговоров\".","Боец",[],["Иония"],"РЕДКОЕ"],"07IO011":["Сетт","Когда мое здоровье впервые становится меньше 1 во время моей атаки, вместо этого дайте мне Щит.","Вы потратили 40+ ед. маны.","Наслаждаясь ревом толпы, до отказа заполнившей подпольный клуб, его владелец Сетт изредка заглядывает внутрь себя. Он вспоминает все, за что он дрался, и представляет, что его ждет впереди. Впрочем, лишь одно он знает наверняка: хорошо быть Боссом.","Боец",[],["Иония"],"Чемпион"],"07IO046":["Королевский переливчатокрыл","Остальные союзные птицы получают +1|+0 и Быструю атаку.","","\"В этих джунглях я беспрестанно обнаруживаю, что самые прекрасные образцы оказываются наиболее смертоносными хищниками\". – Анура","Боец",["ПТИЦА"],["Иония"],"РЕДКОЕ"],"07IO009":["Рачительная бухгалтерша","Удар по нексусу: создайте в руке карту Монета.","","По сравнению с толпой амбициозных мошенников и меркантильных комбинаторов у Лиз есть одно качество, которое Сетт ценит превыше всего. Это качество – надежность. Она не берет отгулов, у нее не бывает недостач, и она ни разу не дала Сетту повода вмешаться в дела. Это обеспечивает Лиз его покровительство и служит предупреждением для тех, кто собирается мутить воду: поставишь против конторы – проиграешь.","Боец",[],["Иония"],"РЕДКОЕ"],"07IO019":["Компанейский миксолог","Разыгрывая карту: восстановите союзнику или своему нексусу 3 ед. здоровья и создайте в руке карту Монета.","","\"Выпить первую – это как поздороваться. После второй мы уже приятели. После третьей жалуются на проблемы, а на четвертой у гостей развязывается язык – и ты не поверишь, что порой приходится услышать!\"","Боец",[],["Иония"],"ОБЫЧНОЕ"],"07IO017":["Делайте ставки","Вытяните 2 карты и создайте в руке 2 Монеты.",""," \"Они дают нам реальные деньги, а мы даем им шанс. Хе-хе... Некоторые еще удивляются, почему контора все время в выигрыше\".","Заклинание",[],["Иония"],"ОБЫЧНОЕ"],"07IO047":["Затаившаяся кобра","Впервые разыгрывая другого сторонника в каждом раунде, призовите его точную копию. Если поле заполнено, вместо этого даруйте мне его характеристики и навыки.","","\"Как думаешь, за эти цветы можно что-то выручить? Кстати, не подумай, будто я рехнулся, но они что, танцуют?\" – Пилтоверский браконьер","Боец",["РЕПТИЛИЯ"],["Иония"],"ЭПИЧЕСКОЕ"],"07IO013":["Боец-профессионал","Призвав меня, создайте в руке карту Монета.","","\"Одни приходят сюда ради денег, другие – ради крови, а некоторые – ради рева толпы. Что насчет меня? До сих пор не могу определиться. Мне нужно все это – и я получаю всего вдоволь\".","Боец",[],["Иония"],"ОБЫЧНОЕ"],"07IO012":["Охранник ринга","Призвав меня, создайте в руке мимолетную карту Охранник ринга и даруйте +1|+1 остальным Охранникам ринга.\nУкрепление от 5: Быстрая атака.","","\"Если они считают тебя тупицей, не суетись. Оставь все как есть. Пусть паршивцы думают, что могут без опаски играть в свои игры. В жизни нет ничего приятнее, чем когда-нибудь посмотреть в глаза тому, кто осознал, насколько тебя недооценивал\". - Сетт","Боец",[],["Иония"],"РЕДКОЕ"],"07IO007":["Мордобой","Оглушите 2 врагов и создайте в руке карту Монета.","","\"Ну и чего? Он сказал, что сегодня в ударе. Но не уточнил – в чьем!\" - Сетт","Заклинание",[],["Иония"],"ОБЫЧНОЕ"],"07SH023":["Генерал Падших Песков","У меня +1|+0 за каждого эфемерного союзника, призванного вами в этом матче.","","\"Может, ты для этого недруга не опаснее песчинки, но я вижу тебя. Я чувствую твое присутствие среди дюн. Одолжи мне свою силу – и вместе мы раздавим наших врагов!\"","Боец",[],["Шурима"],"РЕДКОЕ"],"07SH018":["Хранитель тайн","Призвав меня, создайте внизу вашей колоды двух случайных чемпионов 2-го уровня, которых еще нет у вас в руке, в колоде или на поле боя.","","Он еще не вполне осознал то, что увидел, и то, каких масштабов может достичь бедствие и когда оно случится. Но он знает этот мир и этот народ. Они не готовы. И возможно, никогда не будут.","Боец",[],["Шурима"],"ЭПИЧЕСКОЕ"],"07SH008":["Атака стаей","Отправьте в самостоятельную атаку точные эфемерные копии каждого кошачьего союзника.","","Даже одна охотница наводит страх – но целая стая и вовсе беспощадна.","Заклинание",[],["Шурима"],"ОБЫЧНОЕ"],"07FR008":["Волчонок-ледошуб","Потратьте 6 ед. маны, чтобы сыграть меня в виде карты Волчица-ледошубка.","","Во Фрельйорде много опасностей – особенно для тех, кому только предстоит узнать его морозные истины.","Боец",["ПЕС"],["Фрельйорд"],"ОБЫЧНОЕ"],"07FR009":["Изобретательный кузнец","Призвав меня, посмотрите, как я применяю Импровизацию.\nВпервые применяя Кузницу к союзнику в каждом раунде или снаряжая его, восстановите вашему нексусу 1 ед. здоровья.","","\"Хотя маленький пушистик не помогает мне работать быстрее, но зато заставляет меня улыбаться. Помощь что надо\". – Изобретательный кузнец","Боец",["МАСТЕР ОРУЖИЯ"],["Фрельйорд"],"РЕДКОЕ"],"07FR005":["Оплот рабства","Союзные заклинания и способности не наносят мне урон.","","\"Если лавина тронулась с места, ее уже не остановить\".\n- Лиссандра","Боец",[],["Фрельйорд"],"РЕДКОЕ"],"07SI002":["Урожай душ","Убейте сторонника с силой до 3 либо потратьте 3 ед. маны, чтобы убить чемпиона с силой до 3.","","Это лишь шепот в воздухе, едва слышный, но причиняющий муки, и он обменивает одну жизнь на другую.","Заклинание",[],["Сумрачные острова"],"РЕДКОЕ"],"07SI001":["Искоренение","Убейте ВСЕХ бойцов с силой до 3.","","Всякому, кто узрит меня, дано познать прикосновение забытья – и вовек его не избыть.","Заклинание",[],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"07SI007":["Замогильный хвостик","Когда впервые в раунде гибнет другой союзник, вытяните 1 карту.","","\"Я только что обучила его новому трюку! Хочешь глянуть?\" – Призрачная шутница","Боец",["ПЕС"],["Сумрачные острова"],"ОБЫЧНОЕ"],"07MT003":["Космический Детеныш","Начало раунда: восстановите 1 ед. здоровья мне и вашему нексусу.","","Подобно отблеску зари, они бороздят небеса, а их лучистый взор приносит спокойствие, утоляет боль от ран и исправляет то, что было повреждено.","Боец",[],["Таргон"],"РЕДКОЕ"],"07MT001":["Падающая звезда","Нанесите 4 ед. урона врагу, который атаковал в этом раунде или оглушен.","","Звезды смотрят на наши поступки – и на добрые, и на злые. Праведные вознесутся, а нечестивые пройдут судилище.","Заклинание",[],["Таргон"],"ОБЫЧНОЕ"],"07MT007":["Самоотверженный ученый","Предсмертный вздох: создайте в руке копии 3 первых заклинаний, которые вы применили ко мне.","","\"Камфор отняла слишком многое – и у слишком многих. Когда придет твой смертный час, убедись, что умираешь на своих условиях. Лиши ее удовольствия\". – Пантеон","Боец",[],["Таргон"],"ЭПИЧЕСКОЕ"],"07BC005":["Резная мечница","","","\"Так, что-то новенькое\". - Хвостатая мечница","Боец",["ФАЭ"],["Бандл Сити"],"ОБЫЧНОЕ"],"07BC009":["Бросок пирога","Нанесите бойцу 1 ед. урона. Создайте в руке карту Гибельная выпечка.","","Приготовься.","Заклинание",[],["Бандл Сити"],"РЕДКОЕ"],"07BC015":["Уплотнение","Выберите сторонника. Создайте в руке его копию стоимостью 1 и сделайте его характеристики равными 1|1.","","\"Хм-м-м... Кажется, маленькое – не всегда миленькое!\"\n– Лулу","Заклинание",[],["Бандл Сити"],"РЕДКОЕ"],"07DE002":["Ордер на обыск","Союзник с силой 4+ берет в плен бойца, либо союзник берет в плен место силы.","","\"Храните молчание и неподвижность. Любое сопротивление неблагоразумно\". - Инспектор-Охотник на магов","Заклинание",[],["Демасия"],"РЕДКОЕ"],"07DE005":["Боевое построение!","Дайте союзнику +2|+2 до конца раунда.","","\"Не отступать! Вас оттеснили, но не сломили!\" - Воин Бесстрашного авангарда","Заклинание",[],["Демасия"],"ОБЫЧНОЕ"],"07DE008":["Алтарь Единства","Призвав меня, вытяните карту бойца.\nПризывая союзника, увеличьте его характеристики до значения его стоимости.","","Впервые увидев Алтарь, Цитрия буквально потеряла дар речи. На какое-то время она просто замерла, благоговея перед величием прославленных героев. Хватит ли ей смелости, чтобы когда-нибудь встать с ними рядом?","Место силы",[],["Демасия"],"РЕДКОЕ"],"07PZ019":["Химтековый доставкомобиль","У меня +1|+0 за каждого союзника стоимостью 1, призванного вами в этом матче.","","\"Мне пришлось пририсовать конику МНОГО ног, господин Ящер, потому что до замка нужно доскакать СКОРЕНЬКО. Эм... Гм... И получился он чуточку... сикось-накось. И чуточку зеленовый\". – Ингвар Младшая","Боец",[],["Пилтовер и Заун"],"РЕДКОЕ"],"07PZ021":["Анура и Жабыч","Стоимость союзников, имеющих подтип, отличный от прочих союзников на поле боя, снижается на 1.","","\"Я не обижу тебя, дружочек! В джунглях я ради науки, а не ради разрушения!\"","Боец",["РЕПТИЛИЯ"],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"07PZ022":["Божественный ветерок","Нанесите 1 ед. урона вражескому бойцу или нексусу и 1 ед. урона другому бойцу.","","Большинству пилтоверцев нет дела до того, в какую сторону дует ветер. Однако для многих заунцев даже случайный бриз имеет привкус блаженства.","Заклинание",["СТИХИЯ"],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"07PZ013":["Монумент в Сточных ямах","Если ваш нексус должен получить урон от любой карты кроме карты Ядовитый гриб, вместо этого ваш оппонент прикрепляет 5 Ядовитых грибов в вашей колоде за каждую единицу урона.","","Глубоко под улицами Зауна ты то, что ты ешь.","Место силы",[],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"07PZ015":["Эпическое хлам-устройство","Чтобы сыграть эту карту, потратьте всю ману. Призовите карту Бешеный утилятор и увеличьте ее характеристики до того же значения.","","\"Наипервейшая обязанность ученого – контролировать переменные. В нашей области изучения последствия непредвиденных случаев... Ох, без содрогания и думать об этом не могу!\" – Профессор Хеймердингер","Заклинание",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"07NX028":["Капитан Келрикс","Удар по нексусу: нанесите вражескому нексусу урон, равный половине его здоровья (значение округляется вверх).","","Ноксус – империя, созданная прежде всего для захвата земель. Дерево, камень, сталь – ничто не остановит напор ноксианского тарана.","Боец",[],["Ноксус"],"ЭПИЧЕСКОЕ"],"07NX034":["Алый пиршественный зал","Стоимость союзников снижается на 1. Разыгрывая союзника, нанесите ему 2 ед. урона.","","\"Проходите, друзья мои, рассаживайтесь! Общество нынче приятное, а напитки текут рекой. Жду не дождусь, когда вы узнаете, что у нас приготовлено на ужин\".\n– Владимир","Место силы",[],["Ноксус"],"ЭПИЧЕСКОЕ"],"07NX032":["Фолиант Рейвенблум","Когда мой носитель разыгрывает способность, скопируйте ее.","","Школа Рейвенблум была специально отремонтирована для хранения текстов, многие из которых в итоге сгорели в ревущем пламени, разожженном одним особо проблемным учеником...","Снаряжение",[],["Ноксус"],"РЕДКОЕ"],"07NX033":["Костешкурый троехвост","Призвав меня, даруйте мне +1|+1 за каждый отдельный подтип, имеющийся у союзников.","","\"Осторожней, тупицы! Ноксианцы купят бойцовых зверей только в идеальном состоянии. За каждую царапинку буду вычитать из вашего жалованья!\"\n– Торговец крупной дичью","Боец",["КОШКА"],["Ноксус"],"ОБЫЧНОЕ"],"07RU015":["Король поро","Исток: Указ Короля Поро.\nВпервые призвав поро в каждом раунде, создайте в руке Поро-снэк.","Вы призвали 6+ других новых поро. Когда мой уровень повышается, создайте в руке случайный Особый снэк.","Ингвар способна сходу распознать потенциал. Если не обращать внимания на импровизированный образ, то ясно, что этот милый питомец легко мог бы править сикстиллионом триллионов поро. При должной силе воображения, конечно. ","Боец",["ПОРО"],["Рунтерра"],"Чемпион"],"07RU012":["Нико","Исток: Разнообразные лесные друзья!\nРазыгрывая карту: вы можете замаскировать меня как 1 из 3 сторонников стоимостью 2 из моего Истока.","Атака: вы отправили в атаку союзников, имеющих 6+ разных подтипов.","Нико способна принять множество обличий, но веление сердца неизменно: ее всегда тянет обратно в лес, к семье.","Боец",["ПЕРЕВЕРТЫШ"],["Рунтерра"],"Чемпион"],"07BW043":["Приливные чары","Нанесите бойцу 1 ед. урона. Используйте Порождение x1 за каждую единицу нанесенного урона.","","Подчинять стихии своей воле могут лишь самые сведущие.","Заклинание",["СТИХИЯ"],["Билджвотер"],"РЕДКОЕ"],"07BW035":["Плутовское логово","Карты у вас в руке становятся мимолетными.\nСыграв карту, вытяните 1 карту.","","\"Полагаю, ты помнишь, что у тебя в руке, и бережешь это. Иначе готовься потерять все подчистую\". – Твистед Фэйт","Место силы",[],["Билджвотер"],"ЭПИЧЕСКОЕ"],"07BW042":["Палубный охотник","Разыгрывая карту: воплотите сторонника, чей подтип отличен от подтипов союзников на поле боя.","","\"Знаете, зачем нам нужен этот растрепанный заморыш? При нем у нас никаких проблем с крысами!\" – Матрос с \"Кошмара\"","Боец",["КОШКА"],["Билджвотер"],"ОБЫЧНОЕ"],"07BW039":["Гринзо, Принц-дракон","В каждом раунде, впервые призывая союзника стоимостью 1, восполните 1 ед. маны заклинаний.","","\"Господин Ящер, что вы тут делаете? Вам тоже нравятся поро?!\" – Ингвар младшая","Боец",["ДРАКОН"],["Билджвотер"],"РЕДКОЕ"],"07BW033":["Песнь сирен","Призовите случайную оболочку.\nДаруйте +1|+1 союзникам стоимостью 1 везде.","","Когда на море опускается тишайшая ночь, некоторые билджвотерские моряки затыкают уши ватой. Им прекрасно известно, что музыка, льющаяся из-под воды, не сулит ничего кроме могилы на дне.","Заклинание",[],["Билджвотер"],"ОБЫЧНОЕ"],"07IO041":["Целительный ветер","Восстановите 3 ед. здоровья своему нексусу и вытяните 2 карты заклинаний.","","\"Только ветер путнику союзник\". – Ясуо","Заклинание",["СТИХИЯ"],["Иония"],"ОБЫЧНОЕ"],"07IO043":["Всевидящий оракул","Разыгрывая карту: выберите 1 из 3 быстрых или медленных заклинаний в руке или колоде оппонента. Создайте для него карту Гадательные палочки.","","Око, что не связано материальным миром, видит все. Пусть оракул кажется слепым – но те, кто принимают его за легкую мишень, получают мгновенный и беспощадный отпор.","Боец",[],["Иония"],"РЕДКОЕ"],"07IO049":["Эйрис","Удар по нексусу: призовите случайную Оболочку.","","\"Тс-с-с, мы почти на месте. Говоришь, что хочешь познакомиться с моей подругой, так ведь? Поверь мне – ты ей наверняка понравишься\".","Боец",[],["Иония"],"РЕДКОЕ"],"07SH038":["Пакаа-детеныш","Засада 1\nУдар по нексусу: призовите карту Пакаа-защитница.","","Милая внешность – часть облика, а вот свирепость – уже инстинкт. Со временем, обучившись всему, даже самые маленькие пакити становятся сильными и дикими.","Боец",["КОШКА"],["Шурима"],"ОБЫЧНОЕ"],"07SH041":["Рекогносцировка","Воплотите карту с Засадой.","","Разведка в джунглях – наименее приятное занятие. Всего по одной причине: многовато неожиданностей.","Заклинание",[],["Шурима"],"РЕДКОЕ"],"07SH004":["Крадущийся зверь","Дайте союзнику +2|+0 до конца раунда. Если это карта Тень в кустах, вместо этого дайте ему +2|+2.","","\"Ступайте мягко, пакити. Разите метко\". – Нидали","Заклинание",[],["Шурима"],"ОБЫЧНОЕ"],"07SH013":["Нидали","Засада 2","На моих глазах вы призвали или превратили 4 других союзников.","\"Я всегда буду защищать тебя, ящерка. Браконьеры нам за все заплатят. Если мы будем вместе\". – Нидали","Боец",["КОШКА"],["Шурима"],"Чемпион"],"07SH009":["Мстительный вастайи","Засада 3\nПревратив меня из карты Засада Мстительного вастайи, остановите все вражеские способности, а также быстрые и медленные заклинания.","","\"Не бойтесь, малыши. Я защищу вас – и тем уплачу свой долг Нидали\".","Боец",[],["Шурима"],"ОБЫЧНОЕ"],"07SH039":["Штурмовик-внедорожник","Засада 0\nПризвав или превратив меня, даруйте слабейшему врагу Уязвимость.","","\"Здешние красоты даже новичка превратят в профессионала, карабкающегося по деревьям и прыгающего по валунам. Попасть сюда стоило целое состояние, но я уверен, что смогу отбить долги благодаря паре-тройке шкур местных редких зверьков...\"","Боец",[],["Шурима"],"РЕДКОЕ"],"07SH044":["Сияющий морок","Засада 4\nПревратив меня, призовите карту Сияющий морок.","","\"Как бы мне хотелось самой это увидеть! Большинство путешественников считают, что Сияющий морок – это миф, но один молодой человек клянется, что все наоборот. Он утверждает, что это птица ярчайшей расцветки с размахом крыльев, примерно равным росту взрослого человека. Однажды вечером он поведал мне, что посмотрев в глаза птицы, ты понимаешь, что добыча здесь – это ты\". – Выдержки из дневника Ануры, День 21","Боец",["ПТИЦА"],["Шурима"],"РЕДКОЕ"],"07SH003":["Браконьер-дирижаблист","Засада 3\nПревратив меня из карты Засада Браконьера-дирижаблиста, в следующий раз, когда в этом раунде блокирую я или блокируют меня, плените моего противника.","","\"Ха! Теперь попробуйте достать меня, глупые звери. Высшему виду и земное притяжение нипочем!\"","Боец",[],["Шурима"],"ЭПИЧЕСКОЕ"],"07SH011":["Ловушка в зарослях","Призывая меня или впервые превращая союзника в каждом раунде, даруйте слабейшему врагу Уязвимость.","","\"В воздухе кровь\". – Нидали","Место силы",[],["Шурима"],"ОБЫЧНОЕ"],"07SH046":["Долина Имитации","Разыгрывая сторонника, превратите меня в его точную копию до конца раунда.","","\"А тут у нас САМЫЙ П'Е-К'А-А-А-АС-НЫЙ и всеми йюбимый пункт на ма'ш'уте нашей экску'сии. Очень многим йюдям так пон'авийись мои экску'сии, что они пост'оийи ОГ'О-О-О-О-О-ОМНОГО К'УТЕЦКОГО СКОЛА, кото'ый навечно будет важным пунктом экску'сии. Давайте поздо'оваемся – все вместе скажем: П'ИВЕ-Е-Е-ЕТ, ОГ'ОМНЫЙ СКОЛ! Ог'омный Скол йюбит ВСЕХ-П'ЕВСЕХ, а о-со-би-сто – всех тех йюдей, кото'ые п'ошйи всю экску'сию до конца\". – \"Путешествия со Сколом\", часть VI","Место силы",[],["Шурима"],"ОБЫЧНОЕ"],"07SH043":["Огромный хоботач","Засада 5","","Некоторые утверждают, что хоботачи, старейшие обитатели этих мест, хранят в себе память и душу самих джунглей. Обычно это смирные существа, но в случае любой опасности они не раздумывая защитят свой дом. ","Боец",[],["Шурима"],"ЭПИЧЕСКОЕ"],"07SH040":["Иглоносец","После превращения первого союзника даруйте мне +2|+1.","","\"Небольшие всеядные млекопитающие, покрытые щетиноподобными иголками, которыми они могут активно отстреливаться в случае опасности. Хвост колючий и подвижный; возможно, используется как орудие самозащиты. Если верить бывалым путешественникам, эти существа славятся своей неуживчивостью и не даются в руки...\" – Выдержки из дневника Ануры, День 3","Боец",[],["Шурима"],"РЕДКОЕ"],"07SH005":["Торговец крупной дичью","Разыгрывая карту: воплотите карту с Засадой.\nПревратив союзника, удвойте его силу и здоровье.","","\"КТО-КТО у вас все отобрал?! Ученая с рептильной образиной? И чего вы тогда тут стоите, шуты гороховые? Ну-ка бегом возвращайте мои денежки!\"","Боец",[],["Шурима"],"РЕДКОЕ"],"07FR011":["Храм Истинного льда","Призывая союзника, увеличьте его здоровье до значения его силы.","","Хотя назначение этого храма давно кануло во тьму веков, его каменный страж все еще бдит, не сломавшись под гнетом множества лавин. Покрывшись изморозью, он словно пронизан каким-то необычным и притягательным светом.","Место силы",[],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"07FR010":["Снежный когтехват","Разграбление: увеличьте характеристики союзника до моих значений.","","Хотя снежный когтехват охотится в основном на мелких млекопитающих, у этого фрельйордского зверя хватит остроты когтей, чтобы кого угодно превратить в еду.","Боец",["ПТИЦА"],["Фрельйорд"],"ОБЫЧНОЕ"],"07FR015":["Ингвар Младшая","Разыгрывая карту: выберите союзника. Даруйте +1|+1 ему и всем остальным союзникам, имеющим тот же подтип, или воплотите сторонника, имеющего тот же подтип, что у союзника.","","Ингвар – самоназначенная смотрительница поро и исследовательница Фрельйорда. Она уверена, что приключения ждут неподалеку – и скоро отыщутся. ","Боец",[],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"07FR017":["Кристаллический буреклюв","Разыгрывая карту: нанесите 2 ед. урона ВСЕМ остальным бойцам.","","Ярость кристаллического буреклюва неразборчива и молниеносна. Она способна перевернуть ход битвы за считанные мгновения. Многие считают эту птицу первым предзнаменованием сильной и страшной бури – одной из тех, что могут встряхнуть нутро земли.","Боец",["ПТИЦА"],["Фрельйорд"],"РЕДКОЕ"],"07FR016":["Ледниковый ящер","Призвав меня, даруйте 3 верхним бойцам в вашей колоде +1|+1. Если подтип союзника отличен от моего, вытяните 1 из этих бойцов.","","Внутри костистого тела скрыто огромное сердце. Эти надежные скакуны неоценимы при расчистке обледеневших горных дорог.","Боец",["РЕПТИЛИЯ"],["Фрельйорд"],"РЕДКОЕ"],"07SI010":["Некротический мизгирь","Призвав меня, призовите 2 Некротических выводка. Когда погибнет другой союзник, истощите вражеский нексус на 1 ед. здоровья.","","Эти пауки обитают лишь в самых темных пределах Сумрачных островов, вырабатывая смертельный трупный яд, от которого коченеет кожа и тут же загнивает плоть.","Боец",["ПАУК"],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"07SI012":["Клокастый сетеплет","Разыгрывая карту: если подтип союзника отличен от моего, дайте врагу -2|-0 до конца раунда.","","Клокастые сетеплеты мастерят свои сети с великим прилежанием. Они обожают выводки своих детенышей... но становятся весьма злобными, когда им кто-то угрожает.","Боец",["ПАУК"],["Сумрачные острова"],"ОБЫЧНОЕ"],"07SI013":["Разрастающийся призрак тьмы","Предсмертный вздох: создайте в колоде точную копию сильнейшей из ваших карт Разрастающийся призрак тьмы в колоде, после чего удвойте характеристики Разрастающихся призраков тьмы в колоде.","","\"Этот туман меня многому научил. Самый важный его урок – это то, что теперь я знаю, когда нужно убегать\".\n– Страж Ишталя","Боец",[],["Сумрачные острова"],"РЕДКОЕ"],"07SI004":["Пресвятые ножницы","Атака: когда другой союзник получает усиление Благих, его получает и мой носитель.","","\"Имея хорошие ножницы и качественные нитки, можно починить почти все что угодно!\" – Гвен","Снаряжение",[],["Сумрачные острова"],"РЕДКОЕ"],"07MT009":["Эра драконов","Просмотрите 9 верхних карт своей колоды, вытяните каждого дракона и снизьте их стоимость до 0 до конца раунда. Остальные карты замешайте в колоду.","","\"Знать одного дракона значит владеть собой. Знать многих драконов значит владеть миром\". – Оттрани, Чтящая драконов","Заклинание",[],["Таргон"],"РЕДКОЕ"],"07MT013":["Космический зов","Позовите творение небес стоимостью 7 или более либо выплатите 8 ед. маны, чтобы наполовину снизить стоимость ваших творений небес везде (с округлением в большую сторону).","","Судия вовеки пребывает в созерцании, наблюдая за тем, как нисходит благословение небес.","Заклинание",[],["Таргон"],"ОБЫЧНОЕ"],"07MT006":["Злополучные влюбленные","Разыгрывая карту: верните союзника и даруйте ему мои характеристики.","","\"Мало есть примет столь же красноречивых, как встреча солнца и луны\". – Диана","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"07BC020":["Господин Скопидом","Когда активируется одна или несколько ваших ловушек или поощрений, прикрепите 2 из них в колоде того же игрока.","","Никто не знает, как давно Господин Скопидом собирает свою коллекцию. Никто не знает, откуда он вообще взялся. Выглядит он довольно дружелюбно – если не обращать внимания на небезопасную тропинку из непредсказуемых штуковин, которую он оставляет за собой.","Боец",[],["Бандл Сити"],"РЕДКОЕ"],"07BC016":["Неразменный гайковерт","Сбросив меня, снарядите мной случайного союзника без снаряжения.","","\"Врать не буду – иногда я теряю свои инструменты. Впрочем, вот эта штука всегда окажется под рукой, когда в ней есть надобность!\" – Пожарный инспектор","Снаряжение",[],["Бандл Сити"],"ОБЫЧНОЕ"],"07BC018":["Порталовед","Призвав меня, прикрепите Таинственный портал к 1 из 4 верхних карт в своей колоде.\nПризвав созданного союзника, даруйте ему Таран.","","В начале любого исследования не обойдется без сюрпризов. К счастью, этот благоприятен. ","Боец",["ФАЭ"],["Бандл Сити"],"ЭПИЧЕСКОЕ"],"07BC011":["Свирепые пушистики","Призвав меня, даруйте остальным союзникам, у которых есть подтипы, +1|+1 и Таран.","","Безобидны они только с виду – к несчастью этой бригады пилтоверских браконьеров.","Боец",["ПТИЦА"],["Бандл Сити"],"ОБЫЧНОЕ"],"07DE014":["Дотошный сержант","Разыгрывая карту: выберите бойца из 5 верхних карт вашей колоды стоимостью до 3. Призовите его и уберите остальные карты в вашу колоду.","","На демасийского сержанта возложена немалая ответственность. Впоследствии его рекруты займут многие важные должности – а объединит их долг и любовь к Демасии.","Боец",["ЭЛИТА"],["Демасия"],"ЭПИЧЕСКОЕ"],"07DE015":["Хохлатый львиноястреб","Разыгрывая карту: если подтип союзника отличен от моего, воплотите демасийское заклинание.","","\"Запись номер один подтверждает первое за пятьдесят лет появление львиноястреба. Прекрасный синий хохолок, умные глаза. На теле есть броня, однако кости достаточно тонкие, чтобы лазать по деревьям, а возможно, даже планировать в воздухе. Строение крыльев очень походит на демасийского среброкрыла. Предстоит выполнить новые замеры\". – Выдержки из дневника Ануры, День 12","Боец",["ПТИЦА"],["Демасия"],"РЕДКОЕ"],"07DE011":["Охотник на магов – новичок","Заклинания стоимостью ниже 3 вместо этого имеют стоимость 3.","","\"Молчать! Ты заявляешь, что это не более чем игра, но нет – это прикрытие для коварного мистического действа. Я намереваюсь разоблачить тебя как обманщика и чародея, подлый ты старикан, даже если для этого мне придется спалить дотла все это строение!\"","Боец",[],["Демасия"],"ОБЫЧНОЕ"],"07DE016":["Бален Великодушный","Атака: даруйте +0|+1 остальным громадным союзникам везде.","","Глядя на то, как огромен Бален, давний товарищ семейства Дюран, трудно поверить в то, что он еще и аккуратнейший мастер. Хотя начинал Бален помощником, он достиг высот в своем ремесле. Творит он с редкостным вдохновением, так что Дюраны гордятся дружбой с ним.","Боец",[],["Демасия"],"ЭПИЧЕСКОЕ"],"08SI042":["Мордекайзер","Разыгрывая карту: убейте до 2 союзников.\nСразив другого союзника, воскресите его.","Погибло 15+ союзников. Союзники с силой 5+ считаются за двоих.","Пока Мордекайзер был прикован к своим доспехам, что хранятся в самом сердце Бессмертного бастиона, он изготовил для себя трон правителя Серого царства. На каждого, кто попытается его одолеть, найдется множество тех, кто станет служить ему при жизни и после смерти.","Боец",[],["Сумрачные острова","Ноксус"],"Чемпион"],"08SI040":["Эрастин Опальный","Призвав меня, даруйте мне Посмертие.\nАтака: дайте врагам -1|-0 до конца раунда.","","Камаворские драконы некогда были величественными и почитаемыми – но даже они не смогли противиться всепожирающей порче Погибели. Эрастин не стал исключением. Его давно утраченный царственный облик превратился в безумную наружность жителя посмертия.","Боец",["ДРАКОН"],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"08SI007":["Легион Растерзанных","Разыгрывая карту: даруйте союзнику в руке Посмертие.","","Неважно, какую форму приняли души перед тем, как угодить в плен Серого царства. Личность там почти ничего не значит. Став безликим и бесстрашным, Легион еще лучше служит Железному призраку.","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"08SI003":["Навь прикованная","Предсмертный вздох: при следующем воскрешении союзника создайте в руке мою копию.","","\"Нас сковали цепями давным-давно. Вскоре и вы познаете наши страдания, и все мы будем мучиться веки вечные – пока длань Хозяина не дарует нам блаженство забытья...\"","Боец",[],["Сумрачные острова"],"РЕДКОЕ"],"08SI021":["Одинокий Слизнезвон","Предсмертный вздох или когда умирает другой союзник: прикрепите в вашей колоде 4 Колокольчика.","","Не переживайте из-за этого зловещего позвякивания. Это просто старый Слизнезвон совершает свой обход. Он всегда рад вновь прибывшим, но вот они его видеть точно не рады.","Боец",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"08SI030":["Могила под водой","Уничтожьте 6 карт снизу вражеской колоды.","","Для некоторых глубоководных чудовищ Рунтерры рыболовное судно – просто легкая закуска.","Заклинание",[],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"08SI037":["Призрачный сталепес","Чтобы сыграть меня, убейте союзника.\nПризвав меня, призовите карту Тысячецапый смертоверт.","","Эти псы никогда не собьются со следа того, кто попытался убежать. Когда жертва будет загнана в угол, смертоверт окажется неподалеку.","Боец",[],["Сумрачные острова"],"РЕДКОЕ"],"08SI041":["Смертельная хватка","Убейте союзника, чтобы нанести бойцу 5 ед. урона.","","\"Тьма – вот что ждет каждого кроме меня\".\n– Мордекайзер","Заклинание",[],["Сумрачные острова"],"ОБЫЧНОЕ"],"08SI036":["Преддверие Серого царства","Разыгрывая карту: прокляните врага с помощью карты Ужас.\nПризвав титанического союзника, разрушьте меня, чтобы вытянуть 2 карты.","","\"Эти души мы жертвуем тебе. Этот путь мы устелем костями для тебя. Эти царства мы разорвем на куски, дабы проложить дорогу твоему войску из неразрушимого металла\". – Культистка Смертельной хватки","Место силы",[],["Сумрачные острова"],"РЕДКОЕ"],"08SI004":["Царство смерти","Союзник идет в самостоятельную атаку, выбирая противником сильнейшего врага.\nУбейте ВСЕХ остальных бойцов.","","\"Смерть – вот моя вотчина\". – Мордекайзер","Заклинание",[],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"08SI026":["Культистка Смертельной хватки","Призвав меня или титанического союзника, прокляните сильнейшего врага с помощью карты Ужас.","","В глазах своих приверженцев Железный призрак – единственная надежда тех, кто ищет забытья. Мир воцарится с обретением владычества. Культисты желают этого всей душой.","Боец",[],["Сумрачные острова"],"РЕДКОЕ"],"08SI018":["Призрачный землемер","Разыгрывая карту: выберите заклинание Исследователя, чтобы создать его в руке.","","\"Эта местность мне непонятна. Видимость здесь почти нулевая. Врагов я тут встречаю на каждом шагу. Но что странно – попадаются и неожиданные союзники\". – Из записок экспедиции, снаряженной Подразделением Дальних Краев Гильдии Исследователей, пункт назначения: Сумрачные острова","Боец",[],["Сумрачные острова","Таргон"],"РЕДКОЕ"],"08SI015":["Слияние нечистых обрядов","Чтобы сыграть меня, убейте союзника.\nПредсмертный вздох: восстановите 2 ед. здоровья своему нексусу.","","Боевые чудовища ценятся в любом войске. В Сером царстве они представляют собой совокупности измученных душ, каждая из которых в своем бесчувствии жестока и разрушительна. ","Боец",[],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"08BW008":["Нила","Атака: создайте карту Нырок среди 6 верхних карт в вашей колоде.","Вы вытянули 15+ карт.","На севере Нилу и ее команду охотников на монстров ждет новый вызов – существо по имени Волибир, угрожающее разрушить Фрельйорд, который некогда ему поклонялся. Этот шанс проверить себя в схватке с монстром, которого другие называют богом, для Нилы стал главной в жизни целью. И это не говоря уже о чудовищах помельче, которых она попутно добавит в свой список достижений. ","Боец",[],["Билджвотер"],"Чемпион"],"08BW032":["Безграничная радость","Дайте союзникам +1|+0 до конца раунда и восстановите раненым союзникам по 2 ед. здоровья.","","\"Радость, бьющая ключом и непреходящая!\" – Нила","Заклинание",["СТИХИЯ"],["Билджвотер"],"ОБЫЧНОЕ"],"08BW038":["Плясунья с шакрамом","Разыгрывая карту: нанесите 1 ед. урона любой цели.\nВаши способности истощают.","","Она кружится в пляске воды и клинков, извлекая сталь из скопища пены и брызг. Ей не нужно зрение, чтобы разить врагов: ее оружие – ожившая вода и вечно пребудет водой.","Боец",[],["Билджвотер"],"ЭПИЧЕСКОЕ"],"08BW015":["Танцующая на волнах","Призвав меня, вытяните карту Нила.\nВ каждом раунде, разыгрывая свою третью карту, дайте остальным союзникам +2|+0 и Вспыльчивость до конца раунда.\nВместо того чтобы обрести Мимолетность, разоблачите меня.","","\"Ходят слухи, что этот странноватый корабль – самый быстрый из всех, что видел Билджвотер. Еще и маневренный. Капитанша у него своеобразная, но сдается мне – она свое дело знает туго. Может, попозже еще что-то узнаем\". – Билджвотерский бартендер","Боец",[],["Билджвотер"],"ЭПИЧЕСКОЕ"],"08BW002":["Хлесткий клинок","Нанесите 2 ед. урона бойцу. Его здоровье не может опуститься ниже 1 ед.","","\"Монстрам, что называют себя богами, предстоит долго падать – в любой стране\". – Нила","Заклинание",["СТИХИЯ"],["Билджвотер"],"ОБЫЧНОЕ"],"08BW025":["Главный впередсмотрящий","Вытянув в этом матче 3+ карты за раунд, даруйте мне +1|+1 и Вспыльчивость.","","\"Эй, дружище, что за переполох? Расслабься! В воде нет ничего такого, с чем бы мы не справились!\" – Служитель Вызова","Боец",[],["Билджвотер"],"ОБЫЧНОЕ"],"08BW026":["Служитель Вызова","Призвав меня, примените Порыв, чтобы даровать мне +1|+1 за каждую карту, к которой был применен Порыв, и вытяните 2 карты.","","\"Ой, да ладно, ты даже не стараешься! Ощущение, будто мне приходится сдерживать себя! Дурацкое ощущение!\"","Боец",[],["Билджвотер"],"РЕДКОЕ"],"08BW028":["Осьми-авантюрист","Разыгрывая карту: выберите заклинание Исследователя, чтобы создать его в руке.","","\"Причудливый экземпляр. Очень синий. Глаза довольно большие. Неприятно большие. Принимаем для дальнейшего изучения\". – Из записок экспедиции, снаряженной Подразделением Дальних Краев Гильдии Исследователей, пункт назначения: Пилтовер","Боец",[],["Билджвотер","Пилтовер и Заун"],"РЕДКОЕ"],"08BW009":["Престарелый кормчий","Разыгрывая карту: воплотите два разных стихийных заклинания, сыгранных вами в этом матче. Их стоимость равна 0 до конца раунда.","","\"Разум подобен реке. За долгое время его упорное течение способно стереть с лица земли даже гору. И разум точно так же способен в мгновение ока разлиться вширь и достичь новых берегов\".","Боец",[],["Билджвотер"],"РЕДКОЕ"],"08BW010":["Наводнение","До конца матча все ваши стихийные заклинания и способности наносят на 1 ед. урона больше.","","\"В руках мудреца вода примет любую форму\".\n– Служитель Мудрости","Заклинание",["СТИХИЯ"],["Билджвотер"],"ЭПИЧЕСКОЕ"],"08BW031":["Сефирса, Кара из глубин","Потратив ману на розыгрыш другого бойца, создайте в руке случайную карту той же стоимости. Ее стоимость равна 0, она мимолетная.","","Есть кое-какие монстры, на которых не охотятся даже опытнейшие билджвотерские капитаны – несмотря на желание добыть даже самых необыкновенных морских чудищ. Упоминая Сефирсу, мореходы приглушают голос и рассказывают о чарующем свете, пробивающемся из глубин сквозь толщу волн. Говорят, это чудовище громоздится на огромном могильнике из затопленных кораблей и погибших моряков.","Боец",["МОРСКОЕ ЧУДОВИЩЕ","ДРАКОН"],["Билджвотер"],"ЭПИЧЕСКОЕ"],"08BW037":["Правдивый крупье","Разыграв карту, стоимость которой равна моей силе, даруйте мне +1|+1.","","\"Скажите-ка, вы... ну как бы... не хотите поставить побольше? Без риска нет награды, сами знаете. Сегодня это счастливый стол, вот что я хочу сказать. И в этом милом заведении игра ведется честно. Клянусь языком моей матушки!\"","Боец",[],["Билджвотер"],"РЕДКОЕ"],"08BW036":["Рифовый шпиль мараи","Потратив ману, чтобы разыграть бойца, восполните 1 ед. маны заклинаний.","","\"Этот риф издавна был убежищем и союзником. Он заботится о нас, а мы – о нем, чтобы никто из нас не утонул во тьме Мрака\". – Праматерь мараи","Место силы",[],["Билджвотер"],"ОБЫЧНОЕ"],"08BW023":["Викраш Жизнерадостный","Призвав меня, создайте карту Нырок среди 6 верхних карт в вашей колоде.","","\"Поглядите, друзья мои, как весь мир движется вместе с нами! Волны пляшут под днищем, ветер надувает паруса, в воздухе порхают птицы. Присоединяйтесь ко мне, услышьте высший зов – и возрадуйтесь!\"","Боец",[],["Билджвотер"],"ЭПИЧЕСКОЕ"],"08PZ007":["Ветропевчая стая","Призовите карту Ветропевчая ласточка и даруйте ей +1|+1 за каждое другое стихийное заклинание и каждую стихийную способность, разыгранную вами в этом матче.\nВытяните 1 карту.","","Когда ветропевчие ласточки собираются в стаю, это значит, что буря не за горами.","Заклинание",["СТИХИЯ"],["Пилтовер и Заун"],"РЕДКОЕ"],"08PZ031":["Затемненные очки","Выберите союзного сторонника. Превратите моего носителя в его точную копию, снаряжая его мною.","","Не спрашивайте, как это работает.","Снаряжение",[],["Пилтовер и Заун"],"РЕДКОЕ"],"08PZ025":["Поробот-прототип","Предсмертный вздох: даруйте случайному заклинанию стоимостью 6+ в руке особенность \"Разыгрывая меня, призовите карту Поробот-прототип\".","","\"Это всего лишь прототип! – закричал подмастерье, когда по лаборатории разбежалось пламя. – Чтобы он съедал все шестеренки вокруг – такого в программе не заложено! Я даже не знаю, куда ОН ЭТО ВСЕ ДЕВАЕТ!\"","Боец",["ПОРО"],["Пилтовер и Заун"],"РЕДКОЕ"],"08PZ005":["Око бури","Дайте союзнику +2|+0 до конца раунда.\nВытяните 2 карты.","","\"Примирись с собой! Буря может яриться вокруг тебя, но вреда тебе не причинит\". – Жанна","Заклинание",["СТИХИЯ"],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"08PZ019":["Божественный смерч","Если в этом раунде вы вытянули 3+ карты, моя стоимость снижается на 2.\nНанесите 3 ед. урона бойцу и 2 ед. урона вражескому нексусу.","","\"В храме распоряжаюсь я\". – Жанна","Заклинание",["СТИХИЯ"],["Пилтовер и Заун"],"РЕДКОЕ"],"08PZ028":["Химтековый дракон","Разыграв заклинание, вытяните 1 карту. Если вы вытягиваете карту, имея полную руку карт, нанесите 1 ед. урона вражескому нексусу.","","В Зауне без адаптации никуда. Не исключение и этот химтековый дракон, переливающийся болезненным зеленым светом аугментаций и обитающий в самом чреве города. Двойная тень от обломанных крыльев дракона скользит вдоль мрачных переулков словно предвестница ярости, порожденной муками от собственной скверны.","Боец",["ДРАКОН"],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"08PZ001":["Жанна","Разыгрывая карту: примените Порыв x2, чтобы вытянуть 2 карты в начале следующего раунда.\nКогда вы вытягиваете каждую из 3 первых карт за раунд, снижайте ее стоимость на 1 до конца раунда.","На моих глазах вы разыграли 8 карт со сниженной стоимостью.","\"Из Зауна добраться до Жанны будет проще, чем откуда-либо еще. В конце концов, это же она спасла тех бедолаг, что пилтоверцы бросили помирать. Точно. Если где и сыщутся ответы, то только там\". – Моряк-ветрогон","Боец",[],["Пилтовер и Заун"],"Чемпион"],"08PZ026":["Ветропевчий зов","Призовите карту Ветропевчая ласточка.","","\"Все дети ветра отвечают на мой зов\". – Жанна","Заклинание",["СТИХИЯ"],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"08PZ006":["Ясцилла, Удильщица из глубин","Разыгрывая стихийное заклинание или способность, повторите их на тех же целях.","","\"Подходи, Ясцилла! Ты, должно быть, стара, раз Ашлеш знает твое имя. Что ж, старые, молодые, красивые, уродливые – мне все равно. Нет большей чести для чудовища, чем пасть от моего клинка в открытом море\". – Нила","Боец",[],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"08PZ018":["Моряк-ветрогон","Если в этом раунде вы вытянули 3+ карты, моя стоимость снижается на 2.","","\"Ага, у меня было все, чего я хотел. Но все это я получил захватом – и теперь ощущаю пустоту внутри. Ветер стал первой вещью, сумевшей позвать меня за собой, так что вот он я. Надеюсь, Жанна выведет меня на верную дорогу\".","Боец",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"08PZ008":["Марьям, Смотрительница храма","Разыгрывая карту: примените Порыв x1, чтобы либо вытянуть 1 карту, либо восполнить свою ману заклинаний.","","Марьям убеждена, что в детстве ее спас от смерти дух ветра. Теперь она проповедует благодетели Жанны на всем пространстве от родной Шуримы до Зауна. Она управляет заунским храмом и отдает все силы, чтобы доброта Жанны доставалась юным и угнетенным.","Боец",[],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"08PZ009":["Затопленный храм","Конец раунда: примените Порыв ко всем картам в руке.\nНачало раунда: вытяните столько же карт плюс 1.","","Очень многое было утрачено в итоге страшного обвала, окончательно отделившего Заун от Пилтовера. Пусть храм Жанны и сгинул в волнах, но зато она спасла людей, служивших в нем.","Место силы",[],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"08PZ002":["Воющий вихрь","Нанесите бойцу 2 ед. урона.\nУвеличьте наносимый мной урон на 1 ед. за каждую карту, разыгранную вами в этом раунде, но не более 3 раз.","","\"Ярость моя летит с воем ветра!\" – Жанна","Заклинание",["СТИХИЯ"],["Пилтовер и Заун"],"РЕДКОЕ"],"08PZ024":["Рыбник-пройдоха","Начало раунда: оба игрока вытягивают по 1 карте, затем даруйте карте противника Мимолетность.","","\"Сегодня две по цене одной – и только сегодня! Рыбка свежая, выловил прямо... в этом месяце вроде? Две по цене одной! То есть как это – \"не хочу вторую\"?  Бесплатно же!\"","Боец",[],["Пилтовер и Заун"],"ОБЫЧНОЕ"],"08PZ020":["Одухотворенный тучекрут","Если в этом раунде вы вытянули 3+ карты, моя стоимость снижается на 2.\nПризвав меня, вытяните 2 карты в начале следующего раунда.","","\"Мой дорогой Западный ветер. Спустись с облаков и посиди немного у меня на плече, ты же не против?\"\n– Жанна","Боец",[],["Пилтовер и Заун"],"РЕДКОЕ"],"08FR012":["Призыв Грома","Вытяните 1 карту.\nПризовите карту Сигил Бури.","","\"Именем Валхира мы приносим эту жертву...\"\n– Пророчица Валхира","Заклинание",["СТИХИЯ"],["Фрельйорд"],"ОБЫЧНОЕ"],"08FR033":["Берсерк-клиночник","Разыграв медленное заклинание, целью для которого выбран один союзник, повторите его на мне.","","\"Думаешь, пара стрел меня остановят? Ха! Все, что вы метнете в меня, станет моим собственным оружием. Все, что утрачено, я перекую в лед!\"","Боец",[],["Фрельйорд"],"ОБЫЧНОЕ"],"08FR019":["Громовержец","Дайте союзнику +1|+3 до конца раунда.","","Окутанный облаками и увитый молниями, бог-медведь остается невредимым в самом сердце бури.","Заклинание",["СТИХИЯ"],["Фрельйорд"],"ОБЫЧНОЕ"],"08FR001":["Волибир","Разыгрывая карту: 3 раза примените способность Неутихающая буря. Целью каждый раз выбирается случайный враг (всегда разный) или вражеский нексус (если врагов нет).","Конец раунда: вы нанесли 50+ ед. урона.","\"На колени предо мной, смертный! И тогда я, возможно, пощажу тебя! Твоя сила ничтожна, но может пригодиться в услужении. На колени! Или я сотру тебя с лица земли!\"","Боец",[],["Фрельйорд"],"Чемпион"],"08FR018":["Битва гигантов","Призовите 2 случайных титанических сторонников.\nМоя стоимость снижается на 1 за каждое стихийное заклинание или способность, разыгранную вами в этом матче (максимум 10).","","\"Из его туши я изваял горы. Огнем из его утробы я выплавил тысячи фьордов\". – Волибир","Заклинание",["СТИХИЯ"],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"08FR011":["Козлорогая огневестница","Разыгрывая стихийное заклинание или способность, примените ко мне Кузницу.","","\"Владыка кузницы обещал перемены, но вместо них он выковал цепи бездействия. Те, кто поклоняется слабому богу, сами слабы. Лишь могучая воля Валхира вернет нам былую славу!\"","Боец",[],["Фрельйорд"],"РЕДКОЕ"],"08FR008":["Вестник бури","Нанесите 4 ед. урона ВСЕМ бойцам кроме титанических союзников.","","\"Пусть по тундре разольется кровь!\" – Волибир","Заклинание",["СТИХИЯ"],["Фрельйорд"],"РЕДКОЕ"],"08FR024":["Ядулский снегопес","Атака: даруйте двум верхним союзникам в вашей колоде +1|+1.","","Хотя выведена порода в Ядулске, этих щенков приручают во многих фрельйордских племенах, ценящих их за нюх, охотничьи навыки и умение спасать попавших под лавину. За крепкий стан и дружелюбную игривость этих псов любят повсюду – от тайги до тундры.","Боец",["ПЕС"],["Фрельйорд"],"ОБЫЧНОЕ"],"08FR015":["Ронд, Магматический змей","Разыгрывая карту: призовите 3 Сигила Бури.","","Все фрельйордцы знают сказание о великой битве Волибира против Ронда – хотя самому Ронду нынче мало кто поклоняется. Задолго до того, как на промерзший Север пришли смертные, в итоге этой могучей схватки появились хребты и реки, пересекающие тундру.","Боец",[],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"08FR030":["Боадир из Черненого льда","Призвав меня, призовите 2 Ледяных рабов и продвиньте их счетчики до значения 2.","","\"Она была з-з-злобная! Рабы, впаянные в черный лед... В когтях у нее лавины... Рев такой, что снег с гор сшибает! Королева воинов, истинно вам говорю! Уб-б-б-бивать рабов – это работа для королевы воинов\". – Бормочущий Бьорг","Боец",["ДРАКОН"],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"08FR002":["Пророчица Валхира","Призвав меня, призовите Сигил Бури.","","\"Я вижу то, что другим не увидеть: бурю, что расколет гору, вывороченное нутро земли. Тот Фрельйорд, что был в старину, будет выкован заново. Это лишь вопрос времени\".","Боец",[],["Фрельйорд"],"ОБЫЧНОЕ"],"08FR028":["Удобная привязь","У меня +1|+0 за каждый отдельный подтип, призванный вами в этом матче.","","\"Наверху есть звери, которым и лавина не помеха. Вот почему добрая привязь всегда стоит своих денег\".\n– Зверолов из племени аваросан","Снаряжение",[],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"08FR003":["Урсин-берсерк","Разыгрывая заклинание или способность, призовите карту Сигил Бури.","","Временами поклоняющиеся Волибиру настолько забываются, что в своем беспредельном фанатизме сами начинают приобретать медвежий облик. Ничто не помешает исполнению воли Валхира – даже те, кого племя урсинов когда-то величало \"земляками\".","Боец",[],["Фрельйорд"],"РЕДКОЕ"],"08RU014":["Старший дракон","Исток: Сущность дракона.\nМоя стоимость снижается на 1 за каждое уникальное драконье поощрение, разыгранное вами в этом матче.\nРазыгрывая карту: примените ко мне все драконьи поощрения.","Ваши союзники атаковали с суммарным значением силы 75+.","\"Легенда гласит, что этот дракон – старейший из всех, что он царь всех крылатых тварей. Если мы укротим его... Что такое, Алатис, что еще может нам помешать? Весь мир наконец осознает, что человек и дракон вместе сильнее всего на свете\". – Воликс, драконий адепт","Боец",["ДРАКОН"],["Рунтерра"],"Чемпион"],"08NX003":["Разъяренный огнеплюй","Разыгрывая карту: нанесите 2 ед. урона врагу и 2 ед. урона вражескому нексусу.","","Ноксианская экспансия подмяла под себя множество народов, поселений и культур. Создания природы зачастую тоже оказываются во власти военной машины. Однако в случае с этим драконом любая решительная мера, принимаемая Ноксусом, натыкается на столь же яростную вспышку гнева.","Боец",["ДРАКОН"],["Ноксус"],"ЭПИЧЕСКОЕ"],"08NX024":["Железный легионер","Разыгрывая карту: нанесите союзнику 3 ед. урона, а затем 3 ед. урона врагу.","","\"Вырвите эти души из темниц их тел!\"\n– Мордекайзер","Боец",[],["Ноксус"],"РЕДКОЕ"],"08NX011":["Лесной пожар","Нанесите 1 ед. урона вражескому нексусу и увеличьте этот урон на 1 ед. за каждую разыгранную вами карту Лесной пожар. Создайте в своей колоде карту Лесной пожар.","","\"Пепел, пепел...\" – Энни","Заклинание",["СТИХИЯ"],["Ноксус"],"ОБЫЧНОЕ"],"08NX028":["Несокрушимый","Даруйте союзнику Посмертие.","","\"Вечный металл!\" – Мордекайзер","Заклинание",[],["Ноксус"],"ОБЫЧНОЕ"],"08NX019":["Красношипый острошкур","Удар по нексусу: прокляните противника с помощью карты Ихор.","","Острошкур не только приносит пользу военной машине Ноксуса, но и высоко ценится в бойцовых ямах столицы. Мало кто из людей или зверей осмеливается выйти на арену против этого чудища, и поэтому редкие бои с участием острошкура собирают толпы зрителей со всех концов города.","Боец",["РЕПТИЛИЯ"],["Ноксус"],"ОБЫЧНОЕ"],"08NX014":["Директриса Телси","Эффекты Атаки и Поддержки союзников активируются еще один раз.","","Отличительной особенностью курса личной дисциплины, который ведет Директриса Телси, является обилие неподъемных домашних заданий, оплеух и объяснительных записок. Для учащихся в школе Рейвенблум этот курс всегда был обязательным – иначе добровольно на него никто не записался бы.","Боец",[],["Ноксус"],"ЭПИЧЕСКОЕ"],"08NX012":["Вооруженный закупщик","Разыгрывая карту: выберите заклинание Исследователя, чтобы создать его в руке.","","\"Вы могли подумать, что в пустыне копать проще – но нет! Со временем песок неизбежно превращается в камень. Снова запрашиваем финансирование для покупки новых инструментов\". – Из записок экспедиции, снаряженной Подразделением Дальних Краев Гильдии Исследователей, пункт назначения: Шуримa","Боец",[],["Ноксус","Шурима"],"РЕДКОЕ"],"08NX029":["Подсечка Касури","Убейте бойца, если он ранен. Если нет, вместо этого нанесите ему 2 ед. урона.","","\"Это в ваших же интересах. Поверьте мне\". – Лорд Бродмейн","Заклинание",[],["Ноксус"],"ЭПИЧЕСКОЕ"],"08NX009":["Лорд Маллат","","","\"Целые века ушли на то, чтобы придумать, как пленить этого кошмарного воителя, – а теперь ваши жалкие друзья намереваются победить его какой-то там \"радостью\"? Ох и глупая же ты девчонка. Этим ты лишь навлечешь на себя гнев Призрака – и в то же время поставишь под удар нас всех\".","Боец",[],["Ноксус"],"ОБЫЧНОЕ"],"08NX025":["Пронзенный призрак","Воскресив союзника, даруйте ему Выбор противника.","","\"Ты улыбаешься, но я знаю, как вероломно твое сердце! Они улыбались мне и ели за одним столом со мной, даже когда уже задумали вонзить меч мне в спину. Теперь меня не провести. Ты умрешь так же, как остальные: с воплем раскаяния на устах!\"","Боец",[],["Ноксус"],"РЕДКОЕ"],"08SH009":["Древнее проклятие","Прокляните врага с помощью карты Ужас.","","Некоторым вещам лучше оставаться в толще песков.","Заклинание",[],["Шурима"],"ОБЫЧНОЕ"],"08SH014":["Рогатый вестник стаи","Разыгрывая карту: даруйте двум врагам -1|-0 и лишите их полезных навыков.","","Несмотря на внушительные размеры, вестник стаи редко нападает сам. Когда его стая появляется вблизи какого-нибудь шуримского поселения, жители выносят в прилегающую пустыню дары в виде сладких фруктов, чтобы отвлечь гостей от посевов на полях.","Боец",["ДРАКОН"],["Шурима"],"ОБЫЧНОЕ"],"08SH004":["Генерал дюн","День или при активации другого дневного эффекта: даруйте слабейшему врагу Уязвимость.","","Огромные шуримские армии готовы доказать могущество пустыни. Когда будет отдан приказ, они пойдут вперед без колебаний.","Боец",["ЭЛИТА"],["Шурима"],"РЕДКОЕ"],"08SH005":["Защитники Солнечного диска","День: вытяните карту Защитники Солнечного диска.","","\"Мы хранители вечно сущей пустыни, мы живая история, мы путники на сияющей дороге. Мы преклоняем колена пред Солнечным диском – и ни пред чем иным, так что пусть весь мир падет на колени пред сиянием шуримской славы\". – Азир","Боец",["ЭЛИТА"],["Шурима"],"ОБЫЧНОЕ"],"08SH012":["Барбара-Расхитительница","После гибели первого другого союзника в каждом раунде, а также Предсмертный вздох: создайте в руке карту Удачная находка.","","\"Вот это хабар что надо, Барб. Я знал, что на тебя можно положиться. Стоп... В каком это смысле \"тебя заметили\"?!\" – Векаурский воин","Боец",["РЕПТИЛИЯ"],["Шурима"],"РЕДКОЕ"],"08SH002":["Дюноглот","Чтобы сыграть меня, трижды убейте союзника или разрушьте свой кристалл маны.","","Дюноглот дремлет на куда большей глубине, нежели его более мелкие родичи зер'сай. Он известен тем, что легко съедает прочих хищников-зер'сай, однако случаев встречи с ним описано мало. Видимо, из-за того, что он способен проглотить целую дюну (а вместе с ней и всех очевидцев). ","Боец",[],["Шурима"],"ЭПИЧЕСКОЕ"],"08MT003":["Моргана","Разыгрывая карту: дважды прокляните врага с помощью карты Оковы.","Вы выбрали целью бойцов 10+ раз.","\"Ты пришла ко мне в синяках и порезах – и все равно выказывала невиданное торжество самообладания. Ты, без сомнения, странная женщина – но здесь ты в безопасности. Отдохни как следует, а когда поправишься – я охотно выслушаю твою историю\".","Боец",[],["Таргон","Демасия"],"Чемпион"],"08MT005":["Михира, Вознесшаяся сущность","Разыгрывая карту: дважды прокляните 2 врагов с помощью карты Оковы.","","\"Я приняла божественное обличье только во имя моих дочерей. Лишь ради семьи я отказалась от рода человеческого, чтобы этим пылающим мечом заново выковать мир правды и справедливости\".","Боец",[],["Таргон"],"ЭПИЧЕСКОЕ"],"08MT042":["Плен грешника","Прокляните врага с помощью карты Оковы.\nПовысьте стоимость вражеских Проклятий везде на 1.","","\"Чтобы обрести свободу, признай, что внутри живет тьма\". – Моргана","Заклинание",[],["Таргон"],"РЕДКОЕ"],"08MT024":["Рубиноокий заклинатель","Разыгрывая карту: даруйте союзнику в руке Щит от магии или Пробивание.","","\"Не бойся! Иди вперед и не оглядывайся! Когда-то мы тоже проделали этот путь. Теперь наш долг – помочь тебе пройти его. Скорее ступай в ее святилище – и Госпожа в вуали даст тебе защиту, которая тебе нужна\".","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"08MT045":["Закованный заклинатель","Разыгрывая карту: прокляните меня с помощью карты Оковы.","","Охотники на магов действительно умеют ломать людей. Они связали его и укротили его магию. Они забрали у него голос. Однако один раз он их уже пережил – а теперь на его стороне сама Госпожа в вуали.","Боец",[],["Таргон"],"РЕДКОЕ"],"08MT015":["Лиза и Долли","Разыгрывая карту: прокляните врага с помощью карты Оковы.","","\"Смотри, Долли! Я делаю ровно так, как ты меня учила! Как думаешь – получится когда-нибудь показать маме, сколько всего мы усвоили? Думаешь, она уже знает? Правда?! Надеюсь, ты права\".\n– Лиза","Боец",[],["Таргон"],"ОБЫЧНОЕ"],"08MT030":["Самоцветный дракон","Разыгрывая быстрое либо медленное заклинание или способность, даруйте остальным союзникам-драконам +1|+1.","","Характеры драконов могут различаться так же разительно, как и их облик. На каждый вид, склонный к самозабвенному разрушению, – вроде огненных дракончиков – найдется вид, оберегающий свою семью и окружающую местность — подобно тому, как это делает медлительный и доброжелательный самоцветный дракон.","Боец",["ДРАКОН"],["Таргон"],"РЕДКОЕ"],"08MT023":["Темные узы","Оглушите врага и прокляните его с помощью карты Оковы.","","\"Страдай так, как из-за тебя страдали другие!\" – Моргана","Заклинание",[],["Таргон"],"РЕДКОЕ"],"08MT031":["Оттрани, Чтящая драконов","Призвав меня, восстановите 2 ед. здоровья своему нексусу и получите дополнительный кристалл маны в следующем раунде.","","Одинокая оттрани, живущая высоко на склонах Таргона, посвятила свою жизнь драконам. Она украшает свое одеяние отпавшими чешуйками и древними костями, прокладывая себе путь в гору сквозь россыпь драконьих зубов и клубы дыма.","Боец",[],["Таргон"],"ЭПИЧЕСКОЕ"],"08MT009":["Таинственный защитник","Призвав меня или титанического союзника, восстановите вашему нексусу 3 ед. здоровья.","","Этот таинственный защитник не забыл то благословение, что вознесло его над прочими зверями. Он отплачивает за награду, делая путь безопасным для всех, кто ищет прибежища на склонах Таргона.","Боец",[],["Таргон"],"РЕДКОЕ"],"08MT006":["Черный щит","Дайте союзнику Щит от магии до конца раунда и прокляните его с помощью карты Оковы.","","\"Защита от преследования!\" – Моргана","Заклинание",[],["Таргон"],"РЕДКОЕ"],"08MT027":["Вестница Небесной конвергенции","Разыгрывая карту: активируйте дневные и ночные эффекты остальных союзников.\nДень: даруйте мне Пробивание.\nНочь: даруйте мне Щит от магии.","","\"Кольцо из огня пылает в вышине. В предсказанной тьме все мы одинаковы\". – Певец убывающей луны","Боец",["ПТИЦА"],["Таргон"],"ЭПИЧЕСКОЕ"],"08MT025":["Сейсмический осколок","Если вы владеете титаническим бойцом, моя стоимость снижается на 3.\nНанесите бойцу 7 ед. урона.","","\"Ай-яй, ой-ей-ей, не войнуйтесь насчет вот этого всего, п'осто майенькая т'ещина в скайах, небойшое п'оисшествие, это не Папа, НЕ-А! Впейод!\" – Скол","Заклинание",["СТИХИЯ"],["Таргон"],"ОБЫЧНОЕ"],"08DE006":["Образованный первопроходец","Разыгрывая карту: выберите заклинание Исследователя, чтобы создать его в руке.","","\"Очень холодно. Мне холодно. Вокруг все время холодно. Есть на свете места, где жить просто невозможно. Отправьте меня, пожалуйста, куда-нибудь, где тепло\".\n– Из записок экспедиции, снаряженной Подразделением Дальних Краев Гильдии Исследователей, пункт назначения: Фрельйорд","Боец",[],["Демасия","Фрельйорд"],"РЕДКОЕ"],"08DE020":["Волшебные путы","Даруйте союзнику +0|+2. Прокляните противника с помощью карты Подавление.","","\"Узнай тяжесть своих грехов!\" – Моргана","Заклинание",[],["Демасия"],"ОБЫЧНОЕ"],"08DE017":["Охотник на магов – инквизитор","Призвав меня, прокляните противника с помощью карты Подавление.","","\"Мы не можем позволить им добраться до святилища падшей сестры. Там живет ее древняя и мудреная магия, которую даже я не сумею подавить. Скорее отведите этих чудищ обратно на корабль, а потом идите в горы и догоняйте остальных!\"","Боец",[],["Демасия"],"РЕДКОЕ"],"08DE025":["Облачный дракон","Призвав меня, снизьте стоимость всех союзных бойцов в руке на 1.","","Благодаря пучкам плотной шерсти, предохраняющей от холода, этот дракон может забираться в куда более высокие слои атмосферы, нежели его сородичи. Эти драконы резвы и изворотливы. Чаще всего их можно увидеть в небесной вышине – взрезая крыльями облака, они перемещаются вместе с порывами шквалистого ветра.","Боец",["ДРАКОН"],["Демасия"],"ЭПИЧЕСКОЕ"],"08DE010":["Джентльменская дуэль","Дайте союзнику +0|+2 до конца раунда.\nЭтот союзник и враг наносят удар друг другу.","","\"К бою, друг мой! Вы же не из тех трусов, что избегают джентльменской дуэли?\" – Шевалье Лоранов","Заклинание",[],["Демасия"],"ОБЫЧНОЕ"],"08DE022":["Зимородок","Призвав меня, вытяните по 1 карте каждого чемпиона из своей колоды.\nВпервые призвав чемпиона в каждом раунде, примените Рвение.","","\"Всегда помни, сын мой, что путешествия к далекому горизонту должны совершаться лишь во имя родной страны, остающейся за спиною\". – Король Джарван III","Боец",[],["Демасия"],"ЭПИЧЕСКОЕ"],"08DE027":["Когтевой удар","Даруйте союзным птицам +1|+1 везде. Союзная птица наносит удар врагу.","","Клекот среброкрыла означает смерть, летящую с небес.","Заклинание",[],["Демасия"],"РЕДКОЕ"],"08DE026":["Алатис Величавый","Ваши драконьи поощрения действуют на всех союзных драконов.","","\"Честно говоря, я не всегда был драконьим адептом. Стать им меня убедил Алатис – когда впервые спас мне жизнь. Он многому меня научил, но знаешь, что самое важное? Нет житья краше, чем служба Демасии верхом на драконе\". – Драконий адепт","Боец",["ДРАКОН"],["Демасия"],"ЭПИЧЕСКОЕ"],"08DE013":["Драконий адепт","Призвав меня, вытяните дракона, если владеете драконом.","","\"Ты знаешь, мне больно это признавать, старина, но одни мы его не укротим. Мы уже сделали все, что могли. Я пошлю весточку генералу. Заручившись мощью Демасии, мы наверняка поставим этого фантастического зверя на колени\".","Боец",[],["Демасия"],"ОБЫЧНОЕ"],"08IO012":["Морской дракон","Разыгрывая быстрое либо медленное заклинание или способность, восстановите 1 ед. здоровья своему нексусу.","","\"Ты великий зверь! Столько радости в твоем скольжении над волнами! Если когда-нибудь ты решишь поохотиться на кого-то покрупнее, чем рыбы и морские птицы, я с удовольствием сойдусь с тобою в поединке\". – Нила","Боец",["ДРАКОН"],["Иония"],"РЕДКОЕ"],"08IO014":["Хейшо, Мировой панцирь","В каждом раунде стоимость первой разыгранной вами карты снижается на 9.","","Для обитателей этой ионийской деревни Хейшо – и почитаемый хранитель, и друг. С незапамятных времен он носит на своей спине дома жителей – и потому они могут доверить ему поиск тихого пристанища во времена невзгод.","Боец",["РЕПТИЛИЯ"],["Иония"],"ЭПИЧЕСКОЕ"],"08IO021":["Танец Эмпирейца","Остановите вражеское быстрое заклинание, медленное заклинание или способность, верните врага и призовите карту Эмпиреец.","","\"Этот танец и есть наше воспоминание\". – Ирелия","Заклинание",[],["Иония"],"РЕДКОЕ"],"08IO019":["Честный Аднер","Призвав меня, призовите карту Птицеводы Аднера.","","\"Эта земля таит в себе множество уроков. Всегда помните: окончание любого времени года – это праздник, ибо лишь в завершении рождается новое начало\".","Боец",[],["Иония"],"РЕДКОЕ"],"08IO010":["Вверх дном","Верните врага, чтобы повысить на 2 стоимость следующего бойца, разыгрываемого вашим оппонентом в этом раунде.","","\"Те, кто желает нам зла, упокоятся на дне морском\".\n– Повелитель рек","Заклинание",["СТИХИЯ"],["Иония"],"ОБЫЧНОЕ"],"08IO023":["Резвые морские духи","Разыгрывая карту: призовите мою точную эфемерную копию.","","В урочный сезон, когда ветер задувает в море, некоторые заунцы клянутся, что приметили нечто вроде двух огромных созданий с плавниками, весело пляшущих на океанских волнах.","Боец",[],["Иония"],"ОБЫЧНОЕ"],"08BC020":["Ранняя пташка","Противник сбрасывает карту с самой высокой стоимостью.","","\"Представьте, что вы червь. Последнее, что вы успеваете увидеть перед смертью, – вот эти глаза. А, у червей нет зрения? Ну, это, пожалуй, даже к лучшему\". – Элли, Надменная странница","Заклинание",[],["Бандл Сити"],"ОБЫЧНОЕ"],"08BC005":["Лопающийся рюкзак","За каждую сыгранную вами в этом матче карту Лопающийся рюкзак прикрепите 4 Колокольчика в вашей колоде и 4 Ядовитых гриба в колоде противника. Создайте в своей колоде карту Лопающийся рюкзак.","","\"Правило 207. Скаут несет на себе только то, что ему нужно!\" – Целеустремленная Эйва","Заклинание",[],["Бандл Сити"],"РЕДКОЕ"],"08BC021":["Коварная рокировка","Верните одного союзника и призовите вместо него другого: Голодная котосова.","","\"МЯУГУ?\" – Котосова","Заклинание",[],["Бандл Сити"],"РЕДКОЕ"],"08BC002":["Скип, \"Король рифа\"","Разыгрывая карту: выберите 1 из 2 карт (не чемпионов) из руки противника. Я пленяю ее.","","\"Ага, я хорош собой, проворен, невозмутим и крут. Разве не знаешь, старичок? Я король этого рифа, а ты вторгся в мое королевство!\"\n\"Погоди-ка! Вернись сию же секунду! Этот образец мне нужен для исследования!\" – Знаток раковин","Боец",[],["Бандл Сити"],"ЭПИЧЕСКОЕ"],"08BC006":["Портальный первопроходец","Разыгрывая карту: выберите заклинание Исследователя, чтобы создать его в руке.","","\"Я беспокоюсь за Банчеза! Ох, что-то он все больше нервничает в последнее время. Даже небольшой рывочек через портал дается ему с трудом! Не понимаю, почему так\". – Из записок экспедиции, снаряженной Подразделением Дальних Краев Гильдии Исследователей, пункт назначения: Бандл Сити","Боец",["ЙОРДЛ"],["Бандл Сити","Иония"],"РЕДКОЕ"],"08BC004":["Порция Чудаковатая","Разыгрывая карту: воплотите титанического сторонника и сделайте его характеристики равными 1|1, а стоимость – равной 0.","","\"Конечно, я знаю старую Порцию! Она слегка с прибабахом, но портал она вам обеспечит до любой точки, если будет надо.  Один взмах хвоста – и понеслось!\" – Портальный первопроходец","Боец",["ДРАКОН"],["Бандл Сити"],"ЭПИЧЕСКОЕ"],"08BC018":["Сладкая западня","Поместите союзника вниз своей колоды, чтобы призвать верхнего союзника из своей колоды.","","\"Правило 571: скаут всегда должен быть начеку. Никогда не знаешь, где тебя ждет вкусное угощение, а где поджидает ловушка\". – Целеустремленная Эйва","Заклинание",[],["Бандл Сити"],"РЕДКОЕ"],"09SI015":["Прекрасная катастрофа","I: убейте бойца с суммарным значением силы и здоровья не больше 5.\nII: истощите вражеский нексус на 2 ед. здоровья.\nIII: призовите точную копию союзника. У нее будет Эфемерность и 1|1.","","Он взобрался по ступенькам на сцену, сжимая в руке лист со стихотворением. Он не расклеивал никаких плакатов, рекламирующих выступление, потому что у него уже была та самая публика, которую он так ждал.","Место силы",["ИСТОРИЯ"],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"09SI013":["Железное вторжение","I-II: выберите союзного сторонника. Создайте в руке его эфемерную копию с +1|+1.\nIII: воскресите сильнейшего погибшего союзного сторонника и даруйте ему Эфемерность.","","В Сером царстве измученные формы собираются в призрачную армию. Как только откроются врата в мир смертных – их ничто не остановит.","Место силы",["ИСТОРИЯ"],["Сумрачные острова"],"РЕДКОЕ"],"09SI012":["Экзистенциальный ужас","Даруйте врагам Безысходность.","","\"В чем смысл хоть чего-нибудь?\" – Векс","Заклинание",[],["Сумрачные острова"],"РЕДКОЕ"],"09SI017":["Харокс","Предсмертный вздох или когда умирает союзник, чей подтип не Щупальце: дважды используйте Порождение.","","Говорят, что Харокс, одинокий гребец на призрачном корабле, который многие моряки называют Последним паромом, общается с духами всех моряков, погибших на пути к островам.","Боец",[],["Сумрачные острова"],"ЭПИЧЕСКОЕ"],"09SI014":["Гримм","Разыгрывая карту: четырежды даруйте бойцу Безысходность.","","Будучи мрачным романтиком, исстрадавшимся поэтом и ценителем всего философского, Гримм умеет ценить негативные стороны жизни. Объект его воздыхания может и уколоть, но в его глазах от этого она лишь прекраснее.","Боец",["ЙОРДЛ"],["Сумрачные острова"],"ОБЫЧНОЕ"],"09DE033":["Юные духи","","","\"Юные духи – восхитительные существа. Их потенциал просто-напросто бесконечен, если дать им время и подходящего сновидца!\" – Мать духов","Боец",[],["Демасия","Иония"],"ОБЫЧНОЕ"],"09DE039":["Свет Демасии","I: даруйте союзнику Мужество.\nII: дважды даруйте союзнику Мужество.\nIII: мотивируйте всех союзников.","","Народ радостно возликовал, когда ее сияние озарило обращенные к ней лица. Она всегда стремилась лишь поддержать своих сограждан и укрепить их дух – и те, в свою очередь, поддержали ее дружным хором обожания: \"Люксанна! Люксанна! Люксанна!\"","Место силы",["ИСТОРИЯ"],["Демасия"],"РЕДКОЕ"],"09DE034":["Люкс Просвещенная","Поддержка: даруйте Мужество союзнику, которого я поддерживаю, и дайте мне Щит до конца раунда.","Союзники получили при атаке или использовали при атаке 20+ полезных навыков.","Горожане в изумлении смотрели, как свет кружился и изгибался вокруг Люксанны. Она была Леди света Демасии, выдающейся молодой представительницей дома Краунгард и талантливым магом. А Демасия была такой, какой она всегда хотела ее видеть.","Боец",[],["Демасия"],"Чемпион"],"09DE047":["Забытый артефакт","Призовите карту Песчаный скакун, затем дайте союзникам Выбор противника до конца раунда.","","Глубоко в хранилище конфискованных магических предметов охотника на магов находится странная резная фигура без пометки, чье назначение давно забыто...","Заклинание",[],["Демасия"],"РЕДКОЕ"],"09DE041":["Петрицитовый зал","I: союзник берет в плен бойца.\nII: прокляните противника с помощью навыка Подавление.\nIII: уничтожьте все карты, плененные союзниками.","","Ликование толпы стихло, когда она вошла в зал. Статуи молчаливо взирали. Впереди ждала тьма, но она не могла отступить – кто еще способен спасти Демасию от кошмара?","Место силы",["ИСТОРИЯ"],["Демасия"],"ЭПИЧЕСКОЕ"],"09DE030":["Свечение","Мотивируйте всех бойцов.","","\"Наше сияние безгранично!\" – Люкс Просвещенная","Заклинание",[],["Демасия"],"ОБЫЧНОЕ"],"09DE043":["Восходящий свет","Трижды мотивируйте всех бойцов.","","\"Воплощение света!\" – Люкс Просвещенная","Заклинание",[],["Демасия"],"РЕДКОЕ"],"09DE031":["Джарро Перышко","Разыгрывая карту: даруйте союзнику в руке Мужество.","","Перед ней в россыпи лепестков роз и в окружении светящихся существ возник молодой человек в маскарадной маске. \"Меня зовут Перышко. Джарро Перышко, – произнес он. – Мне сообщили, что вам может пригодиться помощь. Это так, миледи?\"","Боец",[],["Демасия"],"РЕДКОЕ"],"09DE046":["Чарующая усмешка","Мотивируйте 2 союзников, затем они по очереди нанесут удар врагу.","","\"Спокойно, дамы. Меня на всех хватит\". – Джарро Перышко","Заклинание",[],["Демасия"],"ОБЫЧНОЕ"],"09DE045":["Свет грез Алина","Призвав меня, призовите 5 карт Юные духи. За каждую карту, для которой нет места в руке, вместо этого дважды даруйте слабейшему союзнику Мужество.","","\"В твоем возрасте я боялась света. Никто не объяснил мне, что моя магия – это дар, который я получила не просто так. Но для этого у тебя есть я. Не надо бояться, Алина. Пусть сияет\". – Люкс Просвещенная","Боец",[],["Демасия"],"ЭПИЧЕСКОЕ"],"09DE040":["Нетипичный охотник на магов","Призвав меня, даруйте другим союзникам Мужество.","","\"Леди Краунгард\". Охотник на магов воплотился из теней и протянул к ней руку. На его наполовину скрытом лице зазывающая улыбка казалась излишне широкой. \"Почему бы вам не последовать за мной?\"","Боец",[],["Демасия"],"ОБЫЧНОЕ"],"09DE036":["Древесные духи","Разыгрывая карту: мотивируйте всех остальных бойцов.","","\"Вперед, маленькие духи. Укажите путь своему сновидцу\". – Лиллия","Боец",[],["Демасия","Бандл Сити"],"ОБЫЧНОЕ"],"09DE029":["Дух света","Поддержка: до конца раунда дайте все полезные навыки и их накопления союзнику, которого я поддерживаю.","","\"Ну же, мистер дух. Давай рассеем эти жуткие тени!\"\n– Свет грез Алина","Боец",[],["Демасия"],"РЕДКОЕ"],"09SH010":["Реставратор империи","Разыгрывая карту: даруйте союзному месту силы особенность \"Когда меня разрушают, я возрождаюсь\".","","Восхождение императора пробудило надежду во всей Шуриме. Эта волшебница называет себя \"реставратором империи\". Полная решимости воплотить в жизнь планы Азира, она странствует по пустыням, намереваясь вернуть погребенным руинам их былое великолепие.","Боец",[],["Шурима"],"ОБЫЧНОЕ"],"09SH009":["Войско императора","I: призовите 2 Песчаных солдат.\nII: сделайте Предсказание.\nIII: призвав союзника в этом раунде, дайте ему +2|+0 до конца раунда.","","Азир знает Шуриму прошлого, настоящего и будущего. Он верит: то, что он видит в грядущем, – не просто мечты, но пророчество, которое ему суждено воплотить в жизнь.","Место силы",["ИСТОРИЯ"],["Шурима"],"ЭПИЧЕСКОЕ"],"09SH012":["Призыв Детей солнца","Выберите 1 из 3 чемпионов, которые были в вашей колоде в начале игры, и вытяните его карту.","","Многие артефакты древних воинов Детей солнца были со временем утрачены. Однако сами боги-воители, которых артефакты олицетворяли, иногда могли и уцелеть.","Заклинание",[],["Шурима"],"РЕДКОЕ"],"09PZ044":["Молитва при свечах","I–II: примените Порыв x1, чтобы вытянуть 1 карту.\nIII: вытяните 1 карту.","","Этот храм Жанны почти не имеет стен, что неудивительно, если знать, чем повелевает богиня. Тем не менее, многочисленные свечи продолжают гореть, даже если остальная часть Зауна объята ревущей бурей.","Место силы",["ИСТОРИЯ"],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"09PZ045":["Парящий картограф","Разыгрывая карту: примените Порыв x1, чтобы вытянуть другую карту стоимостью либо меньше, либо больше той, к которой применен Порыв.","","\"Высота – самый верный способ заставить кого-то осознать собственную незначительность\".","Боец",[],["Пилтовер и Заун"],"РЕДКОЕ"],"09PZ046":["Недомутация","Выберите союзного сторонника. Призовите 2 Голодные котосовы, затем превратите союзников в точные копии выбранного союзника.","","\"Еще один экземпляр... и тогда все будет безупречно\".\n– Безумная бракоделка","Заклинание",[],["Пилтовер и Заун"],"ЭПИЧЕСКОЕ"],"09IO055":["Лепестковая пикси","Призвав меня, призовите карту Юные духи.","","\"На голове нашей Лиллии такой беспорядок! Почему бы тебе не причесать ее? Не забывай: первый локон – за желанья, а второй – уже за сны, а последний самый локон – за все то, что не видим мы\". – Мать духов","Боец",[],["Иония"],"РЕДКОЕ"],"09IO056":["Танец духов","Верните союзника, чтобы даровать все накопленное им Мужество другому союзнику.","","\"Сокровенные сны в одной дремоте от реальности!\"\n– Лиллия","Заклинание",[],["Иония"],"РЕДКОЕ"],"09IO048":["Мать духов","Призвав меня, даруйте Мужество союзным картам Юные духи и Матери духов везде.","","Духи энергичны, непостоянны и не всегда слушают охотно. Чтобы каждый из них наверняка добрался до своего сновидца, Мать духов держит их под контролем и не скупится на выговоры.","Боец",[],["Иония"],"ЭПИЧЕСКОЕ"],"09IO049":["Урожай росы","I: призовите карту Юные духи.\nII: усыпите союзника.","","Каждая росинка на матери-дереве позволяет заглянуть в сон, который снится кому-то на Рунтерре, – и все до одной росинки нужно бережно собирать, питать и защищать.","Место силы",["ИСТОРИЯ"],["Иония"],"ОБЫЧНОЕ"],"09IO052":["Лиллия","Призвав меня либо когда я наношу удар: создайте в руке карту Посох снов, а если она у вас уже есть, снизьте ее стоимость на 1.","Вы призвали 15+ союзников или мест силы.","В самом сердце Сада Забвения близится время сбора росяного урожая. Хотя за этой росой с любовью ухаживали Лиллия и остальные смотрители сада, в ней появилась странная гниль, а сны, которые показывает роса, стали мрачными и жуткими...","Боец",[],["Иония"],"Чемпион"],"09IO046":["Смотрительница Офелис","Разыгрывая карту: полностью исцелите союзника, затем усыпите его.","","Уход за Древом Грез и окружающим его садом – большая честь, требующая самопожертвования. Чтобы выразить свое уважение и признательность, смотрители сада делятся своими воспоминаниями, каждую ночь теряя частичку себя.","Боец",[],["Иония"],"ОБЫЧНОЕ"],"09IO051":["Тропа среди корней","I-II: вытяните 1 карту.\nIII: снизьте стоимость карт в вашей руке на 1 до конца раунда.","","Сад Забвения – пристанище самых странных существ от мала до велика, и некоторые из них более разумны, чем им бы самим хотелось.","Место силы",["ИСТОРИЯ"],["Иония"],"РЕДКОЕ"],"09IO053":["Мистер Корень","Призвав меня, вытяните 1 карту.","","\"Ух ты, однажды настанет конец нам и всей этой красоте. Надеюсь, я уйду раньше. Хе-хе!\"","Боец",[],["Иония"],"ОБЫЧНОЕ"],"09IO045":["Распускающийся бутон","Усыпите бойца.","","\"Мечты расцветают!\" – Лиллия","Заклинание",[],["Иония"],"РЕДКОЕ"],"09IO058":["Сердце Древа","I: исцелите ваш нексус на 3 ед. здоровья и призовите карту Юные духи.\nII: даруйте союзникам везде Мужество.\nIII: воплотите карту стоимостью 8 или более и наполовину снизьте ее стоимость (с округлением в большую сторону).","","Духи снов – одни из самых многочисленных обитателей Сада. Их форма, размер, темперамент могут разниться. Многие из них заходят внутрь капель росы, чтобы проводить спящих к их самым сокровенным желаниям.","Место силы",["ИСТОРИЯ"],["Иония"],"ЭПИЧЕСКОЕ"],"09IO059":["Ураган стали","Оглушите врага, вновь оглушите его в начале следующего раунда.","","\"Клинок превыше всего\". – Ёнэ, Охотник на ветер","Заклинание",[],["Иония"],"ОБЫЧНОЕ"],"09FR009":["Парад поро","I-II: воплотите сторонника, чей подтип отличен от подтипов союзников на поле боя.\nIII: дайте союзнику +1|+1 до конца раунда за каждого союзника с подтипом.","","После визита в королевство Ингвар еще прочнее укрепила связи с подданными Короля поро. Лучший способ улучшить дипломатические отношения – носиться по Фрельйорду в поисках приключений.","Место силы",["ИСТОРИЯ"],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"09FR014":["Брюнхир Громогласная","Разыгрывая карту: уничтожьте бойца в руке, чтобы призвать карту Иссеченный бурей шпиль, значение счетчика которой равно ее стоимости и которая призывает точную копию бойца. (не менее 1)","","\"Я выкована горной бурей и песней моего народа!\"","Боец",[],["Фрельйорд"],"ЭПИЧЕСКОЕ"],"09FR010":["Сверхмягкий поро","Разыгрывая карту: восстановите 1 ед. здоровья нексусу за каждого союзника с подтипом.","","\"О-хо-хо, вот это пушок!\" – Пастух поро","Боец",["ПОРО"],["Фрельйорд"],"ОБЫЧНОЕ"],"09FR012":["Ледяная рубка","Даруйте союзнику столько ед. здоровья, сколько у него силы, и навык Громадный, после чего его сила станет 0.","","Некоторые деревья во Фрельйорде под силу свалить разве что зимним холодам.","Заклинание",[],["Фрельйорд"],"РЕДКОЕ"],"09BC020":["Презрительный взгляд","Даруйте бойцу Безысходность, чтобы вытянуть 1 карту.","","\"Мои поздравления. Я тебя ненавижу\". – Векс","Заклинание",[],["Бандл Сити","Сумрачные острова"],"ОБЫЧНОЕ"],"09BC012":["Вся семья в сборе","I: даруйте бойцу Безысходность.\nII: даруйте союзнику Таран.\nIII: мотивируйте 2 бойцов.","","Тепла в ее сердце не прибавилось и после отсутствия. Зато семейные ужины теперь довольно тихие – как раз по нраву Векс.","Место силы",["ИСТОРИЯ"],["Бандл Сити"],"ЭПИЧЕСКОЕ"],"09BC001":["Векс","Атака: даруйте сильнейшему врагу Безысходность.","Вы даровали Безысходность 5+ раз в разное время.","\"Уф, вот ведь тупица розовая. Я же говорила, что НЕНАВИЖУ вечеринки. Особенно с тортом. Отстой.\nВ общем... Разбудите меня, когда она свалит\".","Боец",["ЙОРДЛ"],["Бандл Сити","Сумрачные острова"],"Чемпион"],"09BC002":["Дядюшка Милти","Как только завершите историю, дважды даруйте мне Мужество.","","Хотя Дядюшка Милти совсем не похож на свою мрачную племянницу, он всегда старается изо всех сил, чтобы найти с ней общий язык. Особенно когда рассказывает страшные сказки при свечах.","Боец",["ЙОРДЛ"],["Бандл Сити"],"РЕДКОЕ"],"09BC013":["Крылодарение","I-II: выберите союзника. Затем выберите 1 из 3 случайных сторонников стоимостью на 1 ед. выше, чтобы совершить превращение в него.\nIII: выберите союзника. Затем выберите 1 из 3 случайных сторонников стоимостью на 2 ед. выше, чтобы совершить превращение в него.","","Глядя на Старого Тревора Соннопупса, всякий раз думаешь, что он витает где-то во снах. Но этот сон, к счастью, выглядит довольно мирно... Впрочем, как ни странно, все, кого он в нем встречает, хотят такие же крылья, как у него...","Место силы",["ИСТОРИЯ"],["Бандл Сити"],"РЕДКОЕ"],"09BC004":["Аллай","Разыгрывая карту: даруйте мне Мужество или даруйте бойцу Безысходность.","","\"Ве-е-е-е-е-е! Погоди-и-и-и! Тут кое-что для тебя! Это приглашение на ВЕЧЕРИНКУ В ЧЕСТЬ ТВОЕГО ДНЯ РОЖДЕНИЯ! И вот твой подарок! Чуть-чуть заранее! Я просто НЕ МОГЛА БОЛЬШЕ ждать. Ну как, ты в восторге? Надо обсудить, кто в чем придет, а еще ТОРТИК, а еще... Ве-е-е?..\"","Боец",["ЙОРДЛ"],["Бандл Сити"],"ОБЫЧНОЕ"],"09BC016":["Монструозный прорыв","Увеличьте силу или здоровье союзника до 5 до конца раунда.","","\"Худший. Подарок. В истории\". – Векс","Заклинание",[],["Бандл Сити"],"ОБЫЧНОЕ"],"09BC003":["Зловещий подарок","Когда призван первый враг, даруйте ему Безысходность.","","\"Ух, а оказалось-то, что подарок не так уж и плох\".\n– Векс","Боец",[],["Бандл Сити"],"РЕДКОЕ"],"09BC018":["Тень","Призвав меня, вытяните карту Векс.\nУ меня +1|+0 за каждый раз, когда вы даровали Безысходность в этом матче.","","\"Давай, покажи им, Тень! Обойдемся без подарков, конфетти и УЖ ТОЧНО без праздничных колпаков\".\n– Векс","Боец",[],["Бандл Сити","Сумрачные острова"],"ЭПИЧЕСКОЕ"],"09BC011":["Духи Безысходности","Удар: даруйте мне Таран.","","\"Сны довольно забавно влияют на духов. Вот эти вроде бы оказались... ого, это что, тортик?\" – Лиллия","Боец",[],["Бандл Сити"],"ОБЫЧНОЕ"],"09BC006":["Накачанный мэр","Начало раунда: мотивируйте меня.","","Вдруг из неимоверно огромного торта выскочил чертовски мускулистый мэр. Это было словно в замедленной съемке. \"ПОЗДРАВЛЯ-А-А-А-А-А-АЮ С ДНЕМ РОЖДЕНИЯ! – манерно произнес мэр, – от лица самого главного – и самого подтянутого – из всех чиновников!\"\n\nСреди всех снов, что приходилось видеть Векс, этот она ненавидела больше всего. ","Боец",["ЙОРДЛ"],["Бандл Сити"],"ОБЫЧНОЕ"],"09BW022":["Абсолютная чемпионка","I: союзник и враг наносят удар друг другу. После удара у них остается не менее 1 ед. здоровья.\nII: полностью исцелите союзника.\nIII: создайте в руке 3 Монеты.","","Ангел годами готовилась выиграть в бою, который положит конец всем боям. Каждую ночь ей снится гора монет, способная заполнить всю бухту Билджвотера. Иначе говоря, этих денег хватит на покупку картофельной фермы.","Место силы",["ИСТОРИЯ"],["Билджвотер"],"ЭПИЧЕСКОЕ"],"09BW028":["Пылкий служитель","У меня +1|+0 за каждую вытянутую вами карту до конца раунда.","","\"Что значит \"нужно больше тренироваться\"? Смотри, я тренируюсь!\"","Боец",[],["Билджвотер"],"РЕДКОЕ"],"09BW027":["Наемничьи обычаи","Украдите вражеского сторонника с 3 или менее ед. здоровья до конца раунда. Нельзя использовать, если у вас уже есть 6 союзников или мест силы.","","\"Доброе утро начинается с награды за голову\".\n– Наемница","Заклинание",[],["Билджвотер"],"ОБЫЧНОЕ"],"09MT002":["Дымношкурый хозяин","I-II: для активации сбросьте 1 карту. Позовите творение небес стоимостью 7 или более.\nIII: снизьте стоимость случайной карты в руке на 5.","","Эта одинокая оттрани посвятила жизнь почитанию и поклонению драконам – до такой степени, что видит этих царственных зверей как наяву, так и во сне.","Место силы",["ИСТОРИЯ"],["Таргон"],"ЭПИЧЕСКОЕ"],"09MT004":["Таинственное благословение","Дважды даруйте союзнику Мужество.","","\"Я стану их святилищем\". – Моргана","Заклинание",[],["Таргон"],"ОБЫЧНОЕ"],"09MT005":["Сновидица песни дракона","Впервые применяя Зов в каждом раунде, призовите карту Дракончик.","","\"Драконы близко. Я это чувствую. Даже сейчас они проплывают в моих снах\".","Боец",[],["Таргон"],"ЭПИЧЕСКОЕ"],"09NX025":["Величайший боец арены","I–II: дайте союзнику +2|+0 до конца раунда.\nIII: дайте врагу Не блокирует до конца раунда.","","Популярность арены отчасти связана с тем, что на ней кто угодно может прославиться. Один фанат посмотрел все матчи Дрейвена, которые только смог, и теперь уверен, что если дать ему шанс, то он тоже сможет взойти на вершину.","Место силы",["ИСТОРИЯ"],["Ноксус"],"ЭПИЧЕСКОЕ"],"09NX032":["Укротитель йети","Чтобы сыграть меня, сбросьте 1 карту.\nПризвав меня, призовите карту Разгневанный йети.","","Успех военщины Ноксуса объясняется универсальностью его армии. Если пересеченная местность или сложные условия потребуют адаптации, воины извлекут пользу даже из самых неочевидных местных ресурсов.","Боец",[],["Ноксус"],"РЕДКОЕ"],"09NX033":["Оскверненный боевой топор","Конец раунда: если мой носитель в этом раунде не атаковал, даруйте ему Безысходность.","","Трусость обходится дорого.","Снаряжение",[],["Ноксус"],"РЕДКОЕ"]};
window.ATLAS_I18N_LOR_G={"sets":{"Call of the Mountain":"Зов Горы","Beyond the Bandlewood":"Гости из бандлового леса","Foundations":"Основы","Rising Tides":"Прилив","Worldwalker":"Странники","Empires of the Ascended":"Империи вознесшихся","Dreamlit Paths":"Тропы под светом грез","Glory in Navori":"Слава в Навори","Fate's Voyage":"Судьбоносное путешествие","Heart of the Huntress":"Сердце Охотницы","Events":"События","The Darkin Saga":"Сага о даркинах"},"regions":{"Noxus":"Ноксус","ElderDragon":"Старший дракон","Ryze":"Райз","Jhin":"Джин","Varus":"Варус","Aatrox":"Атрокс","Neeko":"Нико","Jax":"Джакс","Kayn":"Каин","PoroKing":"Король поро","Evelynn":"Эвелинн","Bard":"Бард","Demacia":"Демасия","Runeterra":"Рунтерра","Freljord":"Фрельйорд","ShadowIsles":"Сумрачные острова","Targon":"Таргон","Ionia":"Иония","Shurima":"Шурима","Bilgewater":"Билджвотер","PiltoverZaun":"Пилтовер и Заун","BandleCity":"Бандл Сити","SpiritBlossom":"Праздник цветения"},"rarities":{"COMMON":"ОБЫЧНОЕ","RARE":"РЕДКОЕ","EPIC":"ЭПИЧЕСКОЕ","CHAMPION":"Чемпион","NONE":"Нет"}};
